// ─── Laguna GPU bit-exact gate helpers ───────────────────────────────────────

/// Deterministic pseudo-random f32 fill in [-1, 1] (xorshift, seeded) — the
/// reproducible input for the Laguna GPU-vs-oracle gate.
#[cfg(feature = "laguna")]
fn laguna_gate_fill(n: usize, seed: u64) -> Vec<f32> {
    let mut s = seed.wrapping_add(0x9E3779B97F4A7C15);
    (0..n)
        .map(|_| {
            s ^= s << 13;
            s ^= s >> 7;
            s ^= s << 17;
            let u = (s >> 40) as f32 / (1u64 << 24) as f32; // [0,1)
            u * 2.0 - 1.0
        })
        .collect()
}

/// (cosine, max_abs_diff, argmax_match) between GPU and CPU-oracle outputs.
fn laguna_cos_maxdiff(gpu: &[f32], cpu: &[f32]) -> (f64, f64, bool) {
    let mut dot = 0f64;
    let mut ng = 0f64;
    let mut nc = 0f64;
    let mut maxd = 0f64;
    for (&a, &b) in gpu.iter().zip(cpu.iter()) {
        dot += a as f64 * b as f64;
        ng += (a as f64).powi(2);
        nc += (b as f64).powi(2);
        maxd = maxd.max((a as f64 - b as f64).abs());
    }
    let argmax = |v: &[f32]| -> usize {
        v.iter().enumerate().fold((0usize, f32::NEG_INFINITY), |(bi, bv), (i, &x)| {
            if x > bv { (i, x) } else { (bi, bv) }
        }).0
    };
    let cos = dot / (ng.sqrt() * nc.sqrt() + 1e-12);
    (cos, maxd, argmax(gpu) == argmax(cpu))
}

/// (dir, cfg) of the resident Laguna model, for the gate's CPU-oracle load.
#[cfg(feature = "laguna")]
fn laguna_gpu_dir_cfg(m: &VulkanModel) -> PyResult<(std::path::PathBuf, laguna::LagunaConfig)> {
    let g = m.laguna_gpu.as_ref()
        .ok_or_else(|| PyRuntimeError::new_err(
            "no resident Laguna model (set VLLM_VULKAN_LAGUNA_RESIDENT=1)"))?;
    Ok((g.dir.clone(), g.config.clone()))
}

// ─── Device query functions ──────────────────────────────────────────────────

/// Return True if at least one Vulkan-capable device is present.
#[pyfunction]
fn is_available() -> bool {
    device::is_vulkan_available()
}

/// Number of Vulkan-capable physical devices.
#[pyfunction]
fn get_device_count() -> usize {
    device::device_count()
}

/// Enumerate all Vulkan physical devices as a list of dicts.
#[pyfunction]
fn enumerate_devices(py: Python<'_>) -> PyResult<Vec<PyObject>> {
    device::enumerate_devices()
        .into_iter()
        .map(|info| {
            let dict = pyo3::types::PyDict::new(py);
            dict.set_item("name", &info.name)?;
            dict.set_item("vendor_id", info.vendor_id)?;
            dict.set_item("device_type", &info.device_type)?;
            dict.set_item("api_version", &info.api_version)?;
            dict.set_item("driver_version", info.driver_version)?;
            dict.set_item("total_memory_bytes", info.total_memory_bytes)?;
            Ok(dict.into())
        })
        .collect()
}

/// Return device info dict for `device_idx`.
#[pyfunction]
fn get_device_info(py: Python<'_>, device_idx: usize) -> PyResult<PyObject> {
    let devs = device::enumerate_devices();
    let info = devs
        .get(device_idx)
        .ok_or_else(|| PyRuntimeError::new_err(format!("no device at index {device_idx}")))?;
    let dict = pyo3::types::PyDict::new(py);
    dict.set_item("name", &info.name)?;
    dict.set_item("vendor_id", info.vendor_id)?;
    dict.set_item("device_type", &info.device_type)?;
    dict.set_item("api_version", &info.api_version)?;
    dict.set_item("driver_version", info.driver_version)?;
    dict.set_item("total_memory_bytes", info.total_memory_bytes)?;
    Ok(dict.into())
}


/// Synchronise all pending Vulkan work across all devices.
#[pyfunction]
fn synchronize() -> PyResult<()> {
    device::synchronize_all().map_err(PyRuntimeError::new_err)
}

/// Return `(used_bytes, total_bytes)` for `device_idx`.
#[pyfunction]
fn get_memory_info(device_idx: usize) -> PyResult<(u64, u64)> {
    device::memory_info(device_idx).map_err(PyRuntimeError::new_err)
}


// ─── SPIR-V embedding ────────────────────────────────────────────────────────

/// Embed all pre-compiled SPIR-V files using `include_bytes!` at compile time.
///
/// Shader names use the exact filenames (without `.spv`) from the
/// `shaders/spirv/` directory as generated by `vulkan-shaders-gen`.
pub(crate) fn include_all_shaders() -> std::collections::HashMap<String, Vec<u8>> {
    shader_registry::SHADER_REGISTRY
        .iter()
        .map(|(name, _class, bytes)| ((*name).to_owned(), bytes.to_vec()))
        .collect()
}

