// ─── VulkanModel — end-to-end Gemma4 forward pass ────────────────────────────

/// Gemma4-E2B model with GPU-accelerated matmuls via Vulkan.
///
/// Weights are uploaded to GPU-resident host-coherent buffers once at load
/// time.  Each forward step dispatches matmuls to the GPU (one vkQueueSubmit
/// per layer) while norms and attention run on CPU.
///
/// Usage from Python:
///   vk_model = VulkanModel(safetensors_path, device_idx=0)
// Slot indices for persistent activation buffers (allocated once per model).
const ACT_QKV_IN:  usize = 0;
const ACT_Q_OUT:   usize = 1;
const ACT_K_OUT:   usize = 2;
const ACT_V_OUT:   usize = 3;
const ACT_O_IN:    usize = 4;
const ACT_O_OUT:   usize = 5;
const ACT_FFIN:    usize = 6;
const ACT_GATE:    usize = 7;
const ACT_UP:      usize = 8;
const ACT_MID:     usize = 9;
const ACT_DOWN:    usize = 10;
const ACT_GELU:    usize = 11; // gelu(gate) output           [ffn_inter]
const ACT_PLE_G:   usize = 12; // PLE gate output             [ple_dim]
const ACT_PLE_C:   usize = 13; // PLE contribution output     [H]
const ACT_COUNT:   usize = 14;

// Slot indices for the FUSED GPU-resident Qwen decode layer (roadmap #2).
// hidden ping-pongs between QR_HA and QR_HB so residual adds need no buffer
// copies: attn add reads HA → writes HB; ffn add reads HB → writes HA. Each
// layer therefore ends with hidden back in QR_HA.

// Slot indices for the FUSED GPU-resident Gemma4 decode layer (roadmap P4).
// Gemma uses SANDWICH norms (norm applied to the sublayer OUTPUT before the
// residual add), so each sublayer needs an extra "normed output" buffer that is
// the second operand of the residual add. hidden ping-pongs GR_HA↔GR_HB.
// Buffers are sized for the MAX over layer types (global head_dim=512,
// double-wide ffn_inter). The PLE tail keeps the reference's small CPU glue.

/// Persistent RDMA-registered 1-elem scratch for the PP ring-back token
/// broadcast (last stage → rank 0). Pinned ONCE via `vcclCommRegister` so the
/// per-token bcast skips the per-call temp-MR (`ibv_reg_mr`/dereg) — the
/// "buffer not registered with the comm" warning on the token hop. Shared by
/// every PP decode arch (kimi/qwen35/nemotron) through `pp_bcast_token`; the
/// token id round-trips exactly through the single f32 (vocab ≪ 2^24, so an
/// integer token is bit-exact in f32). `handle == 0` ⇒ not registered → falls
/// back to a fresh-Vec send/recv (correct, just per-call regMr).
#[derive(Default)]
struct PpTokRing {
    buf: Vec<f32>,
    handle: usize,
}

/// (Re-)pin a [`PpTokRing`] as a `len`-f32 RDMA-registered scratch on `comm`:
/// deregister any prior handle, reallocate the buffer to `len` (a stable
/// address while live), and `comm_register` it. On registration failure the
/// buffer is cleared and `handle` left 0 so the caller falls back to the
/// fresh-`Vec` send/recv (correct, just the per-call regMr). Free function so
/// callers can pass `&mut self.pp_hop_send` while reading other `self` fields.
/// Stage the `[vocab]` logits `out` into `ring` for a registered ring-back
/// send. When `ring` is pinned (`handle != 0`) and correctly sized, `out` is
/// copied into the NIC-registered buffer (stable address, no per-call temp-MR)
/// and `true` is returned — the caller sends from `ring.buf`. Otherwise `ring`
/// is left untouched and `false` is returned — the caller sends `out` directly
/// (fresh-`Vec` fallback). The BYTES put on the wire are identical either way;
/// only WHICH backing memory holds them changes. Free function (mirrors
/// [`pin_pp_hop`]) so it can be unit-tested without a live comm.
fn stage_vocab_send(ring: &mut PpTokRing, out: &[f32]) -> bool {
    if ring.handle != 0 && ring.buf.len() == out.len() {
        ring.buf.copy_from_slice(out);
        true
    } else {
        false
    }
}

fn pin_pp_hop(comm: *mut std::os::raw::c_void, ring: &mut PpTokRing, len: usize, tag: &str) {
    if ring.handle != 0 {
        let _ = vccl_ffi::comm_deregister(comm, ring.handle);
        ring.handle = 0;
    }
    ring.buf = vec![0.0f32; len];
    let addr = ring.buf.as_ptr() as usize;
    match vccl_ffi::comm_register(comm, addr, len * std::mem::size_of::<f32>()) {
        Ok(h) => ring.handle = h,
        Err(e) => {
            log::warn!("{tag}: register PP hop scratch ({len} f32) failed: {e}; per-call regMr");
            ring.buf.clear();
        }
    }
}

/// Registered PP-hop scratch for the fused `pp_step_gemma` native hop. Unlike
/// nemotron/kimi/laguna (whose scratch lives on a dedicated sub-model struct),
/// Gemma's PP forward is a `VulkanModel` method, so its recv/send scratch lives
/// here. Both buffers are sized to the composite `pp_gemma_msg_len`
/// (`hidden+ple+target_kv`, identical on every stage), `comm_register`'d ONCE on
/// first use, and reused each token (stable address). `handle==0` ⇒ not pinned;
/// the hop falls back to a fresh-`Vec` `recv_f32`/`send_f32` (still native — no
/// PyList — just a per-call regMr). `Default` = all-empty/unpinned.
#[derive(Default)]
struct GemmaPpHop {
    recv_scratch: Vec<f32>,
    recv_handle: usize,
    send_scratch: Vec<f32>,
    send_handle: usize,
}

///   logits = vk_model.forward(token_id, position)
#[pyclass]

pub struct VulkanModel {
    /// Gemma4 path.  When `qwen` is Some (Qwen3 model), this holds an empty
    /// placeholder and is never used.
    #[cfg(feature = "gemma")]
    inner: model::Gemma4Model,
    // Foundation-carve placeholder: with the `gemma` feature off there is no
    // base Gemma4 model, but the field name must still exist so the (unreachable)
    // construction sites keep compiling. `()`-typed twin, never read.
    #[cfg(not(feature = "gemma"))]
    #[allow(dead_code)]
    inner: (),
    /// Qwen3 path (None for Gemma4 models).  Selected by architecture detection.
    #[cfg(feature = "gemma")]
    qwen: Option<model::Qwen3Model>,
    #[cfg(not(feature = "gemma"))]
    #[allow(dead_code)]
    qwen: Option<()>,
    /// Qwen3.6 (qwen3_5) hybrid path (GatedDeltaNet + GatedAttention, dense/MoE).
    /// Some when config.json model_type == "qwen3_5". Holds its own per-layer
    /// state (DeltaNetState / KvCache) and full forward. (Phase 1 wiring.)
    #[cfg(feature = "qwen35")]
    qwen35: Option<qwen35::Qwen35Model>,
    #[cfg(not(feature = "qwen35"))]
    #[allow(dead_code)]
    qwen35: Option<()>,
    /// Some when config.json model_type == "step3p7" (Step-3.7-Flash-148B, a
    /// REAP-pruned 212-expert sigmoid-router MoE). CPU-only reference forward
    /// (weight+1 RMSNorm, head-wise sigmoid attn gate, DeepSeek-V3 bias router
    /// ×3.0, partial-RoPE + llama3 scaling, dual 64/96 heads, 3D NVFP4 experts).
    /// Loaded by the `mt=="step3p7"` dispatch in `new`; the GPU-resident expert
    /// path + full 45-layer + TP-2×PP-5 @ 10 nodes is the node-count-blocked phase.
    #[cfg(feature = "step3p7")]
    step3p7: Option<step3p7::Step3p7Model>,
    #[cfg(not(feature = "step3p7"))]
    #[allow(dead_code)]
    step3p7: Option<()>,
    max_seq_len: usize,
    /// Vulkan engine for GPU matmuls (None = CPU-only fallback)
    engine: Option<compute::ComputeEngine>,
    /// GPU-resident weight buffers keyed by weight name
    gpu_weights: std::collections::HashMap<String, GpuWeight>,
    /// Pre-allocated persistent activation buffers (fixed Vec, stable pointers)
    act_bufs: Vec<compute::Buffer>,
    /// Whether act_bufs are initialised for the current model config
    act_bufs_ready: bool,
    /// Pipeline-parallel layer range [pp_start, pp_end) this rank owns.
    /// Full model = [0, num_hidden_layers); only these layers' weights load.
    pp_start: usize,
    pp_end: usize,
    pp_first: bool,  // owns the embedding (runs the input embed)
    pp_last: bool,   // owns the final norm + LM head (produces logits)
    /// Megatron tensor-parallel rank / world size (VLLM_VULKAN_TP_RANK/_SIZE).
    /// tp_size==1 => no TP (full tensors). When >1, each rank holds a column- or
    /// row-shard of every projection weight (see `tp_shard` in the loader) and
    /// `forward_tp` all-reduces the o_proj and down_proj partial sums.
    tp_rank: usize,
    tp_size: usize,
    /// Gemma's `embed_tokens_per_layer` table kept bf16-resident (it is ~9.4GB
    /// as f32 and OOMs a node). Row-major [vocab, num_layers*ple_dim]; one row
    /// is converted to f32 per token. Only loaded on the PLE-owning (first) stage.
    gemma_ple_bf16: Option<Vec<u16>>,
    /// GPU-resident KV cache (roadmap #3a): per-layer persistent device buffer
    /// laid out [K-plane(max_seq×num_kv×hd)][V-plane], so GPU attention reads the
    /// KV in place instead of re-uploading the whole host cache every token
    /// (the per-call cost in gpu_sdpa). Lazily allocated per layer.
    gpu_kv: std::collections::HashMap<usize, compute::Buffer>,
    /// Watermark for the Gemma 1-CB resident decode fold (VLLM_VULKAN_GEMMA_RESIDENT_1CB):
    /// number of token positions [0..gemma_kv_filled) already resident in EVERY
    /// layer's `gpu_kv`. In the shipping token-by-token decode flow this always
    /// equals the current position (no seeding needed); it exists so a future
    /// batched-prefill-then-resident-decode path can lazily seed the prefill KV
    /// from the host cache. Reset to 0 by `reset_kv_cache`.
    gemma_kv_filled: usize,
    /// Persistent activation buffers for the FUSED GPU-resident Qwen layer
    /// (roadmap #2). Distinct from `act_bufs` (Gemma) — Qwen has its own slot
    /// layout (QR_* consts). Indexed once, reused every layer/token.
    qres_bufs: Vec<compute::Buffer>,
    qres_ready: bool,
    /// GPU-resident f32 norm weights (input/post-attn/q/k/final layernorms),
    /// uploaded once so the fused layer never re-writes them per token.
    gpu_norm_w: std::collections::HashMap<String, compute::Buffer>,
    /// Persistent activation buffers for the FUSED GPU-resident Gemma4 layer
    /// (roadmap P4). Distinct slot layout (GR_* consts) from act_bufs/qres_bufs.
    gres_bufs: Vec<compute::Buffer>,
    gres_ready: bool,
    /// GPU-resident f32 norm weights for the fused Gemma layer (input/q/k/
    /// post-attn/pre-ffn/post-ffn/ple-input + final), uploaded once up front.
    gemma_norm_w: std::collections::HashMap<String, compute::Buffer>,
    /// UNIFIED engine (VLLM_VULKAN_UNIFIED=1): one persistent buffer set + one
    /// norm-weight map serving BOTH arches via `gpu_layer(spec)`. Sized from the
    /// loaded config (a model instance is qwen XOR gemma). UR_* slot layout.
    ures_bufs: Vec<compute::Buffer>,
    ures_ready: bool,
    unified_norm_w: std::collections::HashMap<String, compute::Buffer>,
    /// EAGLE3 fast-verify (`forward_batched`): persistent T-wide (max_t=8)
    /// activation buffers, one command buffer PER LAYER (1 submit/layer) over
    /// GEMM projections + resident-KV attention. Dense/Qwen3-unified only
    /// (BR_* slot layout in `batched_forward.rs`). Distinct from `ures_bufs`
    /// (per-token unified decode) — sized `max_t * dim`, reused across calls.
    bres_bufs: Vec<compute::Buffer>,
    bres_ready: bool,
    /// qwen3_5 only: embed_tokens + lm_head kept as f16 on the HOST (the 27B's
    /// two ~5GB-as-f32 tables won't fit a 14GB node twice over). The CPU
    /// reference forward (forward_qwen35_cpu_ref) reads the embed row and runs
    /// the lm_head matmul straight from these f16 bytes. Row-major [rows, hidden].
    q35_f16_host: std::collections::HashMap<String, Vec<u16>>,
    /// Raw `vcclComm_t` pointer handed in by the launcher via
    /// `set_collective_comm` (the launcher owns the bootstrap/lifetime). When
    /// `VLLM_VULKAN_NATIVE_COMM != "0"` and this is non-null, the TP all-reduces
    /// and PP send/recv call libvccl directly (no Python callback). Stored as a
    /// usize because raw pointers aren't `Send`; we only ever use it on the
    /// forward thread that holds the GIL. 0 = unset.
    collective_comm: usize,
    /// Persistent RDMA-registered scratch for the native TP all-reduce. vCCL
    /// registers the recvbuff with the NIC on EVERY collective call (`ScopedReg`
    /// → `ibv_reg_mr`/dereg) unless it's already covered by a prior
    /// `vcclCommRegister`. A fresh `Vec<f32>` partial (new address each call) is
    /// never covered → re-registered every reduce, the dominant per-call cost
    /// for a 20 KB reduce. We register ONE fixed buffer up front and reduce
    /// through it (copy in → in-place reduce → copy out) so the per-call regMr
    /// is skipped. `Vec` with reserved capacity = stable address while live.
    /// Handle from `vcclCommRegister`; 0 = not registered (falls back to direct).
    reduce_scratch: Vec<f32>,
    reduce_scratch_handle: usize,
    /// Persistent RDMA-registered scratch for the native PP ring-back token
    /// broadcast (last stage → rank 0), pinned ONCE via `pp_bcast_token` so the
    /// per-token bcast skips the temp-MR. Shared by every PP arch. See
    /// [`PpTokRing`]. Deregistered/re-pinned when the comm handle changes.
    pp_tok_ring: PpTokRing,
    /// Persistent RDMA-registered [H] scratch for the NON-fused forward hidden
    /// hop (`pp_send_hidden`/`pp_recv_hidden`), the path the qwen3.5 PP driver
    /// takes (`forward_pp_qwen35` + explicit hop). Reused across tokens so vCCL
    /// skips the per-call temp-MR + "buffer not registered" warn; sized lazily
    /// to the H the driver sends (variable across archs), re-pinned on a size
    /// or comm-handle change. Gated by `VLLM_VULKAN_REG_REDUCE`; empty/0 falls
    /// back to the fresh-`Vec` send/recv (correct, per-call regMr). Nemotron's
    /// FUSED hop uses `NemotronModel::pp_{recv,send}_scratch` instead; kimi's
    /// fused hop has its own registered scratch — see `pp_step_{nemotron,kimi}`.
    pp_hop_send: PpTokRing,
    pp_hop_recv: PpTokRing,
    /// Persistent RDMA-registered `[vocab]` scratch for the PP logits ring-back
    /// (LAST stage → rank0) in `pp_step_{qwen35,gemma,nemotron,kimi}_logits`.
    /// Those seams used to `send_f32`/`recv_f32` the full `[vocab]` f32 through a
    /// FRESH per-call `Vec` (new address each token) → vCCL re-`ibv_reg_mr`/dereg'd
    /// it every decode step AND logged "vocab ring-back buffer (vocab*4 B) not
    /// registered with the comm". Pinning ONE buffer up front (re-pinned on a
    /// vocab/comm change) skips the temp-MR and silences the warn. Laguna has its
    /// own per-model `pp_vocab_scratch`; this is the SHARED buffer for the four
    /// arches whose logits seam is a `VulkanModel`/sub-model method with no vocab
    /// scratch of its own (one model loads per process → one buffer suffices; a
    /// rank is EITHER rank0-recv OR last-send, never both). Gated by
    /// `VLLM_VULKAN_REG_REDUCE`; empty/0 falls back to the fresh-`Vec` send/recv
    /// (correct, per-call regMr). Deregistered/re-pinned when the comm changes.
    /// See [`PpTokRing`].
    pp_vocab_ring: PpTokRing,
    /// INC-5b piece 3 (EAGLE drafter step-0 seed): a small position-keyed
    /// ring of the TARGET's pre-final-norm hidden states (backbone `[h]`,
    /// post-final-decoder-layer) — the `recurrent_hidden` half of the
    /// drafter's `inputs_embeds` on draft step 0
    /// (`GEMMA31B_SPEC_PLAN.md` §1.1). Stashed by
    /// `forward_tp_gemma`/`forward_tp_gemma_verify` keyed by absolute
    /// position (replicated — identical on every TP rank, so no gather is
    /// needed to read it); looked up via `gemma_hidden_for_pos()`. Mirrors
    /// qwen's `q35_prenorm_ring`/`stash_verify_prenorm` pattern.
    gemma_hidden_ring: std::collections::VecDeque<(usize, Vec<f32>)>,
    /// Registered recv/send scratch for the fused `pp_step_gemma` native-vCCL PP
    /// hop (`VLLM_VULKAN_GEMMA_NATIVE_HOP`). Pinned once, reused each token; see
    /// [`GemmaPpHop`]. Empty/unpinned when the native hop is off.
    gemma_pp_hop: GemmaPpHop,
    /// GPU-resident 4-bit MoE experts (VLLM_VULKAN_MOE_GPU). Per GLOBAL layer
    /// index: the whole layer's gate/up/down packed+scales+biases uploaded once
    /// to device buffers, sliced per expert at dispatch time via the mlx4 kernel's
    /// `packed_off`/`sb_off` push constants. Lazily built on first MoE call.
    moe_gpu: std::collections::HashMap<usize, MoeGpuLayer>,
    /// GPU-resident MoE CPU-glue weights (WS2): per GLOBAL layer index, the
    /// small host-f32 tensors the resident MoE path used to burn CPU on every
    /// token — shared expert gate/up/down, the shared-expert sigmoid gate and
    /// the router gate — uploaded once as raw f32 and dispatched with the
    /// pinned `mul_mat_vec_f32_f32_f32` variants. Lazily built alongside
    /// `moe_gpu`; host copies are kept (small) so the `MOE_GPU=0` CPU
    /// fallback still works.
    moe_shared_gpu: std::collections::HashMap<usize, MoeSharedGpu>,
    /// GPU-resident GatedDeltaNet decode state + per-layer constants (WS1b,
    /// VLLM_VULKAN_DN_GPU), per GLOBAL layer index. Lazily built on the
    /// layer's first deltanet forward; conv/delta state advances in place on
    /// the GPU (see `DnGpuLayer`).
    dn_gpu: std::collections::HashMap<usize, DnGpuLayer>,
    /// Persistent activation buffers for the WS3 qwen3.6 resident stage
    /// (VLLM_VULKAN_Q35_1CB): hidden/normed/attn/MoE intermediates stay in
    /// these fixed device buffers between layers AND tokens, so a layer is
    /// one (linear) or two (full-attn) fenced CBs + one un-fenced MoE CB.
    /// Q35R_* slot layout in qwen35_forward.rs. Fixed Vec, stable addresses.
    q35res_bufs: Vec<compute::Buffer>,
    q35res_ready: bool,
    /// Cached readiness verdict for the WS3 resident path (None = not yet
    /// probed; Some(false) = permanently fall back to the WS1b/WS2 path).
    q35res_ok: Option<bool>,
    /// Speculative-pipelining rollback ring (P1). Grown lazily to the requested
    /// slot; each slot's device snapshot buffers are allocated once and reused.
    /// Empty until the first `spec_snapshot`.
    spec_slots: Vec<SpecSlot>,
    /// Snapshot of all VLLM_VULKAN_* runtime flags, read once at construction
    /// (see `flags::Flags`). Removes the per-dispatch env::var storm and the
    /// load-vs-dispatch mutation hazard.
    flags: Flags,
    /// TP vocab-sharded lm_head: `Some` iff this rank's `gpu_weights[lm_name]`
    /// holds only ITS slice of the vocab (not the full table). A residency
    /// property (like `gpu_weights`), not a `Qwen35Model`/`Qwen3Model` field,
    /// since it's set/cleared by the loader's upload outcome (R5) independent
    /// of model family. `None` = replicated lm_head (today's behavior, or the
    /// TP-shard-lmhead kill switch / old-libvccl fallback).
    lm_shard: Option<LmShard>,
    /// Chunked-alloc weights (VLLM_VULKAN_MAX_ALLOC_MB, default OFF — see
    /// `flags::Flags::max_alloc_mb`): weight buffers too big for one
    /// host-coherent alloc, split on row boundaries. Disjoint keyspace from
    /// `gpu_weights` (a weight name lives in exactly one of the two maps).
    chunked_weights: std::collections::HashMap<String, ChunkedGpuWeight>,
    /// Nemotron-H-Puzzle (`nemotron_h_puzzle`) hybrid path (Mamba2 + NoPE
    /// attention + latent-MoE, single-mixer per layer). `Some` when
    /// `config.json`'s `model_type == "nemotron_h_puzzle"`. CPU-only for now
    /// (no GPU-resident streaming yet — this is the loader-validation
    /// increment; see `nemotron_loader::load_nemotron_weights`): weights are
    /// dequantized to host f32 (FP8/NVFP4 groups) or passed through (BF16)
    /// and `forward_pp_range` runs entirely on CPU, mirroring where the
    /// qwen3.6 path started before its GPU streaming was added incrementally.
    #[cfg(feature = "nemotron")]
    nemotron: Option<nemotron::NemotronModel>,
    #[cfg(not(feature = "nemotron"))]
    #[allow(dead_code)]
    nemotron: Option<()>,
    /// Phase-1 MTP acceptance sim (`VLLM_VULKAN_NEMOTRON_MTP=1`): the shipped
    /// draft head, loaded alongside `nemotron` when this rank owns the LAST
    /// layer range. `None` unless the flag is set AND this is the last PP
    /// stage of a `nemotron_h_puzzle` model. See `nemotron_mtp` module doc.
    #[cfg(feature = "nemotron")]
    nemotron_mtp_head: Option<nemotron_mtp::NemMtpHead>,
    #[cfg(not(feature = "nemotron"))]
    #[allow(dead_code)]
    nemotron_mtp_head: Option<()>,
    /// Kimi-Linear-48B-A3B (`kimi_linear`, Moonshot) hybrid path (KDA + MLA +
    /// sigmoid-router MoE). `Some` when `config.json`'s `model_type == "kimi_linear"`.
    /// CPU-only reference assembly (P4½): the 27-layer heterogeneous forward is
    /// dispatched per the `KimiConfig` schedule. Currently loads a single PP window
    /// `[0, num_hidden_layers)`; non-zero PP `layer_start` is rejected at load
    /// (the `[start,end)` window loader exists in `kimi::KimiModel::load_cpu`, but
    /// the multi-stage forward/comm wiring is the P5 cluster follow-on).
    #[cfg(feature = "kimi")]
    kimi: Option<kimi::KimiModel>,
    #[cfg(not(feature = "kimi"))]
    #[allow(dead_code)]
    kimi: Option<()>,
    /// Ling-3.0-flash (`model_type == "bailing_hybrid"`, BailingMoeV3) hybrid path
    /// (KDA + RoPE-MLA + grouped-topk INT4-sym MoE). `Some` when a `bailing_hybrid`
    /// checkpoint is loaded through `ling::LingModel::load_cpu`. CPU-reference PP
    /// window; the resident GPU decode is the cluster follow-on.
    #[cfg(feature = "ling")]
    ling: Option<ling::LingModel>,
    #[cfg(not(feature = "ling"))]
    #[allow(dead_code)]
    ling: Option<()>,
    /// Laguna-S-2.1-NVFP4 (`model_type == "laguna"`) hybrid model: YaRN/sliding
    /// attention + per-head softplus gate + NVFP4 top-10 MoE. Loaded by the
    /// `mt=="laguna"` dispatch in `new`. CPU-only for now (the pure-`cpu_matmul`
    /// reference the `laguna_cpu_stage_oracle` gate validates); the GPU-resident
    /// expert path + 48-layer + PP-8..10 is the node-count-blocked later phase.
    #[cfg(feature = "laguna")]
    laguna: Option<laguna::LagunaModel>,
    #[cfg(not(feature = "laguna"))]
    #[allow(dead_code)]
    laguna: Option<()>,
    /// GPU-resident Laguna forward (`VLLM_VULKAN_LAGUNA_RESIDENT`): the
    /// quantized-resident `[start,end)` window + GPU matvec forward
    /// (`laguna_gpu::LagunaGpuModel`, owns its own engine). Mutually exclusive
    /// with `laguna` (the CPU reference); the `mt=="laguna"` dispatch picks one.
    #[cfg(feature = "laguna")]
    laguna_gpu: Option<laguna_gpu::LagunaGpuModel>,
    #[cfg(not(feature = "laguna"))]
    #[allow(dead_code)]
    laguna_gpu: Option<()>,
    /// MTP draft head (plan §P2 GPU-dense wiring), qwen3_5 only. `Some` once
    /// `load_mtp_gpu` succeeds (auto-loaded at construction when
    /// `VLLM_VULKAN_MTP_PATH` is set, or via the explicit `load_mtp` pymethod).
    /// Holds its own KV + host f32 weights; `mtp_draft` threads the dense
    /// projections through `qwen35_matvec` when their buffers were uploaded to
    /// `gpu_weights` (same weight-name keyspace, `mtp::MV_FC`/`MV_Q`/etc — see
    /// `load_mtp_gpu`), else falls back to a CPU matvec off the head's own host
    /// copy — so engine-less (Mac) construction still drafts correctly.
    #[cfg(feature = "mtp")]
    mtp_head: Option<mtp::MtpHead>,
    #[cfg(not(feature = "mtp"))]
    #[allow(dead_code)]
    mtp_head: Option<()>,
    /// MTP head's MoE layer resident on the GPU (plan §P2 D-gate). `Some` once
    /// `load_mtp_gpu` uploads the 256 f16 experts + f32 shared expert (gated by
    /// `mtp_moe_gpu_enabled`, default ON; needs an engine). `mtp_moe_mlp_gpu`
    /// dispatches the fused per-draft MoE from it; when `None` (Mac, or the
    /// flag off) the node path falls back to the head's host-f32 rayon MoE, so
    /// both stay correct.
    #[cfg(feature = "mtp")]
    mtp_moe_gpu: Option<MtpMoeGpu>,
    #[cfg(not(feature = "mtp"))]
    #[allow(dead_code)]
    mtp_moe_gpu: Option<()>,
    /// P3 speculative-pipelining: the target's pre-`model.norm` residual hidden
    /// from the MOST RECENT last-stage forward, stashed so `mtp_draft_after` can
    /// feed it to the MTP head without a second forward. Captured only on the
    /// last stage and only while an MTP head is loaded (the readback is skipped
    /// otherwise). `None` until the first last-stage forward.
    q35_last_prenorm: Option<Vec<f32>>,
    /// P4 continuous-refill α fix: a small `position → pre-norm` ring. Each
    /// last-stage argmax pass (`forward_pp_qwen35_argmax`) records `(pos,
    /// prenorm)` so a chain refill can draft `d_1` off the EXACT producing pass's
    /// hidden rather than merely the freshest one. On a PARTIAL accept the new
    /// real token came from a MIDDLE verify pass (position `cposA+k`, not the
    /// deepest `cposA+DEPTH`), so the freshest `q35_last_prenorm` is the wrong
    /// hidden — using it collapses α_1 and makes it (wrongly) depend on chain
    /// depth. Keyed by position, read most-recent-first so a re-fed speculative
    /// position resolves to the current cycle's write; bounded to the last few
    /// positions. Empty ⇒ fall back to `q35_last_prenorm` (e.g. prefill
    /// bootstrap, whose freshest stash IS the producing hidden).
    q35_prenorm_ring: std::collections::VecDeque<(usize, Vec<f32>)>,
    /// Design-A batched-verify (MTP re-gate, spec §3): per-`LinearAttention`
    /// layer input `x` ([T,h], GLOBAL layer idx) captured by the most recent
    /// `forward_qwen35_verify_core`. `qwen35_verify_rollback_impl` re-scans the
    /// first `accept_len+1` of these through the GDN layers only (option-B
    /// rollback) — full-attn/MoE need no recompute (KV counter truncate /
    /// stateless). Cleared at the start of every verify; empty ⇒ no verify
    /// pending. GDN is the ONLY recurrent state that a partial accept must roll
    /// back (full-attn is overwrite-in-place KV, MoE/MLP are stateless).
    spec_verify_gdn_inputs: Vec<(usize, Vec<f32>)>,
    /// `(base_pos R, T)` of the most recent verify. Rollback truncates full-attn
    /// KV to `R+accept_len+1` (exposing the committed prefix's already-written
    /// K/V) and re-scans GDN over the first `accept_len+1` captured inputs.
    /// `None` ⇒ no verify pending.
    spec_verify_span: Option<(usize, usize)>,
    /// Design-A batched-verify projection swap (spec §6): while set, `qwen35_gemm`
    /// routes eligible f16/q8_0 GDN/attn projections through the single-stream
    /// `mul_mat_vec_{f16,q8_0}_cols` kernel (weight streamed ONCE for all T
    /// columns — the Phase-0-confirmed GFX1013 amortization) instead of the
    /// occupancy-starved decode-shape GEMM / T-serial matvec. Set true only
    /// around the attn/GDN mixers inside `forward_qwen35_verify_core`'s GPU path
    /// (MoE keeps its grouped MUL_MAT_ID GEMM), so it never changes prefill or
    /// decode numerics. Engine-less (Mac) never consults it.
    spec_verify_cols: bool,
    /// LMCache-NAS Step 1: content-addressed KV-cache backend (`kvstore.rs`).
    /// `None` until first use — lazily opened from `VLLM_VULKAN_KV_STORE_DIR`/
    /// `VLLM_VULKAN_KV_LRU_MB` by `kv_cache_store`/`kv_cache_load`, or
    /// explicitly via the `kv_cache_init` pymethod. `qwen3_5` only.
    kv_store: Option<kvstore::KvStore>,
}

/// One MoE layer's experts resident on the GPU in packed 4-bit form. Each of
/// gate/up/down is a single device buffer holding ALL `num_experts` experts
/// contiguously ([E*out*(in/8)] words packed; [E*out*groups] scales/biases),
/// matching `moe::QuantSwitch`'s host layout exactly. A token's routed expert
/// `e` is read by dispatching mul_mat_vec_mlx4 with packed_off = e*pack_stride
/// and sb_off = e*sb_stride.
struct MoeGpuProj {
    packed: compute::Buffer,
    scales: compute::Buffer,
    biases: compute::Buffer,
    out_features: usize,
    in_features: usize,
    group_size: usize,
    pack_stride: usize, // words per expert = out*(in/8)
    sb_stride: usize,   // scales/biases elems per expert = out*groups
}

struct MoeGpuLayer {
    gate: MoeGpuProj,
    up: MoeGpuProj,
    down: MoeGpuProj,
}

/// One MoE layer's CPU-glue weights resident on the GPU as raw f32 (WS2):
/// the dense shared-expert SwiGLU projections, the 1-row shared-expert
/// sigmoid gate, and the `[num_experts, hidden]` router gate. All are small
/// (~14 MB/layer at 35B-A3B dims: h=2048, shared_inter=512, E=256) so they
/// ride alongside the 4-bit routed experts without pressuring GTT.
struct MoeSharedGpu {
    gate: compute::Buffer,       // shared_expert.gate_proj [shared_inter, h]
    up: compute::Buffer,         // shared_expert.up_proj   [shared_inter, h]
    down: compute::Buffer,       // shared_expert.down_proj [h, shared_inter]
    expert_gate: compute::Buffer, // shared_expert_gate     [1, h]
    router: compute::Buffer,     // mlp.gate (router)       [num_experts, h]
}

/// The MTP draft head's single MoE layer, resident on the GPU (plan §P2
/// D-gate). The 256 routed experts are stored f16 — one big device buffer per
/// projection holding ALL experts contiguously ([E*out, in] row-major), so a
/// routed expert `e`'s slice is read by a `record_to_off` byte offset
/// `e * out * in * 2` with the proven f16 matvec shader (no new kernel, no
/// quantization). f16 (not 4-bit) is the right choice at head scale: the whole
/// expert set is only ~1.6 GB resident and a draft touches just the top-8
/// (~50 MB traffic ≈ 0.15-0.3 ms), so the mlx4 encoder work buys nothing here,
/// while f16 keeps the draft numerically closest to the f32 CPU parity path.
/// The dense shared expert + sigmoid gate ride along f32 (small); the router
/// gate stays a host f32 copy — the h→256 route is negligible on CPU and
/// avoids a second GPU submit + readback to select the routed offsets.
#[cfg(feature = "mtp")]
struct MtpMoeGpu {
    gate: compute::Buffer,        // switch gate_proj, f16 [E*moe_inter, h]
    up: compute::Buffer,          // switch up_proj,   f16 [E*moe_inter, h]
    down: compute::Buffer,        // switch down_proj, f16 [E*h, moe_inter]
    s_gate: compute::Buffer,      // shared_expert.gate_proj f32 [shared_inter, h]
    s_up: compute::Buffer,        // shared_expert.up_proj   f32 [shared_inter, h]
    s_down: compute::Buffer,      // shared_expert.down_proj f32 [h, shared_inter]
    s_expert_gate: compute::Buffer, // shared_expert_gate    f32 [1, h]
    router: Vec<f32>,             // mlp.gate (router) host f32 [E, h] — CPU route
}

/// One GatedDeltaNet layer's GPU-resident decode state + constants (WS1b,
/// VLLM_VULKAN_DN_GPU). `conv_state`/`state` are AUTHORITATIVE on the GPU
/// while the flag is on — they advance in place every decode step inside the
/// fused deltanet command buffer and never round-trip to the host (the CPU
/// `DeltaNetState` copy goes stale; `reset_kv_cache` zeroes the GPU buffers
/// alongside it). The small per-layer constants (conv weight; A_log | dt_bias
/// | norm.weight packed into `params`) are uploaded once, lazily, on the
/// layer's first deltanet forward.
struct DnGpuLayer {
    conv_w: compute::Buffer,     // conv1d.weight [conv_dim, kern] f32
    params: compute::Buffer,     // [A_log(nv) | dt_bias(nv) | norm.weight(vd)] f32
    conv_state: compute::Buffer, // sliding conv window [conv_dim, kern-1] f32
    state: compute::Buffer,      // delta-rule state [nv, kd, vd] f32
}

/// Speculative-pipelining rollback depth (P1): a fixed ring of snapshot slots,
/// one per in-flight draft depth. Slot indices `0..SPEC_RING_DEPTH` are the
/// documented API; the ring is grown lazily to whatever the caller asks for.
const SPEC_RING_DEPTH: usize = 4;

/// One slot of the speculative-rollback ring (P1): a bit-exact snapshot of ALL
/// per-token mutable decode state on this PP stage, taken between decode steps.
///
/// - `dn_gpu`: device-side copies of every `DN_GPU`-authoritative GatedDeltaNet
///   layer's `conv_state` + delta `state` buffers (keyed by GLOBAL layer idx).
///   Preallocated host-coherent buffers, reused across snapshots into this slot;
///   populated by a single fenced `vkCmdCopyBuffer` batch (device→device, no
///   host round-trip). Empty on the engine-less / `DN_GPU`-off path.
/// - `host`: the KV `seq_len` counters (always host) + any CPU-path DeltaNet
///   state (see `qwen35::HostStateSnapshot`).
///
/// The transient Q35R_* activation buffers are NOT snapshotted: they are fully
/// overwritten every layer within a token, so they carry no cross-token state.
#[derive(Default)]
struct SpecSlot {
    dn_gpu: std::collections::HashMap<usize, (compute::Buffer, compute::Buffer)>,
    host: host_state::HostStateSnapshot,
    valid: bool,
}

/// A GPU-resident weight buffer paired with the `QuantFormat` it was quantized
/// into at load time. Storing the format alongside the buffer (instead of
/// relying solely on the global `flags.quant` snapshot at dispatch) decouples
/// kernel selection from the environment: the buffer's own bytes always match
/// the format recorded here, regardless of what the process-wide flag reads.
struct GpuWeight {
    buffer: compute::Buffer,
    // Recorded at load time for every buffer (closing the mutate-mid-process
    // hazard structurally); dispatch still reads the uniform process-wide
    // `flags.quant` snapshot (matvec format is uniform across gpu_weights
    // today — see M4 in IMPROVEMENTS.md). Threading this into every
    // `matvec_variant` call site is future work once formats diverge per
    // buffer.
    #[allow(dead_code)]
    format: QuantFormat,
    // Format-specific second GPU buffer(s). `Some` iff the format is packed
    // (Nvfp4 in V1/V2; Fp8 added in V2 Item 2); the dispatch branch keys off
    // this Option/variant. `None` for f16/q8/etc.
    aux: Option<QuantAux>,
}

/// Recover a loaded matvec weight's `out_features` (row count) from its GPU
/// buffer byte size, given the contraction dim `in_features`. Format-aware
/// because bytes-per-element differ: FP8 = 1 raw byte, NVFP4 = 2 nibbles/byte,
/// F16/Bf16 = 2 bytes, Q8_0 = 34 bytes per 32-elem block. Used by the
/// `debug_gemma_kv_dims` probe to read the ACTUAL k_proj rows (attn is FP8 on
/// the g31b checkpoint), independent of the config the forward believes.
fn gpu_weight_out_features(w: &GpuWeight, in_features: usize) -> usize {
    if in_features == 0 { return 0; }
    let bytes = w.buffer.size as usize;
    match w.format {
        QuantFormat::Fp8 => bytes / in_features,
        QuantFormat::Nvfp4 => (bytes * 2) / in_features,
        QuantFormat::F16 | QuantFormat::Bf16 => bytes / (2 * in_features),
        QuantFormat::Q8_0 => (bytes * 32) / (34 * in_features),
        _ => bytes / in_features, // F32 fallthrough (4 bytes → caller rarely hits)
    }
}

/// TP vocab-sharded lm_head residency metadata (see `tp.rs::tp_vocab_shard_range`
/// and the plan's §2.2/§2.5). Set by the loader when this rank's lm_head slice
/// uploaded successfully under TP; cleared (R5) if the upload fails, so the
/// forward falls back to the replicated f16-host tail instead of gathering
/// garbage from a partial GPU buffer. `lo`/`per` are this rank's contiguous
/// vocab-row range; `v` is the FULL (unsharded) vocab size, needed by every
/// rank to recompute every OTHER rank's range for the allgather merge.
#[derive(Clone, Copy, Debug)]
pub(crate) struct LmShard {
    pub lo: usize,
    pub per: usize,
    pub v: usize,
}

/// A GPU weight buffer too big for one alloc (plan §5, P2 chunked-alloc
/// mitigation), split on row boundaries into several host-coherent buffers.
/// Dispatched as N `record_to_off` calls into the SAME command buffer,
/// writing into contiguous row ranges of one output buffer — one submit/
/// fence regardless of chunk count. Row-major `[out_features, in_features]`
/// weights only (row = one output neuron, so a row boundary is always a
/// clean split point for both plain and q8_0-block formats since `h%32==0`
/// is asserted at quantize time). NOT wired into the resident WS3 1-CB path
/// (`q35r_meta`/`q35r_rec_mv`) — v1 scope excludes it per the plan (R4:
/// protect the PP flagship); `ensure_q35res`'s probe must treat a chunked
/// lm_head as resident-unavailable and fall back to the per-block path.
pub(crate) struct ChunkedGpuWeight {
    pub buffers: Vec<compute::Buffer>,
    /// Row count owned by each buffer in `buffers` (same length, sums to the
    /// weight's total out_features).
    pub rows: Vec<usize>,
    pub format: QuantFormat,
}

/// Format-specific residency metadata for a packed GPU weight.
enum QuantAux {
    /// NVFP4: `GpuWeight.buffer` holds the u8 nibbles. Two scale residencies:
    /// * `e4m3 == false` (default, f32-fold): `scales` holds
    ///   `nvfp4_fold_scales(...)` = e4m3*global f32, one per (row,group), and
    ///   `global` is unused (1.0). Dispatches `mul_mat_vec_nvfp4_f32_f32`.
    /// * `e4m3 == true` (VLLM_VULKAN_NVFP4_E4M3_SCALES): `scales` holds the RAW
    ///   per-group e4m3 block-scale BYTES (1 byte/(row,group), 4x smaller) and
    ///   `global` is the per-tensor `.weight_scale_2`. Dispatches the
    ///   `mul_mat_vec_nvfp4_e4m3_f32_f32` kernel, which decodes e4m3 + applies
    ///   `global` in-loop (bit-exact vs the fold path). The ≥150B footprint
    ///   lever (6.0 → 4.5 bits/param).
    Nvfp4 { scales: compute::Buffer, group_size: u32, e4m3: bool, global: f32 },
    /// FP8-E4M3: `GpuWeight.buffer` = raw FP8 bytes; `scale` = f32 (1 elem
    /// per-tensor, or out_features per-row -> `per_row`).
    Fp8 { scale: compute::Buffer, per_row: bool },
    /// MLX4-affine 4-bit DENSE: `GpuWeight.buffer` holds the packed u32
    /// nibbles; `scales`/`biases` are the raw per-(row,group) f32 arrays (no
    /// folding — the mlx4 shader reads both, unlike NVFP4's single folded
    /// scale).
    Mlx4 { scales: compute::Buffer, biases: compute::Buffer, group_size: u32 },
}

/// Copy metadata describing which matvec kernel + aux buffer(s) a `GpuWeight`
/// dispatches to. Gathered as raw pointers (Copy) BEFORE `engine.as_mut()` so
/// the immutable borrow of `self.gpu_weights` ends before the mutable borrow
/// of `self.engine` begins (see `qwen35_matvec`/`qwen35_matvec_multi`).
#[derive(Clone, Copy)]
enum MvKind {
    Plain,
    Nvfp4 { s: *const compute::Buffer, gs: u32, e4m3: bool, global: f32 },
    Fp8 { s: *const compute::Buffer, per_row: bool },
    Mlx4 { s: *const compute::Buffer, b: *const compute::Buffer, gs: u32 },
}

/// Cross-stage KV-share "target" layers for `forward_pp_gemma`/
/// `pp_gemma_msg_len`: the last sliding layer and the last global layer
/// BEFORE `cfg.first_kv_shared_layer()`, sorted ascending (≤2 entries).
/// Returns empty when the model has no kv-shared layers at all
/// (`num_kv_shared_layers == 0`, e.g. g12b) — there `first_kv_shared_layer()`
/// == `num_hidden_layers`, so there is nothing to share cross-stage and the
/// tkv payload must be empty, not "whatever the last two layers happen to
/// be" (that was the source of the 4096-vs-512 panic on g12b PP=2: g12b's
/// last global layer uses MQA head_dim 512, and the old code both included
/// it as a bogus target AND sized it with a fixed `num_key_value_heads`
/// instead of the per-layer count).
fn gemma_pp_kv_targets(cfg: &model::Gemma4Config) -> Vec<usize> {
    let first_kv = cfg.first_kv_shared_layer();
    if first_kv >= cfg.num_hidden_layers {
        return Vec::new();
    }
    let (mut last_slide, mut last_full) = (None, None);
    for i in 0..first_kv {
        if cfg.is_full_attention(i) { last_full = Some(i); } else { last_slide = Some(i); }
    }
    let mut targets: Vec<usize> = Vec::new();
    if let Some(s) = last_slide { targets.push(s); }
    if let Some(f) = last_full { targets.push(f); }
    targets.sort_unstable();
    targets
}

/// Per-target-layer K/V length (`layer_num_kv_heads(t) * layer_head_dim(t)`),
/// one per entry of `gemma_pp_kv_targets`. Per-layer (not a fixed
/// `num_key_value_heads`) because global/MQA layers may use a different
/// kv-head count than sliding layers.
fn gemma_pp_tkv_lens(cfg: &model::Gemma4Config, targets: &[usize]) -> Vec<usize> {
    targets.iter().map(|&t| cfg.layer_num_kv_heads(t) * cfg.layer_head_dim(t)).collect()
}

/// Strict GPU lm_head/embed upload policy (default ON).
///
/// When a last-stage lm_head (or tied-embed) GPU upload is ATTEMPTED and FAILS
/// (alloc failure, VLLM_VULKAN_MAX_ALLOC_MB overflow, GTT exhaustion, …) the
/// legacy behaviour was to `warn!` and continue — which silently degrades decode
/// to the naive single-thread f16 HOST matmul over the full vocab
/// (~151936 qwen / ~262144 gemma / 163840 kimi rows), a hundreds-of-ms/token
/// "mystery slowdown" that reads as a perf regression, not a load error.
///
/// With strict ON, such an upload FAILURE is promoted to a hard load-time error
/// so the mis-load surfaces at load rather than as decode latency. Set
/// `VLLM_VULKAN_STRICT_GPU_LMHEAD=0` to restore the warn-and-continue host
/// fallback for the rare intended-host-lm_head config.
///
/// IMPORTANT: this governs only upload *failures*. A BY-DESIGN skip (e.g. the
/// g31b loader deliberately not uploading a non-f16 global-quant lm_head, which
/// is a legitimate CPU-fallback config) must NOT route through here.
fn strict_gpu_lmhead() -> bool {
    std::env::var("VLLM_VULKAN_STRICT_GPU_LMHEAD")
        .map(|v| v != "0")
        .unwrap_or(true)
}

/// Phase A2 carve helper: the empty `inner` placeholder that non-gemma model
/// arms stow in the `inner` field. With `gemma` on it is a real (empty)
/// `Gemma4Model`; with `gemma` off the `inner` field is `()`, so this returns
/// `()` and the same `inner: placeholder` construction compiles in both
/// configurations. The value is never read on a non-gemma path.
#[cfg(feature = "gemma")]
#[inline]
fn carve_placeholder_inner() -> model::Gemma4Model {
    model::Gemma4Model {
        config: model::Gemma4Config::e2b(),
        weights: model::ModelWeights { tensors: std::collections::HashMap::new() },
        kv_caches: Vec::new(),
    }
}
#[cfg(not(feature = "gemma"))]
#[inline]
fn carve_placeholder_inner() {}

#[pymethods]
impl VulkanModel {
    /// Load a Gemma4-E2B model from a safetensors file.
    ///
    /// `safetensors_path`: path to the model.safetensors file.
    /// `max_seq_len`: maximum context length (default 512).
    /// `device_idx`: Vulkan device index (default 0 = first discrete/integrated GPU).
    #[new]
    #[pyo3(signature = (safetensors_path, max_seq_len = 512, device_idx = 0, layer_start = None, layer_end = None))]
    fn new(safetensors_path: &str, max_seq_len: usize, device_idx: usize,
           layer_start: Option<usize>, layer_end: Option<usize>) -> PyResult<Self> {
        use std::path::Path;
        use std::collections::HashMap;

        let path = Path::new(safetensors_path);

        // Detect the architecture from config.json sitting next to the weights.
        let config_path = path
            .parent()
            .unwrap_or_else(|| Path::new("."))
            .join("config.json");

        // ── Qwen3.6 (qwen3_5) hybrid path ────────────────────────────────────
        // Detect by model_type and take the dedicated GatedDeltaNet +
        // GatedAttention model. Phase 1: CPU forward (engine left None). Full
        // real-27B (~108GB f32) needs PP across the cluster (Phase 3) to fit;
        // single-node works for tiny models or a layer-limited load.
        if let Ok(cfg_text) = std::fs::read_to_string(&config_path) {
            if let Ok(cfg_json) = serde_json::from_str::<serde_json::Value>(&cfg_text) {
                let mt = cfg_json.get("model_type")
                    .or_else(|| cfg_json.get("text_config").and_then(|t| t.get("model_type")))
                    .and_then(|v| v.as_str()).unwrap_or("");
                // ── Step-3.7-Flash-148B path (model_type == "step3p7") ──────────
                // REAP-pruned (212/288 experts) sigmoid-router MoE reusing ~85% of
                // the qwen3_5 MoE stack. CPU-only reference forward for now (the
                // same pure `cpu_matmul`/`cpu_sdpa` reference the assembled-forward
                // gate validates): `step3p7::load_step3p7_weights_cpu` reads the
                // checkpoint's `model.safetensors.index.json` (whatever shard layout
                // is present — no count assumption), dequantizes BF16→f32 for the
                // attn/norm/dense/router/shared/embed/lm tensors and keeps the
                // routed experts PACKED (3D-stacked NVFP4 nibbles + F8_E4M3 group-16
                // scales + F32 per-expert modelopt global) for top-8 dequant-on-
                // demand. The 3 MTP heads (checkpoint layers 45-47) are dropped via
                // `num_hidden_layers == 45`. GPU-resident experts + full 45-layer +
                // TP-2×PP-5 @ 10 nodes is the node-count-blocked later phase.
                #[cfg(feature = "step3p7")]
                if mt == "step3p7" {
                    let cfg = step3p7::Step3p7Config::from_json(&cfg_json)
                        .map_err(PyRuntimeError::new_err)?;
                    let total_layers = cfg.num_hidden_layers;
                    let s3_start = layer_start.unwrap_or(0);
                    let s3_end = layer_end.unwrap_or(total_layers).min(total_layers);
                    let s3_first = s3_start == 0;
                    let s3_last = s3_end >= total_layers;
                    if s3_start >= s3_end || s3_end > total_layers {
                        return Err(PyRuntimeError::new_err(format!(
                            "step3p7: bad PP window [{s3_start},{s3_end}) for {total_layers} layers")));
                    }
                    // TRUE [s3_start, s3_end) PP window: the loader materializes only
                    // this stage's layers (embed on the first stage, lm_head on the
                    // last) and, with the overflow-stream harness
                    // (VLLM_VULKAN_MOE_STREAM_OVERFLOW), bounds each stage's expert
                    // DRAM to a budget — so PP-6 fits + runs on today's 5-6 nodes,
                    // decoupled from the N>=10 cluster (fit-to-validate).
                    let dir = path.parent().unwrap_or_else(|| Path::new("."));
                    log::info!(
                        "Loading Step-3.7-Flash-148B: layers [0,{s3_end}) of {total_layers}, \
                         hidden {}, {} experts top-{} (first={s3_first} last={s3_last}) from {}",
                        cfg.hidden_size, cfg.num_experts, cfg.num_experts_per_tok,
                        safetensors_path);
                    // GPU-resident decode (Phase 1-2) when VLLM_VULKAN_STEP3P7_GPU_RESIDENT=1
                    // (default OFF — the CPU reference path stays the byte-identical
                    // default). Resident mode uploads experts (NVFP4) + attn/dense/shared
                    // (f16) to device with per-layer stream-upload-then-free and runs the
                    // stateful GPU decode; TP-2 sharding engages when VLLM_VULKAN_TP_SIZE>1.
                    let s3_gpu_resident = std::env::var("VLLM_VULKAN_STEP3P7_GPU_RESIDENT")
                        .map(|v| v != "0" && v != "false")
                        .unwrap_or(false);
                    let s3_tp_size = std::env::var("VLLM_VULKAN_TP_SIZE").ok()
                        .and_then(|v| v.parse::<usize>().ok()).unwrap_or(1).max(1);
                    let s3_tp_rank = std::env::var("VLLM_VULKAN_TP_RANK").ok()
                        .and_then(|v| v.parse::<usize>().ok()).unwrap_or(0).min(s3_tp_size - 1);
                    let s3_model = if s3_gpu_resident {
                        step3p7::Step3p7Model::load_gpu_resident(
                            dir, cfg, s3_start, s3_end, s3_last, device_idx,
                        ).map_err(|e| PyRuntimeError::new_err(
                            format!("step3p7 GPU-resident loader failed: {e}")))?
                    } else {
                        step3p7::Step3p7Model::load_cpu(
                            dir, cfg, s3_start, s3_end, s3_last,
                        ).map_err(|e| PyRuntimeError::new_err(
                            format!("step3p7 loader failed: {e}")))?
                    };
                    log::info!(
                        "Step-3.7-Flash-148B: window [{s3_start},{s3_end}) loaded ({}; TP {s3_tp_rank}/{s3_tp_size})",
                        if s3_gpu_resident { "GPU-resident decode" } else { "CPU reference" });
                    let inner = carve_placeholder_inner();
                    return Ok(VulkanModel {
                        inner,
                        qwen: None,
                        qwen35: None,
                        step3p7: Some(s3_model),
                        max_seq_len,
                        engine: None,
                        gpu_weights: HashMap::new(),
                        act_bufs: Vec::new(),
                        act_bufs_ready: false,
                        pp_start: s3_start,
                        pp_end: s3_end,
                        pp_first: s3_first,
                        pp_last: s3_last,
                        tp_rank: s3_tp_rank,
                        tp_size: s3_tp_size,
                        gemma_ple_bf16: None,
                        gpu_kv: HashMap::new(),
                        qres_bufs: Vec::new(),
                        qres_ready: false,
                        gres_bufs: Vec::new(),
                        gres_ready: false,
                        gemma_norm_w: HashMap::new(),
                        gpu_norm_w: HashMap::new(),
                        ures_bufs: Vec::new(),
                        ures_ready: false,
                        unified_norm_w: HashMap::new(),
                        bres_bufs: Vec::new(),
                        bres_ready: false,
                        q35_f16_host: HashMap::new(),
                        collective_comm: 0,
                        reduce_scratch: Vec::new(),
                        reduce_scratch_handle: 0,
                        moe_gpu: std::collections::HashMap::new(),
                        moe_shared_gpu: std::collections::HashMap::new(),
                        dn_gpu: std::collections::HashMap::new(),
                        q35res_bufs: Vec::new(),
                        q35res_ready: false,
                        q35res_ok: None,
                        spec_slots: Vec::new(),
                        flags: Flags::from_env(),
                        lm_shard: None,
                        chunked_weights: std::collections::HashMap::new(),
                        gemma_kv_filled: 0,
                        pp_tok_ring: PpTokRing::default(),
                        pp_hop_send: PpTokRing::default(),
                        pp_hop_recv: PpTokRing::default(),
                        pp_vocab_ring: PpTokRing::default(),
                        gemma_hidden_ring: std::collections::VecDeque::new(),
                        gemma_pp_hop: Default::default(),
                        nemotron: None,
                        nemotron_mtp_head: None,
                        kimi: None,
                        ling: None,
                        laguna: None,
                        laguna_gpu: None,
                        mtp_head: None,
                        mtp_moe_gpu: None,
                        q35_last_prenorm: None,
                        q35_prenorm_ring: std::collections::VecDeque::new(),
                        spec_verify_gdn_inputs: Vec::new(),
                        spec_verify_span: None,
                        spec_verify_cols: false,
                        kv_store: None,
                    });
                }
                // `qwen3_5` (dense 27B) + `qwen3_5_moe` (35B-A3B) share this path;
                // is_moe() (num_experts>0) selects the MoE MLP per layer.
                #[cfg(feature = "qwen35")]
                if mt == "qwen3_5" || mt == "qwen3_5_moe" {
                    let cfg = qwen35::Qwen35Config::from_json(&cfg_json)
                        .map_err(PyRuntimeError::new_err)?;
                    // `cfg.num_hidden_layers` / `cfg.layer_types` stay the FULL
                    // GLOBAL model (never truncated): a PP stage must index
                    // `layer_types[global_idx]` for its resident range. The
                    // resident layer window is `[q35_start, q35_end)`:
                    //   - single-node full:      [0, num_hidden_layers)
                    //   - single-node truncated: [0, layer_end)   (B3 parity)
                    //   - PP stage s:             [layer_start, layer_end)
                    let total_layers = cfg.num_hidden_layers;
                    let q35_start = layer_start.unwrap_or(0);
                    let q35_end = layer_end.unwrap_or(total_layers).min(total_layers);
                    let q35_first = q35_start == 0;
                    let q35_last = q35_end >= total_layers;
                    // Tied embeddings: the last stage's lm_head IS embed_tokens, so a
                    // non-first last stage must still load the embed table. When a
                    // separate lm_head.weight exists (untied) the last stage gets it
                    // via keep_lm and the embed table stays first-stage-only.
                    let tied = cfg.tie_word_embeddings;
                    // P3: an UNTIED last stage (rank4) normally drops embed_tokens
                    // (it carries only lm_head), but the MTP draft head needs the
                    // embedding row of the last-emitted token. When MTP is
                    // requested (env auto-load), keep the embed f16 host table on
                    // the last stage so `mtp_draft_after` can index it on-node.
                    let mtp_requested = std::env::var("VLLM_VULKAN_MTP_PATH").is_ok();
                    let keep_embed = q35_first || (q35_last && (tied || mtp_requested));
                    let q = cfg_json.get("quantization").or_else(|| {
                        cfg_json.get("text_config").and_then(|t| t.get("quantization"))
                    });
                    let group_size = q.and_then(|q| q["group_size"].as_u64()).unwrap_or(64) as usize;
                    let bits = q.and_then(|q| q["bits"].as_u64()).unwrap_or(4) as usize;
                    log::info!("Loading Qwen3.6 (qwen3_5): layers [{q35_start},{q35_end}) of {total_layers}, hidden {}, MoE={} (first={q35_first} last={q35_last}) from {}",
                        cfg.hidden_size, cfg.is_moe(), safetensors_path);
                    // Split loader: embed_tokens + lm_head come back as f16 (their
                    // ~5GB-each f32 dequant is downcast and freed inside the loader,
                    // capping the load-time peak on a 14GB node); everything else
                    // (projections + conv/norm/etc.) is f32. PP: only the resident
                    // layer range loads; embed kept only on the first stage, lm_head
                    // + final norm only on the last.
                    // ── Phase 2/3: GPU engine + STREAMING projection upload ──
                    // The 27B-4bit dequantizes 4-bit -> f32 -> f16. Accumulating
                    // every projection as f32 (the old path) peaks at the WHOLE
                    // stage's f32 (~tens of GB) and OOMs a 14GB node even for a
                    // 1/4 layer slice. So we create the engine FIRST and stream:
                    // the loader hands each dequantized projection to a closure
                    // that uploads it f16 to the GPU and drops the f32 immediately,
                    // capping host f32 peak at ONE tensor. CPU-only mode (no
                    // engine) keeps the f32 (the closure hands it back).
                    // Single env snapshot for this construction; reused for both
                    // the load-time decisions below and the stored `flags` field.
                    let flags = Flags::from_env();
                    // A packed-GPU-residency request (NVFP4_GPU=1) implies wanting
                    // the engine: qwen3_5 is the only model branch that flag-gates
                    // engine creation, and running the NVFP4 recipe without
                    // QWEN35_GPU=1 silently declined every packed upload and
                    // retained the full f32 dequant on the host (~1.5GB/layer,
                    // 4B/weight) — the 27B-NVFP4 PP load-OOM root cause.
                    let want_gpu = flags.qwen35_gpu || flags.nvfp4_gpu;
                    let mut gpu_weights: HashMap<String, GpuWeight> = HashMap::new();
                    let mut chunked_weights: HashMap<String, ChunkedGpuWeight> = HashMap::new();
                    let mut engine_opt: Option<compute::ComputeEngine> = if want_gpu {
                        match device::ComputeDevice::create(device_idx) {
                            Ok(dev) => {
                                let shader_spvs = include_all_shaders();
                                let refs: HashMap<&str, &[u8]> = shader_spvs.iter()
                                    .map(|(k, v)| (k.as_str(), v.as_slice())).collect();
                                match compute::ComputeEngine::new(
                                    dev.instance.clone(),
                                    dev.physical_device,
                                    dev.device.clone(),
                                    dev.compute_queue,
                                    dev.compute_queue_family,
                                    dev.caps(),
                                    &refs,
                                ) {
                                    Ok(engine) => Some(engine),
                                    Err(e) => {
                                        // eprintln (not log::warn) on purpose: the box runs
                                        // with no logger, and a silent CPU fallback here
                                        // f32-retains every projection (~1.5GB/layer) and
                                        // OOMs PP stages — must be visible.
                                        eprintln!("qwen3_5: compute engine FAILED ({e}); CPU-only \
                                                   fallback retains host f32 projections (~4B/weight)");
                                        None
                                    }
                                }
                            }
                            Err(e) => {
                                eprintln!("qwen3_5: no Vulkan device {device_idx} ({e}); CPU-only \
                                           fallback retains host f32 projections (~4B/weight)");
                                None
                            }
                        }
                    } else {
                        if flags.nvfp4_gpu || flags.qwen35_resident {
                            eprintln!("qwen3_5: NO GPU ENGINE (VLLM_VULKAN_QWEN35_GPU unset) but \
                                       GPU-residency flags set — projections stay HOST F32 \
                                       (~4B/weight, ~1.5GB/layer); expect load OOM on PP stages");
                        }
                        None
                    };
                    // device-weights: stage to device-local VRAM (low-RAM nodes);
                    // else host-coherent (GPU-visible system RAM).
                    let dw_q35 = std::env::var("VLLM_VULKAN_DEVICE_WEIGHTS")
                        .map(|v| v == "1" || v.eq_ignore_ascii_case("true")).unwrap_or(false);
                    // q8_0 quantized-resident weights (VLLM_VULKAN_QUANT=q8_0):
                    // ~half the bytes of f16, which is what makes the 27B fit the
                    // 4-node cluster (f16 = 54GB total > 40GB VRAM; q8 = 27GB). The
                    // matvec dispatch picks the q8 dequant kernel via matvec_variant
                    // (same global VLLM_VULKAN_QUANT). lm_head is quantized too so
                    // EVERY gpu_weights buffer is q8 (uniform dispatch). Validated
                    // arch-agnostic (q8 cos>0.999 vs f16) in prior milestones.
                    let quant_q8_q35 = flags.quant == QuantFormat::Q8_0;
                    // lean: in GPU mode DROP the f32 host copy of each projection
                    // (default on when an engine exists). Override LEAN_HOST=0.
                    let lean_q35 = std::env::var("VLLM_VULKAN_LEAN_HOST")
                        .map(|v| v == "1" || v.eq_ignore_ascii_case("true"))
                        .unwrap_or(engine_opt.is_some());

                    let mut gpu_bytes_total = 0u64;
                    let mut host_bytes = 0u64;
                    // Helper: raw weight bytes (f16 or q8_0) -> GPU buffer
                    // (device-local VRAM via staged copy, or host-coherent UMA RAM).
                    fn q35_upload_bytes(eng: &mut compute::ComputeEngine, bytes: &[u8], dw: bool) -> Result<compute::Buffer, String> {
                        if dw {
                            match eng.alloc_device(bytes.len() as u64) {
                                Ok(buf) => eng.upload(&buf, bytes).map(|_| buf),
                                Err(e) => Err(e),
                            }
                        } else {
                            eng.alloc_host_coherent_storage(bytes.len() as u64).map(|buf| {
                                unsafe {
                                    std::ptr::copy_nonoverlapping(
                                        bytes.as_ptr(), buf.mapped_ptr.unwrap() as *mut u8, bytes.len());
                                }
                                // Pin the weight pages. On the UMA APU a host-coherent
                                // GPU-visible buffer is ordinary (swappable) system RAM.
                                // At the memory-pressure edge this fleet runs at (a q8
                                // 27B TP shard on a 16 GB node, heavy zswap), an unpinned
                                // weight page can be reclaimed/compressed and then read
                                // back CORRUPT through the GPU's GART view — a SILENT,
                                // per-load weight corruption (no alloc/upload error, so
                                // the b5c89eb CPU-fallback never fires) that flips greedy
                                // TP decode into a degenerate punctuation attractor
                                // (root cause of the 2026-07 TP-4 nondeterminism: clean
                                // 8/8 at ~11 GB free, intermittent under co-tenant
                                // pressure). mlock keeps the pages resident so the GPU
                                // and CPU always agree. Best-effort: on failure (memlock
                                // rlimit — vrun already raises it to unlimited) we only
                                // warn; correctness is unchanged, the risk simply returns.
                                #[cfg(unix)]
                                if let Some(ptr) = buf.mapped_ptr {
                                    let rc = unsafe {
                                        libc::mlock(ptr as *const libc::c_void, bytes.len())
                                    };
                                    if rc != 0 {
                                        log::warn!(
                                            "mlock of {}-byte host-coherent weight failed \
                                             ({}); weight pages remain swappable — silent \
                                             GTT-corruption risk under memory pressure",
                                            bytes.len(), std::io::Error::last_os_error());
                                    }
                                }
                                buf
                            })
                        }
                    }

                    // ── Tensor parallelism (Megatron) ───────────────────────
                    // VLLM_VULKAN_TP_SIZE / _RANK: shard each projection (and the
                    // GatedDeltaNet recurrence host weights conv1d/A_log/dt_bias)
                    // by this rank's head slice BEFORE f16/quant/upload, so every
                    // GPU buffer is already 1/N and forward_tp_qwen35's matvec dims
                    // line up. embed/lm_head/norms/layernorms are replicated.
                    let q35_tp_size = std::env::var("VLLM_VULKAN_TP_SIZE").ok()
                        .and_then(|v| v.parse::<usize>().ok()).unwrap_or(1).max(1);
                    let q35_tp_rank = std::env::var("VLLM_VULKAN_TP_RANK").ok()
                        .and_then(|v| v.parse::<usize>().ok()).unwrap_or(0).min(q35_tp_size - 1);
                    if q35_tp_size > 1 {
                        // Validate divisibility up front (TP=4 divides 27B cleanly).
                        for (label, val) in [
                            ("num_attention_heads", cfg.num_attention_heads),
                            ("num_key_value_heads", cfg.num_key_value_heads),
                            ("linear_num_key_heads", cfg.linear_num_key_heads),
                            ("linear_num_value_heads", cfg.linear_num_value_heads),
                            ("intermediate_size", cfg.intermediate_size.max(1)),
                        ] {
                            if val % q35_tp_size != 0 {
                                return Err(PyRuntimeError::new_err(format!(
                                    "qwen3_5 TP: {label}={val} not divisible by tp_size={q35_tp_size} \
                                     (use tp_size that divides all head counts; 4 works for 27B)")));
                            }
                        }
                        log::info!("qwen3_5 TP: rank {q35_tp_rank}/{q35_tp_size} \
                                    (col-shard q/k/v/gate/up/in_proj_*, row-shard o/down/out_proj)");
                    }
                    let tp_cfg = cfg.clone();

                    // NVFP4-GPU packed residency now supports TP (V2): packed
                    // row/col shard respects nibble+group boundaries; FP8 attn
                    // shards by plain bytes. Single flag gates both mlp+attn.
                    let nvfp4_gpu = flags.nvfp4_gpu;
                    // ≥150B footprint lever: keep the e4m3 block scale resident
                    // (1 byte) + global uniform instead of the f32 fold (see the
                    // field doc). Only consulted when nvfp4_gpu is already on.
                    let nvfp4_e4m3 = flags.nvfp4_e4m3_scales;

                    // Streaming sink: called per projection weight DURING load.
                    // GPU mode -> upload f16/q8 (or packed NVFP4), drop f32/packed
                    // (return Consumed). Keep f32 when not lean (CPU ref /
                    // debugging): hand it back (KeepF32).
                    let mut host_tensors: HashMap<String, model::SimpleTensor> = HashMap::new();
                    let on_proj = |name: &str, w: model::ProjWeight| -> model::ProjResult {
                        match w {
                            model::ProjWeight::Nvfp4(nv) => {
                                if !nvfp4_gpu { return model::ProjResult::Dequantize; }
                                let eng = match engine_opt.as_mut() {
                                    Some(e) => e, None => return model::ProjResult::Dequantize };
                                // Two scale residencies (see QuantAux::Nvfp4):
                                //  * e4m3-resident (VLLM_VULKAN_NVFP4_E4M3_SCALES):
                                //    TP-shard the RAW e4m3 block-scale bytes
                                //    (1 byte/(row,group)) + stash the per-tensor
                                //    f32 global; the shader re-adds decode+global.
                                //  * f32-fold (default): fold e4m3*global → one
                                //    f32/(row,group), upload that.
                                // The generic `nvfp4_tp_shard` slices either scale
                                // element type identically (packed geometry same).
                                let (packed, sbytes, global) = if nvfp4_e4m3 {
                                    let (packed, scale8, _o, _i) = nvfp4_tp_shard(
                                        name, nv.packed, nv.wscale,
                                        nv.out_features, nv.in_features, nv.group_size,
                                        &tp_cfg, q35_tp_rank, q35_tp_size);
                                    (packed, scale8, nv.global)
                                } else {
                                    let folded = nvfp4_fold_scales(nv.wscale, nv.global);
                                    let (packed, scales, _o, _i) = nvfp4_tp_shard(
                                        name, nv.packed, &folded,
                                        nv.out_features, nv.in_features, nv.group_size,
                                        &tp_cfg, q35_tp_rank, q35_tp_size);
                                    (packed, f32_slice_to_bytes(&scales), 1.0f32)
                                };
                                let pbuf = match q35_upload_bytes(eng, &packed, dw_q35) {
                                    Ok(b) => b,
                                    Err(e) => { log::warn!("nvfp4 packed upload '{name}': {e}");
                                                return model::ProjResult::Dequantize; } };
                                let sbuf = match q35_upload_bytes(eng, &sbytes, dw_q35) {
                                    Ok(b) => b,
                                    Err(e) => { log::warn!("nvfp4 scale upload '{name}': {e}");
                                                return model::ProjResult::Dequantize; } };
                                gpu_bytes_total += (packed.len() + sbytes.len()) as u64;
                                gpu_weights.insert(name.to_string(), GpuWeight {
                                    buffer: pbuf, format: QuantFormat::Nvfp4,
                                    aux: Some(QuantAux::Nvfp4 { scales: sbuf,
                                        group_size: nv.group_size as u32,
                                        e4m3: nvfp4_e4m3, global }),
                                });
                                model::ProjResult::Consumed
                            }
                            model::ProjWeight::Fp8(fp) => {
                                if !nvfp4_gpu { return model::ProjResult::Dequantize; }
                                // Per-row FP8 scale under TP row-shard would need
                                // per-rank scale slicing — not present in this
                                // checkpoint (modelopt FP8 is per-tensor); decline.
                                if q35_tp_size > 1 && fp.scale.len() > 1 {
                                    return model::ProjResult::Dequantize;
                                }
                                let eng = match engine_opt.as_mut() {
                                    Some(e) => e, None => return model::ProjResult::Dequantize };
                                // TP: byte-slice the weight via the generic sharder
                                // (1 byte/elem == an element array). Per-tensor scalar
                                // scale is TP-invariant (factors out of the partial sum).
                                let wbytes = q35_tp_shard::<u8>(
                                    name, fp.weight.to_vec(), &tp_cfg, q35_tp_rank, q35_tp_size);
                                let sbytes = f32_slice_to_bytes(&fp.scale);
                                let per_row = fp.scale.len() > 1;
                                let wbuf = match q35_upload_bytes(eng, &wbytes, dw_q35) {
                                    Ok(b) => b,
                                    Err(e) => { log::warn!("fp8 weight upload '{name}': {e}");
                                                return model::ProjResult::Dequantize; } };
                                let sbuf = match q35_upload_bytes(eng, &sbytes, dw_q35) {
                                    Ok(b) => b,
                                    Err(e) => { log::warn!("fp8 scale upload '{name}': {e}");
                                                return model::ProjResult::Dequantize; } };
                                gpu_bytes_total += (wbytes.len() + sbytes.len()) as u64;
                                gpu_weights.insert(name.to_string(), GpuWeight {
                                    buffer: wbuf, format: QuantFormat::Fp8,
                                    aux: Some(QuantAux::Fp8 { scale: sbuf, per_row }),
                                });
                                model::ProjResult::Consumed
                            }
                            model::ProjWeight::Mlx4(mx) => {
                                if !flags.dense_q4_resident { return model::ProjResult::Dequantize; }
                                let eng = match engine_opt.as_mut() {
                                    Some(e) => e, None => return model::ProjResult::Dequantize };
                                // TP-shard the packed nibbles + matching scale/bias
                                // groups (mirrors nvfp4_tp_shard; single-node/PP
                                // has q35_tp_size==1 -> no-op passthrough).
                                let (packed, scales, biases, _out_f, _in_f) = mlx4_tp_shard(
                                    name, &mx.packed, &mx.scales, &mx.biases,
                                    mx.out_features, mx.in_features, mx.group_size,
                                    &tp_cfg, q35_tp_rank, q35_tp_size);
                                let pbytes = bytemuck::cast_slice::<u32, u8>(&packed).to_vec();
                                let sbytes = f32_slice_to_bytes(&scales);
                                let bbytes = f32_slice_to_bytes(&biases);
                                let pbuf = match q35_upload_bytes(eng, &pbytes, dw_q35) {
                                    Ok(b) => b,
                                    Err(e) => { log::warn!("mlx4 packed upload '{name}': {e}");
                                                return model::ProjResult::Dequantize; } };
                                let sbuf = match q35_upload_bytes(eng, &sbytes, dw_q35) {
                                    Ok(b) => b,
                                    Err(e) => { log::warn!("mlx4 scale upload '{name}': {e}");
                                                return model::ProjResult::Dequantize; } };
                                let bbuf = match q35_upload_bytes(eng, &bbytes, dw_q35) {
                                    Ok(b) => b,
                                    Err(e) => { log::warn!("mlx4 bias upload '{name}': {e}");
                                                return model::ProjResult::Dequantize; } };
                                gpu_bytes_total += (pbytes.len() + sbytes.len() + bbytes.len()) as u64;
                                gpu_weights.insert(name.to_string(), GpuWeight {
                                    buffer: pbuf, format: QuantFormat::Mlx4,
                                    aux: Some(QuantAux::Mlx4 { scales: sbuf, biases: bbuf,
                                        group_size: mx.group_size as u32 }),
                                });
                                model::ProjResult::Consumed
                            }
                            model::ProjWeight::F32(data) => {
                                // TP: shard the projection to this rank's slice first.
                                let data = q35_tp_shard(name, data, &tp_cfg, q35_tp_rank, q35_tp_size);
                                if let Some(eng) = engine_opt.as_mut() {
                                    // q8_0 (len%32==0, true for every 5120-multiple
                                    // proj) or f16. Both upload raw bytes via
                                    // q35_upload_bytes.
                                    let q8 = quant_q8_q35 && data.len() % 32 == 0;
                                    let bytes: Vec<u8> = if q8 {
                                        model::quantize_q8_0(&data)
                                    } else {
                                        let mut b = vec![0u8; data.len() * 2];
                                        for (i, &v) in data.iter().enumerate() {
                                            b[i*2..i*2+2].copy_from_slice(&half::f16::from_f32(v).to_bits().to_le_bytes());
                                        }
                                        b
                                    };
                                    let format = if q8 { QuantFormat::Q8_0 } else { QuantFormat::F16 };
                                    match q35_upload_bytes(eng, &bytes, dw_q35) {
                                        Ok(buf) => {
                                            gpu_bytes_total += bytes.len() as u64;
                                            gpu_weights.insert(name.to_string(),
                                                GpuWeight { buffer: buf, format, aux: None });
                                            if lean_q35 {
                                                return model::ProjResult::Consumed;  // f32 dropped — the win that fits 27B
                                            }
                                        }
                                        // Upload failed: the weight exists NOWHERE on the GPU, so
                                        // dropping the f32 here (as lean mode used to) silently
                                        // corrupts any forward that survives load (bug found in the
                                        // 2026-07-05 q8/GTT-overflow postmortem). Keep the host copy
                                        // so the CPU fallback path stays correct.
                                        Err(e) => log::warn!(
                                            "qwen3_5 GPU upload '{name}' failed ({e}); keeping f32 host copy"),
                                    }
                                }
                                // No engine, or not lean: keep the f32 host copy.
                                model::ProjResult::KeepF32(data)
                            }
                        }
                    };

                    // Split + STREAMING loader: embed/lm_head -> f16 host (their
                    // ~5GB f32 temp is freed inside the loader); projections ->
                    // streamed to the GPU via on_proj (peak = one tensor); conv/
                    // norm/A_log/dt_bias -> f32 host (CPU recurrence).
                    log_load_rss("qwen3_5 before load_qwen35_weights_split");
                    let (raw, mut q35_f16_host, mut embed_packed, mut lmhead_packed) = model::load_qwen35_weights_split(
                        path, group_size, bits, q35_start, Some(q35_end), keep_embed, q35_last, on_proj,
                    ).map_err(PyRuntimeError::new_err)?;
                    log_load_rss("qwen3_5 after load_qwen35_weights_split (proj on GPU; embed/lm f16 host)");

                    // Tied embeddings unless a separate lm_head is present.
                    let lm_name = if q35_f16_host.contains_key("lm_head.weight") {
                        "lm_head.weight".to_string()
                    } else {
                        "model.embed_tokens.weight".to_string()
                    };

                    // Non-projection f32 (conv1d/A_log/dt_bias/norm/layernorm) +
                    // any projection f32 the sink handed back (non-lean) -> host.
                    // TP: the GatedDeltaNet recurrence host weights (conv1d/A_log/
                    // dt_bias) are sharded by head here (q35_tp_shard replicates
                    // the norms/layernorms it doesn't recognize). Projections the
                    // sink handed back (non-lean) were already sharded in on_proj.
                    for (name, data) in raw.into_iter() {
                        let data = if q35_tp_size > 1 && !is_qwen35_matvec_weight(&name) {
                            q35_tp_shard(&name, data, &tp_cfg, q35_tp_rank, q35_tp_size)
                        } else {
                            data
                        };
                        host_bytes += (data.len() * 4) as u64;
                        host_tensors.insert(name, model::SimpleTensor { data, shape: vec![] });
                    }
                    // lm_head f16 → GPU (the final matvec), from the f16 host table.
                    // Force HOST-COHERENT (not device-local): the 248k×5120 lm_head
                    // is ~2.5GB and a device-local alloc that big fails on GFX1013's
                    // limited VRAM carveout (RADV "Failed to allocate a buffer").
                    // Host-coherent is GPU-readable system RAM and allocs fine.
                    //
                    // TP vocab-sharding (§2.2 of the plan): under TP>1, every rank
                    // replicating the FULL lm_head is what pushes this single alloc
                    // past the GTT edge (1.35GB q8 at 27B) — the actual fix, not just
                    // a mitigation. Each rank instead uploads only its contiguous
                    // vocab-row slice (`tp_vocab_shard_range`), 4x smaller at TP-4,
                    // and the forward tail all-gathers to reassemble/merge (tp.rs).
                    // Gated: tp_size>1 AND the kill switch AND native comm/allgather
                    // are available; otherwise falls through to today's replicated
                    // upload. `lm_shard_local` feeds the `VulkanModel.lm_shard` field.
                    let want_shard_lmhead = q35_tp_size > 1
                        && flags.tp_shard_lmhead
                        && flags.native_comm
                        && vccl_ffi::allgather_available();
                    let mut lm_shard_local: Option<LmShard> = None;
                    // Only the LAST PP stage computes logits, so only it needs the
                    // lm_head GPU buffer. On a non-last stage `lm_name` falls back to
                    // `model.embed_tokens.weight` (present because the FIRST stage
                    // keeps embed), which would otherwise make stage 0 build a full
                    // vocab×hidden (~1.3GB q8 / ~2.5GB f16) host-coherent buffer from
                    // the embed table for nothing — a fixed, layer-count-independent
                    // allocation on the exact stage (rank 0) that OOMs at load. Gate
                    // the whole build on q35_last (NR==1 sets both first & last, so the
                    // single-node path still builds it).
                    // lm_head source: the whole f16 table (legacy), OR — when the
                    // tied embed is kept PACKED (VLLM_VULKAN_Q35_EMBED_PACKED) —
                    // stream-dequant the packed embed rows into the q8/f16 target
                    // buffer, never materializing the whole-vocab f16/f32 table.
                    let lm_from_packed = !q35_f16_host.contains_key(&lm_name)
                        && lm_name == "model.embed_tokens.weight"
                        && embed_packed.is_some();
                    // Packed-resident (untied) lm_head (VLLM_VULKAN_Q35_LMHEAD_PACKED):
                    // upload the mlx-affine 4-bit lm_head PACKED (u32 nibbles + f32
                    // scales/biases) as an `MvKind::Mlx4` GPU weight and skip the
                    // whole-vocab f16 dequant + q8 requant entirely — the rank5
                    // load-transient the untied 122B PP-6 last stage OOMs on. The
                    // decode dispatch (`qwen35_matvec` / the WS3 resident tail) already
                    // format-routes `QuantFormat::Mlx4`, so no forward change is needed.
                    // Not wired for TP vocab-sharding (want_shard_lmhead): that path
                    // keeps the existing q8 shard build below.
                    let lmhead_from_packed = q35_last
                        && lmhead_packed.is_some()
                        && !want_shard_lmhead;
                    if let (Some(eng), true) =
                        (engine_opt.as_mut().filter(|_| q35_last), lmhead_from_packed)
                    {
                        let lmp = lmhead_packed.take().unwrap();
                        let pbytes = bytemuck::cast_slice::<u32, u8>(&lmp.packed).to_vec();
                        let sbytes = f32_slice_to_bytes(&lmp.scales);
                        let bbytes = f32_slice_to_bytes(&lmp.biases);
                        let gs = lmp.group_size as u32;
                        let up = |eng: &mut compute::ComputeEngine, b: &[u8], what: &str|
                            -> PyResult<compute::Buffer> {
                            q35_upload_bytes(eng, b, dw_q35).map_err(|e| PyRuntimeError::new_err(
                                format!("qwen3_5 lm_head packed {what} GPU upload FAILED: {e}. \
                                         The last stage cannot compute logits without it; \
                                         set VLLM_VULKAN_Q35_LMHEAD_PACKED=0 to fall back to \
                                         the whole-table f16/q8 lm_head build.")))
                        };
                        let pbuf = up(eng, &pbytes, "packed")?;
                        let sbuf = up(eng, &sbytes, "scales")?;
                        let bbuf = up(eng, &bbytes, "biases")?;
                        gpu_bytes_total += (pbytes.len() + sbytes.len() + bbytes.len()) as u64;
                        gpu_weights.insert(lm_name.clone(), GpuWeight {
                            buffer: pbuf, format: QuantFormat::Mlx4,
                            aux: Some(QuantAux::Mlx4 { scales: sbuf, biases: bbuf, group_size: gs }),
                        });
                        log::info!(
                            "qwen3_5: lm_head kept PACKED-4bit mlx4-resident ({:.2}GB), \
                             skipped whole-vocab f16 dequant + q8 requant (vocab={}, hidden={})",
                            (pbytes.len() + sbytes.len() + bbytes.len()) as f64 / 1e9,
                            lmp.vocab, lmp.hidden);
                    }
                    // TP vocab-shard + LMHEAD_PACKED both requested: the packed path
                    // above declined (want_shard_lmhead), but the loader already
                    // skipped the whole f16 table — so materialize it here (into the
                    // f16 host map) so the legacy sharded q8 build below finds it.
                    // Only hit under TP>1 (PP-6 fit path has want_shard_lmhead=false).
                    if q35_last && want_shard_lmhead {
                        if let Some(lmp) = lmhead_packed.take() {
                            log::warn!("qwen3_5: LMHEAD_PACKED + TP vocab-shard both set; \
                                        dequantizing lm_head to f16 for the shard build");
                            let f16 = model::dequantize_mlx_affine_f16(
                                &lmp.packed, &lmp.scales, &lmp.biases,
                                lmp.vocab, lmp.hidden, lmp.group_size, lmp.bits);
                            q35_f16_host.insert(lm_name.clone(), f16);
                        }
                    }
                    // The loader never built a whole f16 lm_head table when packed,
                    // so `q35_f16_host` has no `lm_name`, and `lm_from_packed` (the
                    // TIED path) is false here — this legacy build is skipped.
                    if let Some(eng) = engine_opt.as_mut().filter(|_| q35_last && !lmhead_from_packed) {
                        if q35_f16_host.contains_key(&lm_name) || lm_from_packed {
                            let vocab = cfg.vocab_size;
                            let h_dim = cfg.hidden_size;
                            // Row-major [vocab, h] -> a row slice is contiguous.
                            let (lo, per) = if want_shard_lmhead {
                                tp::tp_vocab_shard_range(vocab, q35_tp_rank, q35_tp_size)
                            } else {
                                (0, vocab)
                            };
                            // lm_head: q8_0 when quant is on (so the global QUANT=q8
                            // matvec dispatch matches it), else f16. Always
                            // host-coherent (the 248k×hidden buffer is too big for a
                            // single device-local alloc on GFX1013's VRAM carveout).
                            // q8_0 needs len%32==0; h%32==0 (3072/5120 ✓) makes ANY
                            // row count valid, so slicing never breaks the alignment.
                            let n = per * h_dim;
                            let lm_q8 = quant_q8_q35 && n % 32 == 0;
                            let bytes: Vec<u8> = if let Some(f16v) = q35_f16_host.get(&lm_name) {
                                // Legacy whole f16 table: contiguous row slice.
                                let slice: &[u16] = &f16v[lo * h_dim..(lo + per) * h_dim];
                                if lm_q8 {
                                    // Stream-quantize straight from f16 (no f32 temp).
                                    model::quantize_q8_0_from_f16(slice)
                                } else {
                                    let mut b = vec![0u8; slice.len() * 2];
                                    for (i, &hh) in slice.iter().enumerate() {
                                        b[i * 2..i * 2 + 2].copy_from_slice(&hh.to_le_bytes());
                                    }
                                    b
                                }
                            } else {
                                // PACKED embed → per-chunk row dequant → q8/f16, so the
                                // whole-vocab f16 table is NEVER held (the last-stage
                                // load transient this fix removes). Whole rows per chunk
                                // keep q8_0's 32-elem blocks intact (h_dim % 32 == 0).
                                let pe = embed_packed.as_ref().unwrap();
                                let mut b: Vec<u8> =
                                    Vec::with_capacity(if lm_q8 { n / 32 * 34 } else { n * 2 });
                                const RC: usize = 8192; // rows per chunk (~one 32MB f16 slab)
                                let mut r = lo;
                                while r < lo + per {
                                    let take = RC.min(lo + per - r);
                                    let mut f16c: Vec<u16> = Vec::with_capacity(take * h_dim);
                                    for row in r..r + take {
                                        f16c.extend_from_slice(&pe.row_f16(row));
                                    }
                                    if lm_q8 {
                                        b.extend_from_slice(&model::quantize_q8_0_from_f16(&f16c));
                                    } else {
                                        for &hh in &f16c {
                                            b.extend_from_slice(&hh.to_le_bytes());
                                        }
                                    }
                                    r += take;
                                }
                                b
                            };
                            let lm_format = if lm_q8 { QuantFormat::Q8_0 } else { QuantFormat::F16 };
                            // Chunked-alloc mitigation (§5, P2; default OFF —
                            // see flags::Flags::max_alloc_mb doc): row-boundary
                            // split when this buffer exceeds the configured
                            // limit, instead of one monolithic host-coherent
                            // alloc. row_bytes is uniform per row for both q8_0
                            // (h%32==0 asserted) and f16.
                            let row_bytes = if per > 0 { bytes.len() / per } else { 0 };
                            let limit_bytes = (flags.max_alloc_mb as usize) * 1024 * 1024;
                            let chunk_plan = model::chunk_row_plan(per, row_bytes, limit_bytes);
                            if chunk_plan.len() > 1 {
                                let mut buffers = Vec::with_capacity(chunk_plan.len());
                                let mut off = 0usize;
                                let mut failed = false;
                                for &rows in &chunk_plan {
                                    let nbytes = rows * row_bytes;
                                    match eng.alloc_host_coherent_storage(nbytes as u64) {
                                        Ok(buf) => {
                                            unsafe {
                                                std::ptr::copy_nonoverlapping(
                                                    bytes[off..off + nbytes].as_ptr(),
                                                    buf.mapped_ptr.unwrap() as *mut u8, nbytes);
                                            }
                                            buffers.push(buf);
                                        }
                                        Err(e) => {
                                            let msg = format!(
                                                "qwen3_5 chunked lm_head GPU upload FAILED (rows={rows}): {e}. \
                                                 Continuing would silently degrade decode to a single-thread f16 \
                                                 host matmul over the full vocab (hundreds of ms/token). Set \
                                                 VLLM_VULKAN_STRICT_GPU_LMHEAD=0 to allow the host fallback.");
                                            if strict_gpu_lmhead() {
                                                return Err(PyRuntimeError::new_err(msg));
                                            }
                                            log::error!("{msg}");
                                            failed = true;
                                            break;
                                        }
                                    }
                                    off += nbytes;
                                }
                                if failed {
                                    // R5-equivalent: no partial chunked entry; CPU
                                    // f16-host fallback (q35_f16_host kept full)
                                    // takes over via qwen35_matvec's fallback arm.
                                } else {
                                    gpu_bytes_total += bytes.len() as u64;
                                    log::info!("qwen3_5: lm_head chunked into {} buffers ({:.2}GB, limit {}MB)",
                                        chunk_plan.len(), bytes.len() as f64 / 1e9, flags.max_alloc_mb);
                                    chunked_weights.insert(lm_name.clone(),
                                        ChunkedGpuWeight { buffers, rows: chunk_plan, format: lm_format });
                                    if want_shard_lmhead {
                                        lm_shard_local = Some(LmShard { lo, per, v: vocab });
                                    }
                                }
                            } else {
                                match eng.alloc_host_coherent_storage(bytes.len() as u64).map(|buf| {
                                    unsafe {
                                        std::ptr::copy_nonoverlapping(
                                            bytes.as_ptr(), buf.mapped_ptr.unwrap() as *mut u8, bytes.len());
                                    }
                                    buf
                                }) {
                                    Ok(buf) => {
                                        gpu_bytes_total += bytes.len() as u64;
                                        gpu_weights.insert(lm_name.clone(), GpuWeight { buffer: buf, format: lm_format, aux: None });
                                        if want_shard_lmhead {
                                            lm_shard_local = Some(LmShard { lo, per, v: vocab });
                                            log::info!("qwen3_5 TP: lm_head sharded [{lo},{}) of {vocab} ({:.2}GB)",
                                                lo + per, bytes.len() as f64 / 1e9);
                                        }
                                    }
                                    // R5: upload failure must NOT leave a stale Some(..)
                                    // from a previous branch — lm_shard_local is already
                                    // None here, so the forward correctly falls back to
                                    // the replicated f16-host tail (no garbage gather).
                                    Err(e) => {
                                        let msg = format!(
                                            "qwen3_5 lm_head GPU upload FAILED: {e}. Continuing would silently \
                                             degrade decode to a single-thread f16 host matmul over the full \
                                             vocab (hundreds of ms/token). Set VLLM_VULKAN_STRICT_GPU_LMHEAD=0 \
                                             to allow the host fallback.");
                                        if strict_gpu_lmhead() {
                                            return Err(PyRuntimeError::new_err(msg));
                                        }
                                        log::error!("{msg}");
                                    }
                                }
                            }
                        }
                    }
                    // PP memory: the f16 embed table (~2.5GB for 27B) is only
                    // needed for the token-row lookup, which ONLY the first stage
                    // does. On a last-but-not-first (lm_head) stage with tied
                    // weights we loaded embed solely to build the q8 lm_head GPU
                    // buffer — now that it is uploaded, drop the f16 host copy so
                    // the lm_head stage doesn't pay +2.5GB host RAM (the OOM lever
                    // on a 14GB node carrying ~20 q8 layers + the lm_head).
                    if engine_opt.is_some() && q35_last && !q35_first && !mtp_requested {
                        if q35_f16_host.remove("model.embed_tokens.weight").is_some() {
                            log::info!("qwen3_5: dropped f16 embed host copy on lm_head-only stage");
                        }
                        // Same for the PACKED embed: an lm_head-only stage does the
                        // vocab matvec (built above) but never the per-token embed
                        // row lookup, so drop the ~0.5GB packed table too.
                        if embed_packed.take().is_some() {
                            log::info!("qwen3_5: dropped packed embed on lm_head-only stage");
                        }
                    }
                    log_load_rss("qwen3_5 after lm_head GPU build");
                    // Return freed per-tensor load transients (dequant/pread buffers)
                    // from glibc's arenas back to the OS. Without this, malloc keeps
                    // the high-water pages mapped as process anon even though they are
                    // logically freed — inflating the resident set of the stage that
                    // just streamed ~GBs of weights through transient Vecs.
                    #[cfg(all(target_os = "linux", target_env = "gnu"))]
                    unsafe { libc::malloc_trim(0); }
                    log_load_rss("qwen3_5 after malloc_trim");
                    for v in q35_f16_host.values() { host_bytes += (v.len() * 2) as u64; }
                    if let Some(pe) = embed_packed.as_ref() {
                        host_bytes += pe.resident_bytes() as u64;
                        log::info!("qwen3_5: embed kept PACKED-4bit resident ({:.2}GB, was ~{:.2}GB f16)",
                            pe.resident_bytes() as f64 / 1e9,
                            (pe.vocab * pe.hidden * 2) as f64 / 1e9);
                    }
                    log::info!("qwen3_5: GPU f16 {:.2}GB ({} bufs); host {:.2}GB (embed/lm f16/packed, proj+misc f32)",
                        gpu_bytes_total as f64 / 1e9, gpu_weights.len(), host_bytes as f64 / 1e9);
                    let _ = &mut q35_f16_host;

                    let weights = model::ModelWeights { tensors: host_tensors };
                    let lm_head_name = lm_name.clone();
                    // PP-resident model: holds only the layers in [q35_start,q35_end);
                    // `cfg` keeps the full global layer_types so state maps correctly.
                    // Under TP, per-layer state is sized for this rank's head shard.
                    let mut m = if q35_tp_size > 1 {
                        qwen35::Qwen35Model::new_range_tp(
                            cfg.clone(), weights, max_seq_len, lm_head_name,
                            q35_start, q35_end, q35_tp_size,
                        )
                    } else {
                        qwen35::Qwen35Model::new_range(
                            cfg.clone(), weights, max_seq_len, lm_head_name, q35_start, q35_end,
                        )
                    };
                    // Packed embed → the model (per-token row decode at the first
                    // stage). Already `None` on an lm_head-only stage (dropped
                    // above) and on middle stages (loader skipped embed).
                    m.embed_packed = embed_packed;
                    // 35B-A3B MoE: load the resident layer range's experts in
                    // their packed 4-bit form (the `switch_mlp.*` f32 dequant was
                    // skipped above) — ~0.4GB/layer vs ~3.2GB, so an 8-layer PP
                    // stage fits a 15GB node. Dense (27B) has no switch_mlp.
                    if cfg.is_moe() && model::moe_q4_resident_enabled() {
                        // This call is only made for MoE configs — a failure here
                        // means `m.quant_moe` stays empty and every routed-expert
                        // forward call on this model is guaranteed to panic (no
                        // valid CPU-fallback data, no GPU-resident data). Warning
                        // and continuing to `Ok(...)` used to defer that panic to
                        // mid-forward, well after load-time error reporting would
                        // have been actionable. Hard-fail the load instead.
                        let qm = model::load_qwen35_moe_quant_experts(
                            path, group_size, bits, q35_start, q35_end,
                        ).map_err(|e| PyRuntimeError::new_err(
                            format!("qwen3_5 MoE quant-expert load failed: {e}")))?;
                        let nl = qm.gate.len();
                        m.quant_moe = qm;
                        log::info!("qwen3_5 MoE: {nl} layers' experts loaded 4-bit-resident");
                    }
                    let mut vm = VulkanModel {
                        inner: carve_placeholder_inner(),
                        qwen: None,
                        qwen35: Some(m),
                        step3p7: None,
                        max_seq_len,
                        engine: engine_opt,
                        gpu_weights,
                        act_bufs: Vec::new(),
                        act_bufs_ready: false,
                        pp_start: q35_start,
                        pp_end: q35_end,
                        pp_first: q35_first,
                        pp_last: q35_last,
                        tp_rank: q35_tp_rank,
                        tp_size: q35_tp_size,
                        gemma_ple_bf16: None,
                        gpu_kv: std::collections::HashMap::new(),
                        gemma_kv_filled: 0,
                        qres_bufs: Vec::new(),
                        qres_ready: false,
                        gpu_norm_w: std::collections::HashMap::new(),
                        gres_bufs: Vec::new(),
                        gres_ready: false,
                        gemma_norm_w: std::collections::HashMap::new(),
                        ures_bufs: Vec::new(),
                        ures_ready: false,
                        unified_norm_w: std::collections::HashMap::new(),
                        bres_bufs: Vec::new(),
                        bres_ready: false,
                        q35_f16_host,
                        collective_comm: 0,
                        reduce_scratch: Vec::new(),
                        reduce_scratch_handle: 0,
                        pp_tok_ring: PpTokRing::default(),
                        pp_hop_send: PpTokRing::default(),
                        pp_hop_recv: PpTokRing::default(),
                        pp_vocab_ring: PpTokRing::default(),
            gemma_hidden_ring: std::collections::VecDeque::new(),
            gemma_pp_hop: Default::default(),
            moe_gpu: std::collections::HashMap::new(),
            moe_shared_gpu: std::collections::HashMap::new(),
            dn_gpu: std::collections::HashMap::new(),
            q35res_bufs: Vec::new(),
            q35res_ready: false,
            q35res_ok: None,
            spec_slots: Vec::new(),
                        flags,
                        lm_shard: lm_shard_local,
                        chunked_weights,
                        nemotron: None,
                        nemotron_mtp_head: None,
                        kimi: None,
                        ling: None,
                        laguna: None,
                        laguna_gpu: None,
                        mtp_head: None,
                        mtp_moe_gpu: None,
                        q35_last_prenorm: None,
                        q35_prenorm_ring: std::collections::VecDeque::new(),
                        spec_verify_gdn_inputs: Vec::new(),
                        spec_verify_span: None,
                        spec_verify_cols: false,
                        kv_store: None,
                    };
                    // ─── EAGER MoE GPU upload (PP-2 transient-peak OOM fix) ──────────
                    // PROBLEM: `ensure_moe_gpu_layer` uploads a layer's 4-bit experts
                    // to GTT LAZILY, on that layer's first forward. Mid-first-token
                    // the node therefore transiently holds the FULL host quant_moe
                    // (~10GB — freed only for already-visited layers) PLUS the GTT
                    // mirrors accumulated so far → peak ≈ host(~10GB) + GTT(~0.5GB×L)
                    // + dense + activations, which OOMs a 15.2GB UMA BC-250 around
                    // layer 10-15 of a 20-MoE-layer PP-2 stage even with the
                    // per-layer host-free of 95f98db (that fixes steady-state, not
                    // the sweep transient).
                    //
                    // FIX: upload+free every resident layer NOW, at load. This flips
                    // WHEN, not HOW — it drives the SAME idempotent
                    // `ensure_moe_gpu_layer` (upload → then free the host copy under
                    // VLLM_VULKAN_MOE_HOST_FREE, default on). Because each per-layer
                    // host free returns ~0.5GB to the unified-memory pool exactly as
                    // that layer's ~0.5GB GTT mirror is allocated, the running total
                    // stays ≈ the resident GTT footprint (~10GB) rather than
                    // host+GTT doubled. INVARIANT: at most ONE layer's experts are
                    // simultaneously host-resident-and-not-yet-in-GTT during this
                    // loop, so the load peak ≈ GTT(all layers) + ~1 host layer. By
                    // the time forward runs, host quant_moe is empty → the forward
                    // sweep peak drops to GTT + dense + activations (no transient).
                    //
                    // Gating: eager only when the GPU MoE path will actually be used
                    // (moe_gpu on) AND an engine exists. Engine-less runs (Mac tests,
                    // MOE_GPU=0 CPU experts) skip the whole pass and fall back to the
                    // unchanged lazy `ensure_moe_gpu_layer` (its map-guard keeps that
                    // fallback correct for any un-uploaded layer). PP: we iterate only
                    // the layers this stage actually loaded (quant_moe.gate keys).
                    if moe_gpu_enabled() && moe_eager_upload_enabled() && vm.engine.is_some() {
                        let mut layers: Vec<usize> = vm
                            .qwen35.as_ref().unwrap()
                            .quant_moe.gate.keys().copied().collect();
                        layers.sort_unstable();
                        for l in layers {
                            // Hard-fail on upload failure (consistent with 95f98db's
                            // load-time hard-fail policy): a false here means an
                            // alloc/write into GTT failed (or a projection tensor is
                            // missing). With host-free on, limping into the forward
                            // would hit a freed/empty host copy and panic mid-token;
                            // fail the LOAD loudly instead.
                            if !vm.ensure_moe_gpu_layer(l) {
                                return Err(PyRuntimeError::new_err(format!(
                                    "qwen3_5 MoE eager GPU upload failed at layer {l} \
                                     (GTT alloc/write failed or expert tensor missing); \
                                     refusing to construct a model whose forward would \
                                     OOM or panic")));
                            }
                        }
                        log::info!(
                            "qwen3_5 MoE: eager-uploaded {} layers' experts to GTT at \
                             load (peak ≈ resident GTT + ~1 host layer, not host+GTT \
                             doubled; forward sweep now transient-free)",
                            vm.moe_gpu.len());
                    }
                    // MTP draft head (plan §P2 GPU-dense remainder), env-gated so a
                    // plain qwen3_5 load is unaffected when the sidecar isn't
                    // present. `load_mtp_gpu` uploads `fc`/`q/k/v/o_proj` f16-
                    // resident on the GPU (this stage's engine, if any) and stores
                    // the head for `mtp_draft`. A missing/bad sidecar only logs a
                    // warning (speculative drafting is an optimization, not
                    // correctness-load-bearing) — never fails the base model load.
                    #[cfg(feature = "mtp")]
                    if let Ok(mtp_path) = std::env::var("VLLM_VULKAN_MTP_PATH") {
                        match vm.load_mtp_gpu(std::path::Path::new(&mtp_path)) {
                            Ok(()) => log::info!(
                                "qwen3_5: MTP draft head loaded (GPU-dense path) from {mtp_path}"),
                            Err(e) => log::warn!(
                                "VLLM_VULKAN_MTP_PATH={mtp_path} set but MTP head load failed: {e}"),
                        }
                    }
                    return Ok(vm);
                }
                // De-chained from the qwen35 `if` above so `gemma` and `qwen35`
                // gate independently (Phase A2). Each arm returns, so separate
                // `if`s are behaviour-identical to the former else-if chain.
                #[cfg(feature = "gemma")]
                if mt == "gemma4_unified" {
                    // ── Gemma-4-12B-it (dense hybrid text model) ────────────
                    // gemma4_unified is the multimodal wrapper's model_type;
                    // the checkpoint's text tower is the g12b architecture
                    // (48L, GQA(8) sliding / value-less MQA(1) global, no
                    // PLE, tied embeddings). MLX-affine quantized 4-bit attn +
                    // 8-bit MLP (group 64) — see `load_gemma_resident_weights`.
                    let cfg = model::Gemma4Config::g12b();
                    let total_layers = cfg.num_hidden_layers;
                    let g_start = layer_start.unwrap_or(0);
                    let g_end = layer_end.unwrap_or(total_layers).min(total_layers);
                    log::info!(
                        "Loading Gemma-12B (gemma4_unified): layers [{g_start},{g_end}) of {total_layers}, hidden {} from {}",
                        cfg.hidden_size, safetensors_path);

                    let flags = Flags::from_env();
                    let mut engine_opt: Option<compute::ComputeEngine> =
                        match device::ComputeDevice::create(device_idx) {
                            Ok(dev) => {
                                let shader_spvs = include_all_shaders();
                                let refs: HashMap<&str, &[u8]> = shader_spvs.iter()
                                    .map(|(k, v)| (k.as_str(), v.as_slice())).collect();
                                match compute::ComputeEngine::new(
                                    dev.instance.clone(),
                                    dev.physical_device,
                                    dev.device.clone(),
                                    dev.compute_queue,
                                    dev.compute_queue_family,
                                    dev.caps(),
                                    &refs,
                                ) {
                                    Ok(engine) => Some(engine),
                                    Err(e) => {
                                        log::warn!("gemma4_unified: compute engine failed: {e}; CPU only");
                                        None
                                    }
                                }
                            }
                            Err(e) => {
                                log::warn!("gemma4_unified: no Vulkan device {device_idx}: {e}; CPU only");
                                None
                            }
                        };

                    let dw_g12b = std::env::var("VLLM_VULKAN_DEVICE_WEIGHTS")
                        .map(|v| v == "1" || v.eq_ignore_ascii_case("true")).unwrap_or(false);
                    // Lean-host: drop the f32 host copy of an uploaded attn/mlp
                    // projection (default on when an engine exists), matching
                    // the qwen3.6 resident-loader convention (b5c89eb: keep
                    // the f32 host copy when the GPU upload itself FAILS, so a
                    // dropped tensor is never left GPU-absent AND host-absent).
                    let lean_g12b = std::env::var("VLLM_VULKAN_LEAN_HOST")
                        .map(|v| v == "1" || v.eq_ignore_ascii_case("true"))
                        .unwrap_or(engine_opt.is_some());

                    // Raw weight bytes -> GPU buffer (device-local VRAM via
                    // staged copy, or host-coherent UMA RAM). Mirrors
                    // `q35_upload_bytes` (same mlock rationale: an unpinned
                    // host-coherent weight page is ordinary swappable system
                    // RAM on the UMA APU fleet and can be silently corrupted
                    // under memory pressure).
                    fn g12b_upload_bytes(eng: &mut compute::ComputeEngine, bytes: &[u8], dw: bool) -> Result<compute::Buffer, String> {
                        if dw {
                            match eng.alloc_device(bytes.len() as u64) {
                                Ok(buf) => eng.upload(&buf, bytes).map(|_| buf),
                                Err(e) => Err(e),
                            }
                        } else {
                            eng.alloc_host_coherent_storage(bytes.len() as u64).map(|buf| {
                                unsafe {
                                    std::ptr::copy_nonoverlapping(
                                        bytes.as_ptr(), buf.mapped_ptr.unwrap() as *mut u8, bytes.len());
                                }
                                #[cfg(unix)]
                                if let Some(ptr) = buf.mapped_ptr {
                                    let rc = unsafe {
                                        libc::mlock(ptr as *const libc::c_void, bytes.len())
                                    };
                                    if rc != 0 {
                                        log::warn!(
                                            "mlock of {}-byte gemma4_unified weight failed ({}); \
                                             weight pages remain swappable",
                                            bytes.len(), std::io::Error::last_os_error());
                                    }
                                }
                                buf
                            })
                        }
                    }

                    let mut gpu_weights: HashMap<String, GpuWeight> = HashMap::new();
                    let mut gpu_bytes_total = 0u64;
                    let quant_q8 = flags.quant == QuantFormat::Q8_0;
                    let quant_q4 = flags.quant == QuantFormat::Q4_0;
                    let quant_q4k = flags.quant == QuantFormat::Q4_K;
                    let quant_bf16 = flags.quant == QuantFormat::Bf16;

                    // Streaming sink: 4-bit attn offered packed (Mlx4) -> upload
                    // verbatim; 8-bit MLP arrives already f32-dequantized (no
                    // packed 8-bit shader exists) -> ALWAYS q8_0-requantize on
                    // upload (near-lossless re-round of an 8-bit source, and the
                    // only way to avoid doubling MLP GPU residency to f16).
                    // EXCEPTION (VLLM_VULKAN_GEMMA_MLP_Q4, H1 lever): the loader
                    // requants the MLP to mlx4 4-bit and offers it as `Mlx4` too,
                    // so it takes the SAME packed-upload arm as attn below. The
                    // resident-layer matvec dispatch (`gemma_forward.rs`) reads
                    // each `GpuWeight`'s own `format`/`aux`, NOT the global
                    // `VLLM_VULKAN_QUANT` snapshot, so this is correct regardless
                    // of that env var.
                    let on_proj = |name: &str, w: model::ProjWeight| -> model::ProjResult {
                        match w {
                            model::ProjWeight::Mlx4(mx) => {
                                let eng = match engine_opt.as_mut() {
                                    Some(e) => e, None => return model::ProjResult::Dequantize };
                                let pbytes = bytemuck::cast_slice::<u32, u8>(&mx.packed).to_vec();
                                let sbytes = f32_slice_to_bytes(&mx.scales);
                                let bbytes = f32_slice_to_bytes(&mx.biases);
                                let pbuf = match g12b_upload_bytes(eng, &pbytes, dw_g12b) {
                                    Ok(b) => b,
                                    Err(e) => { log::warn!("gemma4_unified mlx4 packed upload '{name}': {e}");
                                                return model::ProjResult::Dequantize; } };
                                let sbuf = match g12b_upload_bytes(eng, &sbytes, dw_g12b) {
                                    Ok(b) => b,
                                    Err(e) => { log::warn!("gemma4_unified mlx4 scale upload '{name}': {e}");
                                                return model::ProjResult::Dequantize; } };
                                let bbuf = match g12b_upload_bytes(eng, &bbytes, dw_g12b) {
                                    Ok(b) => b,
                                    Err(e) => { log::warn!("gemma4_unified mlx4 bias upload '{name}': {e}");
                                                return model::ProjResult::Dequantize; } };
                                gpu_bytes_total += (pbytes.len() + sbytes.len() + bbytes.len()) as u64;
                                gpu_weights.insert(name.to_string(), GpuWeight {
                                    buffer: pbuf, format: QuantFormat::Mlx4,
                                    aux: Some(QuantAux::Mlx4 { scales: sbuf, biases: bbuf,
                                        group_size: mx.group_size as u32 }),
                                });
                                model::ProjResult::Consumed
                            }
                            model::ProjWeight::F32(data) => {
                                if let Some(eng) = engine_opt.as_mut() {
                                    if data.len() % 32 == 0 {
                                        let bytes = model::quantize_q8_0(&data);
                                        match g12b_upload_bytes(eng, &bytes, dw_g12b) {
                                            Ok(buf) => {
                                                gpu_bytes_total += bytes.len() as u64;
                                                gpu_weights.insert(name.to_string(),
                                                    GpuWeight { buffer: buf, format: QuantFormat::Q8_0, aux: None });
                                                if lean_g12b {
                                                    return model::ProjResult::Consumed;
                                                }
                                            }
                                            // Upload failed: keep the f32 host copy (never drop a
                                            // tensor that isn't GPU-resident — b5c89eb's fix).
                                            Err(e) => log::warn!(
                                                "gemma4_unified MLP GPU upload '{name}' failed ({e}); keeping f32 host copy"),
                                        }
                                    } else {
                                        log::warn!(
                                            "gemma4_unified MLP tensor '{name}' len {} not 32-aligned \
                                             for q8_0; keeping f32 host (CPU matmul)", data.len());
                                    }
                                }
                                model::ProjResult::KeepF32(data)
                            }
                            _ => model::ProjResult::Dequantize,
                        }
                    };

                    // `load_gemma_resident_weights`/`load_gemma_mlx_affine` do
                    // `dir.join("model.safetensors")` before handing off to
                    // `discover_shards` (which strips the filename back off via
                    // `.parent()`), so — unlike `load_qwen35_weights`, which takes
                    // the shard-FILE path directly — this loader wants the
                    // checkpoint DIRECTORY. `safetensors_path` follows the same
                    // qwen/nemotron convention (a shard file, e.g.
                    // `model-00001-of-00003.safetensors`, with `config.json` a
                    // sibling); `path.parent()` recovers that directory. Passing
                    // `path` itself here (the bug) made a shard-file arg do
                    // `shard_file.join("model.safetensors")` -> ENOTDIR.
                    let g12b_dir = path.parent().unwrap_or_else(|| Path::new("."));
                    let (mut host_f32, embed_raw) = model::load_gemma_resident_weights(g12b_dir, g_start, g_end, flags.gemma_mlp_q4, on_proj)
                        .map_err(PyRuntimeError::new_err)?;

                    // Tied embed/lm_head, STREAMED — no ~4GB f32 whole-vocab
                    // transient (the single biggest full-48L single-node load
                    // OOM driver). The loader handed us the embed's RAW on-disk
                    // 4-bit mlx-affine form (`embed_raw`: packed u32 + f32
                    // scales/biases, group 64) instead of dequantizing it. Build
                    // BOTH (a) the GPU lm_head projection copy and (b) the host
                    // f16 input-embed lookup table straight from it; the f16
                    // table comes from a per-row streaming dequant
                    // (`dequantize_mlx_affine_f16`), never a whole-vocab f32.
                    let mut g12b_f16_host: std::collections::HashMap<String, Vec<u16>> = std::collections::HashMap::new();
                    if let Some(embed) = embed_raw {
                        let (vocab, hidden, gs) = (embed.out_features, embed.in_features, embed.group_size);
                        // Sanity: the raw embed must match the model config and be
                        // a consistent 4-bit mlx-affine tensor before we upload it
                        // verbatim / stream it (guards against a silent-garbage
                        // lm_head from a mis-shaped checkpoint).
                        if vocab != cfg.vocab_size || hidden != cfg.hidden_size
                            || embed.packed.len() != vocab * (hidden / 8)
                            || embed.scales.len() != vocab * (hidden / gs)
                            || embed.biases.len() != vocab * (hidden / gs) {
                            return Err(PyRuntimeError::new_err(format!(
                                "gemma4_unified embed shape mismatch: [{vocab},{hidden}] gs={gs} \
                                 packed={} scales={} biases={} vs cfg [{},{}]",
                                embed.packed.len(), embed.scales.len(), embed.biases.len(),
                                cfg.vocab_size, cfg.hidden_size)));
                        }
                        // (a) GPU lm_head projection copy. `gemma_final` reads the
                        // uploaded weight's own `format`/`aux`, so upload format is
                        // the single source of truth for dispatch.
                        if let Some(eng) = engine_opt.as_mut() {
                            // H2 lever (VLLM_VULKAN_GEMMA_LMHEAD_Q4): upload the
                            // ORIGINAL on-disk 4-bit packed VERBATIM — no dequant,
                            // no requant, no f32/f16 (~0.5GB packed + ~0.13GB
                            // scale/bias vs ~2GB f16). Strictly more faithful than
                            // the old requant path (it IS the on-disk weight), and
                            // the packed nibble order already matches the mlx4 GPU
                            // kernel. Only this GPU projection copy is 4-bit; the
                            // host f16 lookup (b) stays f16-exact.
                            let lmhead_mlx4 = flags.gemma_lmhead_q4
                                && hidden % 64 == 0 && hidden % 8 == 0;
                            if lmhead_mlx4 {
                                let pbytes = bytemuck::cast_slice::<u32, u8>(&embed.packed).to_vec();
                                let sbytes = f32_slice_to_bytes(&embed.scales);
                                let bbytes = f32_slice_to_bytes(&embed.biases);
                                let up = (|eng: &mut compute::ComputeEngine| -> Result<GpuWeight, String> {
                                    let pbuf = g12b_upload_bytes(eng, &pbytes, dw_g12b)?;
                                    let sbuf = g12b_upload_bytes(eng, &sbytes, dw_g12b)?;
                                    let bbuf = g12b_upload_bytes(eng, &bbytes, dw_g12b)?;
                                    Ok(GpuWeight { buffer: pbuf, format: QuantFormat::Mlx4,
                                        aux: Some(QuantAux::Mlx4 { scales: sbuf, biases: bbuf,
                                            group_size: gs as u32 }) })
                                })(eng);
                                match up {
                                    Ok(gw) => {
                                        let nb = (pbytes.len() + sbytes.len() + bbytes.len()) as u64;
                                        gpu_bytes_total += nb;
                                        gpu_weights.insert("model.embed_tokens.weight".to_string(), gw);
                                        log::info!(
                                            "gemma4_unified: LM-head w4 (VLLM_VULKAN_GEMMA_LMHEAD_Q4) \
                                             uploaded on-disk mlx4 4-bit VERBATIM, {:.2}GB (packed+scale+bias) vs {:.2}GB f16",
                                            nb as f64 / 1e9, (vocab * hidden * 2) as f64 / 1e9);
                                    }
                                    Err(e) => {
                                        let msg = format!(
                                            "gemma4_unified embed/lm_head mlx4-4bit GPU upload FAILED: {e}. \
                                             Set VLLM_VULKAN_GEMMA_LMHEAD_Q4=0 (falls back to f16 lm_head) \
                                             or VLLM_VULKAN_STRICT_GPU_LMHEAD=0 for the host fallback.");
                                        if strict_gpu_lmhead() {
                                            return Err(PyRuntimeError::new_err(msg));
                                        }
                                        log::error!("{msg}");
                                    }
                                }
                            } else {
                                // Baseline: stream 4-bit -> f16 (bit-identical to
                                // the old whole-table dequant-then-f16), upload f16.
                                // Explicit global quant formats (q8/q4/q4k/bf16)
                                // round from a locally-dequantized f32 table (a rare
                                // non-default config; keeps it functionally intact).
                                let gpu_format = if quant_q4k && (vocab * hidden) % 256 == 0 {
                                    QuantFormat::Q4_K
                                } else if quant_q4 && (vocab * hidden) % 32 == 0 {
                                    QuantFormat::Q4_0
                                } else if quant_q8 && (vocab * hidden) % 32 == 0 {
                                    QuantFormat::Q8_0
                                } else if quant_bf16 {
                                    QuantFormat::Bf16
                                } else {
                                    QuantFormat::F16
                                };
                                let bytes: Vec<u8> = if gpu_format == QuantFormat::F16 {
                                    // Stream 4-bit -> f16 directly (no whole f32).
                                    let f16v = model::dequantize_mlx_affine_f16(
                                        &embed.packed, &embed.scales, &embed.biases, vocab, hidden, gs, 4);
                                    bytemuck::cast_slice::<u16, u8>(&f16v).to_vec()
                                } else {
                                    // Rare explicit-quant embed: dequant whole f32.
                                    let deq = model::dequantize_mlx_affine(
                                        &embed.packed, &embed.scales, &embed.biases, vocab, hidden, gs, 4);
                                    match gpu_format {
                                        QuantFormat::Q4_K => model::quantize_q4_k(&deq),
                                        QuantFormat::Q4_0 => model::quantize_q4_0(&deq),
                                        QuantFormat::Q8_0 => model::quantize_q8_0(&deq),
                                        QuantFormat::Bf16 => {
                                            let mut b = vec![0u8; deq.len() * 2];
                                            for (i, &v) in deq.iter().enumerate() {
                                                b[i*2..i*2+2].copy_from_slice(&half::bf16::from_f32(v).to_bits().to_le_bytes());
                                            }
                                            b
                                        }
                                        _ => unreachable!(),
                                    }
                                };
                                match g12b_upload_bytes(eng, &bytes, dw_g12b) {
                                    Ok(buf) => {
                                        gpu_bytes_total += bytes.len() as u64;
                                        gpu_weights.insert("model.embed_tokens.weight".to_string(),
                                            GpuWeight { buffer: buf, format: gpu_format, aux: None });
                                    }
                                    Err(e) => {
                                        let msg = format!(
                                            "gemma4_unified embed/lm_head GPU upload FAILED: {e}. The tied embed \
                                             doubles as the lm_head; continuing would silently degrade decode to a \
                                             single-thread f16 host matmul over the full vocab (hundreds of \
                                             ms/token). Set VLLM_VULKAN_STRICT_GPU_LMHEAD=0 to allow the host \
                                             fallback.");
                                        if strict_gpu_lmhead() {
                                            return Err(PyRuntimeError::new_err(msg));
                                        }
                                        log::error!("{msg}");
                                    }
                                }
                            }
                        }
                        // (b) Host f16 lookup table (per-token input embed row +
                        // CPU lm_head fallback), streamed 4-bit -> f16. Bit-
                        // identical to the pre-fix whole-table dequant-then-f16.
                        let f16v = model::dequantize_mlx_affine_f16(
                            &embed.packed, &embed.scales, &embed.biases, vocab, hidden, gs, 4);
                        g12b_f16_host.insert("model.embed_tokens.weight".to_string(), f16v);
                    } else if let Some(embed) = host_f32.remove("model.embed_tokens.weight") {
                        // Fallback: embed wasn't 4-bit mlx-affine on disk (some
                        // other gemma variant). Upload an f16 GPU copy from the
                        // f32 the loader kept, and retain an f16 host copy.
                        if let Some(eng) = engine_opt.as_mut() {
                            let mut bytes = vec![0u8; embed.len() * 2];
                            for (i, &v) in embed.iter().enumerate() {
                                bytes[i*2..i*2+2].copy_from_slice(&half::f16::from_f32(v).to_bits().to_le_bytes());
                            }
                            match g12b_upload_bytes(eng, &bytes, dw_g12b) {
                                Ok(buf) => {
                                    gpu_bytes_total += bytes.len() as u64;
                                    gpu_weights.insert("model.embed_tokens.weight".to_string(),
                                        GpuWeight { buffer: buf, format: QuantFormat::F16, aux: None });
                                }
                                Err(e) => {
                                    if strict_gpu_lmhead() {
                                        return Err(PyRuntimeError::new_err(format!(
                                            "gemma4_unified embed/lm_head GPU upload FAILED: {e}")));
                                    }
                                    log::error!("gemma4_unified embed/lm_head GPU upload FAILED: {e}");
                                }
                            }
                        }
                        let mut f16v = vec![0u16; embed.len()];
                        for (dst, &v) in f16v.iter_mut().zip(embed.iter()) {
                            *dst = half::f16::from_f32(v).to_bits();
                        }
                        g12b_f16_host.insert("model.embed_tokens.weight".to_string(), f16v);
                    }

                    let mut host_bytes = 0u64;
                    for v in host_f32.values() { host_bytes += (v.len() * 4) as u64; }
                    let f16_bytes: u64 = g12b_f16_host.values().map(|v| (v.len() * 2) as u64).sum();
                    log::info!(
                        "gemma4_unified: GPU {:.2}GB ({} bufs); host f32 {:.2}GB + f16 embed {:.2}GB",
                        gpu_bytes_total as f64 / 1e9, gpu_weights.len(), host_bytes as f64 / 1e9,
                        f16_bytes as f64 / 1e9);

                    let host_tensors: HashMap<String, model::SimpleTensor> = host_f32.drain()
                        .map(|(k, v)| (k, model::SimpleTensor { data: v, shape: vec![] }))
                        .collect();
                    let weights = model::ModelWeights { tensors: host_tensors };

                    // KV cache: full GLOBAL range (like E2B) since `forward_layer`/
                    // `gemma_resident_layer` index `kv_caches` by the raw global
                    // layer_idx, not a PP-stage-relative offset. Per-layer typed:
                    // global (k_eq_v) layers are 1kv-head x 512 head_dim, sliding
                    // are 8kv-head x 256 (mirrors the CPU golden test, model.rs
                    // ~3067).
                    // Per-layer KV sizing (Phase-0 host half): sliding-window
                    // layers only ever attend the last `sliding_window`
                    // positions, so their host cache is a `window`-sized RING
                    // (capacity = layer_kv_capacity < max_seq_len); global/full
                    // layers keep a full max_seq cache (capacity == max_seq, so
                    // `new_windowed` is byte-identical to the old `new`). Gated
                    // by VLLM_VULKAN_KV_RING_DISABLE (mirrors the GPU-resident
                    // ring in `gemma_resident_layer_1cb`) so the host and GPU
                    // halves engage/disengage together for A/B.
                    let kv_caches: Vec<model::KvCache> = (0..total_layers)
                        .map(|l| {
                            let cap = if flags.kv_ring_disable {
                                max_seq_len
                            } else {
                                cfg.layer_kv_capacity(l, max_seq_len)
                            };
                            model::KvCache::new_windowed(max_seq_len, cap, cfg.layer_num_kv_heads(l), cfg.layer_head_dim(l))
                        })
                        .collect();

                    let inner = model::Gemma4Model { config: cfg, weights, kv_caches };

                    let vm = VulkanModel {
                        inner,
                        qwen: None,
                        qwen35: None,
                        step3p7: None,
                        max_seq_len,
                        engine: engine_opt,
                        gpu_weights,
                        act_bufs: Vec::new(),
                        act_bufs_ready: false,
                        pp_start: g_start,
                        pp_end: g_end,
                        pp_first: g_start == 0,
                        pp_last: g_end >= total_layers,
                        tp_rank: 0,
                        tp_size: 1,
                        // g12b has PLE off (hidden_size_per_layer_input=0); no
                        // per-layer-embedding table to load.
                        gemma_ple_bf16: None,
                        gpu_kv: std::collections::HashMap::new(),
                        gemma_kv_filled: 0,
                        qres_bufs: Vec::new(),
                        qres_ready: false,
                        gpu_norm_w: std::collections::HashMap::new(),
                        gres_bufs: Vec::new(),
                        gres_ready: false,
                        gemma_norm_w: std::collections::HashMap::new(),
                        ures_bufs: Vec::new(),
                        ures_ready: false,
                        unified_norm_w: std::collections::HashMap::new(),
                        bres_bufs: Vec::new(),
                        bres_ready: false,
                        q35_f16_host: g12b_f16_host,
                        collective_comm: 0,
                        reduce_scratch: Vec::new(),
                        reduce_scratch_handle: 0,
                        pp_tok_ring: PpTokRing::default(),
                        pp_hop_send: PpTokRing::default(),
                        pp_hop_recv: PpTokRing::default(),
                        pp_vocab_ring: PpTokRing::default(),
            gemma_hidden_ring: std::collections::VecDeque::new(),
                        gemma_pp_hop: Default::default(),
                        moe_gpu: std::collections::HashMap::new(),
                        moe_shared_gpu: std::collections::HashMap::new(),
                        dn_gpu: std::collections::HashMap::new(),
                        q35res_bufs: Vec::new(),
                        q35res_ready: false,
                        q35res_ok: None,
                        spec_slots: Vec::new(),
                        flags,
                        lm_shard: None,
                        chunked_weights: std::collections::HashMap::new(),
                        nemotron: None,
                        nemotron_mtp_head: None,
                        kimi: None,
                        ling: None,
                        laguna: None,
                        laguna_gpu: None,
                        mtp_head: None,
                        mtp_moe_gpu: None,
                        q35_last_prenorm: None,
                        q35_prenorm_ring: std::collections::VecDeque::new(),
                        spec_verify_gdn_inputs: Vec::new(),
                        spec_verify_span: None,
                        spec_verify_cols: false,
                        kv_store: None,
                    };
                    return Ok(vm);
                } else if mt == "gemma4" {
                    // ── Gemma-4-31B-it base (EAGLE-spec target) ─────────────
                    // `gemma4` (distinct from the 12B's `gemma4_unified`) is
                    // the compressed-tensors mixed NVFP4+FP8 checkpoint (see
                    // `scripts/GEMMA31B_SPEC_PLAN.md` INC-1/INC-1b): FP8 attn
                    // (every layer) + FP8 mlp on layers 1/57/58/59, NVFP4 mlp
                    // everywhere else. `load_gemma_nvfp4_weights` does the
                    // per-tensor routing; this block does GPU upload plumbing
                    // (mirrors qwen3_5's NVFP4/FP8 `on_proj` sink — see
                    // `tp.rs`/the block above ~L723-793) PLUS the head-aware
                    // TP shard (`tp::gemma_nvfp4_tp_shard`/
                    // `tp::gemma_fp8_tp_shard`, INC-1b) — unlike qwen3_5's
                    // uniform head layout, gemma's sliding vs global layers
                    // differ in both kv-head count and head_dim, so the shard
                    // is layer-index-aware (see tp.rs doc comment). GPU/
                    // multi-rank EXECUTION of the sharded weights is
                    // cluster-deferred; this wiring is validated by the
                    // CPU-only reassembly gate (`gemma_shard_tests` in
                    // tp.rs), not by an actual multi-rank run on this box.
                    let cfg = model::Gemma4Config::g31b();
                    let total_layers = cfg.num_hidden_layers;
                    let g_start = layer_start.unwrap_or(0);
                    let g_end = layer_end.unwrap_or(total_layers).min(total_layers);
                    log::info!(
                        "Loading Gemma-31B (gemma4, NVFP4+FP8): layers [{g_start},{g_end}) of {total_layers}, hidden {} from {}",
                        cfg.hidden_size, safetensors_path);

                    let g31b_tp_size = std::env::var("VLLM_VULKAN_TP_SIZE").ok()
                        .and_then(|v| v.parse::<usize>().ok()).unwrap_or(1).max(1);
                    let g31b_tp_rank = std::env::var("VLLM_VULKAN_TP_RANK").ok()
                        .and_then(|v| v.parse::<usize>().ok()).unwrap_or(0).min(g31b_tp_size - 1);
                    if g31b_tp_size > 1 {
                        // Validate divisibility up front (TP=4 divides g31b's
                        // 32 q-heads, 16 sliding kv-heads, 4 global kv-heads,
                        // and 21504 intermediate cleanly).
                        for (label, val) in [
                            ("num_attention_heads", cfg.num_attention_heads),
                            ("num_key_value_heads (sliding)", cfg.num_key_value_heads),
                            ("num_global_key_value_heads (global)", cfg.num_global_key_value_heads),
                            ("intermediate_size", cfg.intermediate_size),
                        ] {
                            if val % g31b_tp_size != 0 {
                                return Err(PyRuntimeError::new_err(format!(
                                    "gemma4 (31B) TP: {label}={val} not divisible by tp_size={g31b_tp_size} \
                                     (use a tp_size that divides every head count; 4 works for g31b)")));
                            }
                        }
                        log::info!("gemma4 (31B) TP: rank {g31b_tp_rank}/{g31b_tp_size} \
                                    (col-shard q/k/v/gate/up, row-shard o/down; head-aware \
                                    per sliding/global layer type)");
                    }
                    let g31b_tp_cfg = cfg.clone();

                    let flags = Flags::from_env();
                    let mut engine_opt: Option<compute::ComputeEngine> =
                        match device::ComputeDevice::create(device_idx) {
                            Ok(dev) => {
                                let shader_spvs = include_all_shaders();
                                let refs: HashMap<&str, &[u8]> = shader_spvs.iter()
                                    .map(|(k, v)| (k.as_str(), v.as_slice())).collect();
                                match compute::ComputeEngine::new(
                                    dev.instance.clone(),
                                    dev.physical_device,
                                    dev.device.clone(),
                                    dev.compute_queue,
                                    dev.compute_queue_family,
                                    dev.caps(),
                                    &refs,
                                ) {
                                    Ok(engine) => Some(engine),
                                    Err(e) => {
                                        log::warn!("gemma4 (31B): compute engine failed: {e}; CPU only");
                                        None
                                    }
                                }
                            }
                            Err(e) => {
                                log::warn!("gemma4 (31B): no Vulkan device {device_idx}: {e}; CPU only");
                                None
                            }
                        };

                    let dw_g31b = std::env::var("VLLM_VULKAN_DEVICE_WEIGHTS")
                        .map(|v| v == "1" || v.eq_ignore_ascii_case("true")).unwrap_or(false);
                    let lean_g31b = std::env::var("VLLM_VULKAN_LEAN_HOST")
                        .map(|v| v == "1" || v.eq_ignore_ascii_case("true"))
                        .unwrap_or(engine_opt.is_some());
                    // NVFP4/FP8-GPU packed residency gate — same flag qwen3_5
                    // uses (`VLLM_VULKAN_NVFP4_GPU`); off (or engine-less)
                    // falls back to f32 dequant + q8_0 upload, byte-identical
                    // to the flag-off path.
                    let nvfp4_gpu_g31b = flags.nvfp4_gpu;
                    // e4m3-resident scales (VLLM_VULKAN_NVFP4_E4M3_SCALES); see
                    // the qwen loader arm + QuantAux::Nvfp4 field doc.
                    let nvfp4_e4m3_g31b = flags.nvfp4_e4m3_scales;

                    fn g31b_upload_bytes(eng: &mut compute::ComputeEngine, bytes: &[u8], dw: bool) -> Result<compute::Buffer, String> {
                        if dw {
                            match eng.alloc_device(bytes.len() as u64) {
                                Ok(buf) => eng.upload(&buf, bytes).map(|_| buf),
                                Err(e) => Err(e),
                            }
                        } else {
                            eng.alloc_host_coherent_storage(bytes.len() as u64).map(|buf| {
                                unsafe {
                                    std::ptr::copy_nonoverlapping(
                                        bytes.as_ptr(), buf.mapped_ptr.unwrap() as *mut u8, bytes.len());
                                }
                                #[cfg(unix)]
                                if let Some(ptr) = buf.mapped_ptr {
                                    let rc = unsafe {
                                        libc::mlock(ptr as *const libc::c_void, bytes.len())
                                    };
                                    if rc != 0 {
                                        log::warn!(
                                            "mlock of {}-byte gemma4 (31B) weight failed ({}); \
                                             weight pages remain swappable",
                                            bytes.len(), std::io::Error::last_os_error());
                                    }
                                }
                                buf
                            })
                        }
                    }

                    let mut gpu_weights: HashMap<String, GpuWeight> = HashMap::new();
                    let mut gpu_bytes_total = 0u64;
                    let quant_q8 = flags.quant == QuantFormat::Q8_0;
                    // LEVER 2: requant FP8 attn weights -> q8_0 at load (see the
                    // ProjWeight::Fp8 arm below). Captured as a plain bool so the
                    // `on_proj` closure needn't borrow all of `flags`.
                    let gemma_fp8_q8 = flags.gemma_fp8_q8;

                    // Streaming sink: NVFP4/FP8 offered packed (no f32
                    // dequant) when the flag+engine allow it; F32 (the
                    // unquantized norms/layer_scalar-adjacent path never
                    // reaches here — only matvec projections are offered)
                    // gets q8_0-requantized on upload. Declining (`Dequantize`)
                    // falls through to the exact same dequant the loader
                    // already did without this sink.
                    let on_proj = |name: &str, w: model::ProjWeight| -> model::ProjResult {
                        match w {
                            model::ProjWeight::Nvfp4(nv) => {
                                if !nvfp4_gpu_g31b { return model::ProjResult::Dequantize; }
                                let eng = match engine_opt.as_mut() {
                                    Some(e) => e, None => return model::ProjResult::Dequantize };
                                // TP: head/intermediate-aware shard (packed nibbles +
                                // matching NVFP4 group scales) BEFORE upload — mlp
                                // gate/up/down are the only NVFP4 tensors in this
                                // checkpoint (attn is always FP8; see tp.rs doc comment).
                                // e4m3-resident vs f32-fold: same generic shard, byte
                                // vs f32 scale element (see the qwen loader arm).
                                let (packed, sbytes, global) = if nvfp4_e4m3_g31b {
                                    let (packed, scale8, _o, _i) = gemma_nvfp4_tp_shard(
                                        name, nv.packed, nv.wscale, nv.out_features, nv.in_features,
                                        nv.group_size, g31b_tp_rank, g31b_tp_size);
                                    (packed, scale8, nv.global)
                                } else {
                                    let folded = nvfp4_fold_scales(nv.wscale, nv.global);
                                    let (packed, scales, _o, _i) = gemma_nvfp4_tp_shard(
                                        name, nv.packed, &folded, nv.out_features, nv.in_features,
                                        nv.group_size, g31b_tp_rank, g31b_tp_size);
                                    (packed, f32_slice_to_bytes(&scales), 1.0f32)
                                };
                                let pbuf = match g31b_upload_bytes(eng, &packed, dw_g31b) {
                                    Ok(b) => b,
                                    Err(e) => { log::warn!("gemma4 (31B) nvfp4 packed upload '{name}': {e}");
                                                return model::ProjResult::Dequantize; } };
                                let sbuf = match g31b_upload_bytes(eng, &sbytes, dw_g31b) {
                                    Ok(b) => b,
                                    Err(e) => { log::warn!("gemma4 (31B) nvfp4 scale upload '{name}': {e}");
                                                return model::ProjResult::Dequantize; } };
                                gpu_bytes_total += (packed.len() + sbytes.len()) as u64;
                                gpu_weights.insert(name.to_string(), GpuWeight {
                                    buffer: pbuf, format: QuantFormat::Nvfp4,
                                    aux: Some(QuantAux::Nvfp4 { scales: sbuf,
                                        group_size: nv.group_size as u32,
                                        e4m3: nvfp4_e4m3_g31b, global }),
                                });
                                model::ProjResult::Consumed
                            }
                            model::ProjWeight::Fp8(fp) => {
                                if !nvfp4_gpu_g31b { return model::ProjResult::Dequantize; }
                                let eng = match engine_opt.as_mut() {
                                    Some(e) => e, None => return model::ProjResult::Dequantize };
                                // TP: head-aware shard (unpacked bytes + the matching
                                // per-row scale slice, or the per-tensor scalar
                                // unchanged) BEFORE upload — covers attn q/k/v/o on
                                // every layer plus the FP8-exception mlp layers.
                                let (wbytes, scales, out_f, in_f) = gemma_fp8_tp_shard(
                                    name, fp.weight, &fp.scale, fp.out_features, fp.in_features,
                                    &g31b_tp_cfg, g31b_tp_rank, g31b_tp_size);
                                // LEVER 2 (VLLM_VULKAN_GEMMA_FP8_Q8): requant this
                                // rank's FP8 attn shard to q8_0 so decode dispatches
                                // the cheaper `mul_mat_vec_q8_0deq_f32_f32` instead
                                // of the ALU-heavy e4m3 dequant-matvec. Gated to
                                // self_attn.* (q/k/v/o_proj — the `gemma_attn_mv`
                                // targets) whose (out*in)%32==0 (q8_0 block). Same
                                // nemotron mamba-q8 pattern; q8_0 ≈ fp8 footprint so
                                // no GTT increase. Falls through to the FP8 upload on
                                // a size miss or upload failure.
                                if gemma_fp8_q8
                                    && name.contains("self_attn")
                                    && (out_f * in_f) % 32 == 0
                                {
                                    let deq = model::dequantize_fp8(&wbytes, &scales, out_f, in_f);
                                    let q8 = model::quantize_q8_0(&deq);
                                    match g31b_upload_bytes(eng, &q8, dw_g31b) {
                                        Ok(buf) => {
                                            gpu_bytes_total += q8.len() as u64;
                                            gpu_weights.insert(name.to_string(), GpuWeight {
                                                buffer: buf, format: QuantFormat::Q8_0, aux: None,
                                            });
                                            return model::ProjResult::Consumed;
                                        }
                                        Err(e) => log::warn!(
                                            "gemma4 (31B) fp8->q8_0 requant upload '{name}': {e}; keeping fp8"),
                                    }
                                }
                                let sbytes = f32_slice_to_bytes(&scales);
                                let per_row = scales.len() > 1;
                                let wbuf = match g31b_upload_bytes(eng, &wbytes, dw_g31b) {
                                    Ok(b) => b,
                                    Err(e) => { log::warn!("gemma4 (31B) fp8 weight upload '{name}': {e}");
                                                return model::ProjResult::Dequantize; } };
                                let sbuf = match g31b_upload_bytes(eng, &sbytes, dw_g31b) {
                                    Ok(b) => b,
                                    Err(e) => { log::warn!("gemma4 (31B) fp8 scale upload '{name}': {e}");
                                                return model::ProjResult::Dequantize; } };
                                gpu_bytes_total += (wbytes.len() + sbytes.len()) as u64;
                                gpu_weights.insert(name.to_string(), GpuWeight {
                                    buffer: wbuf, format: QuantFormat::Fp8,
                                    aux: Some(QuantAux::Fp8 { scale: sbuf, per_row }),
                                });
                                model::ProjResult::Consumed
                            }
                            model::ProjWeight::F32(data) => {
                                // TP: shard the (already-dequantized) projection to
                                // this rank's slice first — the fallback path when
                                // NVFP4/FP8 declined the packed form above.
                                let data = gemma_tp_shard_f32(name, data, &g31b_tp_cfg, g31b_tp_rank, g31b_tp_size);
                                if let Some(eng) = engine_opt.as_mut() {
                                    if data.len() % 32 == 0 && quant_q8 {
                                        let bytes = model::quantize_q8_0(&data);
                                        match g31b_upload_bytes(eng, &bytes, dw_g31b) {
                                            Ok(buf) => {
                                                gpu_bytes_total += bytes.len() as u64;
                                                gpu_weights.insert(name.to_string(),
                                                    GpuWeight { buffer: buf, format: QuantFormat::Q8_0, aux: None });
                                                if lean_g31b {
                                                    return model::ProjResult::Consumed;
                                                }
                                            }
                                            Err(e) => log::warn!(
                                                "gemma4 (31B) F32 GPU upload '{name}' failed ({e}); keeping f32 host copy"),
                                        }
                                    }
                                }
                                model::ProjResult::KeepF32(data)
                            }
                            model::ProjWeight::Mlx4(_) => model::ProjResult::Dequantize, // not present in this checkpoint
                        }
                    };

                    let g31b_dir = path.parent().unwrap_or_else(|| Path::new("."));
                    let (mut host_f32, mut g31b_f16_host) =
                        model::load_gemma_nvfp4_weights(g31b_dir, g_start, g_end, on_proj)
                            .map_err(PyRuntimeError::new_err)?;

                    // ── Last-stage LM-head GPU residency (PP whole-table + TP shard) ─
                    // The tied embed/lm_head is loaded f16 on the HOST. Its lm_head
                    // projection — `cpu_matmul` over the f16→f32-widened table on the
                    // weak BC-250 CPU — is the whole last-stage decode cost: ~4020ms
                    // for the PP whole-table (262144×5376) and ~1000ms for a TP
                    // per-rank shard (65536×5376). Upload the f16 weight to a GPU
                    // buffer ONCE at load so the existing GPU f16 matvec runs it
                    // on-device. Two shapes, one flag:
                    //   • PP / single node (tp_size==1): the WHOLE table, consumed by
                    //     `gemma_final` (keyed off gpu_weights["model.embed_tokens.weight"],
                    //     matvec_variant(true, vocab)).
                    //   • TP (tp_size>1): only THIS rank's [lo,lo+per) vocab shard,
                    //     consumed by `gemma_tp_lmhead_logits` via `gemma_matvec`
                    //     (matvec_variant(true, per)) before the existing all_gather.
                    // Both dispatch the f16 shader on the GLOBAL quant_format(), so
                    // the upload is F16-dispatch-only (a non-f16 quant would read the
                    // f16 buffer as q8/etc → garbage): skip+log otherwise.
                    // Default ON; VLLM_VULKAN_GEMMA_GPU_LMHEAD=0 restores CPU for A/B.
                    let gpu_lmhead_g31b = std::env::var("VLLM_VULKAN_GEMMA_GPU_LMHEAD")
                        .map(|v| v != "0").unwrap_or(true);
                    let g31b_last = g_end >= total_layers;
                    let g31b_first = g_start == 0;
                    if gpu_lmhead_g31b && g31b_last {
                        let f16_dispatch = matches!(flags.quant, QuantFormat::F16);
                        let have_embed = g31b_f16_host.contains_key("model.embed_tokens.weight");
                        if f16_dispatch && have_embed {
                            if let Some(eng) = engine_opt.as_mut() {
                                let hdim = cfg.hidden_size;
                                let vocab = cfg.vocab_size;
                                let f16v = &g31b_f16_host["model.embed_tokens.weight"];
                                // Whole table (tp==1) vs this rank's vocab shard (tp>1).
                                let (lo, per) = if g31b_tp_size == 1 {
                                    (0usize, vocab)
                                } else {
                                    tp::tp_vocab_shard_range(vocab, g31b_tp_rank, g31b_tp_size)
                                };
                                // f16 host bits (u16 LE) → raw bytes; no transient f32
                                // blow-up (shard = ~0.7GB/rank, whole = ~2.8GB).
                                let slice = &f16v[lo * hdim..(lo + per) * hdim];
                                let mut bytes = vec![0u8; slice.len() * 2];
                                for (dst, &w) in bytes.chunks_exact_mut(2).zip(slice.iter()) {
                                    dst.copy_from_slice(&w.to_le_bytes());
                                }
                                match g31b_upload_bytes(eng, &bytes, dw_g31b) {
                                    Ok(buf) => {
                                        gpu_bytes_total += bytes.len() as u64;
                                        gpu_weights.insert("model.embed_tokens.weight".to_string(),
                                            GpuWeight { buffer: buf, format: QuantFormat::F16, aux: None });
                                        if g31b_tp_size == 1 {
                                            log::info!(
                                                "gemma4 (31B): GPU LM-head resident (f16 embed {:.2}GB on last stage)",
                                                bytes.len() as f64 / 1e9);
                                            // Last-but-not-first PP stage: the host f16
                                            // embed was kept ONLY for the (now GPU)
                                            // lm_head — drop it so the last stage doesn't
                                            // pay +2.8GB host (the OOM lever). GPU buffer
                                            // becomes the sole copy (net-zero memory).
                                            // Keep on first==last single node (token
                                            // embedding still reads it host-side).
                                            if !g31b_first
                                                && g31b_f16_host.remove("model.embed_tokens.weight").is_some() {
                                                log::info!(
                                                    "gemma4 (31B): dropped f16 embed host copy on lm_head-only stage");
                                            }
                                        } else {
                                            log::info!(
                                                "gemma4 (31B) TP: GPU LM-head shard [{lo},{}) of {vocab} resident \
                                                 ({:.2}GB/rank)", lo + per, bytes.len() as f64 / 1e9);
                                            // Do NOT drop the host f16 embed here: a TP
                                            // rank is first==last, so it still needs the
                                            // WHOLE table for gemma_embed_and_ple's
                                            // per-token row lookup (forward_tp_gemma).
                                        }
                                    }
                                    Err(e) => {
                                        // ATTEMPTED-and-FAILED (this rank IS an f16 dispatch
                                        // config that wanted the GPU lm_head): a real upload
                                        // error, NOT the by-design non-f16 skip below. Fail
                                        // loud so it does not degrade to the ~4020ms/token
                                        // (whole-table) single-core CPU cpu_matmul unnoticed.
                                        let msg = format!(
                                            "gemma4 (31B) GPU LM-head upload FAILED: {e}. Continuing would \
                                             silently degrade the last stage to a single-core host cpu_matmul \
                                             over the full vocab (~4020ms/token whole-table). Set \
                                             VLLM_VULKAN_STRICT_GPU_LMHEAD=0 to allow the host fallback.");
                                        if strict_gpu_lmhead() {
                                            return Err(PyRuntimeError::new_err(msg));
                                        }
                                        log::error!("{msg}");
                                    }
                                }
                            }
                        } else if !f16_dispatch {
                            log::info!(
                                "gemma4 (31B): GPU LM-head skipped (VLLM_VULKAN_QUANT={:?} != F16; \
                                 dispatch shader would mismatch the f16 embed)", flags.quant);
                        }
                    }

                    let mut host_bytes = 0u64;
                    for v in host_f32.values() { host_bytes += (v.len() * 4) as u64; }
                    let f16_bytes: u64 = g31b_f16_host.values().map(|v| (v.len() * 2) as u64).sum();
                    log::info!(
                        "gemma4 (31B): GPU {:.2}GB ({} bufs); host f32 {:.2}GB + f16 embed {:.2}GB",
                        gpu_bytes_total as f64 / 1e9, gpu_weights.len(), host_bytes as f64 / 1e9,
                        f16_bytes as f64 / 1e9);

                    let host_tensors: HashMap<String, model::SimpleTensor> = host_f32.drain()
                        .map(|(k, v)| (k, model::SimpleTensor { data: v, shape: vec![] }))
                        .collect();
                    let weights = model::ModelWeights { tensors: host_tensors };

                    // Per-layer KV sizing (Phase-0 host half): see the g12b site
                    // above. Sliding layers get a `window`-sized ring; full
                    // layers stay max_seq (byte-identical to the old `new`).
                    // Gated by VLLM_VULKAN_KV_RING_DISABLE to co-engage with the
                    // GPU-resident ring.
                    let kv_caches: Vec<model::KvCache> = (0..total_layers)
                        .map(|l| {
                            let cap = if flags.kv_ring_disable {
                                max_seq_len
                            } else {
                                cfg.layer_kv_capacity(l, max_seq_len)
                            };
                            model::KvCache::new_windowed(max_seq_len, cap, cfg.layer_num_kv_heads(l), cfg.layer_head_dim(l))
                        })
                        .collect();

                    let inner = model::Gemma4Model { config: cfg, weights, kv_caches };

                    let vm = VulkanModel {
                        inner,
                        qwen: None,
                        qwen35: None,
                        step3p7: None,
                        max_seq_len,
                        engine: engine_opt,
                        gpu_weights,
                        act_bufs: Vec::new(),
                        act_bufs_ready: false,
                        pp_start: g_start,
                        pp_end: g_end,
                        pp_first: g_start == 0,
                        pp_last: g_end >= total_layers,
                        // The loader shards every projection with
                        // `g31b_tp_rank`/`g31b_tp_size` (from VLLM_VULKAN_TP_RANK/
                        // _SIZE), but this struct previously hardcoded 0/1 — so
                        // `forward_tp_gemma`/`gemma_attn_tp` read `self.tp_size == 1`
                        // (n=1) and dispatched FULL-width matvecs against 1/N-sized
                        // sharded buffers (OOB reads → garbage, no panic → silently
                        // incoherent TP-4 decode), and `q_head_offset =
                        // self.tp_rank*r_num_q` was stuck at rank 0's heads on every
                        // rank. Wire the runtime tp identity to the SAME env values
                        // the loader sharded with (mirrors the qwen3_5 loader).
                        tp_rank: g31b_tp_rank,
                        tp_size: g31b_tp_size,
                        gemma_ple_bf16: None,
                        gpu_kv: std::collections::HashMap::new(),
                        gemma_kv_filled: 0,
                        qres_bufs: Vec::new(),
                        qres_ready: false,
                        gpu_norm_w: std::collections::HashMap::new(),
                        gres_bufs: Vec::new(),
                        gres_ready: false,
                        gemma_norm_w: std::collections::HashMap::new(),
                        ures_bufs: Vec::new(),
                        ures_ready: false,
                        unified_norm_w: std::collections::HashMap::new(),
                        bres_bufs: Vec::new(),
                        bres_ready: false,
                        q35_f16_host: g31b_f16_host,
                        collective_comm: 0,
                        reduce_scratch: Vec::new(),
                        reduce_scratch_handle: 0,
                        pp_tok_ring: PpTokRing::default(),
                        pp_hop_send: PpTokRing::default(),
                        pp_hop_recv: PpTokRing::default(),
                        pp_vocab_ring: PpTokRing::default(),
            gemma_hidden_ring: std::collections::VecDeque::new(),
                        gemma_pp_hop: Default::default(),
                        moe_gpu: std::collections::HashMap::new(),
                        moe_shared_gpu: std::collections::HashMap::new(),
                        dn_gpu: std::collections::HashMap::new(),
                        q35res_bufs: Vec::new(),
                        q35res_ready: false,
                        q35res_ok: None,
                        spec_slots: Vec::new(),
                        flags,
                        lm_shard: None,
                        chunked_weights: std::collections::HashMap::new(),
                        nemotron: None,
                        nemotron_mtp_head: None,
                        kimi: None,
                        ling: None,
                        laguna: None,
                        laguna_gpu: None,
                        mtp_head: None,
                        mtp_moe_gpu: None,
                        q35_last_prenorm: None,
                        q35_prenorm_ring: std::collections::VecDeque::new(),
                        spec_verify_gdn_inputs: Vec::new(),
                        spec_verify_span: None,
                        spec_verify_cols: false,
                        kv_store: None,
                    };
                    return Ok(vm);
                }
            }
        }

        // ── Laguna-S-2.1-NVFP4 path ─────────────────────────────────────────
        // Detect by model_type == "laguna" (`poolside/Laguna-S-2.1-NVFP4`, a
        // hybrid YaRN/sliding-attention + per-head softplus-gate + NVFP4 top-10
        // MoE model). CPU-only for now (see the `laguna` field doc on
        // `VulkanModel`): the pure-`cpu_matmul` reference
        // `laguna::load_laguna_weights_cpu` reads the checkpoint's
        // `model.safetensors.index.json` (the current 15-shard layout — it never
        // assumes a shard count), dequantizes BF16→f32 for the
        // attn/norm/dense/router/shared/embed/lm tensors and keeps the routed
        // experts PACKED (NVFP4 nibbles + F8_E4M3 group-16 scales + F32
        // reciprocal global) as 3 contiguous qwen35-shape buffers/layer for
        // top-10 dequant-on-demand. The `.mlp.experts.e_score_correction_bias`
        // router bias is loaded (NOT `.gate.*`), and input_global_scale/k/v
        // scales are skipped (W4A16). The GPU-resident expert path (qwen35_moe
        // kernels) + full 48-layer load + PP-8..10 sharding is the
        // node-count-blocked later phase, mirroring how qwen3.6/nemotron added
        // GPU only after their CPU loaders landed.
        if let Ok(cfg_text) = std::fs::read_to_string(&config_path) {
            if let Ok(cfg_json) = serde_json::from_str::<serde_json::Value>(&cfg_text) {
                let mt = cfg_json.get("model_type").and_then(|v| v.as_str()).unwrap_or("");
                #[cfg(feature = "laguna")]
                if mt == "laguna" {
                    let cfg = laguna::LagunaConfig::from_json(&cfg_json)
                        .map_err(PyRuntimeError::new_err)?;
                    let total_layers = cfg.num_hidden_layers;
                    let lag_start = layer_start.unwrap_or(0);
                    let lag_end = layer_end.unwrap_or(total_layers).min(total_layers);
                    // STANDALONE gate: force a partial [0,K) window to be BOTH
                    // first and last (embed + lm_head) for a comm-free single-node
                    // free-gen repro. Mirrors LagunaGpuModel::load's own override.
                    let lag_standalone = std::env::var("VLLM_VULKAN_LAGUNA_STANDALONE")
                        .map(|v| v != "0").unwrap_or(false);
                    let lag_first = lag_standalone || lag_start == 0;
                    let lag_last = lag_standalone || lag_end >= total_layers;
                    // The checkpoint dir (index.json + shards) is the weights'
                    // parent directory.
                    let dir = path.parent().unwrap_or_else(|| Path::new("."));

                    // ── GPU-RESIDENT branch (VLLM_VULKAN_LAGUNA_RESIDENT) ──────
                    // Quantized-resident `[lag_start, lag_end)` window + GPU
                    // matvec forward (LagunaGpuModel, owns its engine). Supports
                    // an arbitrary window (unlike the CPU loader below, which
                    // forces start 0), so it is the PP path too. Hard-errors
                    // without a device.
                    if crate::flags::flags_global().laguna_resident {
                        log::info!(
                            "Loading Laguna-S-2.1-NVFP4 RESIDENT: layers [{lag_start},{lag_end}) of \
                             {total_layers}, {} experts top-{} (first={lag_first} last={lag_last}) from {}",
                            cfg.num_experts, cfg.num_experts_per_tok, safetensors_path);
                        let dev = device::ComputeDevice::create(device_idx)
                            .map_err(|e| PyRuntimeError::new_err(format!(
                                "laguna resident needs a Vulkan device: {e}")))?;
                        let shader_spvs = include_all_shaders();
                        let refs: HashMap<&str, &[u8]> = shader_spvs.iter()
                            .map(|(k, v)| (k.as_str(), v.as_slice())).collect();
                        let engine = compute::ComputeEngine::new(
                            dev.instance.clone(), dev.physical_device, dev.device.clone(),
                            dev.compute_queue, dev.compute_queue_family, dev.caps(), &refs)
                            .map_err(PyRuntimeError::new_err)?;
                        let gpu = laguna_gpu::LagunaGpuModel::load(
                            path, cfg, engine, lag_start, lag_end, max_seq_len,
                        ).map_err(|e| PyRuntimeError::new_err(
                            format!("laguna resident loader failed: {e}")))?;
                        log::info!(
                            "Laguna-S-2.1-NVFP4 RESIDENT loaded: {} f16 tensors + {} MoE-layer \
                             expert holders + {} host tensors",
                            gpu.gpu_weights.len(), gpu.gpu_experts.len(), gpu.host.len());
                        let placeholder = carve_placeholder_inner();
                        return Ok(VulkanModel {
                            inner: placeholder,
                            qwen: None,
                            qwen35: None,
                            step3p7: None,
                            max_seq_len,
                            engine: None,
                            gpu_weights: HashMap::new(),
                            act_bufs: Vec::new(),
                            act_bufs_ready: false,
                            pp_start: lag_start,
                            pp_end: lag_end,
                            pp_first: lag_first,
                            pp_last: lag_last,
                            tp_rank: 0,
                            tp_size: 1,
                            gemma_ple_bf16: None,
                            gpu_kv: std::collections::HashMap::new(),
                            gemma_kv_filled: 0,
                            qres_bufs: Vec::new(),
                            qres_ready: false,
                            gpu_norm_w: std::collections::HashMap::new(),
                            gres_bufs: Vec::new(),
                            gres_ready: false,
                            gemma_norm_w: std::collections::HashMap::new(),
                            ures_bufs: Vec::new(),
                            ures_ready: false,
                            unified_norm_w: std::collections::HashMap::new(),
                            bres_bufs: Vec::new(),
                            bres_ready: false,
                            q35_f16_host: std::collections::HashMap::new(),
                            collective_comm: 0,
                            reduce_scratch: Vec::new(),
                            reduce_scratch_handle: 0,
                            pp_tok_ring: PpTokRing::default(),
                            pp_hop_send: PpTokRing::default(),
                            pp_hop_recv: PpTokRing::default(),
                            pp_vocab_ring: PpTokRing::default(),
                            moe_gpu: std::collections::HashMap::new(),
                            moe_shared_gpu: std::collections::HashMap::new(),
                            dn_gpu: std::collections::HashMap::new(),
                            q35res_bufs: Vec::new(),
                            q35res_ready: false,
                            q35res_ok: None,
                            spec_slots: Vec::new(),
                            flags: Flags::from_env(),
                            lm_shard: None,
                            chunked_weights: std::collections::HashMap::new(),
                            gemma_hidden_ring: std::collections::VecDeque::new(),
                            gemma_pp_hop: Default::default(),
                            nemotron: None,
                            nemotron_mtp_head: None,
                            kimi: None,
                            ling: None,
                            laguna: None,
                            laguna_gpu: Some(gpu),
                            mtp_head: None,
                            mtp_moe_gpu: None,
                            q35_last_prenorm: None,
                            q35_prenorm_ring: std::collections::VecDeque::new(),
                            spec_verify_gdn_inputs: Vec::new(),
                            spec_verify_span: None,
                            spec_verify_cols: false,
                            kv_store: None,
                        });
                    }

                    // Phase-1 CPU loader materializes layers [0, lag_end); a true
                    // [lag_start, lag_end) PP window is deferred to the GPU phase,
                    // so a non-zero lag_start is rejected rather than silently
                    // loading from layer 0.
                    if lag_start != 0 {
                        return Err(PyRuntimeError::new_err(format!(
                            "laguna: PP layer_start={lag_start} not supported by the \
                             Phase-1 CPU loader (loads [0,{lag_end})); range/PP sharding \
                             is the node-count-blocked GPU phase")));
                    }
                    log::info!(
                        "Loading Laguna-S-2.1-NVFP4: layers [0,{lag_end}) of {total_layers}, \
                         hidden {}, {} experts top-{} (first={lag_first} last={lag_last}) from {}",
                        cfg.hidden_size, cfg.num_experts, cfg.num_experts_per_tok,
                        safetensors_path);
                    let lag_model = laguna::LagunaModel::load_cpu(
                        dir, cfg, lag_start, lag_end, lag_last,
                    ).map_err(|e| PyRuntimeError::new_err(
                        format!("laguna loader failed: {e}")))?;
                    log::info!(
                        "Laguna-S-2.1-NVFP4: {} layers loaded (CPU reference forward; \
                         GPU-resident experts + PP deferred)",
                        lag_model.weights.layers.len());
                    let placeholder = carve_placeholder_inner();
                    return Ok(VulkanModel {
                        inner: placeholder,
                        qwen: None,
                        qwen35: None,
                        step3p7: None,
                        max_seq_len,
                        engine: None,
                        gpu_weights: HashMap::new(),
                        act_bufs: Vec::new(),
                        act_bufs_ready: false,
                        pp_start: lag_start,
                        pp_end: lag_end,
                        pp_first: lag_first,
                        pp_last: lag_last,
                        tp_rank: 0,
                        tp_size: 1,
                        gemma_ple_bf16: None,
                        gpu_kv: std::collections::HashMap::new(),
                        gemma_kv_filled: 0,
                        qres_bufs: Vec::new(),
                        qres_ready: false,
                        gpu_norm_w: std::collections::HashMap::new(),
                        gres_bufs: Vec::new(),
                        gres_ready: false,
                        gemma_norm_w: std::collections::HashMap::new(),
                        ures_bufs: Vec::new(),
                        ures_ready: false,
                        unified_norm_w: std::collections::HashMap::new(),
                        bres_bufs: Vec::new(),
                        bres_ready: false,
                        q35_f16_host: std::collections::HashMap::new(),
                        collective_comm: 0,
                        reduce_scratch: Vec::new(),
                        reduce_scratch_handle: 0,
                        pp_tok_ring: PpTokRing::default(),
                        pp_hop_send: PpTokRing::default(),
                        pp_hop_recv: PpTokRing::default(),
                        pp_vocab_ring: PpTokRing::default(),
                        moe_gpu: std::collections::HashMap::new(),
                        moe_shared_gpu: std::collections::HashMap::new(),
                        dn_gpu: std::collections::HashMap::new(),
                        q35res_bufs: Vec::new(),
                        q35res_ready: false,
                        q35res_ok: None,
                        spec_slots: Vec::new(),
                        flags: Flags::from_env(),
                        lm_shard: None,
                        chunked_weights: std::collections::HashMap::new(),
                        gemma_hidden_ring: std::collections::VecDeque::new(),
                        gemma_pp_hop: Default::default(),
                        nemotron: None,
                        nemotron_mtp_head: None,
                        kimi: None,
                        ling: None,
                        laguna: Some(lag_model),
                        laguna_gpu: None,
                        mtp_head: None,
                        mtp_moe_gpu: None,
                        q35_last_prenorm: None,
                        q35_prenorm_ring: std::collections::VecDeque::new(),
                        spec_verify_gdn_inputs: Vec::new(),
                        spec_verify_span: None,
                        spec_verify_cols: false,
                        kv_store: None,
                    });
                }
            }
        }

        // ── Ling-3.0-flash / BailingMoeV3 path (offline scaffold) ───────────
        // Detect by model_type == "bailing_hybrid" (inclusionAI Ling-3.0-flash:
        // 42-layer Kimi-Linear-class hybrid — 35 KDA + 7 MLA layers, 512-expert
        // top-8 grouped-topk MoE, INT4-symmetric compressed-tensors experts). The
        // arch is REGISTERED + its config VALIDATED (LingConfig parse + schedule),
        // then a PP window `[layer_start,layer_end)` is loaded through
        // `ling::LingModel::load_cpu` (int4-sym experts held quant-resident via the
        // bit-exact `int4_symmetric_to_mlx4` path). The CPU-reference window forward
        // runs (`forward_pp_bailing_prefill`); the resident GPU decode is the
        // cluster follow-on (docs/ling-3.0-flash-int4-bringup.md). Loading requires
        // the on-disk checkpoint. Fail LOUD (never silent-falls-through to gemma).
        if let Ok(cfg_text) = std::fs::read_to_string(&config_path) {
            if let Ok(cfg_json) = serde_json::from_str::<serde_json::Value>(&cfg_text) {
                let mt = cfg_json.get("model_type").and_then(|v| v.as_str()).unwrap_or("");
                let arch0 = cfg_json.get("architectures")
                    .and_then(|a| a.get(0)).and_then(|v| v.as_str()).unwrap_or("");
                #[cfg(feature = "ling")]
                if mt == "bailing_hybrid" || arch0.starts_with("BailingMoeV3") {
                    let cfg = ling::LingConfig::from_json(&cfg_json)
                        .map_err(PyRuntimeError::new_err)?;
                    let total_layers = cfg.num_hidden_layers;
                    let l_start = layer_start.unwrap_or(0);
                    let l_end = layer_end.unwrap_or(total_layers).min(total_layers);
                    if l_start >= l_end || l_end > total_layers {
                        return Err(PyRuntimeError::new_err(format!(
                            "bailing_hybrid: bad PP window [{l_start},{l_end}) for {total_layers} layers")));
                    }
                    let l_first = l_start == 0;
                    let l_last = l_end >= total_layers;
                    let ckpt_dir = path.parent().map(|p| p.to_string_lossy().to_string())
                        .unwrap_or_else(|| ".".to_string());
                    log::info!(
                        "Loading Ling/BailingMoeV3 ({mt}): PP window [{l_start},{l_end}) of \
                         {total_layers} layers (MLA at {:?}), {} experts top-{} grouped-topk \
                         (n_group={} topk_group={}), hidden {}, INT4-sym experts from {ckpt_dir}",
                        cfg.mla_layers(), cfg.num_experts, cfg.num_experts_per_token,
                        cfg.n_group, cfg.topk_group, cfg.hidden_size);
                    // Perf port: VLLM_VULKAN_LING_GPU_RESIDENT=1 uploads the window to
                    // the GPU (KDA + MoE + dense + lm_head resident; MLA host seam);
                    // else the CPU-resident decode (the bit-exact oracle) runs.
                    // DEFAULT-ON for the ling arch (the validated 45.9 ms/tok GPU-resident
                    // stack); set =0/false to fall back to the CPU-resident bit-exact oracle.
                    let ling_gpu = std::env::var("VLLM_VULKAN_LING_GPU_RESIDENT")
                        .map(|v| v != "0" && v != "false").unwrap_or(true);
                    let ling_model = if ling_gpu {
                        ling::LingModel::load_gpu_resident(
                            &ckpt_dir, &cfg, l_start, l_end, l_first || l_last, device_idx)
                            .map_err(PyRuntimeError::new_err)?
                    } else {
                        ling::LingModel::load_cpu(
                            &ckpt_dir, &cfg, l_start, l_end, l_first || l_last)
                            .map_err(PyRuntimeError::new_err)?
                    };
                    let placeholder = carve_placeholder_inner();
                    return Ok(VulkanModel {
                        inner: placeholder,
                        qwen: None,
                        qwen35: None,
                        step3p7: None,
                        max_seq_len,
                        engine: None,
                        gpu_weights: HashMap::new(),
                        act_bufs: Vec::new(),
                        act_bufs_ready: false,
                        pp_start: l_start,
                        pp_end: l_end,
                        pp_first: l_first,
                        pp_last: l_last,
                        tp_rank: 0,
                        tp_size: 1,
                        gemma_ple_bf16: None,
                        gpu_kv: std::collections::HashMap::new(),
                        gemma_kv_filled: 0,
                        qres_bufs: Vec::new(),
                        qres_ready: false,
                        gpu_norm_w: std::collections::HashMap::new(),
                        gres_bufs: Vec::new(),
                        gres_ready: false,
                        gemma_norm_w: std::collections::HashMap::new(),
                        ures_bufs: Vec::new(),
                        ures_ready: false,
                        unified_norm_w: std::collections::HashMap::new(),
                        bres_bufs: Vec::new(),
                        bres_ready: false,
                        q35_f16_host: std::collections::HashMap::new(),
                        collective_comm: 0,
                        reduce_scratch: Vec::new(),
                        reduce_scratch_handle: 0,
                        pp_tok_ring: PpTokRing::default(),
                        pp_hop_send: PpTokRing::default(),
                        pp_hop_recv: PpTokRing::default(),
                        pp_vocab_ring: PpTokRing::default(),
                        moe_gpu: std::collections::HashMap::new(),
                        moe_shared_gpu: std::collections::HashMap::new(),
                        dn_gpu: std::collections::HashMap::new(),
                        q35res_bufs: Vec::new(),
                        q35res_ready: false,
                        q35res_ok: None,
                        spec_slots: Vec::new(),
                        flags: Flags::from_env(),
                        lm_shard: None,
                        chunked_weights: std::collections::HashMap::new(),
                        gemma_hidden_ring: std::collections::VecDeque::new(),
                        gemma_pp_hop: Default::default(),
                        nemotron: None,
                        nemotron_mtp_head: None,
                        kimi: None,
                        ling: Some(ling_model),
                        laguna: None,
                        laguna_gpu: None,
                        mtp_head: None,
                        mtp_moe_gpu: None,
                        q35_last_prenorm: None,
                        q35_prenorm_ring: std::collections::VecDeque::new(),
                        spec_verify_gdn_inputs: Vec::new(),
                        spec_verify_span: None,
                        spec_verify_cols: false,
                        kv_store: None,
                    });
                }
            }
        }

        // ── Nemotron-H-Puzzle path ──────────────────────────────────────────
        // Detect by model_type == "kimi_linear" (Kimi-Linear-48B-A3B, Moonshot:
        // KDA + MLA + sigmoid-router MoE). CPU reference assembly (P4½): loads a
        // single PP window through the mlx4 `[start,end)` window loader
        // (`kimi::KimiModel::load_cpu`) and runs the 27-layer heterogeneous forward
        // dispatched per the `KimiConfig` schedule. Non-zero PP `layer_start` is
        // rejected here — the window loader exists, but the multi-stage
        // forward/comm wiring is the P5 cluster follow-on (mirrors how the qwen3.6
        // / nemotron GPU + PP paths were added only after their CPU loaders landed).
        if let Ok(cfg_text) = std::fs::read_to_string(&config_path) {
            if let Ok(cfg_json) = serde_json::from_str::<serde_json::Value>(&cfg_text) {
                let mt = cfg_json.get("model_type").and_then(|v| v.as_str()).unwrap_or("");
                #[cfg(feature = "kimi")]
                if mt == "kimi_linear" {
                    let cfg = kimi::KimiConfig::from_json(&cfg_json)
                        .map_err(PyRuntimeError::new_err)?;
                    let total_layers = cfg.num_hidden_layers;
                    let k_start = layer_start.unwrap_or(0);
                    let k_end = layer_end.unwrap_or(total_layers).min(total_layers);
                    // PP: a non-zero `layer_start` loads a mid/tail stage window. The
                    // `[start,end)` window loader supports it; each stage runs its
                    // resident sub-forward (`KimiModel::forward_pp_stage`) and ships
                    // the [H] hidden over vCCL (`forward_pp_kimi`/`pp_step_kimi`).
                    // NOTE: the CPU `forward_pp_stage` dequantizes MoE experts to f32
                    // (~7GB/MoE layer) — fine for small windows / the shard-1 gate, but
                    // a full-Kimi cluster stage needs the GPU quant-resident decode
                    // (packed experts, dequant only the selected top-8) to fit 14GB
                    // nodes; that GPU-resident path is the remaining Phase-C build.
                    if k_start >= k_end || k_end > total_layers {
                        return Err(PyRuntimeError::new_err(format!(
                            "kimi_linear: bad PP window [{k_start},{k_end}) for {total_layers} layers")));
                    }
                    let ckpt_dir = path
                        .parent()
                        .map(|p| p.to_string_lossy().to_string())
                        .unwrap_or_else(|| ".".to_string());
                    let k_first = k_start == 0;
                    let k_last = k_end >= total_layers;
                    log::info!(
                        "Loading Kimi-Linear ({mt}): PP window [{k_start},{k_end}) of {total_layers} \
                         layers, hidden {} (first={k_first} last={k_last}) from {ckpt_dir}",
                        cfg.hidden_size);
                    // Load the edges this stage OWNS: embed on the first stage,
                    // final_norm+lm_head on the last (load_cpu guards each internally).
                    let load_edges = k_first || k_last;
                    // Phase C: KIMI_GPU_RESIDENT=1 builds the GPU quant-resident
                    // stage (packed 4-bit experts held on-GPU, top-8 dequant/token)
                    // — the path that fits a 14GB node for a full ~9.6GB window.
                    // Otherwise the CPU resident decode (bulk-dequant; small windows).
                    let gpu_resident = std::env::var("KIMI_GPU_RESIDENT")
                        .map(|v| v != "0").unwrap_or(false);
                    let kimi_model = if gpu_resident {
                        log::info!("Kimi-Linear: GPU QUANT-RESIDENT stage (device {device_idx})");
                        kimi::KimiModel::load_gpu_resident(
                            &ckpt_dir, &cfg, k_start, k_end, load_edges, device_idx)
                            .map_err(PyRuntimeError::new_err)?
                    } else {
                        kimi::KimiModel::load_cpu(&ckpt_dir, &cfg, k_start, k_end, load_edges)
                            .map_err(PyRuntimeError::new_err)?
                    };
                    let placeholder = carve_placeholder_inner();
                    return Ok(VulkanModel {
                        inner: placeholder,
                        qwen: None,
                        qwen35: None,
                        step3p7: None,
                        max_seq_len,
                        engine: None,
                        gpu_weights: HashMap::new(),
                        act_bufs: Vec::new(),
                        act_bufs_ready: false,
                        pp_start: k_start,
                        pp_end: k_end,
                        pp_first: k_first,
                        pp_last: k_last,
                        tp_rank: 0,
                        tp_size: 1,
                        gemma_ple_bf16: None,
                        gpu_kv: std::collections::HashMap::new(),
                        gemma_kv_filled: 0,
                        qres_bufs: Vec::new(),
                        qres_ready: false,
                        gpu_norm_w: std::collections::HashMap::new(),
                        gres_bufs: Vec::new(),
                        gres_ready: false,
                        gemma_norm_w: std::collections::HashMap::new(),
                        ures_bufs: Vec::new(),
                        ures_ready: false,
                        unified_norm_w: std::collections::HashMap::new(),
                        bres_bufs: Vec::new(),
                        bres_ready: false,
                        q35_f16_host: std::collections::HashMap::new(),
                        collective_comm: 0,
                        reduce_scratch: Vec::new(),
                        reduce_scratch_handle: 0,
                        pp_tok_ring: PpTokRing::default(),
                        pp_hop_send: PpTokRing::default(),
                        pp_hop_recv: PpTokRing::default(),
                        pp_vocab_ring: PpTokRing::default(),
                        moe_gpu: std::collections::HashMap::new(),
                        moe_shared_gpu: std::collections::HashMap::new(),
                        dn_gpu: std::collections::HashMap::new(),
                        q35res_bufs: Vec::new(),
                        q35res_ready: false,
                        q35res_ok: None,
                        spec_slots: Vec::new(),
                        flags: Flags::from_env(),
                        lm_shard: None,
                        chunked_weights: std::collections::HashMap::new(),
                        gemma_hidden_ring: std::collections::VecDeque::new(),
                        gemma_pp_hop: Default::default(),
                        nemotron: None,
                        nemotron_mtp_head: None,
                        kimi: Some(kimi_model),
                        ling: None,
                        laguna: None,
                        laguna_gpu: None,
                        mtp_head: None,
                        mtp_moe_gpu: None,
                        q35_last_prenorm: None,
                        q35_prenorm_ring: std::collections::VecDeque::new(),
                        spec_verify_gdn_inputs: Vec::new(),
                        spec_verify_span: None,
                        spec_verify_cols: false,
                        kv_store: None,
                    });
                }
            }
        }

        // Detect by model_type == "nemotron_h_puzzle" (the
        // `nvidia/NVIDIA-Nemotron-Labs-3-Puzzle-75B-A9B` hybrid Mamba2 + NoPE
        // attention + latent-MoE model, single-mixer-per-layer per
        // `block_configs`). CPU-only for now (see the `nemotron` field doc on
        // `VulkanModel`): `nemotron_loader::load_nemotron_weights` dequantizes
        // FP8 (group_0) / NVFP4 (group_1) straight to host f32 and BF16 tensors
        // pass through unchanged; `NemotronModel::forward_pp_range` runs
        // entirely on CPU. No GPU-resident streaming yet — that is deferred
        // cluster-hardware-validation work, mirroring how qwen3.6's GPU path
        // was added only after its CPU loader landed.
        if let Ok(cfg_text) = std::fs::read_to_string(&config_path) {
            if let Ok(cfg_json) = serde_json::from_str::<serde_json::Value>(&cfg_text) {
                let mt = cfg_json.get("model_type").and_then(|v| v.as_str()).unwrap_or("");
                #[cfg(feature = "nemotron")]
                if mt == "nemotron_h_puzzle" {
                    let cfg = nemotron::NemotronConfig::from_json(&cfg_json)
                        .map_err(PyRuntimeError::new_err)?;
                    let total_layers = cfg.num_hidden_layers;
                    let nem_start = layer_start.unwrap_or(0);
                    let nem_end = layer_end.unwrap_or(total_layers).min(total_layers);
                    let nem_first = nem_start == 0;
                    let nem_last = nem_end >= total_layers;
                    log::info!(
                        "Loading Nemotron-H-Puzzle: layers [{nem_start},{nem_end}) of \
                         {total_layers}, hidden {} (first={nem_first} last={nem_last}) \
                         from {}", cfg.hidden_size, safetensors_path);
                    let nem_flags = Flags::from_env();
                    let lm_head_name = "lm_head.weight".to_string();
                    // TP=2×PP hybrid: this rank's Megatron tensor-parallel index
                    // within its PP stage-group. `VLLM_VULKAN_TP_SIZE`>1 shards
                    // attn q/k/v/o + shared-expert + routed experts (EP) across
                    // the TP peers; the driver sets _RANK/_SIZE + wires the TP
                    // peer via `set_tp_peer`. tp_size==1 = the shipped PP path.
                    let nem_tp_size = std::env::var("VLLM_VULKAN_TP_SIZE").ok()
                        .and_then(|v| v.parse::<usize>().ok()).unwrap_or(1).max(1);
                    let nem_tp_rank = std::env::var("VLLM_VULKAN_TP_RANK").ok()
                        .and_then(|v| v.parse::<usize>().ok()).unwrap_or(0).min(nem_tp_size - 1);
                    if nem_tp_size > 1 {
                        log::info!("Nemotron TP=2×PP: rank {nem_tp_rank}/{nem_tp_size} \
                            (shard attn q/k/v/o + shared-expert + EP experts; mamba replicated)");
                    }

                    // Engine factory (shared by the resident + gpu-mamba paths).
                    let make_engine = |dev: &device::ComputeDevice| -> Result<compute::ComputeEngine, String> {
                        let shader_spvs = include_all_shaders();
                        let refs: HashMap<&str, &[u8]> = shader_spvs.iter()
                            .map(|(k, v)| (k.as_str(), v.as_slice())).collect();
                        compute::ComputeEngine::new(
                            dev.instance.clone(), dev.physical_device, dev.device.clone(),
                            dev.compute_queue, dev.compute_queue_family, dev.caps(), &refs)
                    };

                    let mut nem_model = if nem_flags.nemotron_resident {
                        // GPU-RESIDENT quantized load (the 75B OOM fix): never
                        // materialize the f32 weight set; stream each weight to
                        // GPU-resident quantized buffers + keep only small host
                        // tensors. Hard-errors without a device (no host fallback
                        // is the point — the f32 fallback is what OOMs).
                        let fp = nemotron_loader::resident_footprint(
                            &cfg, nem_start, nem_end, nem_first, nem_last);
                        log::info!(
                            "Nemotron-H-Puzzle RESIDENT [{nem_start},{nem_end}): projected \
                             {:.2}GB GTT (nvfp4-experts {:.2} + fp8 {:.2} + f16 {:.2}) + \
                             {:.2}GB host f32",
                            fp.gpu_resident_bytes() as f64 / 1e9,
                            fp.nvfp4_expert_bytes as f64 / 1e9, fp.fp8_bytes as f64 / 1e9,
                            fp.f16_bytes as f64 / 1e9, fp.host_f32_bytes as f64 / 1e9);
                        let dev = device::ComputeDevice::create(device_idx)
                            .map_err(|e| PyRuntimeError::new_err(format!(
                                "nemotron resident needs a Vulkan device: {e}")))?;
                        let mut engine = make_engine(&dev).map_err(PyRuntimeError::new_err)?;
                        let empty = model::ModelWeights { tensors: HashMap::new() };
                        let mut nem_model = nemotron::NemotronModel::new_range(
                            cfg.clone(), empty, max_seq_len, lm_head_name, nem_start, nem_end);
                        let rstats = nemotron_loader::load_nemotron_resident(
                            &path, &cfg, &mut engine,
                            &mut nem_model.gpu_weights, &mut nem_model.gpu_experts,
                            &mut nem_model.weights.tensors,
                            nem_start, nem_end, nem_first, nem_last,
                            nem_tp_rank, nem_tp_size,
                        ).map_err(|e| PyRuntimeError::new_err(
                            format!("nemotron resident loader failed: {e}")))?;
                        nem_model.engine = Some(engine);
                        nem_model.set_tp(nem_tp_rank, nem_tp_size);
                        log::info!(
                            "Nemotron-H-Puzzle RESIDENT loaded: {} nvfp4-expert + {} fp8 + \
                             {} f16 tensors ({:.2}GB GTT), {} host ({:.2}GB)",
                            rstats.nvfp4_expert_tensors, rstats.fp8_tensors, rstats.f16_tensors,
                            rstats.gpu_resident_bytes as f64 / 1e9, rstats.host_tensors,
                            rstats.host_bytes as f64 / 1e9);
                        nem_model
                    } else {
                    let (weights, stats) = nemotron_loader::load_nemotron_weights(
                        &path, &cfg, nem_start, nem_end, nem_first, nem_last,
                    ).map_err(|e| PyRuntimeError::new_err(
                        format!("nemotron loader failed: {e}")))?;
                    log::info!(
                        "Nemotron-H-Puzzle: {} tensors loaded ({} fp8, {} nvfp4), \
                         {:.2}GB host f32", stats.tensors_loaded, stats.fp8_tensors,
                        stats.nvfp4_tensors, stats.bytes_f32 as f64 / 1e9);
                    let mut nem_model = nemotron::NemotronModel::new_range(
                        cfg.clone(), weights, max_seq_len, lm_head_name, nem_start, nem_end,
                    );
                    // Optional GPU Mamba-projection path (VLLM_VULKAN_NEMOTRON_GPU_MAMBA):
                    // create a compute engine and dequant/upload the Mamba in_proj/
                    // out_proj as f16 GPU-resident. Device-less hosts (Mac) skip this
                    // and stay on the CPU cpu_matmul reference. See NemotronModel::
                    // attach_gpu_mamba + the field docs on `nemotron`.
                    if nem_flags.nemotron_gpu_mamba {
                        match device::ComputeDevice::create(device_idx) {
                            Ok(dev) => match make_engine(&dev) {
                                Ok(engine) => {
                                    let n = nem_model.attach_gpu_mamba(engine);
                                    log::info!("nemotron gpu-mamba: {n} Mamba projections GPU-resident (f16)");
                                }
                                Err(e) => log::warn!("nemotron gpu-mamba: engine failed: {e}; CPU only"),
                            },
                            Err(e) => log::warn!("nemotron gpu-mamba: no device: {e}; CPU only"),
                        }
                    }
                    nem_model
                    };
                    // Phase-1 DECOUPLED trace-dump (`VLLM_VULKAN_NEMOTRON_MTP_TRACE=<path>`):
                    // independent of `nemotron_mtp` (the head is NOT loaded here —
                    // that's the whole point, this run stays at the shipped
                    // stack's normal PP-5 footprint) — see `attach_mtp_trace` doc.
                    // Only meaningful on the last stage (only it ever computes a
                    // final hidden/logits to trace).
                    if let Some(trace_path) = &nem_flags.nemotron_mtp_trace {
                        if nem_last {
                            match nem_model.attach_mtp_trace(trace_path) {
                                Ok(()) => log::info!(
                                    "Nemotron MTP trace: writing h_pre+greedy_token per step to {trace_path}"),
                                Err(e) => log::warn!("nemotron MTP trace attach failed: {e}"),
                            }
                        }
                    }
                    // Phase-1 MTP acceptance sim (`VLLM_VULKAN_NEMOTRON_MTP=1`):
                    // load the shipped draft head alongside the LAST stage only
                    // (it reuses the last stage's `lm_head` and needs the last
                    // stage's pre-`norm_f` hidden — see `nemotron_mtp` module
                    // doc). CPU-only regardless of `nemotron_resident` (the
                    // resident/GPU path is out of scope for Phase 1); a load
                    // failure (missing `mtp.safetensors`, shape mismatch) is
                    // logged and leaves `nem_mtp_draft` unavailable rather than
                    // failing the whole model load.
                    let nem_mtp_head: Option<nemotron_mtp::NemMtpHead> = if nem_flags.nemotron_mtp && nem_last {
                        let base_dir = path.parent().unwrap_or_else(|| std::path::Path::new("."));
                        match nemotron_mtp::NemMtpHead::load(base_dir, &cfg) {
                            Ok(head) => {
                                log::info!(
                                    "Nemotron MTP head loaded (Phase 1 acceptance sim; host f32 \
                                     small tensors + BF16-bits 512 routed experts, lazy dequant)");
                                Some(head)
                            }
                            Err(e) => {
                                log::warn!(
                                    "nemotron MTP head load failed: {e}; nem_mtp_draft unavailable");
                                None
                            }
                        }
                    } else {
                        None
                    };
                    let placeholder = carve_placeholder_inner();
                    return Ok(VulkanModel {
                        inner: placeholder,
                        qwen: None,
                        qwen35: None,
                        step3p7: None,
                        max_seq_len,
                        engine: None,
                        gpu_weights: HashMap::new(),
                        act_bufs: Vec::new(),
                        act_bufs_ready: false,
                        pp_start: nem_start,
                        pp_end: nem_end,
                        pp_first: nem_first,
                        pp_last: nem_last,
                        tp_rank: nem_tp_rank,
                        tp_size: nem_tp_size,
                        gemma_ple_bf16: None,
                        gpu_kv: std::collections::HashMap::new(),
                        gemma_kv_filled: 0,
                        qres_bufs: Vec::new(),
                        qres_ready: false,
                        gpu_norm_w: std::collections::HashMap::new(),
                        gres_bufs: Vec::new(),
                        gres_ready: false,
                        gemma_norm_w: std::collections::HashMap::new(),
                        ures_bufs: Vec::new(),
                        ures_ready: false,
                        unified_norm_w: std::collections::HashMap::new(),
                        bres_bufs: Vec::new(),
                        bres_ready: false,
                        q35_f16_host: std::collections::HashMap::new(),
                        collective_comm: 0,
                        reduce_scratch: Vec::new(),
                        reduce_scratch_handle: 0,
                        pp_tok_ring: PpTokRing::default(),
                        pp_hop_send: PpTokRing::default(),
                        pp_hop_recv: PpTokRing::default(),
                        pp_vocab_ring: PpTokRing::default(),
                        moe_gpu: std::collections::HashMap::new(),
                        moe_shared_gpu: std::collections::HashMap::new(),
                        dn_gpu: std::collections::HashMap::new(),
                        q35res_bufs: Vec::new(),
                        q35res_ready: false,
                        q35res_ok: None,
                        spec_slots: Vec::new(),
                        flags: Flags::from_env(),
                        lm_shard: None,
                        chunked_weights: std::collections::HashMap::new(),
                        gemma_hidden_ring: std::collections::VecDeque::new(),
                        gemma_pp_hop: Default::default(),
                        nemotron: Some(nem_model),
                        nemotron_mtp_head: nem_mtp_head,
                        kimi: None,
                        ling: None,
                        laguna: None,
                        laguna_gpu: None,
                        mtp_head: None,
                        mtp_moe_gpu: None,
                        q35_last_prenorm: None,
                        q35_prenorm_ring: std::collections::VecDeque::new(),
                        spec_verify_gdn_inputs: Vec::new(),
                        spec_verify_span: None,
                        spec_verify_cols: false,
                        kv_store: None,
                    });
                }
            }
        }

        // ── Base dense (Gemma4 / Qwen3) fallthrough — the `gemma` feature ──────
        // Everything below is the original base-model loader. It is the tail
        // expression of `new()`; gated behind `gemma` so a foundation build with
        // the base path carved out returns a clear error instead (Phase A2).
        #[cfg(feature = "gemma")]
        {
        let model_config = match model::load_config(&config_path) {
            Ok(c) => c,
            Err(e) => {
                log::warn!("Could not load {}: {e}; defaulting to Gemma4-E2B",
                           config_path.display());
                model::ModelConfig::Gemma4(model::Gemma4Config::e2b())
            }
        };
        match &model_config {
            model::ModelConfig::Gemma4(_) => {
                log::info!("Loading Gemma4-E2B weights from {}", safetensors_path)
            }
            model::ModelConfig::Qwen3(c) => log::info!(
                "Loading Qwen3 weights from {} ({} layers, hidden {})",
                safetensors_path, c.num_hidden_layers, c.hidden_size
            ),
        }

        // Pipeline-parallel layer range. Default = whole model. When a range is
        // given, only these layers' weights load (so each PP stage holds ~1/N
        // of the model), plus the embedding on the first stage and the final
        // norm + LM head on the last.
        let n_layers = match &model_config {
            model::ModelConfig::Gemma4(c) => c.num_hidden_layers,
            model::ModelConfig::Qwen3(c) => c.num_hidden_layers,
        };
        let pp_start = layer_start.unwrap_or(0);
        let pp_end = layer_end.unwrap_or(n_layers).min(n_layers);
        let pp_first = pp_start == 0;
        let pp_last = pp_end == n_layers;
        let pp_active = pp_start != 0 || pp_end != n_layers;

        // ── Megatron tensor parallelism ─────────────────────────────────────
        // Each rank keeps only its column/row slice of every projection weight.
        // q/k/v/gate/up = column-shard (rank r keeps output rows
        // [r*out/N, (r+1)*out/N)); o/down = row-shard (rank r keeps input cols
        // [r*in/N, (r+1)*in/N)). Sliced HERE in the streaming callback, before
        // f16/quantize/upload, so each rank's GPU buffer is already 1/N size and
        // matvec dims line up. embed/lm_head/norms are replicated (not sharded).
        let tp_size = std::env::var("VLLM_VULKAN_TP_SIZE").ok()
            .and_then(|v| v.parse::<usize>().ok()).unwrap_or(1).max(1);
        let tp_rank = std::env::var("VLLM_VULKAN_TP_RANK").ok()
            .and_then(|v| v.parse::<usize>().ok()).unwrap_or(0).min(tp_size - 1);
        // Per-weight dims needed to slice rows/cols (from config, all row-major
        // [out_features, in_features]).
        let is_gemma_tp = matches!(&model_config, model::ModelConfig::Gemma4(_));
        let (tp_h, tp_qdim, tp_kvdim, tp_inter) = match &model_config {
            model::ModelConfig::Qwen3(c) => (
                c.hidden_size,
                c.num_attention_heads * c.head_dim,
                c.num_key_value_heads * c.head_dim,
                c.intermediate_size,
            ),
            // Gemma4: column-shard in_feat is always `hidden`; row-shard in_feat
            // is derived per-weight (data.len()/hidden) since q_dim/inter vary by
            // layer (dual head_dim 256/512, double-wide ffn on KV-shared layers).
            // k/v are REPLICATED (num_kv=1, can't shard), so kvdim is unused.
            model::ModelConfig::Gemma4(c) => (c.hidden_size, 0, 0, 0),
        };
        if tp_size > 1 {
            log::info!(
                "TP enabled: rank {tp_rank}/{tp_size} (column-shard q/k/v/gate/up, row-shard o/down)"
            );
        }
        // Slice a row-major [out,in] weight's f32 data for this TP rank.
        // Returns (sharded_data) or the original if this weight is not sharded.
        let tp_shard = move |name: &str, data: Vec<f32>| -> Vec<f32> {
            if tp_size <= 1 { return data; }
            // Determine in_features (contraction dim) and shard mode per weight.
            let suffix = |s: &str| name.ends_with(s);
            // column-shard: keep output-row slice [r*out/N,(r+1)*out/N) of [out,in]
            let col_shard = |data: Vec<f32>, in_feat: usize| -> Vec<f32> {
                let out = data.len() / in_feat;
                let per = out / tp_size;
                let lo = tp_rank * per;
                let hi = lo + per;
                data[lo * in_feat..hi * in_feat].to_vec()
            };
            // row-shard: keep input-col slice [r*in/N,(r+1)*in/N) of [out,in]
            let row_shard = |data: Vec<f32>, in_feat: usize| -> Vec<f32> {
                let out = data.len() / in_feat;
                let per = in_feat / tp_size;
                let lo = tp_rank * per;
                let mut o = Vec::with_capacity(out * per);
                for r in 0..out {
                    o.extend_from_slice(&data[r * in_feat + lo..r * in_feat + lo + per]);
                }
                o
            };
            if is_gemma_tp {
                // Gemma4 TP. column-shard q/gate/up by output rows (in_feat=hidden);
                // row-shard o/down by input cols (in_feat derived = out/hidden, since
                // q_dim & inter vary per layer). k/v REPLICATED (num_kv=1). PLE
                // tables, projections, embed, lm_head, norms, layer_scalar replicated.
                if suffix("self_attn.q_proj.weight") { return col_shard(data, tp_h); }
                if suffix("self_attn.k_proj.weight") { return data; } // replicate (num_kv=1)
                if suffix("self_attn.v_proj.weight") { return data; } // replicate (num_kv=1)
                if suffix("self_attn.o_proj.weight") {
                    // [hidden, q_dim]; in_feat = data.len()/hidden (per-layer q_dim).
                    let in_feat = data.len() / tp_h;
                    return row_shard(data, in_feat);
                }
                if suffix("mlp.gate_proj.weight") { return col_shard(data, tp_h); }
                if suffix("mlp.up_proj.weight")   { return col_shard(data, tp_h); }
                if suffix("mlp.down_proj.weight") {
                    // [hidden, inter]; in_feat = data.len()/hidden (per-layer inter,
                    // double-wide on KV-shared layers).
                    let in_feat = data.len() / tp_h;
                    return row_shard(data, in_feat);
                }
                // Everything else (PLE gate/proj, per_layer_* tables, embed_tokens,
                // lm_head, all norms, layer_scalar) is replicated.
                return data;
            }
            if suffix("self_attn.q_proj.weight") { return col_shard(data, tp_h); }
            if suffix("self_attn.k_proj.weight") { return col_shard(data, tp_h); }
            if suffix("self_attn.v_proj.weight") { return col_shard(data, tp_h); }
            if suffix("self_attn.o_proj.weight") {
                // o_proj is [hidden, q_dim]; row-shard over the q_dim input.
                let _ = tp_qdim;
                return row_shard(data, tp_qdim);
            }
            if suffix("mlp.gate_proj.weight") { return col_shard(data, tp_h); }
            if suffix("mlp.up_proj.weight")   { return col_shard(data, tp_h); }
            if suffix("mlp.down_proj.weight") {
                // down_proj is [hidden, inter]; row-shard over the inter input.
                return row_shard(data, tp_inter);
            }
            let _ = tp_kvdim;
            data
        };
        // Keep tensor `name` on this PP stage?
        let pp_keep = move |name: &str| -> bool {
            if let Some(rest) = name.strip_prefix("model.layers.") {
                let idx: usize = rest.split('.').next()
                    .and_then(|s| s.parse().ok()).unwrap_or(usize::MAX);
                return idx >= pp_start && idx < pp_end;
            }
            if name == "model.embed_tokens.weight" { return pp_first || pp_last; }
            if name == "lm_head.weight" || name == "model.norm.weight" {
                return pp_last;
            }
            // Gemma PLE weights (per_layer_*) are only needed where ple_inputs is
            // computed — the first stage, which forwards ple_inputs downstream.
            if name.starts_with("model.per_layer") {
                return pp_first;
            }
            true  // misc small tensors: keep everywhere
        };

        // Create the Vulkan compute engine first (no weights yet), so we can
        // stream-upload tensors to the GPU as they are decoded.
        let mut engine_opt: Option<compute::ComputeEngine> =
            match device::ComputeDevice::create(device_idx) {
                Ok(dev) => {
                    let shader_spvs = include_all_shaders();
                    let refs: HashMap<&str, &[u8]> = shader_spvs.iter()
                        .map(|(k, v)| (k.as_str(), v.as_slice())).collect();
                    match compute::ComputeEngine::new(
                        dev.instance.clone(),
                        dev.physical_device,
                        dev.device.clone(),
                        dev.compute_queue,
                        dev.compute_queue_family,
                        dev.caps(),
                        &refs,
                    ) {
                        Ok(engine) => Some(engine),
                        Err(e) => {
                            log::warn!("Failed to create compute engine: {e}, using CPU");
                            None
                        }
                    }
                }
                Err(e) => {
                    log::warn!("No Vulkan device at {device_idx}: {e}, using CPU");
                    None
                }
            };

        // Lean-host mode: after uploading a projection weight to the GPU (as f16),
        // do NOT also retain its f32 copy in host RAM.  Essential on low-RAM
        // boxes (BC-250: ~3.5 GB) where the full f32 weight set won't fit.  The
        // GPU forward path never reads projection weights from host; only the
        // CPU reference path does, so lean mode disables `debug_*`/CPU fallback.
        //
        // Both lean-host and device-weights are auto-enabled on low-RAM systems
        // and overridable via env (set the var to "0" to force off, "1" to force
        // on).  Device-weights uploads GPU weight buffers to device-local VRAM
        // (staged) instead of host-coherent system RAM; on UMA APUs like the
        // BC-250, host-coherent buffers consume the scarce system RAM (~3.5 GB)
        // while VRAM (~10 GB) sits unused, so this is the difference between
        // fitting and OOM.  Big-RAM / true-UMA systems (e.g. GB10) keep the
        // default host-coherent, full-host-copy path.
        //
        // Heuristic: the default (non-lean, host-coherent) path needs roughly
        // 3x the on-disk weight size — host f32 copy (~2x bf16) plus the GPU
        // host-coherent buffers (~1x) — so auto-enable when system RAM can't
        // comfortably hold that.
        let model_bytes: u64 = {
            let dir = path.parent().unwrap_or_else(|| Path::new("."));
            let summed: u64 = std::fs::read_dir(dir)
                .map(|rd| {
                    rd.flatten()
                        .filter(|e| e.path().extension().and_then(|x| x.to_str()) == Some("safetensors"))
                        .filter_map(|e| e.metadata().ok().map(|m| m.len()))
                        .sum()
                })
                .unwrap_or(0);
            if summed > 0 { summed } else { std::fs::metadata(path).map(|m| m.len()).unwrap_or(0) }
        };
        let sys_ram = system_ram_bytes();
        let auto_low_ram = engine_opt.is_some()
            && sys_ram > 0
            && model_bytes > 0
            && sys_ram < model_bytes.saturating_mul(3).saturating_add(1 << 30);

        let env_flag = |name: &str| -> Option<bool> {
            std::env::var(name).ok().map(|v| v == "1" || v.eq_ignore_ascii_case("true"))
        };
        let lean_host = env_flag("VLLM_VULKAN_LEAN_HOST").unwrap_or(auto_low_ram);
        let device_weights = env_flag("VLLM_VULKAN_DEVICE_WEIGHTS").unwrap_or(auto_low_ram);
        // Quantize matvec/LM-head weights on the GPU (VLLM_VULKAN_QUANT=q8_0|q4_0).
        // Matvec dispatch must pick the matching shader (see matvec_variant).
        // Single env snapshot for this construction; reused for both the
        // load-time decisions below and the stored `flags` field.
        let flags = Flags::from_env();
        let quant_q8 = flags.quant == QuantFormat::Q8_0;
        let quant_q4 = flags.quant == QuantFormat::Q4_0;
        let quant_q4k = flags.quant == QuantFormat::Q4_K;
        let quant_bf16 = flags.quant == QuantFormat::Bf16;
        if auto_low_ram && (lean_host || device_weights) {
            log::info!(
                "Low-RAM auto-config: system RAM {:.1}GB vs ~{:.1}GB needed; \
                 lean_host={lean_host} device_weights={device_weights}",
                sys_ram as f64 / 1e9,
                (model_bytes as f64 * 3.0 + 1e9) / 1e9,
            );
        }

        // Stream every tensor: upload to the GPU, keep host f32 copies as needed.
        // Peak host memory is one tensor at a time (plus retained host tensors),
        // never the entire f32 weight set.
        let mut gpu_weights: HashMap<String, GpuWeight> = HashMap::new();
        let mut host_tensors: HashMap<String, model::SimpleTensor> = HashMap::new();
        let mut has_lm_head = false;
        let mut total_gpu_bytes = 0u64;
        let mut host_bytes = 0u64;

        let keep_filter = move |name: &str| -> bool {
            // The giant Gemma PLE table is loaded bf16-resident separately
            // (see gemma_ple_bf16); never materialize it as f32 here.
            if name == "model.embed_tokens_per_layer.weight" { return false; }
            !pp_active || pp_keep(name)
        };
        model::for_each_safetensors_tensor_filtered(path, keep_filter, |name, data| {
            if name == "lm_head.weight" {
                has_lm_head = true;
            }
            // TP: slice this tensor to this rank's column/row shard (no-op when
            // tp_size==1 or the tensor is replicated, e.g. embed/lm_head/norms).
            let data = tp_shard(&name, data);
            let matvec = is_matvec_weight(&name);
            // The LM head is the single biggest matmul (vocab×hidden) and on CPU
            // it dominates per-token latency (~290ms for 0.6B). Upload it to the
            // GPU as f16 too — for tied models this is embed_tokens.weight, which
            // also keeps its host f32 copy for the embedding row lookup.
            let is_lm_head = name == "lm_head.weight" || name == "model.embed_tokens.weight";
            let upload_gpu = matvec || is_lm_head;
            if engine_opt.is_some() {
                // Only projection weights + the LM head run through GPU matvec;
                // norms and (the embedding lookup of) embed_tokens stay on CPU.
                if upload_gpu {
                    // Quantize to q8_0 when enabled (and shape-compatible) — the
                    // matvec is bandwidth-bound, so ~half the bytes ≈ faster; else
                    // upload as f16 (halves bandwidth vs f32).
                    let gpu_format = if quant_q4k && data.len() % 256 == 0 {
                        QuantFormat::Q4_K
                    } else if quant_q4 && data.len() % 32 == 0 {
                        QuantFormat::Q4_0
                    } else if quant_q8 && data.len() % 32 == 0 {
                        QuantFormat::Q8_0
                    } else if quant_bf16 {
                        QuantFormat::Bf16
                    } else {
                        QuantFormat::F16
                    };
                    let gpu_bytes: Vec<u8> = match gpu_format {
                        QuantFormat::Q4_K => model::quantize_q4_k(&data),
                        QuantFormat::Q4_0 => model::quantize_q4_0(&data),
                        QuantFormat::Q8_0 => model::quantize_q8_0(&data),
                        QuantFormat::Bf16 => {
                            // bf16 weight (native precision). NOTE: still converts via
                            // the f32 data here — the load-time win (skip f32 entirely
                            // via raw bf16 streaming) needs a for_each_*_raw loader
                            // refactor (follow-on). 2 bytes/weight like f16, so no
                            // bandwidth/footprint win vs f16 — q8/q4 are the fit levers.
                            let mut b = vec![0u8; data.len() * 2];
                            for (i, &v) in data.iter().enumerate() {
                                b[i * 2..i * 2 + 2].copy_from_slice(&half::bf16::from_f32(v).to_bits().to_le_bytes());
                            }
                            b
                        }
                        _ => {
                            let mut f16_bytes = vec![0u8; data.len() * 2];
                            for (i, &v) in data.iter().enumerate() {
                                f16_bytes[i * 2..i * 2 + 2]
                                    .copy_from_slice(&half::f16::from_f32(v).to_bits().to_le_bytes());
                            }
                            f16_bytes
                        }
                    };
                    let engine = engine_opt.as_mut().unwrap();
                    let alloc = if device_weights {
                        // Device-local VRAM via staged upload (transient staging buffer).
                        match engine.alloc_device(gpu_bytes.len() as u64) {
                            Ok(buf) => engine.upload(&buf, &gpu_bytes).map(|_| buf),
                            Err(e) => Err(e),
                        }
                    } else {
                        // Host-coherent (GPU-visible system RAM, no DMA).
                        engine.alloc_host_coherent_storage(gpu_bytes.len() as u64).map(|buf| {
                            unsafe {
                                std::ptr::copy_nonoverlapping(
                                    gpu_bytes.as_ptr(), buf.mapped_ptr.unwrap() as *mut u8, gpu_bytes.len());
                            }
                            buf
                        })
                    };
                    match alloc {
                        Ok(buf) => {
                            total_gpu_bytes += gpu_bytes.len() as u64;
                            gpu_weights.insert(name.clone(), GpuWeight { buffer: buf, format: gpu_format, aux: None });
                        }
                        Err(e) => log::warn!("GPU upload failed for '{name}': {e}"),
                    }
                }

                // Retain host f32: always for non-projection tensors (embeddings,
                // norms, lm_head — used on the CPU side); projections only when
                // NOT lean (lean drops them since they live on the GPU).
                // Exception: Gemma's per_layer_model_projection matches the matvec
                // name pattern but is used on the CPU (PLE preprocessing), so it
                // must stay host even under lean.
                let cpu_used_matvec = name == "model.per_layer_model_projection.weight";
                if !lean_host || !matvec || cpu_used_matvec {
                    host_bytes += (data.len() * 4) as u64;
                    host_tensors.insert(name, model::SimpleTensor { data, shape: vec![] });
                }
            } else {
                // CPU-only: keep every tensor in host f32.
                host_bytes += (data.len() * 4) as u64;
                host_tensors.insert(name, model::SimpleTensor { data, shape: vec![] });
            }
            Ok(())
        })
        .map_err(PyRuntimeError::new_err)?;

        if engine_opt.is_some() {
            log::info!(
                "Uploaded {:.2}GB to GPU; retained {:.2}GB host f32{}",
                total_gpu_bytes as f64 / 1e9,
                host_bytes as f64 / 1e9,
                if lean_host { " (lean host)" } else { "" }
            );
        }

        let weights = model::ModelWeights { tensors: host_tensors };

        if engine_opt.is_some() {
            log::info!("VulkanModel ready: GPU matmuls enabled");
        } else {
            log::info!("VulkanModel ready: CPU-only mode");
        }

        // Build the architecture-specific model, sharing the GPU engine/weights.
        let (inner, qwen) = match model_config {
            model::ModelConfig::Gemma4(cfg) => {
                // Per-layer KV sizing (Phase-0 host half): sliding layers get a
                // `window`-sized ring; full layers keep max_seq (byte-identical
                // to the old `new`). Gated by VLLM_VULKAN_KV_RING_DISABLE to
                // co-engage with the GPU-resident ring.
                let kv_caches: Vec<model::KvCache> = (0..cfg.num_hidden_layers).map(|i| {
                    let head_dim = cfg.layer_head_dim(i);
                    let cap = if flags.kv_ring_disable {
                        max_seq_len
                    } else {
                        cfg.layer_kv_capacity(i, max_seq_len)
                    };
                    model::KvCache::new_windowed(max_seq_len, cap, cfg.num_key_value_heads, head_dim)
                }).collect();
                (model::Gemma4Model { config: cfg, weights, kv_caches }, None)
            }
            model::ModelConfig::Qwen3(cfg) => {
                // One KV cache per layer THIS stage owns (indexed by
                // layer_idx - pp_start in the PP forward). Under TP each rank
                // holds only its 1/N slice of the kv heads.
                let tp_kv_heads = cfg.num_key_value_heads / tp_size;
                let kv_caches: Vec<model::KvCache> = (pp_start..pp_end).map(|_| {
                    model::KvCache::new(max_seq_len, tp_kv_heads, cfg.head_dim)
                }).collect();
                // Tied embeddings (no separate lm_head) reuse embed_tokens.
                let lm_head_name = if has_lm_head {
                    "lm_head.weight".to_string()
                } else {
                    "model.embed_tokens.weight".to_string()
                };
                let qwen = model::Qwen3Model { config: cfg, weights, kv_caches, lm_head_name };
                // Empty placeholder Gemma4 model (unused for the Qwen3 path).
                let placeholder = model::Gemma4Model {
                    config: model::Gemma4Config::e2b(),
                    weights: model::ModelWeights { tensors: HashMap::new() },
                    kv_caches: Vec::new(),
                };
                (placeholder, Some(qwen))
            }
        };

        // Gemma's PLE table is kept bf16-resident, and only on the PLE-owning
        // (first) stage — that stage computes ple_inputs for all layers and
        // forwards them down the pipeline.
        let gemma_ple_bf16 = if qwen.is_none() && pp_first {
            Some(model::load_tensor_raw_bf16(
                Path::new(safetensors_path),
                "model.embed_tokens_per_layer.weight",
            ).map_err(PyRuntimeError::new_err)?)
        } else {
            None
        };

        Ok(VulkanModel {
            inner,
            qwen,
            qwen35: None,
            step3p7: None,
            max_seq_len,
            engine: engine_opt,
            gpu_weights,
            act_bufs: Vec::new(),
            act_bufs_ready: false,
            pp_start,
            pp_end,
            pp_first,
            pp_last,
            tp_rank,
            tp_size,
            gemma_ple_bf16,
            gpu_kv: std::collections::HashMap::new(),
            gemma_kv_filled: 0,
            qres_bufs: Vec::new(),
            qres_ready: false,
            gres_bufs: Vec::new(),
            gres_ready: false,
            gemma_norm_w: std::collections::HashMap::new(),
            gpu_norm_w: std::collections::HashMap::new(),
            ures_bufs: Vec::new(),
            ures_ready: false,
            unified_norm_w: std::collections::HashMap::new(),
            bres_bufs: Vec::new(),
            bres_ready: false,
            q35_f16_host: std::collections::HashMap::new(),
            collective_comm: 0,
            reduce_scratch: Vec::new(),
            reduce_scratch_handle: 0,
            pp_tok_ring: PpTokRing::default(),
            pp_hop_send: PpTokRing::default(),
            pp_hop_recv: PpTokRing::default(),
            pp_vocab_ring: PpTokRing::default(),
            gemma_hidden_ring: std::collections::VecDeque::new(),
            gemma_pp_hop: Default::default(),
            moe_gpu: std::collections::HashMap::new(),
            moe_shared_gpu: std::collections::HashMap::new(),
            dn_gpu: std::collections::HashMap::new(),
            q35res_bufs: Vec::new(),
            q35res_ready: false,
            q35res_ok: None,
            spec_slots: Vec::new(),
            flags,
            lm_shard: None,
            chunked_weights: std::collections::HashMap::new(),
            nemotron: None,
            nemotron_mtp_head: None,
            kimi: None,
            ling: None,
            laguna: None,
            laguna_gpu: None,
            mtp_head: None,
            mtp_moe_gpu: None,
            q35_last_prenorm: None,
            q35_prenorm_ring: std::collections::VecDeque::new(),
            spec_verify_gdn_inputs: Vec::new(),
            spec_verify_span: None,
            spec_verify_cols: false,
            kv_store: None,
        })
        }
        // Foundation carve: with the base `gemma`/Qwen3 dense path compiled out,
        // any checkpoint that fell through every model-arch dispatch above has no
        // loader in this build.
        #[cfg(not(feature = "gemma"))]
        {
            Err(PyRuntimeError::new_err(format!(
                "no enabled model feature matches this checkpoint (model_type in \
                 {config_path:?}); the base gemma/qwen3 dense path is disabled in \
                 this build (feature `gemma` off)"
            )))
        }
    }

    /// GPU-only constructor for kernel debugging: builds the Vulkan engine +
    /// pipeline cache but loads NO model weights (empty Gemma4 placeholder).
    /// Lets `debug_*` methods that only need the engine (e.g. debug_gemma_flash,
    /// debug_flash) run with synthetic tensors and no 6-minute model load.
    #[staticmethod]
    #[pyo3(signature = (device_idx = 0))]
    fn gpu_only(device_idx: usize) -> PyResult<Self> {
        use std::collections::HashMap;
        let engine_opt: Option<compute::ComputeEngine> =
            match device::ComputeDevice::create(device_idx) {
                Ok(dev) => {
                    let shader_spvs = include_all_shaders();
                    let refs: HashMap<&str, &[u8]> = shader_spvs.iter()
                        .map(|(k, v)| (k.as_str(), v.as_slice())).collect();
                    compute::ComputeEngine::new(
                        dev.instance.clone(),
                        dev.physical_device,
                        dev.device.clone(),
                        dev.compute_queue,
                        dev.compute_queue_family,
                        dev.caps(),
                        &refs,
                    ).ok()
                }
                Err(_) => None,
            };
        if engine_opt.is_none() {
            return Err(PyRuntimeError::new_err(
                "gpu_only: no Vulkan device / engine creation failed",
            ));
        }
        let inner = carve_placeholder_inner();
        Ok(VulkanModel {
            inner,
            qwen: None,
            qwen35: None,
            step3p7: None,
            max_seq_len: 512,
            engine: engine_opt,
            gpu_weights: HashMap::new(),
            act_bufs: Vec::new(),
            act_bufs_ready: false,
            pp_start: 0,
            pp_end: 0,
            pp_first: true,
            pp_last: true,
            tp_rank: 0,
            tp_size: 1,
            gemma_ple_bf16: None,
            gpu_kv: HashMap::new(),
            gemma_kv_filled: 0,
            qres_bufs: Vec::new(),
            qres_ready: false,
            gres_bufs: Vec::new(),
            gres_ready: false,
            gemma_norm_w: HashMap::new(),
            gpu_norm_w: HashMap::new(),
            ures_bufs: Vec::new(),
            ures_ready: false,
            unified_norm_w: HashMap::new(),
            bres_bufs: Vec::new(),
            bres_ready: false,
            q35_f16_host: HashMap::new(),
            collective_comm: 0,
            reduce_scratch: Vec::new(),
            reduce_scratch_handle: 0,
            pp_tok_ring: PpTokRing::default(),
            pp_hop_send: PpTokRing::default(),
            pp_hop_recv: PpTokRing::default(),
            pp_vocab_ring: PpTokRing::default(),
            gemma_hidden_ring: std::collections::VecDeque::new(),
            gemma_pp_hop: Default::default(),
            moe_gpu: std::collections::HashMap::new(),
            moe_shared_gpu: std::collections::HashMap::new(),
            dn_gpu: std::collections::HashMap::new(),
            q35res_bufs: Vec::new(),
            q35res_ready: false,
            q35res_ok: None,
            spec_slots: Vec::new(),
            flags: Flags::from_env(),
            lm_shard: None,
            chunked_weights: std::collections::HashMap::new(),
            nemotron: None,
            nemotron_mtp_head: None,
            kimi: None,
            ling: None,
            laguna: None,
            laguna_gpu: None,
            mtp_head: None,
            mtp_moe_gpu: None,
            q35_last_prenorm: None,
            q35_prenorm_ring: std::collections::VecDeque::new(),
            spec_verify_gdn_inputs: Vec::new(),
            spec_verify_span: None,
            spec_verify_cols: false,
            kv_store: None,
        })
    }

    /// Hand the native collective the launcher's `vcclComm_t` handle.
    ///
    /// The Python launcher creates `comm = vccl.Communicator(NR, uid, RANK)`
    /// (it owns the bootstrap recipe and the handle's lifetime) and calls this
    /// ONCE, before the forward loop, passing the raw pointer as an int
    /// (`comm._comm.value`). With this set and `VLLM_VULKAN_NATIVE_COMM != "0"`,
    /// the TP all-reduces and PP send/recv call libvccl directly on the
    /// partial's host memory — no Python round-trip, no PyList marshalling, no
    /// GIL acquire per element. `handle == 0` clears it (revert to the callback).
    ///
    /// Also pre-registers a fixed RDMA scratch buffer (sized to the model's
    /// hidden, the all-reduce width) ONCE, so the per-collective `ibv_reg_mr`/
    /// dereg inside vCCL's `ScopedReg` is skipped (the dominant per-call cost for
    /// the small 20 KB reduce). The native all-reduce then reduces THROUGH this
    /// registered buffer. Best-effort: if libvccl lacks `vcclCommRegister` or
    /// registration fails, we fall back to reducing the partial directly (still
    /// no Python, but paying the per-call regMr). Disable with
    /// `VLLM_VULKAN_REG_REDUCE=0`.
    fn set_collective_comm(&mut self, handle: usize) {
        // Hold the same lock every native collective takes for its whole
        // duration, so an in-flight collective cannot observe a torn-down
        // comm handle (or a second Python thread's re-entrant set) mid-flight.
        let _g = vccl_ffi::comm_lock().lock().unwrap_or_else(|e| e.into_inner());
        // Drop any prior registration (handle is changing).
        if self.reduce_scratch_handle != 0 && self.collective_comm != 0 {
            let _ = vccl_ffi::comm_deregister(
                self.collective_comm as *mut std::os::raw::c_void,
                self.reduce_scratch_handle,
            );
            self.reduce_scratch_handle = 0;
        }
        // Same for the PP ring-back token scratch (registered lazily on the
        // first `pp_bcast_token`, but re-pinned against the new comm here).
        if self.pp_tok_ring.handle != 0 && self.collective_comm != 0 {
            let _ = vccl_ffi::comm_deregister(
                self.collective_comm as *mut std::os::raw::c_void,
                self.pp_tok_ring.handle,
            );
            self.pp_tok_ring.handle = 0;
            self.pp_tok_ring.buf.clear();
        }
        // Same for the non-fused forward-hidden hop scratch (qwen3.5 PP path,
        // registered lazily on the first `pp_send_hidden`/`pp_recv_hidden`).
        let cur_comm = self.collective_comm;
        for ring in [&mut self.pp_hop_send, &mut self.pp_hop_recv, &mut self.pp_vocab_ring] {
            if ring.handle != 0 && cur_comm != 0 {
                let _ = vccl_ffi::comm_deregister(
                    cur_comm as *mut std::os::raw::c_void,
                    ring.handle,
                );
            }
            ring.handle = 0;
            ring.buf.clear();
        }
        self.collective_comm = handle;
        // TP=2×PP: nemotron's per-layer TP all-reduce uses the SAME flat comm.
        // Forward the handle (the TP-peer global rank is wired via set_tp_peer).
        #[cfg(feature = "nemotron")]
        if let Some(nem) = self.nemotron.as_mut() {
            let peer = nem.tp_peer;
            nem.set_tp_comm(handle, peer);
        }
        // TP-2×PP: step3p7's GPU-resident decode folds its per-layer TP-2 pairwise reduce
        // (after o_proj + after the MLP down) onto the SAME flat comm. The peer global
        // rank is (re)wired via set_tp_peer; preserve it across a comm change.
        #[cfg(feature = "step3p7")]
        if let Some(g) = self.step3p7.as_mut().and_then(|m| m.gpu.as_mut()) {
            let peer = g.tp_peer();
            g.set_tp_comm(handle, peer);
        }
        if handle == 0 {
            return;
        }
        let want_reg = self.flags.reg_reduce;
        if !want_reg || !vccl_ffi::registration_available() {
            return;
        }
        // Width of the all-reduce = hidden_size for every arch we TP.
        #[allow(unused_mut)]
        let mut hidden: usize = 0;
        #[cfg(feature = "qwen35")]
        if hidden == 0 { if let Some(m) = self.qwen35.as_ref() { hidden = m.config.hidden_size; } }
        #[cfg(feature = "gemma")]
        if hidden == 0 { if let Some(m) = self.qwen.as_ref() { hidden = m.config.hidden_size; } }
        #[cfg(feature = "gemma")]
        if hidden == 0 { hidden = self.inner.config.hidden_size; }
        if hidden == 0 {
            return;
        }
        self.reduce_scratch = vec![0.0f32; hidden];
        let addr = self.reduce_scratch.as_ptr() as usize;
        let bytes = hidden * std::mem::size_of::<f32>();
        match vccl_ffi::comm_register(handle as *mut std::os::raw::c_void, addr, bytes) {
            Ok(h) => { self.reduce_scratch_handle = h; }
            Err(e) => {
                log::warn!("vcclCommRegister(reduce_scratch) failed: {e}; per-call regMr");
                self.reduce_scratch.clear();
                self.reduce_scratch_handle = 0;
            }
        }
    }

    /// TP=2×PP: set this rank's TP-peer GLOBAL rank (the other rank in the same
    /// PP stage-group) for nemotron's per-layer TP all-reduce. Called by the
    /// TP×PP driver after `set_collective_comm`. `peer < 0` disables the reduce
    /// (single-TP). No-op unless a nemotron model is loaded.
    fn set_tp_peer(&mut self, peer: i64) {
        #[cfg(feature = "nemotron")]
        if let Some(nem) = self.nemotron.as_mut() {
            let comm = nem.collective_comm.max(self.collective_comm);
            nem.set_tp_comm(comm, peer as i32);
            log::info!("Nemotron TP peer global rank = {peer} (comm wired={})", comm != 0);
        }
        // step3p7 GPU-resident decode: wire the TP-2 peer for its pairwise per-layer reduce.
        #[cfg(feature = "step3p7")]
        {
        let comm = self.collective_comm;
        if let Some(g) = self.step3p7.as_mut().and_then(|m| m.gpu.as_mut()) {
            g.set_tp_comm(comm, peer as i32);
            log::info!("step3p7 TP peer global rank = {peer} (comm wired={})", comm != 0);
        }
        }
        let _ = peer;
    }

    /// True when the native vCCL FFI path is active: the env flag is not "0",
    /// libvccl loaded, and a comm handle was supplied. When false, callers fall
    /// back to the Python all_reduce/send/recv callback (clean A/B).
    fn native_comm_enabled(&self) -> bool {
        if self.collective_comm == 0 {
            return false;
        }
        if !self.flags.native_comm {
            return false;
        }
        vccl_ffi::available()
    }

    /// Re-register the pinned all-reduce scratch so it can hold `min_len` f32s
    /// (the batched TP verify — `forward_tp_gemma_verify` — reduces `[T*h]`,
    /// larger than the single-token `[h]` scratch `set_collective_comm`
    /// registers). No-op when native registration is off/unavailable or the
    /// scratch is already big enough. Mirrors the registration in
    /// `set_collective_comm`; on failure the reduce closure falls back to the
    /// non-scratch native all-reduce (still correct, just per-call regMr).
    pub(crate) fn ensure_reduce_scratch(&mut self, min_len: usize) {
        if self.collective_comm == 0 || !self.flags.reg_reduce
            || !vccl_ffi::registration_available() {
            return;
        }
        if self.reduce_scratch_handle != 0 && self.reduce_scratch.len() >= min_len {
            return;
        }
        let _g = vccl_ffi::comm_lock().lock().unwrap_or_else(|e| e.into_inner());
        if self.reduce_scratch_handle != 0 && self.collective_comm != 0 {
            let _ = vccl_ffi::comm_deregister(
                self.collective_comm as *mut std::os::raw::c_void,
                self.reduce_scratch_handle,
            );
            self.reduce_scratch_handle = 0;
        }
        self.reduce_scratch = vec![0.0f32; min_len];
        let addr = self.reduce_scratch.as_ptr() as usize;
        let bytes = min_len * std::mem::size_of::<f32>();
        match vccl_ffi::comm_register(self.collective_comm as *mut std::os::raw::c_void, addr, bytes) {
            Ok(h) => self.reduce_scratch_handle = h,
            Err(e) => {
                log::warn!("ensure_reduce_scratch({min_len}) register failed: {e}; per-call regMr");
                self.reduce_scratch.clear();
                self.reduce_scratch_handle = 0;
            }
        }
    }

    /// Native vCCL send of a hidden-state vector (FLOAT32) to `peer`.
    ///
    /// PP equivalent of the launcher's `comm.send((c_float*H)(*hidden), ...)`:
    /// the `Vec<f32>` goes straight to `vcclSend` from its own memory, skipping
    /// the element-wise PyList→ctypes-array copy. Falls back is the launcher's
    /// job (it picks native vs callback by `native_comm_enabled`). Errors if the
    /// native path isn't ready (no handle / lib / flag off).
    ///
    /// The `[H]` payload is sent FROM the persistent RDMA-registered
    /// `pp_hop_send` scratch (pinned ONCE via `comm_register`, re-pinned on an H
    /// or comm change) so vCCL skips the per-call `ibv_reg_mr`/dereg temp-MR and
    /// the "buffer (H*4 B) not registered with the comm" warning the fresh
    /// per-token `Vec` hit. Gated by `VLLM_VULKAN_REG_REDUCE` (the reduce-scratch
    /// umbrella flag); on unavailable/failed registration it falls back to
    /// sending the caller's `buf` directly (correct, just the per-call regMr).
    fn pp_send_hidden(&mut self, py: Python<'_>, buf: Vec<f32>, peer: i32) -> PyResult<()> {
        if !self.native_comm_enabled() {
            return Err(PyRuntimeError::new_err(
                "pp_send_hidden: native comm not enabled (set_collective_comm + VLLM_VULKAN_NATIVE_COMM!=0)"));
        }
        let comm = self.collective_comm as *mut std::os::raw::c_void;
        let want_reg = self.flags.reg_reduce
            && !comm.is_null()
            && vccl_ffi::registration_available();
        if want_reg && (self.pp_hop_send.handle == 0 || self.pp_hop_send.buf.len() != buf.len()) {
            pin_pp_hop(comm, &mut self.pp_hop_send, buf.len(), "pp_send_hidden");
        }
        if self.pp_hop_send.handle != 0 && self.pp_hop_send.buf.len() == buf.len() {
            self.pp_hop_send.buf.copy_from_slice(&buf);
            vccl_ffi::send_f32(py, comm, &self.pp_hop_send.buf, peer)
                .map_err(PyRuntimeError::new_err)
        } else {
            vccl_ffi::send_f32(py, comm, &buf, peer).map_err(PyRuntimeError::new_err)
        }
    }

    /// Native vCCL recv of `count` FLOAT32 elements from `peer`. Returns the
    /// received vector. PP equivalent of `comm.recv((c_float*H)(), ...)` followed
    /// by `list(recv)` — but the result is already a `Vec<f32>` Rust-side, so the
    /// next `forward_pp_qwen35` consumes it with no PyList→Vec re-marshalling.
    ///
    /// Recv lands IN the persistent RDMA-registered `pp_hop_recv` scratch (same
    /// pinning story as `pp_send_hidden`); the returned `Vec` is a clone of it so
    /// the scratch stays pinned for the next token. Gated + fallback identical to
    /// `pp_send_hidden`.
    fn pp_recv_hidden(&mut self, py: Python<'_>, count: usize, peer: i32) -> PyResult<Vec<f32>> {
        if !self.native_comm_enabled() {
            return Err(PyRuntimeError::new_err(
                "pp_recv_hidden: native comm not enabled"));
        }
        let comm = self.collective_comm as *mut std::os::raw::c_void;
        let want_reg = self.flags.reg_reduce
            && !comm.is_null()
            && vccl_ffi::registration_available();
        if want_reg && (self.pp_hop_recv.handle == 0 || self.pp_hop_recv.buf.len() != count) {
            pin_pp_hop(comm, &mut self.pp_hop_recv, count, "pp_recv_hidden");
        }
        if self.pp_hop_recv.handle != 0 && self.pp_hop_recv.buf.len() == count {
            vccl_ffi::recv_f32_into(py, comm, &mut self.pp_hop_recv.buf, peer)
                .map_err(PyRuntimeError::new_err)?;
            Ok(self.pp_hop_recv.buf.clone())
        } else {
            vccl_ffi::recv_f32(py, comm, count, peer).map_err(PyRuntimeError::new_err)
        }
    }




    /// Run one decode step.
    ///
    /// Returns the full logit vector [vocab_size] as a Python list of floats.
    fn forward(&mut self, token_id: u32, position: usize) -> PyResult<Vec<f32>> {
        self.forward_rs(token_id, position).map_err(Into::into)
    }

    /// Greedy decode that does NOT marshal the full vocab logits to Python.
    /// Runs the same forward but argmaxes in Rust and returns just
    /// `(token_id, max_logit)`. The host-path profile showed converting the
    /// 152k/248k-float logit Vec into a Python list every token is a big chunk
    /// of decode's ~40% Python/glue overhead (the GPU is only ~5% busy) — this
    /// skips it. Use for greedy generation; use `forward` when the sampler needs
    /// the full distribution.
    fn forward_argmax(&mut self, token_id: u32, position: usize) -> PyResult<(u32, f32)> {
        let lg = self.forward(token_id, position)?;
        let (mut bi, mut bv) = (0usize, f32::NEG_INFINITY);
        for (i, &v) in lg.iter().enumerate() {
            if v > bv { bv = v; bi = i; }
        }
        Ok((bi as u32, bv))
    }

    /// LMCache-NAS Phase 1 prefill-delta hook: feed `tokens` through the
    /// model starting at `start_pos` (no existing batched pymethod covers
    /// `qwen3_5` — `forward_batched`/`forward_batched_impl` is dense-Qwen3
    /// (`self.qwen`) only, see `batched_forward.rs`), so this is a thin loop
    /// over the same single-token `forward_rs` every decode step already
    /// uses. This is exactly what the session shim calls to prefill ONLY the
    /// uncached suffix after a `kv_cache_load` hit. Returns the LAST token's
    /// argmax `(token_id, logit)` — the first "next token" of the decode
    /// loop — computed in Rust (not the full vocab logit vector) to avoid
    /// marshalling the 152k/248k-float vocab to Python every prefill token
    /// (same rationale as `forward_argmax`).
    fn prefill(&mut self, tokens: Vec<u32>, start_pos: usize) -> PyResult<(u32, f32)> {
        if tokens.is_empty() {
            return Err(PyRuntimeError::new_err("prefill: empty tokens"));
        }
        let mut last_logits = Vec::new();
        for (i, &tok) in tokens.iter().enumerate() {
            last_logits = self.forward_rs(tok, start_pos + i)?;
        }
        let (mut bi, mut bv) = (0usize, f32::NEG_INFINITY);
        for (i, &v) in last_logits.iter().enumerate() {
            if v > bv { bv = v; bi = i; }
        }
        Ok((bi as u32, bv))
    }

    /// EngineClient serving seam: append `tokens` to the resident KV starting
    /// at `start_pos` and return the LAST token's full `[vocab]` logits for the
    /// Python-side sampler / logprobs.
    ///
    /// This generalizes the two existing prefill entries along two axes:
    ///   * unlike `prefill` (which returns argmax `(id, logit)` only), it returns
    ///     the full last-row logit vector, so sampling / logprobs / structured
    ///     output all work;
    ///   * unlike `forward_prefill` (which RESETS the KV and is Qwen3-dense only),
    ///     it APPENDS at `start_pos` and does NOT reset — so it is arch-general
    ///     and chunked prefill is just a sequence of appends at
    ///     `start_pos = num_computed_tokens`.
    ///
    /// Implementation is a thin loop over the same single-token `forward_rs`
    /// decode step every decode step already uses (discarding intermediate rows'
    /// logits), so it is bit-exact to serial decode for EVERY architecture. The
    /// decode step itself reuses `forward(token, pos)` verbatim; this is the load-
    /// bearing prefill entry for the single-stream (`max_num_seqs=1`) EngineClient
    /// `generate()` MVP.
    fn prefill_logits(&mut self, tokens: Vec<u32>, start_pos: usize) -> PyResult<Vec<f32>> {
        if tokens.is_empty() {
            return Err(PyRuntimeError::new_err("prefill_logits: empty tokens"));
        }
        let mut last_logits = Vec::new();
        for (i, &tok) in tokens.iter().enumerate() {
            last_logits = self.forward_rs(tok, start_pos + i)?;
        }
        Ok(last_logits)
    }

    /// EngineClient FAST decode path: run one decode step for `token_id` at
    /// `position`, then sample the next token entirely in Rust — returning just
    /// the sampled token id, never marshalling the full `[vocab]` logit vector
    /// (152k/248k floats) into a Python object.
    ///
    /// This fuses `forward` + `model::sample_with_temperature` for the
    /// no-logprobs case: the same temperature / top-p / top-k algorithm that
    /// `vllm_vulkan/server.py::temperature_sample` implemented in pure Python
    /// (~82ms/call at Gemma4-E2B's 262144-token vocab), but starting from the
    /// `Vec<f32>` logits Rust already has and ending at a single `u32`, so it
    /// never leaves Rust. Use `forward` / `prefill_logits` (which return the
    /// full distribution) when logprobs or structured output are requested.
    ///
    /// Semantics match `sample_with_temperature`:
    ///   * `temperature < 0.01` ⇒ greedy (argmax), identical to `forward`'s
    ///     logits argmaxed — deterministic and independent of `uniform_random`;
    ///   * `top_k <= 0` ⇒ no top-k filtering (full vocab);
    ///   * `uniform_random` is a caller-supplied uniform `[0, 1)` draw (e.g.
    ///     Python's `random.random()`); output is deterministic given that draw
    ///     (and, transitively, given the caller's RNG seed).
    fn forward_and_sample(
        &mut self,
        token_id: u32,
        position: usize,
        temperature: f32,
        top_p: f32,
        top_k: i64,
        uniform_random: f32,
    ) -> PyResult<u32> {
        let logits = self.forward_rs(token_id, position)?;
        let idx = model::sample_with_temperature(&logits, temperature, top_p, top_k, uniform_random);
        Ok(idx as u32)
    }

    /// Like `forward_argmax` but for SAMPLING: returns the top-`k` `(token_id,
    /// logit)` pairs (descending) instead of the full vocab — enough for
    /// top-k / top-p / temperature sampling without marshalling 152k/248k floats
    /// to Python every token (the win extends beyond greedy). k is clamped to
    /// the vocab size.
    fn forward_topk(&mut self, token_id: u32, position: usize, k: usize) -> PyResult<Vec<(u32, f32)>> {
        let lg = self.forward(token_id, position)?;
        let k = k.min(lg.len());
        // Partial selection: O(vocab) scan keeping the k largest (k is small).
        let mut top: Vec<(u32, f32)> = Vec::with_capacity(k + 1);
        let mut min_in_top = f32::NEG_INFINITY;
        for (i, &v) in lg.iter().enumerate() {
            if top.len() < k {
                top.push((i as u32, v));
                if top.len() == k {
                    min_in_top = top.iter().map(|t| t.1).fold(f32::INFINITY, f32::min);
                }
            } else if v > min_in_top {
                // replace the current minimum
                let (mi, _) = top.iter().enumerate()
                    .min_by(|a, b| a.1.1.partial_cmp(&b.1.1).unwrap()).unwrap();
                top[mi] = (i as u32, v);
                min_in_top = top.iter().map(|t| t.1).fold(f32::INFINITY, f32::min);
            }
        }
        top.sort_unstable_by(|a, b| b.1.partial_cmp(&a.1).unwrap());
        Ok(top)
    }

    /// Zero-(extra-)copy decode step: write the logit vector directly into a
    /// caller-owned host buffer at `addr` (e.g. a numpy array that has been
    /// persistently registered with the RDMA NIC), instead of materializing a
    /// Python list + numpy copy. On a UMA APU the model's host-visible output
    /// is ordinary host pages, so the NIC can then read this buffer directly.
    /// `addr` is a host pointer; `count` is its capacity in f32 elements.
    /// Returns the number of logits written.
    ///
    /// SAFETY: the caller must guarantee [addr, addr + count*4) is a valid,
    /// writable host buffer that outlives this call (keep the numpy array alive).
    #[cfg(feature = "gemma")]
    fn forward_into(&mut self, token_id: u32, position: usize, addr: usize,
                    count: usize) -> PyResult<usize> {
        let logits = if self.engine.is_some() {
            if self.qwen.is_some() {
                self.forward_qwen_gpu(token_id, position)
            } else {
                self.forward_gpu(token_id, position)
            }
        } else {
            self.cpu_model_mut().forward(token_id, position)
        };
        if logits.len() > count {
            return Err(PyRuntimeError::new_err(format!(
                "forward_into: buffer holds {} f32 but logits need {}",
                count,
                logits.len()
            )));
        }
        // SAFETY: contract documented above; non-overlapping host copy.
        unsafe {
            std::ptr::copy_nonoverlapping(
                logits.as_ptr(),
                addr as *mut f32,
                logits.len(),
            );
        }
        Ok(logits.len())
    }

    /// Pipeline-parallel forward over the layers this stage owns
    /// ([pp_start, pp_end)). First stage: pass the token id (hidden_in ignored,
    /// pass []). Mid/last stages: pass the previous stage's hidden state in
    /// hidden_in. Returns the hidden state to send to the next stage, or the
    /// full logit vector on the last stage. Qwen3 GPU path only.
    #[cfg(feature = "gemma")]
    fn forward_pp(&mut self, token_id: u32, hidden_in: Vec<f32>,
                  pos: usize) -> PyResult<Vec<f32>> {
        let cfg = self
            .qwen
            .as_ref()
            .ok_or_else(|| PyRuntimeError::new_err("forward_pp needs a Qwen3 model"))?
            .config
            .clone();
        let h = cfg.hidden_size;
        let eps = cfg.rms_norm_eps;
        let num_q = cfg.num_attention_heads;
        let num_kv = cfg.num_key_value_heads;
        let head_dim = cfg.head_dim;
        let q_dim = num_q * head_dim;
        let kv_dim = num_kv * head_dim;
        let inter = cfg.intermediate_size;
        let vocab = cfg.vocab_size;
        let scale = 1.0f32 / (head_dim as f32).sqrt();
        let (start, first, last) = (self.pp_start, self.pp_first, self.pp_last);

        let mut hidden: Vec<f32> = if first {
            let w = self.qwen.as_ref().unwrap().weights
                .f32_slice("model.embed_tokens.weight");
            w[token_id as usize * h..(token_id as usize + 1) * h].to_vec()
        } else {
            hidden_in
        };

        let gpu_sdpa = self.flags.gpu_sdpa;
        for layer_idx in self.pp_start..self.pp_end {
            let ln = |s: &str| format!("model.layers.{layer_idx}.{s}");
            let cache_idx = layer_idx - start;  // into this stage's kv_caches

            let residual = hidden.clone();
            let inln = self.qwen_w(&ln("input_layernorm.weight"));
            let x = model::cpu_rms_norm(&hidden, &inln, eps);
            let (qn, kn, vn) = (ln("self_attn.q_proj.weight"), ln("self_attn.k_proj.weight"), ln("self_attn.v_proj.weight"));
            let mut qkv = self.qwen_matvec_multi(&x, h, &[(&qn, q_dim), (&kn, kv_dim), (&vn, kv_dim)], true);
            let v = qkv.pop().unwrap();
            let mut k = qkv.pop().unwrap();
            let mut q = qkv.pop().unwrap();
            let q_norm = self.qwen_w(&ln("self_attn.q_norm.weight"));
            let k_norm = self.qwen_w(&ln("self_attn.k_norm.weight"));
            for hi in 0..num_q {
                let s = &mut q[hi * head_dim..(hi + 1) * head_dim];
                let nn = model::cpu_rms_norm(s, &q_norm, eps);
                s.copy_from_slice(&nn);
            }
            for hi in 0..num_kv {
                let s = &mut k[hi * head_dim..(hi + 1) * head_dim];
                let nn = model::cpu_rms_norm(s, &k_norm, eps);
                s.copy_from_slice(&nn);
            }
            model::cpu_rope(&mut q, &mut k, pos, num_q, num_kv, head_dim, head_dim, cfg.rope_theta);
            // Append KV; take owned copies of the cache so we can dispatch GPU SDPA
            // (validated cos=1.0) when VLLM_VULKAN_GPU_SDPA=1, else CPU (cheap at
            // short context; GPU wins as context grows).
            let (ck, cv, slen) = {
                let qm = self.qwen.as_mut().unwrap();
                qm.kv_caches[cache_idx].append(&k, &v);
                let c = &qm.kv_caches[cache_idx];
                (c.k_up_to_now().to_vec(), c.v_up_to_now().to_vec(), c.seq_len)
            };
            let attn_out = if gpu_sdpa {
                self.gpu_sdpa(&q, &ck, &cv, num_q, num_kv, head_dim, slen, scale)
            } else {
                model::cpu_sdpa(&q, &ck, &cv, num_q, num_kv, head_dim, slen, scale, None)
            };
            let attn_proj = self.qwen_matvec(&ln("self_attn.o_proj.weight"), &attn_out, q_dim, h, true);
            let hidden2: Vec<f32> = residual.iter().zip(attn_proj.iter())
                .map(|(&r, &a)| r + a).collect();
            let residual2 = hidden2.clone();

            let pa = self.qwen_w(&ln("post_attention_layernorm.weight"));
            let ff_in = model::cpu_rms_norm(&hidden2, &pa, eps);
            let (gn, un) = (ln("mlp.gate_proj.weight"), ln("mlp.up_proj.weight"));
            let mut gu = self.qwen_matvec_multi(&ff_in, h, &[(&gn, inter), (&un, inter)], true);
            let up = gu.pop().unwrap();
            let gate = gu.pop().unwrap();
            let gate_act = model::cpu_silu(&gate);
            let mid: Vec<f32> = gate_act.iter().zip(up.iter()).map(|(&g, &u)| g * u).collect();
            let ff_out = self.qwen_matvec(&ln("mlp.down_proj.weight"), &mid, inter, h, true);
            hidden = residual2.iter().zip(ff_out.iter()).map(|(&r, &f)| r + f).collect();
        }

        if last {
            let norm_w = self.qwen_w("model.norm.weight");
            let normed = model::cpu_rms_norm(&hidden, &norm_w, eps);
            let lm_name = self.qwen.as_ref().unwrap().lm_head_name.clone();
            Ok(self.qwen_matvec(&lm_name, &normed, h, vocab, true))
        } else {
            Ok(hidden)
        }
    }

    /// Megatron tensor-parallel forward for one Qwen3 token (decode).
    ///
    /// Every rank runs the WHOLE layer stack, but on its 1/N slice of each
    /// projection: column-shard q/k/v/gate/up (this rank computes its
    /// `q_dim/N` q-heads etc.), row-shard o/down (this rank's partial sum over
    /// its input-col slice). The two partial sums (after o_proj, after
    /// down_proj) are completed by an all-reduce(SUM): `all_reduce` is a Python
    /// callable taking the partial Vec<f32> and returning the summed Vec<f32>
    /// (the launcher wires this to vccl Communicator.all_reduce, in-place).
    /// embed / final-norm / lm_head are replicated, so every rank ends with the
    /// identical full logit vector. Validate: TP argmax == single-node argmax.
    #[cfg(feature = "gemma")]
    fn forward_tp(&mut self, py: Python<'_>, token_id: u32, pos: usize,
                  all_reduce: PyObject) -> PyResult<Vec<f32>> {
        let cfg = self
            .qwen
            .as_ref()
            .ok_or_else(|| PyRuntimeError::new_err("forward_tp needs a Qwen3 model"))?
            .config
            .clone();
        let n = self.tp_size.max(1);
        let r = self.tp_rank;
        let h = cfg.hidden_size;
        let eps = cfg.rms_norm_eps;
        let num_q = cfg.num_attention_heads;
        let num_kv = cfg.num_key_value_heads;
        let head_dim = cfg.head_dim;
        // per-rank (sharded) head counts and projection dims
        let r_num_q = num_q / n;
        let r_num_kv = num_kv / n;
        let r_q_dim = r_num_q * head_dim;     // sharded q_proj out / o_proj in
        let r_kv_dim = r_num_kv * head_dim;   // sharded k/v_proj out
        let r_inter = cfg.intermediate_size / n;  // sharded gate/up out, down in
        let vocab = cfg.vocab_size;
        let scale = 1.0f32 / (head_dim as f32).sqrt();

        // Native vCCL FFI (default) vs Python callback (VLLM_VULKAN_NATIVE_COMM=0).
        let native = self.native_comm_enabled();
        let comm = self.collective_comm as *mut std::os::raw::c_void;
        let (scratch_addr, scratch_len) = if self.reduce_scratch_handle != 0 {
            (self.reduce_scratch.as_ptr() as usize, self.reduce_scratch.len())
        } else { (0usize, 0usize) };
        // Closure to all-reduce a partial (sum across ranks). NATIVE: reduce via
        // the pinned scratch (no per-call regMr) or in-place. CALLBACK: callback.
        let reduce = |py: Python<'_>, mut partial: Vec<f32>| -> PyResult<Vec<f32>> {
            if native {
                if scratch_addr != 0 && partial.len() <= scratch_len {
                    unsafe {
                        vccl_ffi::all_reduce_via_scratch(
                            py, comm, scratch_addr, scratch_len, &mut partial)
                    }.map_err(PyRuntimeError::new_err)?;
                } else {
                    vccl_ffi::all_reduce_f32_sum_inplace(py, comm, &mut partial)
                        .map_err(PyRuntimeError::new_err)?;
                }
                Ok(partial)
            } else {
                let out = all_reduce.call1(py, (partial,))?;
                out.extract::<Vec<f32>>(py)
            }
        };

        // Embedding is replicated on every rank.
        let mut hidden: Vec<f32> = {
            let w = self.qwen.as_ref().unwrap().weights
                .f32_slice("model.embed_tokens.weight");
            w[token_id as usize * h..(token_id as usize + 1) * h].to_vec()
        };

        for layer_idx in 0..cfg.num_hidden_layers {
            let ln = |s: &str| format!("model.layers.{layer_idx}.{s}");
            let cache_idx = layer_idx;  // TP: this rank owns all layers

            // ── Attention block ────────────────────────────────────────────
            let residual = hidden.clone();
            let inln = self.qwen_w(&ln("input_layernorm.weight"));
            let x = model::cpu_rms_norm(&hidden, &inln, eps);
            // column-sharded q/k/v: each weight already sliced to r_q_dim/r_kv_dim rows
            let (qn, kn, vn) = (ln("self_attn.q_proj.weight"), ln("self_attn.k_proj.weight"), ln("self_attn.v_proj.weight"));
            let mut qkv = self.qwen_matvec_multi(&x, h, &[(&qn, r_q_dim), (&kn, r_kv_dim), (&vn, r_kv_dim)], true);
            let v = qkv.pop().unwrap();
            let mut k = qkv.pop().unwrap();
            let mut q = qkv.pop().unwrap();
            // q/k norm operate per head_dim — identical regardless of which heads
            let q_norm = self.qwen_w(&ln("self_attn.q_norm.weight"));
            let k_norm = self.qwen_w(&ln("self_attn.k_norm.weight"));
            for hi in 0..r_num_q {
                let s = &mut q[hi * head_dim..(hi + 1) * head_dim];
                let nn = model::cpu_rms_norm(s, &q_norm, eps);
                s.copy_from_slice(&nn);
            }
            for hi in 0..r_num_kv {
                let s = &mut k[hi * head_dim..(hi + 1) * head_dim];
                let nn = model::cpu_rms_norm(s, &k_norm, eps);
                s.copy_from_slice(&nn);
            }
            // RoPE is position-only (no global-head dependence) — per-rank safe.
            model::cpu_rope(&mut q, &mut k, pos, r_num_q, r_num_kv, head_dim, head_dim, cfg.rope_theta);
            let (ck, cv, slen) = {
                let qm = self.qwen.as_mut().unwrap();
                qm.kv_caches[cache_idx].append(&k, &v);
                let c = &qm.kv_caches[cache_idx];
                (c.k_up_to_now().to_vec(), c.v_up_to_now().to_vec(), c.seq_len)
            };
            // attention over THIS rank's heads (GQA ratio preserved)
            let attn_out = model::cpu_sdpa(&q, &ck, &cv, r_num_q, r_num_kv, head_dim, slen, scale, None);
            // row-sharded o_proj: partial sum over this rank's q_dim input slice
            let attn_partial = self.qwen_matvec(&ln("self_attn.o_proj.weight"), &attn_out, r_q_dim, h, true);
            // all-reduce #1: sum the o_proj partials -> full attention output
            let attn_proj = reduce(py, attn_partial)?;
            let hidden2: Vec<f32> = residual.iter().zip(attn_proj.iter())
                .map(|(&a, &b)| a + b).collect();
            let residual2 = hidden2.clone();

            // ── MLP block ──────────────────────────────────────────────────
            let pa = self.qwen_w(&ln("post_attention_layernorm.weight"));
            let ff_in = model::cpu_rms_norm(&hidden2, &pa, eps);
            // column-sharded gate/up (each r_inter wide)
            let (gn, un) = (ln("mlp.gate_proj.weight"), ln("mlp.up_proj.weight"));
            let mut gu = self.qwen_matvec_multi(&ff_in, h, &[(&gn, r_inter), (&un, r_inter)], true);
            let up = gu.pop().unwrap();
            let gate = gu.pop().unwrap();
            let gate_act = model::cpu_silu(&gate);
            let mid: Vec<f32> = gate_act.iter().zip(up.iter()).map(|(&g, &u)| g * u).collect();
            // row-sharded down_proj: partial sum over this rank's inter input slice
            let ff_partial = self.qwen_matvec(&ln("mlp.down_proj.weight"), &mid, r_inter, h, true);
            // all-reduce #2: sum the down_proj partials -> full MLP output
            let ff_out = reduce(py, ff_partial)?;
            hidden = residual2.iter().zip(ff_out.iter()).map(|(&a, &b)| a + b).collect();
        }

        // Final norm + LM head. Replicated -> identical logits on every rank
        // (today's only path: the shared Gemma4/Qwen3-dense streaming loader
        // doesn't populate `lm_shard` for this family yet — vocab-sharding
        // there is loader-side follow-up, tracked with the plan's §2.2 hook;
        // this tail is wired to the generic sharded path so it activates for
        // free once that loader support lands, same tail shape as
        // `forward_tp_qwen35`).
        let norm_w = self.qwen_w("model.norm.weight");
        let normed = model::cpu_rms_norm(&hidden, &norm_w, eps);
        let lm_name = self.qwen.as_ref().unwrap().lm_head_name.clone();
        match self.lm_shard {
            None => Ok(self.qwen_matvec(&lm_name, &normed, h, vocab, true)),
            Some(LmShard { v, .. }) => {
                let (base, rem) = (v / n, v % n);
                let max_per = base + usize::from(rem > 0);
                let per = self.lm_shard.unwrap().per;
                let mut padded = self.qwen_matvec(&lm_name, &normed, h, per, true);
                padded.resize(max_per, 0.0);
                let comm = self.collective_comm as *mut std::os::raw::c_void;
                let recv = vccl_ffi::all_gather_f32(py, comm, &padded, n)
                    .map_err(PyRuntimeError::new_err)?;
                let mut logits = vec![0.0f32; v];
                for r in 0..n {
                    let (rlo, rper) = tp::tp_vocab_shard_range(v, r, n);
                    logits[rlo..rlo + rper].copy_from_slice(&recv[r * max_per..r * max_per + rper]);
                }
                Ok(logits)
            }
        }
    }


































    /// Native vCCL PP ring-back of the sampled/argmax token from the LAST stage
    /// to RANK 0, through a persistent RDMA-registered 1-elem scratch so vCCL
    /// skips the per-call temp-MR (`ibv_reg_mr`/dereg) — the last unregistered
    /// per-token comm buffer (the "buffer not registered with the comm" warning
    /// the hidden-hop registration left behind). SHARED fleet-wide by every PP
    /// decode driver (kimi/qwen35/nemotron), so all inherit one fix.
    ///
    /// Roles mirror the drivers' python `bcast_token` (the ring is last→0 only —
    /// only rank 0 embeds the next token; mid stages forward hidden):
    ///   * LAST stage: `send_to = 0`, `recv_from < 0` ⇒ send `token` onward,
    ///     return it unchanged.
    ///   * RANK 0:     `recv_from = NR-1`, `send_to < 0` ⇒ recv the token,
    ///     return it.
    ///   * MID stage:  both peers `< 0` ⇒ no-op, return `token` unchanged.
    ///
    /// Registered ONCE on first use, gated by `VLLM_VULKAN_REG_REDUCE` (the same
    /// umbrella lever as the TP reduce scratch and the kimi PP hop). Falls back
    /// to a fresh 1-elem send/recv when registration is unavailable. Correctness:
    /// the token id is carried as one f32 and is integer-exact for any vocab
    /// ≪ 2^24, so argmax/gen are byte-identical to the python `INT32` bcast.
    /// NR==1 has no ring — the driver skips this call in that case.
    fn pp_bcast_token(
        &mut self,
        py: Python<'_>,
        token: u32,
        send_to: i32,
        recv_from: i32,
    ) -> PyResult<u32> {
        if !self.native_comm_enabled() {
            return Err(PyRuntimeError::new_err(
                "pp_bcast_token: native comm not enabled (set_collective_comm + VLLM_VULKAN_NATIVE_COMM!=0)"));
        }
        let do_send = send_to >= 0;
        let do_recv = recv_from >= 0;
        // Mid stage (both peers disabled): nothing to ring. With NR>1 a rank is
        // never simultaneously last (send) and first (recv), so send XOR recv.
        if !do_send && !do_recv {
            return Ok(token);
        }
        let comm = self.collective_comm as *mut std::os::raw::c_void;

        // Pin the 1-elem ring scratch ONCE, so send/recv skip the per-call
        // temp-MR. Gated by the reduce-registration umbrella flag; on failure we
        // fall back to the fresh-Vec path (correct, just per-call regMr).
        let want_reg = self.flags.reg_reduce
            && !comm.is_null()
            && vccl_ffi::registration_available();
        if want_reg && self.pp_tok_ring.handle == 0 {
            self.pp_tok_ring.buf = vec![0.0f32; 1];
            let addr = self.pp_tok_ring.buf.as_ptr() as usize;
            match vccl_ffi::comm_register(comm, addr, std::mem::size_of::<f32>()) {
                Ok(h) => self.pp_tok_ring.handle = h,
                Err(e) => {
                    log::warn!("pp_bcast_token: register token scratch failed: {e}; per-call regMr");
                    self.pp_tok_ring.buf.clear();
                }
            }
        }
        let registered = self.pp_tok_ring.handle != 0 && self.pp_tok_ring.buf.len() == 1;

        if do_send {
            if registered {
                self.pp_tok_ring.buf[0] = token as f32;
                vccl_ffi::send_f32(py, comm, &self.pp_tok_ring.buf, send_to)
                    .map_err(PyRuntimeError::new_err)?;
            } else {
                let b = [token as f32];
                vccl_ffi::send_f32(py, comm, &b, send_to).map_err(PyRuntimeError::new_err)?;
            }
            Ok(token)
        } else {
            // do_recv
            let got = if registered {
                vccl_ffi::recv_f32_into(py, comm, &mut self.pp_tok_ring.buf, recv_from)
                    .map_err(PyRuntimeError::new_err)?;
                self.pp_tok_ring.buf[0]
            } else {
                let v = vccl_ffi::recv_f32(py, comm, 1, recv_from)
                    .map_err(PyRuntimeError::new_err)?;
                v[0]
            };
            Ok(got as u32)
        }
    }







    // ── step3p7 STATEFUL DECODE seams (GPU-resident + CPU-oracle) ──────────────
    // The serve-path decode twins of `forward_pp_step3p7_prefill`, resolved BY NAME by
    // the `serve_dist` launcher (`forward_pp_<arch>` / `pp_step_<arch>_logits`). Chaining
    // the single-token decode over a prompt is BIT-IDENTICAL to the stateless prefill
    // (CPU path; the GPU path is argmax-exact vs the oracle up to f16-weight rounding) —
    // the decode==prefill contract, proven offline by `step3p7_decode_equals_prefill`.






    /// Prefill a whole prompt in one pass (Qwen3). Batches the per-layer
    /// projections as GPU GEMMs (each weight read ONCE for all T tokens) instead
    /// of T sequential matvec forwards; norms/RoPE/causal-SDPA run per token on
    /// CPU (cheap). Resets the KV cache and leaves it holding all T tokens, so
    /// decode continues from position T. Returns the LAST token's logits.
    #[cfg(feature = "gemma")]
    fn forward_prefill(&mut self, tokens: Vec<u32>) -> PyResult<Vec<f32>> {
        let cfg = self.qwen.as_ref()
            .ok_or_else(|| PyRuntimeError::new_err("forward_prefill needs a Qwen3 model"))?
            .config.clone();
        let h = cfg.hidden_size; let eps = cfg.rms_norm_eps;
        let num_q = cfg.num_attention_heads; let num_kv = cfg.num_key_value_heads;
        let head_dim = cfg.head_dim;
        let q_dim = num_q * head_dim; let kv_dim = num_kv * head_dim;
        let inter = cfg.intermediate_size; let vocab = cfg.vocab_size;
        let scale = 1.0f32 / (head_dim as f32).sqrt();
        let t = tokens.len();
        if t == 0 { return Err(PyRuntimeError::new_err("empty prompt")); }
        if t > self.max_seq_len {
            return Err(PyRuntimeError::new_err(format!(
                "prompt length {t} exceeds max_seq_len {} — construct VulkanModel with a larger max_seq_len",
                self.max_seq_len)));
        }
        self.reset_kv_cache();

        // Embed all T tokens → [T, h].
        let mut hidden: Vec<f32> = {
            let w = self.qwen.as_ref().unwrap().weights.f32_slice("model.embed_tokens.weight");
            let mut hv = Vec::with_capacity(t * h);
            for &tok in &tokens { hv.extend_from_slice(&w[tok as usize * h..(tok as usize + 1) * h]); }
            hv
        };

        let gpu_sdpa = self.flags.gpu_sdpa;
        for layer_idx in 0..cfg.num_hidden_layers {
            let ln = |s: &str| format!("model.layers.{layer_idx}.{s}");
            let residual = hidden.clone();
            let inln = self.qwen_w(&ln("input_layernorm.weight"));
            let x = model::cpu_rms_norm(&hidden, &inln, eps);              // [T,h] (row-batched)
            // Batched projections via GEMM (weight read once for all T tokens).
            let mut q = self.gpu_gemm(&ln("self_attn.q_proj.weight"), &x, t, h, q_dim);
            let mut k = self.gpu_gemm(&ln("self_attn.k_proj.weight"), &x, t, h, kv_dim);
            let v = self.gpu_gemm(&ln("self_attn.v_proj.weight"), &x, t, h, kv_dim);
            let q_norm = self.qwen_w(&ln("self_attn.q_norm.weight"));
            let k_norm = self.qwen_w(&ln("self_attn.k_norm.weight"));
            let mut attn_out = vec![0f32; t * q_dim];
            for ti in 0..t {
                { let qrow = &mut q[ti * q_dim..(ti + 1) * q_dim];
                  for hi in 0..num_q { let s = &mut qrow[hi * head_dim..(hi + 1) * head_dim];
                      let nn = model::cpu_rms_norm(s, &q_norm, eps); s.copy_from_slice(&nn); } }
                { let krow = &mut k[ti * kv_dim..(ti + 1) * kv_dim];
                  for hi in 0..num_kv { let s = &mut krow[hi * head_dim..(hi + 1) * head_dim];
                      let nn = model::cpu_rms_norm(s, &k_norm, eps); s.copy_from_slice(&nn); } }
                let mut qrow = q[ti * q_dim..(ti + 1) * q_dim].to_vec();
                let mut krow = k[ti * kv_dim..(ti + 1) * kv_dim].to_vec();
                model::cpu_rope(&mut qrow, &mut krow, ti, num_q, num_kv, head_dim, head_dim, cfg.rope_theta);
                let (ck, cv, slen) = {
                    let qm = self.qwen.as_mut().unwrap();
                    qm.kv_caches[layer_idx].append(&krow, &v[ti * kv_dim..(ti + 1) * kv_dim]);
                    let c = &qm.kv_caches[layer_idx];
                    (c.k_up_to_now().to_vec(), c.v_up_to_now().to_vec(), c.seq_len)
                };
                let ao = if gpu_sdpa {
                    self.gpu_sdpa(&qrow, &ck, &cv, num_q, num_kv, head_dim, slen, scale)
                } else {
                    model::cpu_sdpa(&qrow, &ck, &cv, num_q, num_kv, head_dim, slen, scale, None)
                };
                attn_out[ti * q_dim..(ti + 1) * q_dim].copy_from_slice(&ao);
            }
            let attn_proj = self.gpu_gemm(&ln("self_attn.o_proj.weight"), &attn_out, t, q_dim, h);
            let hidden2: Vec<f32> = residual.iter().zip(attn_proj.iter()).map(|(&r, &a)| r + a).collect();
            let residual2 = hidden2.clone();
            let pa = self.qwen_w(&ln("post_attention_layernorm.weight"));
            let ff_in = model::cpu_rms_norm(&hidden2, &pa, eps);
            let gate = self.gpu_gemm(&ln("mlp.gate_proj.weight"), &ff_in, t, h, inter);
            let up = self.gpu_gemm(&ln("mlp.up_proj.weight"), &ff_in, t, h, inter);
            let gate_act = model::cpu_silu(&gate);
            let mid: Vec<f32> = gate_act.iter().zip(up.iter()).map(|(&g, &u)| g * u).collect();
            let ff_out = self.gpu_gemm(&ln("mlp.down_proj.weight"), &mid, t, inter, h);
            hidden = residual2.iter().zip(ff_out.iter()).map(|(&r, &f)| r + f).collect();
        }

        // LM head on the LAST token only (next-token prediction).
        let norm_w = self.qwen_w("model.norm.weight");
        let normed = model::cpu_rms_norm(&hidden[(t - 1) * h..t * h], &norm_w, eps);
        let lm_name = self.qwen.as_ref().unwrap().lm_head_name.clone();
        Ok(self.qwen_matvec(&lm_name, &normed, h, vocab, true))
    }

    /// EAGLE3 fast-verify (design plan §2): T-token (T=2..8) batched forward,
    /// dense/Qwen3-unified only. Appends T tokens at
    /// `start_pos..start_pos+T` and returns `[T*vocab]` logits — next-token
    /// logits at EVERY provisional position, the semantic a real spec-decode
    /// verify pass consumes (unlike `forward_prefill`, which returns only the
    /// last row). GPU path records each layer as ONE command buffer (1
    /// submit/layer) over persistent T-wide buffers so the fixed overhead is
    /// ~1 decode step instead of `forward_prefill`'s ~7 submits/layer; see
    /// `batched_forward.rs` module docs. CPU fallback (no engine / no Qwen3
    /// model) runs T sequential exact `forward` calls.
    #[cfg(feature = "gemma")]
    fn forward_batched(&mut self, tokens: Vec<u32>, start_pos: usize) -> PyResult<Vec<f32>> {
        self.forward_batched_impl(tokens, start_pos).map_err(Into::into)
    }

    /// EAGLE3 Phase 0 gate microbench (spec-decode plan §4): batched-verify
    /// cost vs serial decode, on the SAME loaded model and decode config.
    ///
    /// The qwen3_5 batched forward does not exist yet (that is the Phase 2
    /// item this gate decides), so per the plan's fallback clause this measures
    /// the PROXY on a Qwen3-dense model:
    ///   serial  = T sequential per-token decode forwards (positions 0..T-1)
    ///   batched = `forward_prefill` over the same T tokens (the §2.2 batched
    ///             GEMM template a qwen3_5 verify pass would be built from)
    /// plus the lm_head both ways: prefill does ONE last-row matvec, but a real
    /// k-token verify needs logits at ALL k positions (cheapest as one T-row
    /// GEMM reading the weight once). The gate script composes
    ///   verify(T) ~= prefill(T) - lmhead_matvec1 + lmhead_gemm(T).
    ///
    /// Returns per-iteration mean wall ms:
    ///   (serial_ms, prefill_ms, lmhead_matvec1_ms, lmhead_gemm_t_ms, batched_ms).
    /// `batched_ms` is the DIRECT measurement `forward_batched` was built for
    /// (design plan §4): it already includes the T-row lm_head, so
    /// `verify_direct(T) = batched_ms(T)` needs no `-mv1+gemm` composition —
    /// the legacy `verify(T) ~= prefill(T) - lmhead_matvec1 + lmhead_gemm(T)`
    /// composed from the first four columns stays for cross-check continuity.
    /// Run WITHOUT VLLM_VULKAN_QUANT (gpu_gemm/forward_batched read f16 weights).
    #[cfg(feature = "gemma")]
    fn bench_spec_gate(&mut self, t: usize, iters: usize, warmup: usize) -> PyResult<(f64, f64, f64, f64, f64)> {
        let (h, vocab) = {
            let q = self.qwen.as_ref().ok_or_else(|| PyRuntimeError::new_err(
                "bench_spec_gate needs a Qwen3-dense model (the plan's verify proxy)"))?;
            (q.config.hidden_size, q.config.vocab_size)
        };
        if t == 0 || iters == 0 {
            return Err(PyRuntimeError::new_err("bench_spec_gate: t and iters must be > 0"));
        }
        // Fixed synthetic token ids (always in-vocab); cost is content-independent.
        let tokens: Vec<u32> = (0..t).map(|i| (2 + (i * 97) % 1000) as u32).collect();
        let mean_ms = |total: std::time::Duration, n: usize| total.as_secs_f64() * 1e3 / n as f64;

        // (a) serial: T per-token decode steps from a fresh cache.
        for _ in 0..warmup {
            self.reset_kv_cache();
            for (i, &tok) in tokens.iter().enumerate() { self.forward(tok, i)?; }
        }
        let mut serial = std::time::Duration::ZERO;
        for _ in 0..iters {
            self.reset_kv_cache();
            let t0 = std::time::Instant::now();
            for (i, &tok) in tokens.iter().enumerate() { self.forward(tok, i)?; }
            serial += t0.elapsed();
        }

        // (b) batched: the prefill template over the same T tokens (resets KV itself).
        for _ in 0..warmup { self.forward_prefill(tokens.clone())?; }
        let mut prefill = std::time::Duration::ZERO;
        for _ in 0..iters {
            let t0 = std::time::Instant::now();
            self.forward_prefill(tokens.clone())?;
            prefill += t0.elapsed();
        }

        // (c) lm_head correction terms: 1-row matvec (what prefill pays) vs
        // T-row GEMM (what a real T-token verify pays). Synthetic inputs.
        let lm_name = self.qwen.as_ref().unwrap().lm_head_name.clone();
        let x1: Vec<f32> = (0..h).map(|i| ((i % 13) as f32 - 6.0) * 0.01).collect();
        let xt: Vec<f32> = (0..t * h).map(|i| ((i % 17) as f32 - 8.0) * 0.01).collect();
        for _ in 0..warmup.max(1) {
            self.qwen_matvec(&lm_name, &x1, h, vocab, true);
            self.gpu_gemm(&lm_name, &xt, t, h, vocab);
        }
        let (mut mv1, mut gemm_t) = (std::time::Duration::ZERO, std::time::Duration::ZERO);
        for _ in 0..iters {
            let t0 = std::time::Instant::now();
            self.qwen_matvec(&lm_name, &x1, h, vocab, true);
            mv1 += t0.elapsed();
            let t1 = std::time::Instant::now();
            self.gpu_gemm(&lm_name, &xt, t, h, vocab);
            gemm_t += t1.elapsed();
        }

        // (d) batched: the DIRECT forward_batched measurement. Unlike
        // forward_prefill, forward_batched does NOT reset the KV cache itself
        // (it appends at the caller-given start_pos, trusting caller-managed
        // state — see truncate_kv/§5) so the harness resets explicitly before
        // every timed call, same as the serial loop above.
        for _ in 0..warmup { self.reset_kv_cache(); self.forward_batched(tokens.clone(), 0)?; }
        let mut batched = std::time::Duration::ZERO;
        for _ in 0..iters {
            self.reset_kv_cache();
            let t0 = std::time::Instant::now();
            self.forward_batched(tokens.clone(), 0)?;
            batched += t0.elapsed();
        }

        Ok((mean_ms(serial, iters), mean_ms(prefill, iters), mean_ms(mv1, iters), mean_ms(gemm_t, iters),
            mean_ms(batched, iters)))
    }


    // ── Laguna single-node GPU bit-exact GATE (the make-or-break) ────────────
    // Each feeds an IDENTICAL deterministic-random `hidden`/`h` through the
    // resident GPU forward (`LagunaGpuModel`) and the CPU oracle
    // (`laguna::laguna_*` over `load_owned_layer_cpu` weights) and returns
    // (cos, max_abs_diff, argmax_match). cos≈1.0 + argmax_match + tiny maxdiff =
    // the op is GPU-vs-oracle bit-exact (only the f16 / nvfp4-e4m3 matvec
    // shaders differ from cpu_matmul; every other op is the identical crate fn).
    // The model MUST be loaded resident (VLLM_VULKAN_LAGUNA_RESIDENT=1) with a
    // window containing `layer_idx`.


























    /// SYNTHETIC PP-hop microbench (no model): ping-pong an `[n]` f32 buffer
    /// against the 2-rank peer `iters` times over native vCCL, on a
    /// `comm_register`'d scratch (no PyList, no per-call regMr) — the transport
    /// the fused `pp_step_laguna` uses. `role=0` sends-then-recvs (rank 0),
    /// `role=1` recvs-then-sends (rank 1); the pairing is deadlock-free. Returns
    /// the total wall seconds for `iters` round trips (each = 2 one-way hops).
    /// The Python launcher runs the PyList/`comm.send`/`comm.recv` baseline in a
    /// mirror loop; the per-hop delta isolates the marshal+GIL tax this lever
    /// removes. `comm_handle` is the raw `vcclComm_t` (as usize) from
    /// `comm.handle`; no `set_collective_comm` needed (this bypasses the model).
    #[staticmethod]
    fn bench_pp_hop_native(
        py: Python<'_>,
        comm_handle: usize,
        n: usize,
        iters: usize,
        role: u32,
    ) -> PyResult<f64> {
        let comm = comm_handle as *mut std::os::raw::c_void;
        if comm.is_null() {
            return Err(PyRuntimeError::new_err("bench_pp_hop_native: null comm handle"));
        }
        let peer: i32 = if role == 0 { 1 } else { 0 };
        let mut sbuf = vec![0.0f32; n];
        for (i, s) in sbuf.iter_mut().enumerate() { *s = (i as f32) * 1e-3; }
        let mut rbuf = vec![0.0f32; n];
        // Pin both scratch buffers ONCE (best-effort — matches the fused hop).
        let bytes = n * std::mem::size_of::<f32>();
        let sh = if vccl_ffi::registration_available() {
            vccl_ffi::comm_register(comm, sbuf.as_ptr() as usize, bytes).unwrap_or(0)
        } else { 0 };
        let rh = if vccl_ffi::registration_available() {
            vccl_ffi::comm_register(comm, rbuf.as_ptr() as usize, bytes).unwrap_or(0)
        } else { 0 };
        let t = std::time::Instant::now();
        for _ in 0..iters {
            if role == 0 {
                vccl_ffi::send_f32(py, comm, &sbuf, peer).map_err(PyRuntimeError::new_err)?;
                vccl_ffi::recv_f32_into(py, comm, &mut rbuf, peer).map_err(PyRuntimeError::new_err)?;
            } else {
                vccl_ffi::recv_f32_into(py, comm, &mut rbuf, peer).map_err(PyRuntimeError::new_err)?;
                vccl_ffi::send_f32(py, comm, &sbuf, peer).map_err(PyRuntimeError::new_err)?;
            }
        }
        let elapsed = t.elapsed().as_secs_f64();
        if sh != 0 { let _ = vccl_ffi::comm_deregister(comm, sh); }
        if rh != 0 { let _ = vccl_ffi::comm_deregister(comm, rh); }
        Ok(elapsed)
    }

    /// DEBUG: validate the GPU SwiGLU FFN (qwen_ffn_gpu) vs a CPU reference for
    /// layer `layer` and input x[t*h]. Returns (cosine, max_abs_diff). Needs host
    /// f32 weights (non-lean) for the reference.
    #[cfg(feature = "gemma")]
    fn debug_ffn(&mut self, layer: usize, x: Vec<f32>, t: usize, h: usize, inter: usize) -> PyResult<(f64, f64)> {
        let gn = format!("model.layers.{layer}.mlp.gate_proj.weight");
        let un = format!("model.layers.{layer}.mlp.up_proj.weight");
        let dn = format!("model.layers.{layer}.mlp.down_proj.weight");
        let gpu = self.qwen_ffn_gpu(&x, &gn, &un, &dn, t, h, inter);
        let w = |n: &str| self.qwen.as_ref().unwrap().weights.f32_slice(n).to_vec();
        let gate = model::cpu_matmul(&x, &w(&gn), t, h, inter);
        let up = model::cpu_matmul(&x, &w(&un), t, h, inter);
        let act = model::cpu_silu(&gate);
        let mid: Vec<f32> = act.iter().zip(up.iter()).map(|(&g, &u)| g * u).collect();
        let cpu = model::cpu_matmul(&mid, &w(&dn), t, inter, h);
        let mut dot = 0f64; let mut ng = 0f64; let mut nc = 0f64; let mut maxd = 0f64;
        for (a, b) in gpu.iter().zip(cpu.iter()) {
            dot += (*a as f64) * (*b as f64); ng += (*a as f64).powi(2); nc += (*b as f64).powi(2);
            maxd = maxd.max((*a as f64 - *b as f64).abs());
        }
        Ok((dot / (ng.sqrt() * nc.sqrt() + 1e-12), maxd))
    }

    /// DEBUG: validate GPU decode attention (gpu_sdpa) vs cpu_sdpa for given
    /// q[num_q*hd] and k/v[seq_len*num_kv*hd]. Returns (cosine, max_abs_diff).
    fn debug_sdpa(&mut self, q: Vec<f32>, k: Vec<f32>, v: Vec<f32>,
                  num_q: usize, num_kv: usize, head_dim: usize, seq_len: usize, scale: f32) -> PyResult<(f64, f64)> {
        let gpu = self.gpu_sdpa(&q, &k, &v, num_q, num_kv, head_dim, seq_len, scale);
        let cpu = model::cpu_sdpa(&q, &k, &v, num_q, num_kv, head_dim, seq_len, scale, None);
        let mut dot = 0f64; let mut ng = 0f64; let mut nc = 0f64; let mut maxd = 0f64;
        for (a, b) in gpu.iter().zip(cpu.iter()) {
            dot += (*a as f64) * (*b as f64); ng += (*a as f64).powi(2); nc += (*b as f64).powi(2);
            maxd = maxd.max((*a as f64 - *b as f64).abs());
        }
        Ok((dot / (ng.sqrt() * nc.sqrt() + 1e-12), maxd))
    }

    /// DEBUG: validate the GPU-RESIDENT KV attention (gpu_kv_append +
    /// gpu_sdpa_resident) vs cpu_sdpa. Appends seq_len tokens of k/v to the
    /// resident cache, runs resident attention for q, compares. (roadmap #3a)
    fn debug_kv_resident(&mut self, q: Vec<f32>, k: Vec<f32>, v: Vec<f32>, num_q: usize,
                         num_kv: usize, head_dim: usize, seq_len: usize, scale: f32, max_seq: usize) -> PyResult<(f64, f64)> {
        let stride = num_kv * head_dim;
        self.gpu_kv.remove(&0);
        for t in 0..seq_len {
            self.gpu_kv_append(0, &k[t * stride..(t + 1) * stride], &v[t * stride..(t + 1) * stride], t, num_kv, head_dim, max_seq);
        }
        let gpu = self.gpu_sdpa_resident(0, &q, num_q, num_kv, head_dim, seq_len, scale, max_seq)
            .ok_or_else(|| PyRuntimeError::new_err("gpu_sdpa_resident needs an engine"))?;
        let cpu = model::cpu_sdpa(&q, &k, &v, num_q, num_kv, head_dim, seq_len, scale, None);
        let mut dot = 0f64; let mut ng = 0f64; let mut nc = 0f64; let mut maxd = 0f64;
        for (a, b) in gpu.iter().zip(cpu.iter()) {
            dot += (*a as f64) * (*b as f64); ng += (*a as f64).powi(2); nc += (*b as f64).powi(2);
            maxd = maxd.max((*a as f64 - *b as f64).abs());
        }
        Ok((dot / (ng.sqrt() * nc.sqrt() + 1e-12), maxd))
    }

    /// DEBUG: validate GPU flash attention (gpu_flash_attn) vs cpu_sdpa.
    ///
    /// `causal=false` (decode): q[num_q*head_dim], k/v[seq_len*num_kv*head_dim],
    ///   all keys visible (mask=None). Matches cpu_sdpa directly.
    /// `causal=true` (prefill): q is seq_len query positions laid out per-head as
    ///   [head][pos][head_dim]; each query position i attends keys 0..=i via an
    ///   upper-triangular -inf mask. The reference runs cpu_sdpa once per position
    ///   (seq_len=i+1) so the comparison is exact (modulo f16 K/V).
    /// Returns (cosine, max_abs_diff).
    fn debug_flash(&mut self, q: Vec<f32>, k: Vec<f32>, v: Vec<f32>,
                   num_q: usize, num_kv: usize, head_dim: usize, seq_len: usize,
                   scale: f32, causal: bool) -> PyResult<(f64, f64)> {
        let (gpu, cpu) = if !causal {
            // Decode: 1 query per head, all kv visible.
            let gpu = self.gpu_flash_attn(&q, &k, &v, num_q, num_kv, head_dim, 1, seq_len, scale, None);
            let cpu = model::cpu_sdpa(&q, &k, &v, num_q, num_kv, head_dim, seq_len, scale, None);
            (gpu, cpu)
        } else {
            // Causal prefill: seq_len queries. q layout = [head][pos][head_dim].
            // Build the upper-triangular mask [pos_q × kv]: pos i attends keys
            // 0..=i, blocks the rest with -inf.
            let neg = f32::NEG_INFINITY;
            let mut mask = vec![0f32; seq_len * seq_len];
            for i in 0..seq_len {
                for j in 0..seq_len {
                    if j > i { mask[i * seq_len + j] = neg; }
                }
            }
            let gpu = self.gpu_flash_attn(&q, &k, &v, num_q, num_kv, head_dim,
                                          seq_len, seq_len, scale, Some(&mask));
            // Reference: for each head h and query position i, cpu_sdpa over the
            // first i+1 keys with a single query = q[h][i]. The GPU output is laid
            // out [pos n][head h][head_dim], so write the reference the same way.
            let mut cpu = vec![0f32; num_q * seq_len * head_dim];
            for h in 0..num_q {
                let kvh = h / (num_q / num_kv);
                for i in 0..seq_len {
                    let qslice = &q[(h * seq_len + i) * head_dim..(h * seq_len + i + 1) * head_dim];
                    // single-head cpu_sdpa: pack a [1-head] q and the kv for kvh.
                    let mut kpack = Vec::with_capacity((i + 1) * head_dim);
                    let mut vpack = Vec::with_capacity((i + 1) * head_dim);
                    for kv in 0..=i {
                        let base = (kv * num_kv + kvh) * head_dim;
                        kpack.extend_from_slice(&k[base..base + head_dim]);
                        vpack.extend_from_slice(&v[base..base + head_dim]);
                    }
                    let o = model::cpu_sdpa(qslice, &kpack, &vpack, 1, 1, head_dim, i + 1, scale, None);
                    let dst = (i * num_q + h) * head_dim; // [pos n][head h]
                    cpu[dst..dst + head_dim].copy_from_slice(&o);
                }
            }
            (gpu, cpu)
        };
        let mut dot = 0f64; let mut ng = 0f64; let mut nc = 0f64; let mut maxd = 0f64;
        for (a, b) in gpu.iter().zip(cpu.iter()) {
            dot += (*a as f64) * (*b as f64); ng += (*a as f64).powi(2); nc += (*b as f64).powi(2);
            maxd = maxd.max((*a as f64 - *b as f64).abs());
        }
        Ok((dot / (ng.sqrt() * nc.sqrt() + 1e-12), maxd))
    }



    /// DEBUG: raw GPU flash-attn output (causal, mask-applied) for inspection.
    /// q [head][pos][head_dim], returns [pos][head][head_dim].
    fn debug_flash_raw(&mut self, q: Vec<f32>, k: Vec<f32>, v: Vec<f32>,
                       num_q: usize, num_kv: usize, head_dim: usize, seq_len: usize,
                       scale: f32) -> PyResult<Vec<f32>> {
        let neg = f32::NEG_INFINITY;
        let mut mask = vec![0f32; seq_len * seq_len];
        for i in 0..seq_len { for j in 0..seq_len { if j > i { mask[i * seq_len + j] = neg; } } }
        Ok(self.gpu_flash_attn(&q, &k, &v, num_q, num_kv, head_dim, seq_len, seq_len, scale, Some(&mask)))
    }

    /// DEBUG: validate the GPU tiled GEMM (gpu_gemm) against cpu_matmul for a
    /// given weight and random-ish input x[t,k]. Returns (cosine, max_abs_diff)
    /// over the [t,n] output. Requires the host f32 weight (non-lean load).
    #[cfg(feature = "gemma")]
    fn debug_gemm(&mut self, weight_name: &str, x: Vec<f32>, t: usize, k: usize, n: usize) -> PyResult<(f64, f64)> {
        let gpu = self.gpu_gemm(weight_name, &x, t, k, n);
        let w = if let Some(q) = self.qwen.as_ref() {
            q.weights.f32_slice(weight_name).to_vec()
        } else {
            self.inner.weights.f32_slice(weight_name).to_vec()
        };
        let cpu = model::cpu_matmul(&x, &w, t, k, n);
        let mut dot = 0f64; let mut ng = 0f64; let mut nc = 0f64; let mut maxd = 0f64;
        for (a, b) in gpu.iter().zip(cpu.iter()) {
            dot += (*a as f64) * (*b as f64);
            ng += (*a as f64) * (*a as f64);
            nc += (*b as f64) * (*b as f64);
            maxd = maxd.max((*a as f64 - *b as f64).abs());
        }
        Ok((dot / (ng.sqrt() * nc.sqrt() + 1e-12), maxd))
    }


    /// STEP-7 DRAFT localization harness (MTP re-gate acceptance debug): prime
    /// the LAST-stage model with `prompt`, then draft `depth` tokens off the
    /// prefill frontier via the MTP head AND compute the base model's ACTUAL
    /// greedy continuation at the SAME positions. Returns
    /// `(drafts, greedy, t0, h_pre_l2)`:
    ///   * `drafts[i]` vs `greedy[i]` — a healthy head matches `greedy[0]` ~85%
    ///     of the time (alpha_1); systematic `drafts[0] != greedy[0]` ⇒ the head
    ///     is fed a wrong `h_pre` or the wrong `[embed;hidden]` concat order.
    ///   * `t0` = the first generated (real) token, at position `prompt.len()`.
    ///   * `h_pre_l2` = L2 norm of the pre-`model.norm` hidden fed to `d_1`
    ///     (`prenorm_for_pos(prompt.len()-1)`); a ~0 value ⇒ a zero/absent stash.
    /// Drafts FIRST (advances only the head KV), then greedy (advances base KV),
    /// so the greedy continuation starts from the true prefill frontier. Toggle
    /// `VLLM_VULKAN_MTP_CONCAT_FLIP=1` and re-run to test the concat order.
    /// Advances resident state (call from a fresh/re-primeable harness context).
    #[cfg(feature = "mtp")]
    fn debug_mtp_draft_vs_greedy(&mut self, prompt: Vec<u32>, depth: usize)
        -> PyResult<(Vec<u32>, Vec<u32>, u32, f64)>
    {
        if prompt.is_empty() {
            return Err(PyRuntimeError::new_err("debug_mtp_draft_vs_greedy: empty prompt"));
        }
        self.reset_kv_cache();
        let mut last = Vec::new();
        for (i, &tok) in prompt.iter().enumerate() {
            last = self.forward_pp_qwen35_impl(tok, Vec::new(), i)?;
        }
        let argmax = |v: &[f32]| -> u32 {
            let (mut bi, mut bv) = (0u32, f32::NEG_INFINITY);
            for (i, &x) in v.iter().enumerate() { if x > bv { bv = x; bi = i as u32; } }
            bi
        };
        let t0 = argmax(&last);
        let prompt_pos = prompt.len();
        let head_base = prompt_pos - 1;
        let hpre = self.prenorm_for_pos(head_base).unwrap_or_default();
        let hpre_l2 = hpre.iter().map(|&x| (x as f64) * (x as f64)).sum::<f64>().sqrt();
        // Draft (bootstrap): reset the head KV, chain off t0.
        self.mtp_reset();
        let drafts = self.mtp_draft_chain_impl(t0, head_base, depth)
            .map_err(PyRuntimeError::new_err)?;
        // Base greedy continuation from the prefill frontier (state @ prompt_pos).
        let mut greedy = Vec::with_capacity(depth);
        let (mut tok, mut p) = (t0, prompt_pos);
        for _ in 0..depth {
            let lg = self.forward_pp_qwen35_impl(tok, Vec::new(), p)?;
            let g = argmax(&lg);
            greedy.push(g);
            tok = g;
            p += 1;
        }
        Ok((drafts, greedy, t0, hpre_l2))
    }

    /// DEBUG: validate qwen_rmsnorm_gpu vs model::cpu_rms_norm. Returns (cos, maxd).
    #[cfg(feature = "gemma")]
    fn debug_rmsnorm(&mut self, x: Vec<f32>, weight: Vec<f32>, n_rows: usize,
                     n_cols: usize, eps: f32) -> PyResult<(f64, f64)> {
        let gpu = self.qwen_rmsnorm_gpu(&x, &weight, n_rows, n_cols, eps);
        let cpu = model::cpu_rms_norm(&x, &weight, eps);
        Ok(cos_maxd(&gpu, &cpu))
    }

    /// DEBUG: validate qwen_rope_gpu vs model::cpu_rope. q/k laid out
    /// [num_heads, head_dim]. Returns (cos, maxd) over the concatenated q‖k.
    #[cfg(feature = "gemma")]
    fn debug_rope(&mut self, q: Vec<f32>, k: Vec<f32>, pos: usize, num_q: usize,
                  num_kv: usize, head_dim: usize, theta: f32) -> PyResult<(f64, f64)> {
        let (mut qg, mut kg) = (q.clone(), k.clone());
        self.qwen_rope_gpu(&mut qg, &mut kg, pos, num_q, num_kv, head_dim, head_dim, theta);
        let (mut qc, mut kc) = (q.clone(), k.clone());
        model::cpu_rope(&mut qc, &mut kc, pos, num_q, num_kv, head_dim, head_dim, theta);
        let gpu: Vec<f32> = qg.iter().chain(kg.iter()).copied().collect();
        let cpu: Vec<f32> = qc.iter().chain(kc.iter()).copied().collect();
        Ok(cos_maxd(&gpu, &cpu))
    }

    /// Reset the KV cache (start a new sequence).
    fn reset_kv_cache(&mut self) {
        // Restart the Gemma 1-CB resident-KV watermark for the new sequence.
        // gpu_kv buffers stay allocated (each position is overwritten before it
        // is read, so no stale-read hazard); only the fill counter resets.
        self.gemma_kv_filled = 0;
        // Ling / BailingMoeV3: re-zero the resident decode state (KDA recurrence +
        // conv window + MLA KV cache — host or GPU) so a new serve request starts a
        // fresh sequence. The distributed serve OP_RESET boundary routes here; the
        // ling prefill seam also self-resets, so this is belt-and-suspenders.
        #[cfg(feature = "ling")]
        if let Some(m) = self.ling.as_mut() {
            m.reset_decode_state();
            return;
        }
        #[cfg(feature = "qwen35")]
        if let Some(m) = self.qwen35.as_mut() {
            m.reset();  // resets both DeltaNetState + KvCache for all layers
            // WS1b: the GPU-resident DeltaNet conv/delta state is authoritative
            // while VLLM_VULKAN_DN_GPU is on — zero it alongside the CPU state
            // (host-coherent buffers: a direct write is safe between submits).
            for l in self.dn_gpu.values() {
                let _ = l.conv_state.write(&vec![0u8; l.conv_state.size as usize]);
                let _ = l.state.write(&vec![0u8; l.state.size as usize]);
            }
            return;
        }
        #[cfg(feature = "gemma")]
        self.cpu_model_mut().reset_kv_cache();
    }

    /// P1 speculative-pipelining: snapshot ALL per-token mutable decode state
    /// (GatedDeltaNet conv+delta state, full-attn KV counters) into rollback
    /// ring `slot`, so a rejected speculative token can be rolled back exactly.
    /// See `spec_snapshot_impl`. `slot` is a small ring index (0..~4).
    #[cfg(feature = "qwen35")]
    fn spec_snapshot(&mut self, slot: usize) -> PyResult<()> {
        self.spec_snapshot_impl(slot).map_err(PyRuntimeError::new_err)
    }

    /// P1 speculative-pipelining: restore the state captured by `spec_snapshot`
    /// into ring `slot`, bit-exactly rewinding this stage. Caller owns the
    /// position counter (`pos`) — it is not model state. See `spec_restore_impl`.
    #[cfg(feature = "qwen35")]
    fn spec_restore(&mut self, slot: usize) -> PyResult<()> {
        self.spec_restore_impl(slot).map_err(PyRuntimeError::new_err)
    }

    /// P1 gate helper: FNV-1a fingerprint of ALL resident mutable decode state,
    /// one u64 per resident layer. Compare across a snapshot/restore to prove
    /// bit-exact rollback on the real model. See `spec_state_fingerprint_impl`.
    #[cfg(feature = "qwen35")]
    fn spec_state_fingerprint(&self) -> PyResult<Vec<u64>> {
        self.spec_state_fingerprint_impl().map_err(PyRuntimeError::new_err)
    }









    /// Design-A accept resolver (spec §5): the `src/spec_pipe.rs::resolve_chain`
    /// algebra exposed to the Python driver so the last rank commits the exact
    /// greedy accept-prefix without re-deriving it. Returns
    /// `(accept_len, emitted, new_real, new_pos, restore_slot)` — `restore_slot`
    /// is `-1` on a full accept (no rollback), else `k`.
    fn spec_resolve_chain(
        &self,
        drafts: Vec<u32>,
        real: u32,
        pos: usize,
        a_out: u32,
        b_outs: Vec<u32>,
    ) -> PyResult<(usize, Vec<u32>, u32, usize, i64)> {
        if b_outs.len() != drafts.len() {
            return Err(PyRuntimeError::new_err("spec_resolve_chain: b_outs must have one argmax per draft"));
        }
        let r = spec_pipe::resolve_chain(&drafts, real, pos, a_out, &b_outs);
        Ok((r.accept_len, r.emitted, r.new_real, r.new_pos,
            r.restore_slot.map(|s| s as i64).unwrap_or(-1)))
    }

    /// LMCache-NAS Step 1: export a resumable KV prefix at boundary
    /// `upto_seq_len` for THIS stage's resident layers (full-attn K/V slice
    /// + linear-layer DeltaNet recurrent snapshot), as the versioned `PFX1`
    /// binary blob documented in `qwen35::Qwen35Model::export_prefix`.
    /// Qwen3.6 (`qwen3_5`) only; errors clearly for other model types or an
    /// unloaded model. When any linear layer's DeltaNet state is
    /// GPU-authoritative (`VLLM_VULKAN_DN_GPU=1`, including the `Q35_1CB`
    /// resident stage which reads/writes the same `dn_gpu` buffers), this
    /// first downloads the live device state into the host snapshot
    /// (`dn_gpu_sync_to_host`, direct memcpy — the buffers are host-coherent
    /// and quiescent between tokens, same as `spec_state_fingerprint_impl`)
    /// so the host-only serialization below captures the authoritative
    /// values instead of a stale host copy.
    #[cfg(feature = "qwen35")]
    fn kv_export_prefix(&mut self, py: Python<'_>, upto_seq_len: usize) -> PyResult<PyObject> {
        self.dn_gpu_sync_to_host().map_err(PyRuntimeError::new_err)?;
        let m = self.qwen35.as_ref().ok_or_else(|| {
            PyRuntimeError::new_err("kv_export_prefix requires a loaded qwen3_5 model")
        })?;
        let blob = m.export_prefix(upto_seq_len).map_err(PyRuntimeError::new_err)?;
        Ok(pyo3::types::PyBytes::new(py, &blob).into())
    }

    /// LMCache-NAS Step 1: import a resumable KV prefix produced by
    /// `kv_export_prefix` into THIS stage's resident layers. Validates the
    /// blob's config/layout fingerprint against this model and returns a
    /// clear `Err` on mismatch (never a panic or silent wrong state).
    /// Returns the loaded prefix length. When any linear layer's DeltaNet
    /// state is GPU-authoritative, uploads the restored host snapshot back
    /// into the live `dn_gpu` device buffers after the host-side restore
    /// (`dn_gpu_sync_from_host`) so the next resident-path token reads the
    /// imported state rather than the stale device copy.
    #[cfg(feature = "qwen35")]
    fn kv_import_prefix(&mut self, blob: &[u8]) -> PyResult<usize> {
        let m = self.qwen35.as_mut().ok_or_else(|| {
            PyRuntimeError::new_err("kv_import_prefix requires a loaded qwen3_5 model")
        })?;
        let n = m.import_prefix(blob).map_err(PyRuntimeError::new_err)?;
        self.dn_gpu_sync_from_host().map_err(PyRuntimeError::new_err)?;
        Ok(n)
    }

    /// LMCache-NAS Phase 1 (`plan-lmcache-nas.md` §5/§8): explicitly (re)open
    /// the content-addressed KV NAS-store backend at `dir` with a host-RAM
    /// LRU capped at `lru_mb` megabytes. Optional — `kv_cache_store`/
    /// `kv_cache_load` lazily open from `VLLM_VULKAN_KV_STORE_DIR`/
    /// `VLLM_VULKAN_KV_LRU_MB` on first use if this was never called
    /// (documented ambiguity call: both an explicit pymethod AND an env
    /// default are supported, matching every other `VLLM_VULKAN_*` knob in
    /// this codebase). `dir` is a plain filesystem path — a local directory
    /// on Mac today, the CIFS mount later (`kvstore.rs` is filesystem-agnostic).
    fn kv_cache_init(&mut self, dir: String, lru_mb: usize) -> PyResult<()> {
        self.kv_store = Some(kvstore::KvStore::open(dir, lru_mb).map_err(|e| {
            PyRuntimeError::new_err(format!("kv_cache_init: failed to open store dir: {e}"))
        })?);
        Ok(())
    }

    /// Lazily open `self.kv_store` from env if `kv_cache_init` was never
    /// called. Returns `Ok(false)` (not an error) if neither happened AND
    /// `VLLM_VULKAN_KV_STORE_DIR` is unset — `kv_cache_store`/`kv_cache_load`
    /// treat "no NAS configured" as a clean no-op/miss, not a hard failure.
    fn ensure_kv_store(&mut self) -> PyResult<bool> {
        if self.kv_store.is_some() {
            return Ok(true);
        }
        let dir = match std::env::var("VLLM_VULKAN_KV_STORE_DIR") {
            Ok(d) if !d.is_empty() => d,
            _ => return Ok(false),
        };
        let lru_mb: usize = std::env::var("VLLM_VULKAN_KV_LRU_MB")
            .ok()
            .and_then(|v| v.parse().ok())
            .unwrap_or(512);
        self.kv_cache_init(dir, lru_mb)?;
        Ok(true)
    }

    /// NAS prefix-cache Phase 1: set the `(weights_id, tokenizer_hash)` identity
    /// folded into the topology-agnostic KV content fingerprint (scope §3.3) so
    /// a re-quant or tokenizer bump MISSES cleanly instead of serving stale KV.
    /// Stored process-global (env) so it survives across the `kv_cache_store`/
    /// `kv_cache_load` pymethods without threading a new field through every
    /// `VulkanModel` constructor. The Python side owns both hashes
    /// (`server.py`): `weights_id` = a hash of the checkpoint index / dir
    /// listing, `tokenizer_hash` = a hash of `tokenizer.json` bytes.
    fn kv_cache_set_identity(&mut self, weights_id: u64, tokenizer_hash: u64) {
        std::env::set_var("VLLM_VULKAN_KV_WEIGHTS_ID", weights_id.to_string());
        std::env::set_var("VLLM_VULKAN_KV_TOKENIZER_HASH", tokenizer_hash.to_string());
    }

    /// `(weights_id, tokenizer_hash)` for the content fingerprint — set by
    /// `kv_cache_set_identity`, both default 0 (a store warmed with the default
    /// identity is self-consistent; mixing identities across runs is exactly
    /// what the fingerprint MISS guards against).
    fn kv_identity(&self) -> (u64, u64) {
        let w = std::env::var("VLLM_VULKAN_KV_WEIGHTS_ID")
            .ok()
            .and_then(|v| v.parse().ok())
            .unwrap_or(0);
        let t = std::env::var("VLLM_VULKAN_KV_TOKENIZER_HASH")
            .ok()
            .and_then(|v| v.parse().ok())
            .unwrap_or(0);
        (w, t)
    }

    /// NAS prefix-cache Phase 1 tile WRITE path (scope §2.3): serialize each
    /// owned `(layer, kv_head)` tile at `boundary` under the topology-agnostic
    /// `base_key`, storing only tiles the manifest doesn't already hold
    /// (idempotent). Split into model-borrow / store-borrow phases to satisfy
    /// the borrow checker (the model and `kv_store` are disjoint fields).
    fn kv_cache_store_tiles(&mut self, token_ids: Vec<u32>, boundary: usize) -> PyResult<()> {
        let dtype = crate::kv_prefix::KvDtype::from_env();
        let (weights_id, tokenizer_hash) = self.kv_identity();
        let chain = kvstore::chunk_boundary_hashes(&token_ids)
            .into_iter()
            .find(|(b, _)| *b == boundary)
            .map(|(_, c)| c)
            .ok_or_else(|| {
                PyRuntimeError::new_err(format!(
                    "kv_cache_store: token_ids too short ({}) for chunk-aligned boundary {boundary}",
                    token_ids.len()
                ))
            })?;

        // 1. content_fp + tile addresses (cheap model borrow; also sync any
        //    GPU-authoritative KV to host — a no-op for gemma / Laguna).
        let (bk, specs): (u64, Vec<crate::kv_prefix::TileSpec>) = {
            let m = self.kv_tile_model_mut().unwrap();
            m.sync_before_export().map_err(PyRuntimeError::new_err)?;
            let dims = m.kv_content_dims();
            let content_fp =
                crate::kv_prefix::content_fingerprint(&dims, weights_id, tokenizer_hash, dtype);
            (kvstore::base_key(content_fp, chain), m.owned_tiles())
        };

        // 2. keep only tiles the backend doesn't already hold (store borrow).
        let missing: Vec<crate::kv_prefix::TileSpec> = {
            let store = self.kv_store.as_ref().unwrap();
            specs
                .into_iter()
                .filter(|t| !store.contains(kvstore::tile_key(bk, t.layer, t.kv_head)))
                .collect()
        };

        // 3. export the missing tiles (model borrow).
        let pairs: Vec<(u64, Vec<u8>)> = {
            let m = self.kv_tile_model_ref().unwrap();
            let mut out = Vec::with_capacity(missing.len());
            for t in &missing {
                let blob = m
                    .export_tile(t.layer, t.kv_head, boundary, dtype)
                    .map_err(PyRuntimeError::new_err)?;
                out.push((kvstore::tile_key(bk, t.layer, t.kv_head), blob));
            }
            out
        };

        // 4. persist (store borrow).
        let store = self.kv_store.as_mut().unwrap();
        for (tk, blob) in pairs {
            store.store(tk, &blob).map_err(|e| {
                PyRuntimeError::new_err(format!("kv_cache_store: backend write failed: {e}"))
            })?;
        }
        Ok(())
    }

    /// NAS prefix-cache Phase 1 tile READ path (scope §2.4): longest-prefix tile
    /// coverage → import every needed tile at the winning boundary, set
    /// `seq_len`, and return that boundary (0 on a clean miss). v1 requires FULL
    /// coverage of the rank's owned set at a boundary.
    fn kv_cache_load_tiles(&mut self, token_ids: Vec<u32>) -> PyResult<usize> {
        let dtype = crate::kv_prefix::KvDtype::from_env();
        let (weights_id, tokenizer_hash) = self.kv_identity();

        // 1. content_fp + this rank's needed tile set (model borrow).
        let (content_fp, needed): (u64, Vec<(usize, usize)>) = {
            let m = self.kv_tile_model_ref().unwrap();
            let dims = m.kv_content_dims();
            let fp =
                crate::kv_prefix::content_fingerprint(&dims, weights_id, tokenizer_hash, dtype);
            let needed = m
                .owned_tiles()
                .into_iter()
                .map(|t| (t.layer, t.kv_head))
                .collect();
            (fp, needed)
        };

        // 2. longest-prefix full-coverage lookup (store borrow).
        let (boundary, bk) = match self
            .kv_store
            .as_ref()
            .unwrap()
            .lookup_longest_prefix_tiles(&token_ids, content_fp, &needed)
        {
            Some(x) => x,
            None => return Ok(0),
        };

        // 3. load every needed tile's blob (store borrow).
        let blobs: Vec<(usize, usize, Vec<u8>)> = {
            let store = self.kv_store.as_mut().unwrap();
            let mut out = Vec::with_capacity(needed.len());
            for &(l, h) in &needed {
                match store.load(kvstore::tile_key(bk, l, h)) {
                    Some(b) => out.push((l, h, b)),
                    // Manifest said covered; a load miss here is a torn store —
                    // treat as a clean miss rather than serving partial KV.
                    None => return Ok(0),
                }
            }
            out
        };

        // 4. import + set seq_len + push to device (model borrow; sync a no-op
        //    for gemma / Laguna).
        let m = self.kv_tile_model_mut().unwrap();
        for (l, h, blob) in &blobs {
            m.import_tile(*l, *h, blob).map_err(PyRuntimeError::new_err)?;
        }
        m.set_seq_len(boundary);
        m.sync_after_import().map_err(PyRuntimeError::new_err)?;
        Ok(boundary)
    }

    /// LMCache-NAS Phase 1: store a resumable prefix for `token_ids` at the
    /// chunk-aligned boundary `floor(upto_seq_len / CHUNK) * CHUNK` (v1 pins
    /// storage to whole-chunk boundaries only, per `kvstore.rs`'s module doc
    /// — a sub-chunk remainder tail is NOT persisted and will simply be
    /// recomputed on the next request). A no-op `Ok(())` if the aligned
    /// boundary is 0 (nothing to store yet, e.g. a prompt shorter than one
    /// `kvstore::CHUNK` — logged at `warn` so this legitimate no-op is never
    /// mistaken for a swallowed failure) or if no NAS dir is configured.
    /// Same device-readback handling as `kv_export_prefix` when DN_GPU-resident
    /// linear layers are active.
    fn kv_cache_store(&mut self, token_ids: Vec<u32>, upto_seq_len: usize) -> PyResult<()> {
        if !self.ensure_kv_store()? {
            return Ok(());
        }
        let boundary = (upto_seq_len / kvstore::CHUNK) * kvstore::CHUNK;
        if boundary == 0 {
            log::warn!(
                "kv_cache_store: upto_seq_len={upto_seq_len} < CHUNK={} — nothing stored \
                 (chunk-aligned no-op, not an error)",
                kvstore::CHUNK
            );
            return Ok(());
        }
        // Attention-KV archs (gemma / resident Laguna) use the canonical
        // `(layer, kv_head)`-tile store (topology-agnostic, NAS prefix-cache
        // Phase 1). qwen3_5 keeps its recurrent-state `PFX1` per-stage blob (P4
        // unifies it) — fall through below.
        if self.kv_tile_model_ref().is_some() {
            return self.kv_cache_store_tiles(token_ids, boundary);
        }
        // qwen3_5 recurrent-state (PFX1) per-stage blob path.
        #[cfg(feature = "qwen35")]
        {
        self.dn_gpu_sync_to_host().map_err(PyRuntimeError::new_err)?;
        let layout = self.kv_layout_tag();
        let m = self.qwen35.as_ref().ok_or_else(|| {
            PyRuntimeError::new_err("kv_cache_store requires a loaded qwen3_5 model")
        })?;
        let fp = qwen35::prefix_fingerprint(&m.config, m.pp_start, m.pp_end);
        let chain = kvstore::chunk_boundary_hashes(&token_ids)
            .into_iter()
            .find(|(b, _)| *b == boundary)
            .map(|(_, c)| c)
            .ok_or_else(|| PyRuntimeError::new_err(format!(
                "kv_cache_store: token_ids too short ({}) for chunk-aligned boundary {boundary}",
                token_ids.len()
            )))?;
        let key = kvstore::kv_key(fp, layout, chain);
        let blob = m.export_prefix(boundary).map_err(PyRuntimeError::new_err)?;
        self.kv_store.as_mut().unwrap().store(key, &blob).map_err(|e| {
            PyRuntimeError::new_err(format!("kv_cache_store: backend write failed: {e}"))
        })
        }
        #[cfg(not(feature = "qwen35"))]
        Err(PyRuntimeError::new_err(
            "kv_cache_store: no attention-KV model and the qwen3_5 recurrent-state \
             path is disabled in this build (feature `qwen35` off)"))
    }

    /// LMCache-NAS Phase 1: longest-prefix lookup + load + import for
    /// `token_ids`. Returns the loaded prefix length (0 on a clean miss,
    /// including "no NAS configured" — never an error for a plain cache
    /// miss). Same device-readback handling as `kv_import_prefix` when
    /// DN_GPU-resident linear layers are active.
    fn kv_cache_load(&mut self, token_ids: Vec<u32>) -> PyResult<usize> {
        if !self.ensure_kv_store()? {
            return Ok(0);
        }
        // Attention-KV archs → canonical tile read path (NAS prefix-cache P1).
        if self.kv_tile_model_ref().is_some() {
            return self.kv_cache_load_tiles(token_ids);
        }
        // qwen3_5 recurrent-state (PFX1) per-stage blob path.
        #[cfg(feature = "qwen35")]
        {
        let layout = self.kv_layout_tag();
        let fp = {
            let m = self.qwen35.as_ref().ok_or_else(|| {
                PyRuntimeError::new_err("kv_cache_load requires a loaded qwen3_5 model")
            })?;
            qwen35::prefix_fingerprint(&m.config, m.pp_start, m.pp_end)
        };
        let hit = {
            let store = self.kv_store.as_mut().unwrap();
            store.lookup_longest_prefix(&token_ids, fp, layout)
        };
        let Some((_boundary, key)) = hit else { return Ok(0) };
        let blob = {
            let store = self.kv_store.as_mut().unwrap();
            store.load(key)
        };
        let Some(blob) = blob else { return Ok(0) };
        let m = self.qwen35.as_mut().unwrap();
        let n = m.import_prefix(&blob).map_err(PyRuntimeError::new_err)?;
        self.dn_gpu_sync_from_host().map_err(PyRuntimeError::new_err)?;
        Ok(n)
        }
        // No qwen3_5 recurrent-state path in this build → treat as a clean miss.
        #[cfg(not(feature = "qwen35"))]
        Ok(0)
    }

    /// Current sequence length.
    fn seq_len(&self) -> usize {
        #[cfg(feature = "gemma")]
        { self.cpu_model_ref().seq_len() }
        #[cfg(not(feature = "gemma"))]
        { 0 }
    }

    /// Number of layers.
    fn num_layers(&self) -> usize {
        #[cfg(feature = "gemma")]
        { self.cpu_model_ref().num_layers() }
        #[cfg(not(feature = "gemma"))]
        { 0 }
    }

    /// Whether GPU acceleration is active — reports the truth across EVERY
    /// engine field, not just `self.engine`.
    ///
    /// The dense / qwen35 / gemma paths keep their compute engine in
    /// `self.engine`. The GPU-resident hybrid archs each OWN their engine in a
    /// sub-model and deliberately leave `VulkanModel.engine == None`:
    ///   - Laguna resident   → `laguna_gpu.engine` (`laguna_gpu::LagunaGpuModel`)
    ///   - Nemotron gpu-mamba → `nemotron.engine` (via `attach_gpu_mamba`)
    ///   - Kimi resident      → `kimi.gpu` (a `kimi_gpu::KimiGpuStage`)
    /// Checking only `self.engine` here mislabelled all three as `gpu=False`
    /// even though they run fully GPU-resident (11.7GB GTT / GPU-speed for
    /// Laguna) — the recurring "is it on CPU?" false alarm. This is a pure
    /// REPORTING accessor (no caller uses it to pick an execution path); it just
    /// answers "is a GPU engine live anywhere in this model?".
    fn has_gpu(&self) -> bool {
        self.is_gpu_resident()
    }

    /// True when ANY GPU compute engine is active for this model — covers the
    /// shared `self.engine` AND the per-arch resident engines that live in the
    /// sub-models (see `has_gpu`). Single source of truth for GPU-status
    /// reporting.
    fn is_gpu_resident(&self) -> bool {
        #[allow(unused_mut)]
        let mut r = self.engine.is_some();
        #[cfg(feature = "laguna")]
        { r = r || self.laguna_gpu.as_ref().map_or(false, |g| g.engine.is_some()); }
        #[cfg(feature = "nemotron")]
        { r = r || self.nemotron.as_ref().map_or(false, |n| n.engine.is_some()); }
        #[cfg(feature = "kimi")]
        { r = r || self.kimi.as_ref().map_or(false, |k| k.gpu.is_some()); }
        #[cfg(feature = "ling")]
        { r = r || self.ling.as_ref().map_or(false, |l| l.gpu.is_some()); }
        r
    }

    /// Host-path profiler dump (VLLM_VULKAN_PROFILE=1): [(bucket, total_ms, count)].
    fn dump_profile(&self) -> Vec<(String, f64, u64)> {
        PROFILE.with(|p| p.borrow().iter()
            .map(|(k,(ns,c))| (k.to_string(), *ns as f64 / 1e6, *c)).collect())
    }
    fn reset_profile(&self) {
        PROFILE.with(|p| p.borrow_mut().clear());
    }

    /// Empty-CB submit-overhead FLOOR microbench (submit-tax go/no-go study).
    /// Submits `iters` near-empty command buffers on the real compute queue —
    /// each records `dispatches` tiny 16-byte buffer copies (≈0 GPU work) — and
    /// records into the same eng_qsubmit / eng_fence / floor_record profiler
    /// buckets used by the real decode. Reset the profiler first, run this,
    /// then dump_profile: eng_qsubmit/eng_fence per-submit is the fixed RADV
    /// submit-build + queue + fence-drain floor, INDEPENDENT of real GPU-exec.
    /// Requires VLLM_VULKAN_PROFILE=1 (prof_add is a no-op otherwise).
    fn bench_submit_floor(&mut self, iters: u64, dispatches: u64) -> PyResult<u64> {
        let eng = self.engine.as_mut()
            .ok_or_else(|| PyRuntimeError::new_err("bench_submit_floor: no engine"))?;
        let buf = eng.alloc_host_coherent_storage(4096)
            .map_err(PyRuntimeError::new_err)?;
        for _ in 0..iters {
            let t_rec = std::time::Instant::now();
            let cb = eng.begin_batch().map_err(PyRuntimeError::new_err)?;
            for _ in 0..dispatches.max(1) {
                eng.record_copy_to(cb, &buf, &buf, 0, 2048, 16);
            }
            prof_add("floor_record", t_rec);
            // submit_batch itself buckets eng_qsubmit (end+queue ioctl) and
            // eng_fence (blocking drain) — same split as the real path.
            eng.submit_batch(cb).map_err(PyRuntimeError::new_err)?;
        }
        Ok(iters)
    }



    /// DEBUG: Run forward pass and return hidden state after N layers.
    /// Used to find numerical bugs by comparing with HuggingFace.
    #[cfg(feature = "gemma")]
    fn forward_n_layers(&mut self, token_id: u32, position: usize, n_layers: usize) -> PyResult<Vec<f32>> {
        use model::*;
        if self.qwen.is_some() {
            return Err(PyRuntimeError::new_err(
                "forward_n_layers is only implemented for Gemma4 models",
            ));
        }
        let cfg = self.inner.config.clone();
        let h = cfg.hidden_size;
        let eps = cfg.rms_norm_eps;
        let ple_dim = cfg.hidden_size_per_layer_input;
        let total_ple = cfg.num_hidden_layers * ple_dim;

        // Embedding
        let embed_w = self.inner.weights.f32_slice("model.embed_tokens.weight");
        let mut hidden: Vec<f32> = embed_w[token_id as usize * h..(token_id as usize + 1) * h]
            .iter().map(|&v| v * cfg.embed_scale).collect();

        // PLE preprocessing (bf16-resident table; convert this token's row)
        let ple_bits = self.gemma_ple_bf16.as_ref()
            .expect("gemma_ple_bf16 must be loaded on the PLE-owning stage");
        let row0 = token_id as usize * total_ple;
        let ple_embeds: Vec<f32> = ple_bits[row0..row0 + total_ple]
            .iter().map(|&b| half::bf16::from_bits(b).to_f32() * cfg.ple_scale).collect();
        let proj_w = self.inner.weights.f32_slice("model.per_layer_model_projection.weight");
        let ple_proj = cpu_matmul(&hidden, proj_w, 1, h, total_ple);
        let ple_proj: Vec<f32> = ple_proj.iter().map(|&v| v * cfg.per_layer_projection_scale).collect();
        let pn_w = self.inner.weights.f32_slice("model.per_layer_projection_norm.weight");
        let ple_proj_normed = cpu_rms_norm(&ple_proj, pn_w, eps);
        let ple_inputs: Vec<f32> = ple_proj_normed.iter().zip(ple_embeds.iter())
            .map(|(&p, &e)| (p + e) * cfg.per_layer_input_scale).collect();

        // N layers
        for layer_idx in 0..n_layers.min(cfg.num_hidden_layers) {
            let layer_ple = &ple_inputs[layer_idx * ple_dim..(layer_idx + 1) * ple_dim];
            hidden = self.inner.forward_layer(layer_idx, &hidden, position, layer_ple);
        }

        Ok(hidden)
    }

    // ── MTP draft head, GPU-dense wiring (plan §P2 remainder) ───────────────
    /// Explicit MTP head load (P2 GPU-dense wiring) — alternative to the
    /// `VLLM_VULKAN_MTP_PATH` auto-load at construction time, for harnesses
    /// that build the model first and decide whether to draft afterward.
    #[cfg(feature = "mtp")]
    fn load_mtp(&mut self, mtp_path: &str) -> PyResult<()> {
        self.load_mtp_gpu(std::path::Path::new(mtp_path))
            .map_err(PyRuntimeError::new_err)
    }

    /// One MTP draft position (P2 GPU-dense path). See `mtp_draft` for the
    /// argument/return contract; returns draft logits [vocab].
    #[cfg(feature = "mtp")]
    fn mtp_draft_step(&mut self, embed_next: Vec<f32>, hidden_pre: Vec<f32>, pos: usize) -> PyResult<Vec<f32>> {
        self.mtp_draft(&embed_next, &hidden_pre, pos).map_err(PyRuntimeError::new_err)
    }

    /// Same as `mtp_draft_step`, but returns only the argmax token id. A real
    /// speculative-decode integration (native Rust loop, e.g. `pp_step_qwen35`)
    /// never needs the full [vocab] logits vector to cross the pyo3 boundary —
    /// only the winning token id. Avoids marshalling a ~250K-float Vec per
    /// call, which otherwise dominates a harness-measured D on a large-vocab
    /// model (the PyO3 Vec<f32>->list conversion, not the compute).
    #[cfg(feature = "mtp")]
    fn mtp_draft_argmax(&mut self, embed_next: Vec<f32>, hidden_pre: Vec<f32>, pos: usize) -> PyResult<u32> {
        let logits = self.mtp_draft(&embed_next, &hidden_pre, pos).map_err(PyRuntimeError::new_err)?;
        let mut best_i = 0usize;
        let mut best_v = f32::NEG_INFINITY;
        for (i, &v) in logits.iter().enumerate() {
            if v > best_v {
                best_v = v;
                best_i = i;
            }
        }
        Ok(best_i as u32)
    }

    /// P3 speculative-pipelining: reset the MTP head's KV (start a fresh draft
    /// chain at the top of a new sequence). No-op if no head is loaded.
    #[cfg(feature = "mtp")]
    #[pyo3(name = "mtp_reset")]
    fn mtp_reset_py(&mut self) {
        self.mtp_reset();
    }

    /// P3 speculative-pipelining: draft ONE token off a just-committed
    /// `(hidden, token)` pair, entirely on-node. Unlike `mtp_draft_argmax`, the
    /// driver marshals NO float vectors: `embed_next` is looked up from the
    /// last stage's resident embed table (kept for MTP on the untied last
    /// stage, see `keep_embed`), and `hidden_pre` is the pre-`model.norm`
    /// residual stashed by the most recent last-stage forward
    /// (`q35_last_prenorm`). `token` is the committed token whose embedding
    /// conditions the draft; `head_pos` is the target sequence position of the
    /// stashed hidden (== the head-KV / RoPE position — the caller keeps the
    /// head KV gap-free by advancing `head_pos` by exactly one per committed
    /// token). Returns the drafted next token's argmax and advances the head KV
    /// by one position.
    #[cfg(feature = "mtp")]
    fn mtp_draft_after(&mut self, token: u32, head_pos: usize) -> PyResult<u32> {
        // Embedding row of `token` from the resident f16 embed table.
        let embed_next = self.mtp_embed_row(token).map_err(PyRuntimeError::new_err)?;
        // Pre-norm residual that PRODUCED the token at `head_pos+1` (the pass fed
        // the token at `head_pos`) — by position, so the depth-1 accept/reject
        // drafts and the full-accept catch-up all source the right hidden even
        // when it is not the freshest stash. Falls back to `q35_last_prenorm`.
        let hidden_pre = self.prenorm_for_pos(head_pos).ok_or_else(|| {
            PyRuntimeError::new_err(
                "mtp_draft_after: no captured pre-norm hidden — call after a last-stage forward")
        })?;
        let logits = self.mtp_draft(&embed_next, &hidden_pre, head_pos)
            .map_err(PyRuntimeError::new_err)?;
        let (mut bi, mut bv) = (0usize, f32::NEG_INFINITY);
        for (i, &v) in logits.iter().enumerate() {
            if v > bv { bv = v; bi = i; }
        }
        Ok(bi as u32)
    }

    /// P4 chained draft: produce `depth` autoregressive drafts off a
    /// just-committed `first_token` in ONE pyo3 call (the marshalling win — a
    /// depth-4 chain is 1 round trip, not 4). `head_pos` is the head-KV/RoPE
    /// position of the first draft. See `mtp_draft_chain_impl`. The driver rewinds
    /// the head KV to the confirmed frontier (`mtp_kv_rewind`) before each call so
    /// the chain refills gap-free. Returns `[d_1..d_depth]`.
    #[cfg(feature = "mtp")]
    #[pyo3(signature = (first_token, head_pos, depth = 4))]
    fn mtp_draft_chain(&mut self, first_token: u32, head_pos: usize, depth: usize) -> PyResult<Vec<u32>> {
        self.mtp_draft_chain_impl(first_token, head_pos, depth).map_err(PyRuntimeError::new_err)
    }

    /// P4 continuous refill: rewind the MTP head KV to `len` positions, dropping a
    /// mispredicted speculative suffix while KEEPING the confirmed prefix's KV +
    /// RoPE context (so the head is never reset to position 0). No-op if no head.
    #[cfg(feature = "mtp")]
    fn mtp_kv_rewind(&mut self, len: usize) {
        if let Some(head) = self.mtp_head.as_mut() {
            head.kv_rewind(len);
        }
    }

    /// Current MTP head-KV length (positions consumed) — lets the driver track the
    /// head's confirmed frontier for gap-free refill. 0 if no head.
    #[cfg(feature = "mtp")]
    #[getter]
    fn mtp_kv_len(&self) -> usize {
        self.mtp_head.as_ref().map(|h| h.kv_len()).unwrap_or(0)
    }

    /// Debug/harness hook: apply the target's shared lm_head to an
    /// externally-computed head hidden vector (e.g. the engine-less
    /// `MtpHeadPy.head_hidden` CPU reference). Lets an on-node harness isolate
    /// the dense-projection GPU-vs-CPU numeric delta from the lm_head itself —
    /// both `mtp_draft_step` and this call go through the identical resident
    /// lm_head buffer, so any argmax mismatch is attributable solely to the
    /// dense/attn/MoE path that differs between the two head implementations.
    #[cfg(feature = "mtp")]
    fn mtp_lm_head_logits(&mut self, hidden: Vec<f32>) -> PyResult<Vec<f32>> {
        let cfg = self.qwen35.as_ref()
            .ok_or_else(|| PyRuntimeError::new_err("mtp_lm_head_logits needs a loaded qwen3_5 model"))?;
        let (h, vocab) = (cfg.config.hidden_size, cfg.config.vocab_size);
        if hidden.len() != h {
            return Err(PyRuntimeError::new_err(format!("expected hidden len {h}, got {}", hidden.len())));
        }
        let lm_name = self.qwen35.as_ref().unwrap().lm_head_name.clone();
        Ok(self.qwen35_matvec(&lm_name, &hidden, h, vocab))
    }

    /// Same as `mtp_lm_head_logits`, but returns only the argmax token id —
    /// avoids marshalling the full [vocab] logits vector across pyo3 for
    /// large-vocab harnesses (mirrors `mtp_draft_argmax`'s rationale).
    #[cfg(feature = "mtp")]
    fn mtp_lm_head_argmax(&mut self, hidden: Vec<f32>) -> PyResult<u32> {
        let logits = self.mtp_lm_head_logits(hidden)?;
        let mut best_i = 0usize;
        let mut best_v = f32::NEG_INFINITY;
        for (i, &v) in logits.iter().enumerate() {
            if v > best_v {
                best_v = v;
                best_i = i;
            }
        }
        Ok(best_i as u32)
    }

    /// Reset the MTP head's KV — begin a new draft chain from a freshly-
    /// accepted true token.
    #[cfg(feature = "mtp")]
    fn mtp_reset_head(&mut self) {
        self.mtp_reset();
    }

    /// Whether an MTP draft head is currently loaded (GPU-dense path ready).
    #[cfg(feature = "mtp")]
    #[getter]
    fn mtp_loaded(&self) -> bool {
        self.mtp_head.is_some()
    }
}

// Non-PyO3 implementation methods for VulkanModel
impl VulkanModel {
    /// LAST-stage half of the PP logits ring-back: send the full `[vocab]` logit
    /// vector `out` to rank0 (`peer`) THROUGH the persistent RDMA-registered
    /// `pp_vocab_ring` scratch, so vCCL skips the per-token temp-MR
    /// (`ibv_reg_mr`/dereg) and the "vocab ring-back buffer not registered with
    /// the comm" warn the fresh per-call `Vec` hit. Pinned ONCE (re-pinned on a
    /// vocab/comm change, same guard as `pp_send_hidden`), gated by
    /// `VLLM_VULKAN_REG_REDUCE`; on unavailable/failed registration it sends
    /// `out` directly (correct, just the per-call regMr). BIT-EXACT with the old
    /// path: only the buffer's NIC registration changes — the f32 payload wired
    /// is byte-identical (a `copy_from_slice` of the same `out`). Not a
    /// `#[pymethods]` item — an internal seam helper; kept in this plain `impl`.
    fn pp_send_vocab(&mut self, py: Python<'_>, out: &[f32], peer: i32) -> PyResult<()> {
        let comm = self.collective_comm as *mut std::os::raw::c_void;
        let want_reg = self.flags.reg_reduce
            && !comm.is_null()
            && vccl_ffi::registration_available();
        if want_reg && (self.pp_vocab_ring.handle == 0 || self.pp_vocab_ring.buf.len() != out.len()) {
            pin_pp_hop(comm, &mut self.pp_vocab_ring, out.len(), "pp_step_logits vocab ring-back");
        }
        if stage_vocab_send(&mut self.pp_vocab_ring, out) {
            vccl_ffi::send_f32(py, comm, &self.pp_vocab_ring.buf, peer)
                .map_err(PyRuntimeError::new_err)
        } else {
            vccl_ffi::send_f32(py, comm, out, peer).map_err(PyRuntimeError::new_err)
        }
    }

    /// RANK0 half of the PP logits ring-back: recv the full `[vocab]` logit vector
    /// from the last stage (`peer`) INTO the persistent RDMA-registered
    /// `pp_vocab_ring` scratch and return a clone (the scratch stays pinned for
    /// the next token). Pinning/gating/fallback identical to `pp_send_vocab`;
    /// BIT-EXACT with the old `recv_f32(vocab, peer)` — same bytes land, only the
    /// destination buffer's registration differs.
    fn pp_recv_vocab(&mut self, py: Python<'_>, vocab: usize, peer: i32) -> PyResult<Vec<f32>> {
        let comm = self.collective_comm as *mut std::os::raw::c_void;
        let want_reg = self.flags.reg_reduce
            && !comm.is_null()
            && vccl_ffi::registration_available();
        if want_reg && (self.pp_vocab_ring.handle == 0 || self.pp_vocab_ring.buf.len() != vocab) {
            pin_pp_hop(comm, &mut self.pp_vocab_ring, vocab, "pp_step_logits vocab ring-back");
        }
        if self.pp_vocab_ring.handle != 0 && self.pp_vocab_ring.buf.len() == vocab {
            vccl_ffi::recv_f32_into(py, comm, &mut self.pp_vocab_ring.buf, peer)
                .map_err(PyRuntimeError::new_err)?;
            Ok(self.pp_vocab_ring.buf.clone())
        } else {
            vccl_ffi::recv_f32(py, comm, vocab, peer).map_err(PyRuntimeError::new_err)
        }
    }


    /// The parallelism-layout dimension of the KV NAS key (plan §3.4/§3.5):
    /// PP range + TP rank/size, so a chunk cached under one layout can never
    /// be loaded under another (single-layout on Mac today, but built
    /// correctly for the future TP/PP cluster case). Not a pymethod (return
    /// type isn't PyO3-representable) — internal helper for
    /// `kv_cache_store`/`kv_cache_load`.
    ///
    /// The canonical-tile serializer for the loaded attention-KV arch (gemma or
    /// resident Laguna), or `None` for qwen3_5 (keeps its `PFX1` per-stage path
    /// in P1). `self.inner` is the live gemma exactly when no other arch loaded.
    /// (Plain-impl, non-pymethod: `&dyn` returns aren't PyO3-representable.)
    fn kv_tile_model_mut(&mut self) -> Option<&mut dyn crate::kv_prefix::KvPrefixExport> {
        #[cfg(feature = "laguna")]
        if let Some(m) = self.laguna_gpu.as_mut() {
            return Some(m);
        }
        // `self.inner` (Gemma4Model) is the LIVE model exactly when no other arch
        // sub-model is loaded — else it is an empty placeholder. Every non-gemma
        // arch field must be `None` before the KV-tile path treats `inner` as the
        // gemma tile source (guards the tile store from serializing a placeholder
        // gemma when a non-tile arch is loaded). Inlined field checks (NOT a
        // `&self` helper) so the borrow stays disjoint from `laguna_gpu` above.
        #[cfg(feature = "gemma")]
        if self.qwen.is_none()
            && self.qwen35.is_none()
            && self.step3p7.is_none()
            && self.nemotron.is_none()
            && self.kimi.is_none()
            && self.ling.is_none()
            && self.laguna.is_none()
        {
            return Some(&mut self.inner);
        }
        None
    }

    fn kv_tile_model_ref(&self) -> Option<&dyn crate::kv_prefix::KvPrefixExport> {
        #[cfg(feature = "laguna")]
        if let Some(m) = self.laguna_gpu.as_ref() {
            return Some(m);
        }
        #[cfg(feature = "gemma")]
        if self.qwen.is_none()
            && self.qwen35.is_none()
            && self.step3p7.is_none()
            && self.nemotron.is_none()
            && self.kimi.is_none()
            && self.ling.is_none()
            && self.laguna.is_none()
        {
            return Some(&self.inner);
        }
        None
    }

    fn kv_layout_tag(&self) -> kvstore::LayoutTag {
        kvstore::LayoutTag {
            pp_start: self.pp_start,
            pp_end: self.pp_end,
            tp_rank: self.tp_rank,
            tp_size: self.tp_size,
        }
    }




    /// Rust-native body of `forward` (no pyo3 in the signature or error type),
    /// callable from unit tests and `forward_batched_impl` without pulling
    /// Python C-API symbols into the test binary.
    pub(crate) fn forward_rs(&mut self, token_id: u32, position: usize) -> gpu_error::GpuResult<Vec<f32>> {
        // Qwen3.6 (qwen3_5) hybrid: its own GatedDeltaNet+GatedAttention forward
        // (CPU, Phase 1; GPU = forward_qwen35_gpu, Phase 2).
        #[cfg(feature = "qwen35")]
        if self.qwen35.is_some() {
            // Phase 2: GPU projections when opted in and the engine exists; else
            // the CPU reference forward. (embed/lm_head live f16 in q35_f16_host,
            // so the CPU path is forward_qwen35_cpu_ref, not Qwen35Model::forward
            // which expects f32 embed/lm_head in `weights`.)
            if self.engine.is_some() && self.flags.qwen35_gpu {
                return Ok(self.forward_qwen35_gpu(token_id, position));
            }
            return Ok(self.forward_qwen35_cpu_ref(token_id, position));
        }
        // GPU acceleration is architecture-specific; the CPU reference path is
        // dispatched uniformly through the LanguageModel trait. Base Qwen3/Gemma4
        // dense = the `gemma` feature.
        #[cfg(feature = "gemma")]
        {
        if self.engine.is_some() {
            // UNIFIED GPU layer engine (one `gpu_layer` for BOTH arches). Opt-in;
            // dispatched first so it overrides the per-arch resident paths.
            let unified = self.flags.unified;
            if self.qwen.is_some() {
                if unified {
                    self.forward_unified_qwen(token_id, position)
                } else if self.flags.resident {
                    // GPU-resident decode path (roadmap #2). Opt-in; default untouched.
                    self.forward_qwen_gpu_resident(token_id, position)
                } else {
                    Ok(self.forward_qwen_gpu(token_id, position))
                }
            } else if unified {
                self.forward_unified_gemma(token_id, position)
            } else if self.flags.gemma_resident {
                // Fused GPU-resident Gemma4 decode path (roadmap P4). Opt-in;
                // default path (forward_gpu) untouched.
                Ok(self.forward_gemma_gpu_resident(token_id, position))
            } else {
                Ok(self.forward_gpu(token_id, position))
            }
        } else {
            Ok(self.cpu_model_mut().forward(token_id, position))
        }
        }
        #[cfg(not(feature = "gemma"))]
        {
            let _ = (token_id, position);
            Err("forward_rs: no model matched and the base gemma/qwen3 dense path \
                 is disabled in this build (feature `gemma` off)".to_string().into())
        }
    }

    /// The active CPU reference model (Qwen3 if loaded, else Gemma4), as the
    /// shared `LanguageModel` interface. Base dense pair only → `gemma`.
    #[cfg(feature = "gemma")]
    pub(crate) fn cpu_model_ref(&self) -> &dyn model::LanguageModel {
        match self.qwen.as_ref() {
            Some(q) => q,
            None => &self.inner,
        }
    }

    #[cfg(feature = "gemma")]
    pub(crate) fn cpu_model_mut(&mut self) -> &mut dyn model::LanguageModel {
        match self.qwen.as_mut() {
            Some(q) => q,
            None => &mut self.inner,
        }
    }


























    /// GPU matmul (single) with CPU fallback.
    /// Initialise persistent activation buffers sized for one decode step.
    #[cfg(feature = "gemma")]
    pub(crate) fn init_act_bufs(&mut self) -> bool {
        if self.act_bufs_ready { return true; }
        let eng = match self.engine.as_mut() { Some(e) => e, None => return false };
        let cfg = &self.inner.config;
        let h = cfg.hidden_size;
        let q_dim = cfg.num_attention_heads * cfg.global_head_dim; // largest (full-attn layers)
        let kv_dim = cfg.num_key_value_heads * cfg.global_head_dim;
        let ffn_inter = cfg.intermediate_size * 2; // largest (double-wide KV-shared layers)

        let ple_dim = cfg.hidden_size_per_layer_input; // 256
        let sizes: [u64; ACT_COUNT] = [
            (h * 4) as u64,          // ACT_QKV_IN
            (q_dim * 4) as u64,      // ACT_Q_OUT
            (kv_dim * 4) as u64,     // ACT_K_OUT
            (kv_dim * 4) as u64,     // ACT_V_OUT
            (q_dim * 4) as u64,      // ACT_O_IN
            (h * 4) as u64,          // ACT_O_OUT
            (h * 4) as u64,          // ACT_FFIN
            (ffn_inter * 4) as u64,  // ACT_GATE
            (ffn_inter * 4) as u64,  // ACT_UP
            (ffn_inter * 4) as u64,  // ACT_MID
            (h * 4) as u64,          // ACT_DOWN
            (ffn_inter * 4) as u64,  // ACT_GELU
            (ple_dim * 4) as u64,    // ACT_PLE_G
            (h * 4) as u64,          // ACT_PLE_C
        ];

        self.act_bufs.clear();
        for &sz in &sizes {
            // A 0-byte host-coherent allocation faults RADV (null-deref inside
            // the driver). g12b has no per-layer-embedding table
            // (hidden_size_per_layer_input == 0), so ACT_PLE_G would be size 0;
            // that PLE slot is never dispatched on a non-PLE model (the PLE
            // block is gated on cfg.has_ple()), but the slot index must stay
            // valid for act_ptr(), so allocate a minimal placeholder instead of
            // skipping it. Clamp every slot to a nonzero minimum.
            let sz = sz.max(16);
            match eng.alloc_host_coherent_storage(sz) {
                Ok(buf) => self.act_bufs.push(buf),
                Err(e) => {
                    log::warn!("Failed to allocate activation buffer: {e}");
                    self.act_bufs.clear();
                    return false;
                }
            }
        }
        self.act_bufs_ready = true;
        log::info!("Allocated {} persistent activation buffers ({:.1} KB)",
            ACT_COUNT,
            sizes.iter().sum::<u64>() as f32 / 1024.0);
        true
    }

    /// Get pointer to a persistent activation buffer by slot index.
    /// SAFETY: caller must not hold other borrows to act_bufs.
    pub(crate) fn act_ptr(&self, slot: usize) -> *const compute::Buffer {
        &self.act_bufs[slot] as *const compute::Buffer
    }

    pub(crate) fn act_ptr_mut(&mut self, slot: usize) -> *mut compute::Buffer {
        &mut self.act_bufs[slot] as *mut compute::Buffer
    }

    pub(crate) fn gpu_matmul_or_cpu(&mut self, weight_name: &str, x: &[f32],
                          t: usize, k: usize, n: usize, pc: &[u8]) -> Vec<f32> {
        if let (Some(eng), Some(w_ptr)) = (
            self.engine.as_mut(),
            self.gpu_weights.get(weight_name).map(|w| &w.buffer as *const compute::Buffer)
        ) {
            let xb = f32_slice_to_bytes(x);
            let inp = eng.alloc_host_coherent_storage((x.len() * 4) as u64).unwrap();
            inp.write(&xb).unwrap();
            let out = eng.alloc_host_coherent_storage((t * n * 4) as u64).unwrap();
            let inp_p = &inp as *const compute::Buffer;
            let out_p = &out as *const compute::Buffer;
            let cb = eng.begin_batch().unwrap();
            unsafe {
                eng.record_to(cb, matvec_shader(true),
                    &[&*w_ptr, &*inp_p, &*out_p], pc, (n as u32, t as u32, 1)).unwrap();
            }
            eng.submit_batch(cb).unwrap();
            let result = read_f32_buf(&out, t * n);
            eng.return_to_pool(inp);
            eng.return_to_pool(out);
            result
        } else {
            // CPU fallback reads the base Gemma4 (`inner`) host weights → `gemma`.
            #[cfg(feature = "gemma")]
            { let w = self.inner.weights.f32_slice(weight_name); model::cpu_matmul(x, w, t, k, n) }
            #[cfg(not(feature = "gemma"))]
            { let _ = (weight_name, x, k); vec![0.0f32; t * n] }
        }
    }

    /// GPU double-matmul (gate + up) with CPU fallback.
    pub(crate) fn gpu_matmul2_or_cpu(&mut self, w1_name: &str, w2_name: &str, x: &[f32],
                           t: usize, k: usize, n: usize, pc: &[u8]) -> (Vec<f32>, Vec<f32>) {
        if let (Some(eng), true) = (
            self.engine.as_mut(),
            self.gpu_weights.contains_key(w1_name) && self.gpu_weights.contains_key(w2_name)
        ) {
            let w1_ptr = &self.gpu_weights[w1_name].buffer as *const compute::Buffer;
            let w2_ptr = &self.gpu_weights[w2_name].buffer as *const compute::Buffer;
            let xb = f32_slice_to_bytes(x);
            let inp = eng.alloc_host_coherent_storage((x.len() * 4) as u64).unwrap();
            inp.write(&xb).unwrap();
            let out1 = eng.alloc_host_coherent_storage((t * n * 4) as u64).unwrap();
            let out2 = eng.alloc_host_coherent_storage((t * n * 4) as u64).unwrap();
            let inp_p  = &inp  as *const compute::Buffer;
            let out1_p = &out1 as *const compute::Buffer;
            let out2_p = &out2 as *const compute::Buffer;
            let cb = eng.begin_batch().unwrap();
            unsafe {
                let sh = matvec_shader(true);
                eng.record_to(cb, sh, &[&*w1_ptr, &*inp_p, &*out1_p], pc, (n as u32, t as u32, 1)).unwrap();
                eng.record_barrier_to(cb);
                eng.record_to(cb, sh, &[&*w2_ptr, &*inp_p, &*out2_p], pc, (n as u32, t as u32, 1)).unwrap();
            }
            eng.submit_batch(cb).unwrap();
            let r1 = read_f32_buf(&out1, t * n);
            let r2 = read_f32_buf(&out2, t * n);
            eng.return_to_pool(inp);
            eng.return_to_pool(out1);
            eng.return_to_pool(out2);
            (r1, r2)
        } else {
            // CPU fallback reads the base Gemma4 (`inner`) host weights → `gemma`.
            #[cfg(feature = "gemma")]
            { let w1 = self.inner.weights.f32_slice(w1_name);
              let w2 = self.inner.weights.f32_slice(w2_name);
              (model::cpu_matmul(x, w1, t, k, n), model::cpu_matmul(x, w2, t, k, n)) }
            #[cfg(not(feature = "gemma"))]
            { let _ = (w1_name, w2_name, x, k); (vec![0.0f32; t * n], vec![0.0f32; t * n]) }
        }
    }

    /// GPU tiled GEMM for PREFILL: out[t,n] = x[t,k] @ W[n,k]^T, reading the f16
    /// weight ONCE for all t tokens (vs the matvec batch path which re-reads it
    /// per token). Uses the `matmul_f16_f32_fp32` mul_mm kernel by default
    /// (BM=BN=64, BK=16), or the GEMM-campaign Phase 1 winner
    /// (`matmul_f16_f32_f16_aligned`, shape-keyed geometry — see
    /// `gemm_variant_k`) on the swept (k,n) shapes, unless
    /// VLLM_VULKAN_GEMM_F16ALIGNED=0. CPU fallback when no engine/weight. This
    /// is the prefill lever: prompt processing is weight-bandwidth-bound, so
    /// one read for the whole prompt is ~t× less bandwidth than t sequential
    /// matvecs.
    pub(crate) fn gpu_gemm(&mut self, weight_name: &str, x: &[f32], t: usize, k: usize, n: usize) -> Vec<f32> {
        let (variant, bm, bn) = gemm_variant_k(k, n);
        let (bm, bn) = (bm as usize, bn as usize);
        if let (Some(eng), Some(w_ptr)) = (
            self.engine.as_mut(),
            self.gpu_weights.get(weight_name).map(|w| &w.buffer as *const compute::Buffer),
        ) {
            let xb = f32_slice_to_bytes(x);
            let inp = eng.alloc_host_coherent_storage((t * k * 4) as u64).unwrap();
            inp.write(&xb).unwrap();
            let out = eng.alloc_host_coherent_storage((t * n * 4) as u64).unwrap();
            let inp_p = &inp as *const compute::Buffer;
            let out_p = &out as *const compute::Buffer;
            // mul_mm computes D[m,nn] = sum_k A[m,k]*B[nn,k], storing element
            // (m,nn) at data_d[nn*stride_d + m]. We want row-major
            // out[token*n + col] = sum_k x[token,k]*W[col,k]. Map:
            //   A = weight  (M = n cols, stride_a = k)   -> binding 0 (A_TYPE=f16)
            //   B = input   (N = t tokens, stride_b = k) -> binding 1 (B_TYPE=f32)
            //   D: stride_d = n, so (col, token) lands at token*n + col (row-major).
            // The shader's A/B data types (f16/f32) fix this binding order: the
            // f16 weight MUST be on binding 0 and the f32 input on binding 1.
            // `bm`/`bn` come from `gemm_variant_k` — legacy BM=BN=64 outside
            // the swept win region, the picked tile inside it.
            let pc = gemm_pc(t, n, k);
            let wg = (((n + bm - 1) / bm) as u32, ((t + bn - 1) / bn) as u32, 1u32);
            let cb = eng.begin_batch().unwrap();
            unsafe {
                eng.record_to(cb, &variant, &[&*w_ptr, &*inp_p, &*out_p], &pc, wg).unwrap();
            }
            eng.submit_batch(cb).unwrap();
            let result = read_f32_buf(&out, t * n);
            eng.return_to_pool(inp);
            eng.return_to_pool(out);
            result
        } else {
            // CPU fallback reads the base Gemma4 (`inner`) host weights → `gemma`.
            #[cfg(feature = "gemma")]
            { let w = self.inner.weights.f32_slice(weight_name); model::cpu_matmul(x, w, t, k, n) }
            #[cfg(not(feature = "gemma"))]
            { let _ = (weight_name, x, k); vec![0.0f32; t * n] }
        }
    }

    /// GPU decode attention (single query over cached KV) via paged_attn_decode_f32
    /// driven as ONE contiguous block. Matches cpu_sdpa: q[num_q*hd], k/v are the
    /// cache up to seq_len ([seq_len,num_kv,hd]), GQA, online softmax, full causal
    /// (no sliding window). KV uploaded per call (foundation; GPU-resident KV is
    /// the next increment). CPU fallback is exact.
    pub(crate) fn gpu_sdpa(&mut self, q: &[f32], k: &[f32], v: &[f32], num_q: usize, num_kv: usize,
                head_dim: usize, seq_len: usize, scale: f32) -> Vec<f32> {
        let total_q = num_q * head_dim;
        let plane = seq_len * num_kv * head_dim;
        if let Some(eng) = self.engine.as_mut() {
            let qbuf = eng.alloc_host_coherent_storage((total_q * 4) as u64).unwrap();
            qbuf.write(&f32_slice_to_bytes(q)).unwrap();
            let mut cache = Vec::with_capacity(2 * plane);
            cache.extend_from_slice(&k[..plane]);
            cache.extend_from_slice(&v[..plane]);
            let cbuf = eng.alloc_host_coherent_storage((2 * plane * 4) as u64).unwrap();
            cbuf.write(&f32_slice_to_bytes(&cache)).unwrap();
            let btbuf = eng.alloc_host_coherent_storage(4).unwrap();
            btbuf.write(&0u32.to_le_bytes()).unwrap();
            let obuf = eng.alloc_host_coherent_storage((total_q * 4) as u64).unwrap();
            let pc = sdpa_pc(seq_len, num_q, num_kv, head_dim, seq_len, plane, scale, 0, 0);
            let (qp, btp, cp, op) = (&qbuf as *const compute::Buffer, &btbuf as *const compute::Buffer,
                                     &cbuf as *const compute::Buffer, &obuf as *const compute::Buffer);
            let cb = eng.begin_batch().unwrap();
            let wg = ((total_q as u32 + 255) / 256, 1u32, 1u32);
            unsafe { eng.record_to(cb, "paged_attn_decode_f32", &[&*qp, &*btp, &*cp, &*op], &pc, wg).unwrap(); }
            eng.submit_batch(cb).unwrap();
            let out = read_f32_buf(&obuf, total_q);
            eng.return_to_pool(qbuf); eng.return_to_pool(cbuf);
            eng.return_to_pool(btbuf); eng.return_to_pool(obuf);
            out
        } else {
            model::cpu_sdpa(q, k, v, num_q, num_kv, head_dim, seq_len, scale, None)
        }
    }

    /// Append this token's K/V into the GPU-resident KV cache for `layer`
    /// (lazily allocated [K-plane(max_seq×num_kv×hd)][V-plane]). Written via the
    /// host-coherent mapping at the token's offset — avoids the per-call
    /// whole-cache upload that gpu_sdpa does. (roadmap #3a)
    pub(crate) fn gpu_kv_append(&mut self, layer: usize, k: &[f32], v: &[f32], pos: usize,
                     num_kv: usize, head_dim: usize, max_seq: usize) {
        let stride = num_kv * head_dim;
        let plane = max_seq * stride;
        if !self.gpu_kv.contains_key(&layer) {
            if let Some(eng) = self.engine.as_mut() {
                if let Ok(buf) = eng.alloc_host_coherent_storage((2 * plane * 4) as u64) {
                    self.gpu_kv.insert(layer, buf);
                }
            }
        }
        if let Some(buf) = self.gpu_kv.get(&layer) {
            if let Some(mp) = buf.mapped_ptr {
                let base = mp as *mut u8;
                let (kb, vb) = (f32_slice_to_bytes(k), f32_slice_to_bytes(v));
                unsafe {
                    std::ptr::copy_nonoverlapping(kb.as_ptr(), base.add(pos * stride * 4), stride * 4);
                    std::ptr::copy_nonoverlapping(vb.as_ptr(), base.add((plane + pos * stride) * 4), stride * 4);
                }
            }
        }
    }

    /// GPU decode attention reading the RESIDENT KV (gpu_kv[layer]) — no per-call
    /// KV upload (vs gpu_sdpa). Caller must gpu_kv_append this token's K/V first.
    /// block_size = max_seq (the resident plane is max_seq-sized). (roadmap #3a)
    pub(crate) fn gpu_sdpa_resident(&mut self, layer: usize, q: &[f32], num_q: usize, num_kv: usize,
                         head_dim: usize, seq_len: usize, scale: f32, max_seq: usize) -> Option<Vec<f32>> {
        let total_q = num_q * head_dim;
        let plane = max_seq * num_kv * head_dim;
        let kv_ptr = self.gpu_kv.get(&layer).map(|b| b as *const compute::Buffer);
        if let (Some(eng), Some(kv_ptr)) = (self.engine.as_mut(), kv_ptr) {
            let qbuf = eng.alloc_host_coherent_storage((total_q * 4) as u64).unwrap();
            qbuf.write(&f32_slice_to_bytes(q)).unwrap();
            let btbuf = eng.alloc_host_coherent_storage(4).unwrap();
            btbuf.write(&0u32.to_le_bytes()).unwrap();
            let obuf = eng.alloc_host_coherent_storage((total_q * 4) as u64).unwrap();
            let pc = sdpa_pc(seq_len, num_q, num_kv, head_dim, max_seq, plane, scale, 0, 0);
            let (qp, btp, op) = (&qbuf as *const compute::Buffer, &btbuf as *const compute::Buffer, &obuf as *const compute::Buffer);
            let cb = eng.begin_batch().unwrap();
            // Honor VLLM_VULKAN_ATTN so debug_kv_resident validates whichever decode
            // kernel the 1-CB layer will use (same resident plane + push-constants).
            let kernel = attn_decode_kernel();
            let wg = match kernel {
                "paged_attn_decode_f32_sg"   => (num_q as u32, 1u32, 1u32),
                "paged_attn_decode_f32_coop" => (num_q as u32, (head_dim as u32 + 255) / 256, 1u32),
                _                            => ((total_q as u32 + 255) / 256, 1u32, 1u32),
            };
            unsafe { eng.record_to(cb, kernel, &[&*qp, &*btp, &*kv_ptr, &*op], &pc, wg).unwrap(); }
            eng.submit_batch(cb).unwrap();
            let out = read_f32_buf(&obuf, total_q);
            eng.return_to_pool(qbuf); eng.return_to_pool(btbuf); eng.return_to_pool(obuf);
            Some(out)
        } else {
            None
        }
    }

    /// GPU flash attention (causal/decode) via the precompiled
    /// `flash_attn_f32_f16_f32` kernel (ggml/llama.cpp scalar wave64 path).
    ///
    /// Layouts (all f32 host-side, K/V converted to f16 for the GPU buffer):
    ///   q : [head h][query n][head_dim]  (n in 0..n_queries; for decode n_queries=1
    ///        this is just [num_q*head_dim], matching cpu_sdpa's q)
    ///   k : [kv_pos][num_kv][head_dim]   (kv_len positions)  — matches cpu_sdpa
    ///   v : [kv_pos][num_kv][head_dim]
    ///   mask: Some([n_queries * kv_len]) f32 (0=attend, -inf=block) enables the
    ///        masked kernel variant; None attends all kv_len keys (decode).
    /// Returns [query n][head h][head_dim] (decode n_queries=1: [num_q*head_dim]).
    ///
    /// One workgroup per (query-tile i, head h); GQA handled by the kernel's
    /// broadcast factors (neq2/nek2 = gqa_ratio), gqa_ratio push-const left at 1
    /// so each head writes its own contiguous output (no interleaved gqaStore).
    pub(crate) fn gpu_flash_attn(&mut self, q: &[f32], k: &[f32], v: &[f32], num_q: usize,
                      num_kv: usize, head_dim: usize, n_queries: usize, kv_len: usize,
                      scale: f32, mask: Option<&[f32]>) -> Vec<f32> {
        const BR: usize = 8; // must match compile_flash Br
        if let Some(eng) = self.engine.as_mut() {
            let total_q = num_q * n_queries * head_dim;
            let kv_plane = kv_len * num_kv * head_dim;
            // Q (f32)
            let qbuf = eng.alloc_host_coherent_storage((total_q * 4) as u64).unwrap();
            qbuf.write(&f32_slice_to_bytes(q)).unwrap();
            // K, V (f16)
            let kbuf = eng.alloc_host_coherent_storage((kv_plane * 2) as u64).unwrap();
            kbuf.write(&f32_to_f16_bytes(&k[..kv_plane])).unwrap();
            let vbuf = eng.alloc_host_coherent_storage((kv_plane * 2) as u64).unwrap();
            vbuf.write(&f32_to_f16_bytes(&v[..kv_plane])).unwrap();
            // Mask M (f16): [n_queries * kv_len]. -inf -> a large negative f16.
            let masked = mask.is_some();
            let mvec: Vec<f32> = match mask {
                Some(m) => m.to_vec(),
                None => vec![0.0; n_queries * kv_len],
            };
            let mbuf = eng.alloc_host_coherent_storage((mvec.len().max(1) * 2) as u64).unwrap();
            mbuf.write(&f32_to_f16_bytes(&mvec)).unwrap();
            // S (sinks/scale aux) — zeroed, one per head is plenty.
            let sbuf = eng.alloc_host_coherent_storage((num_q.max(1) * 4) as u64).unwrap();
            sbuf.write(&vec![0u8; num_q.max(1) * 4]).unwrap();
            // O (f32)
            let obuf = eng.alloc_host_coherent_storage((total_q * 4) as u64).unwrap();
            // MO (mask_opt) — zeroed.
            let mobuf = eng.alloc_host_coherent_storage(16).unwrap();
            mobuf.write(&[0u8; 16]).unwrap();

            let pc = flash_pc(n_queries, kv_len, num_q, num_kv, head_dim, scale);
            let (qp, kp, vp, mp, sp, op, mop) = (
                &qbuf as *const compute::Buffer, &kbuf as *const compute::Buffer,
                &vbuf as *const compute::Buffer, &mbuf as *const compute::Buffer,
                &sbuf as *const compute::Buffer, &obuf as *const compute::Buffer,
                &mobuf as *const compute::Buffer);
            // grid: x = ceil(N/Br) query tiles, y = num_q heads, z = 1 batch.
            let wg = (((n_queries + BR - 1) / BR) as u32, num_q as u32, 1u32);
            // Pick the compiled pipeline matching head_dim. head_dim 128 uses the
            // base name; 256/512 (Gemma sliding/global) use the _hs* variants that
            // compile_flash registered with HSK/HSV set accordingly.
            let base = match head_dim {
                256 => "flash_attn_f32_f16_f32_hs256",
                512 => "flash_attn_f32_f16_f32_hs512",
                _ => "flash_attn_f32_f16_f32",
            };
            let masked_name = format!("{base}_mask");
            let shader: &str = if masked { &masked_name } else { base };
            let cb = eng.begin_batch().unwrap();
            unsafe {
                eng.record_to(cb, shader, &[&*qp, &*kp, &*vp, &*mp, &*sp, &*op, &*mop], &pc, wg).unwrap();
            }
            eng.submit_batch(cb).unwrap();
            let out = read_f32_buf(&obuf, total_q);
            for b in [qbuf, kbuf, vbuf, mbuf, sbuf, obuf, mobuf] { eng.return_to_pool(b); }
            out
        } else {
            model::cpu_sdpa(q, k, v, num_q, num_kv, head_dim, kv_len, scale, None)
        }
    }




    pub(crate) fn rope_one(&mut self, x: &mut [f32], pos: usize, num_heads: usize, head_dim: usize,
                rotary_dim: usize, freq_dim: usize, theta: f32) {
        if let Some(eng) = self.engine.as_mut() {
            let n = num_heads * head_dim;
            let inp = eng.alloc_host_coherent_storage((n * 4) as u64).unwrap();
            inp.write(&f32_slice_to_bytes(x)).unwrap();
            // pos buffer (int [pos]) — one per row (i2 index). All heads share pos
            // here; the shader reads rope_data_pos[i2], and i2 is the channel/sample
            // index which is 0 for our (num_heads rows, 1 channel) layout. Provide a
            // single-element pos buffer.
            let posbuf = eng.alloc_host_coherent_storage(4).unwrap();
            posbuf.write(&(pos as i32).to_le_bytes()).unwrap();
            // dummy freq-factors + dummy set_rows idx
            let ffbuf = eng.alloc_host_coherent_storage(4).unwrap();
            ffbuf.write(&1.0f32.to_le_bytes()).unwrap();
            let idxbuf = eng.alloc_host_coherent_storage(8).unwrap();
            idxbuf.write(&0u64.to_le_bytes()).unwrap();
            // Seed output with input so the non-rotary tail passes through.
            let out = eng.alloc_host_coherent_storage((n * 4) as u64).unwrap();
            out.write(&f32_slice_to_bytes(x)).unwrap();
            let (ip, pp, fp, op, xp) = (
                &inp as *const compute::Buffer, &posbuf as *const compute::Buffer,
                &ffbuf as *const compute::Buffer, &out as *const compute::Buffer,
                &idxbuf as *const compute::Buffer);
            let pc = rope_neox_pc(num_heads, head_dim, rotary_dim, freq_dim, theta);
            // rope_head.glsl local_size = (1,256,1); i0 = 2*GlobalInvocationID.y.
            // We need i0 in [0,head_dim) → GlobalInvocationID.y in [0,head_dim/2) →
            // workgroup.y = ceil((head_dim/2)/256). row = GlobalInvocationID.x
            // (local_size_x=1) → workgroup.x = num_heads.
            let wgy = (((head_dim / 2) as u32) + 255) / 256;
            let cb = eng.begin_batch().unwrap();
            unsafe { eng.record_to(cb, "rope_neox_f32_f32", &[&*ip, &*pp, &*fp, &*op, &*xp], &pc, (num_heads as u32, wgy, 1)).unwrap(); }
            eng.submit_batch(cb).unwrap();
            let result = read_f32_buf(&out, n);
            x.copy_from_slice(&result);
            eng.return_to_pool(inp); eng.return_to_pool(posbuf); eng.return_to_pool(ffbuf);
            eng.return_to_pool(idxbuf); eng.return_to_pool(out);
        } else {
            // CPU fallback (rotate this tensor's heads in place). Mirrors
            // model::cpu_rope_with_basis: rotary_dim sets the rotated pair
            // count, freq_dim sets both the pairing distance and the
            // frequency denominator.
            let n_pairs = rotary_dim / 2;
            let pair_off = freq_dim / 2;
            for hd in 0..num_heads {
                let s = &mut x[hd * head_dim..(hd + 1) * head_dim];
                for i in 0..n_pairs {
                    let freq = 1.0 / theta.powf(i as f32 * 2.0 / freq_dim as f32);
                    let (sin, cos) = (pos as f32 * freq).sin_cos();
                    let (x0, x1) = (s[i], s[i + pair_off]);
                    s[i] = x0 * cos - x1 * sin;
                    s[i + pair_off] = x0 * sin + x1 * cos;
                }
            }
        }
    }










    // ─── UNIFIED GPU LAYER ENGINE (VLLM_VULKAN_UNIFIED=1) ───────────────────
    // One config-parameterized `gpu_layer(spec)` records BOTH Qwen3 and Gemma4
    // decoder layers into the shared persistent UR_* buffers, collapsing the two
    // near-duplicate fused paths (forward_qwen_gpu_resident + gemma_resident_layer)
    // into a single code path. Qwen is a degenerate Gemma: PRE-norm residual,
    // full-rotary RoPE, no sandwich/PLE, silu instead of gelu.













    pub fn num_layers_impl(&self) -> usize {
        #[cfg(feature = "gemma")]
        { self.inner.config.num_hidden_layers }
        #[cfg(not(feature = "gemma"))]
        { 0 }
    }
}

/// Cosine similarity + max abs diff between two equal-length vectors.
fn cos_maxd(a: &[f32], b: &[f32]) -> (f64, f64) {
    let mut dot = 0f64; let mut na = 0f64; let mut nb = 0f64; let mut maxd = 0f64;
    for (x, y) in a.iter().zip(b.iter()) {
        dot += (*x as f64) * (*y as f64);
        na += (*x as f64).powi(2);
        nb += (*y as f64).powi(2);
        maxd = maxd.max((*x as f64 - *y as f64).abs());
    }
    (dot / (na.sqrt() * nb.sqrt() + 1e-12), maxd)
}



// ─── Helper functions for VulkanModel ────────────────────────────────────────




/// GPU-resident MoE expert path toggle (VLLM_VULKAN_MOE_GPU). Default ON — HW-proven
/// bit-exact (cos=1.0, identical gen) and 46x faster than the CPU expert path on the
/// 35B-A3B (10404->227 ms/tok). Set VLLM_VULKAN_MOE_GPU=0 to fall back to CPU experts.
pub(crate) fn moe_gpu_enabled() -> bool {
    flags::flags_global().moe_gpu
}

/// Phase B grouped-expert MoE GEMM toggle (VLLM_VULKAN_MOE_GEMM). Default OFF:
/// a brand-new, cluster-unvalidated dispatch path (no on-node cos/argmax gate
/// yet — see plan-phaseB-moe-mulmatid.md). When ON, `qwen35_moe_mlp_prefill_gpu`
/// batches the routed-expert gate/up/down matmuls across all T tokens through
/// the `matmul_mlx4_id_f32_fp32` grouped GEMM instead of the per-token loop;
/// falls back automatically if the grouped path returns None.
pub(crate) fn moe_gemm_enabled() -> bool {
    flags::flags_global().moe_gemm
}

/// Epilogue-fused grouped MoE GEMM toggle (VLLM_VULKAN_MOE_GEMM_FUSED).
/// Default OFF — see plan-epilogue-fused-moe-gemm.md and `Flags::moe_gemm_fused`'s
/// doc-comment. Only consulted from `qwen35_moe_mlp_prefill_gpu_grouped` when
/// `moe_gemm_enabled()` has already routed prefill through the grouped path;
/// `=1` swaps the routed gate+up+silu+mul (4 dispatches, 2 barriers) for ONE
/// `matmul_mlx4_id_gateup_silu_f32_fp32` dispatch.
pub(crate) fn moe_gemm_fused_enabled() -> bool {
    flags::flags_global().moe_gemm_fused
}

/// Phase 3 down-combine fusion toggle (VLLM_VULKAN_MOE_GEMM_COMBINE). Default
/// OFF — see plan-epilogue-fused-moe-gemm.md §5 and `Flags::moe_gemm_combine`.
/// Only consulted from `qwen35_moe_mlp_prefill_gpu_grouped` (after
/// `moe_gemm_enabled()` has routed prefill through the grouped path); `=1`
/// swaps the host score-weighted combine + the 16384-f/token `down_out`
/// readback for ONE batched `q35_moe_accum_batched` dispatch (readback ->
/// 2048 f/token). Independent of `moe_gemm_fused_enabled()`.
pub(crate) fn moe_gemm_combine_enabled() -> bool {
    flags::flags_global().moe_gemm_combine
}

/// GPU GatedDeltaNet decode path toggle (VLLM_VULKAN_DN_GPU, WS1b). Default ON:
/// the whole deltanet block (in_proj → conv1d+SiLU → q/k norm → delta-rule
/// recurrence → gated norm → out_proj) records into ONE command buffer per
/// layer with the conv/delta state GTT-resident, replacing the 2 fenced
/// projection submits + CPU conv/recurrence. Set VLLM_VULKAN_DN_GPU=0 to fall
/// back to the CPU conv/recurrence path (the A/B + fallback baseline). The
/// GPU path also falls back automatically when the engine or any weight is
/// missing. NOTE: while the GPU path runs, the CPU `DeltaNetState` is stale
/// (the GPU copy is authoritative); do not mix per-token GPU and CPU deltanet
/// calls within one sequence.
pub(crate) fn dn_gpu_enabled() -> bool {
    flags::flags_global().dn_gpu
}

/// WS3 qwen3.6 resident CB-consolidation toggle (VLLM_VULKAN_Q35_1CB, default
/// ON). The whole stage runs through persistent GPU buffers: input/post-attn
/// RMSNorms, residual adds and the MoE tail (score-weighted accumulate +
/// sigmoid-gated shared add) move onto the GPU, and each layer collapses to
/// ONE fenced command buffer (linear-attention layers; the routing top-8 is
/// the only host boundary) or two (full-attention layers; +the host SDPA)
/// plus one un-fenced MoE CB. Combine with VLLM_VULKAN_CB_RING=1 to submit
/// the MoE CB without a fence so its execution overlaps the next layer's
/// recording. Set =0 for the WS1b/WS2 per-block submit path (the A/B
/// baseline). Falls back automatically when the engine, a resident weight or
/// the fixed top-8 assumption is missing.
pub(crate) fn q35_1cb_enabled() -> bool {
    flags::flags_global().q35_1cb
}

/// VLLM_VULKAN_Q35_GEOM=1 (default OFF): route the qwen3.6 TP q8 matvec dispatch
/// sites (`qwen35_matvec`/`qwen35_matvec_multi`, MvKind::Plain) through
/// `matvec_variant_geom` so the swept-winner (BLOCK_SIZE,rows) geometry fires for
/// the TP-4 sharded 27B projection shapes. OFF = byte-identical legacy dispatch.
pub(crate) fn q35_geom_enabled() -> bool {
    flags::flags_global().q35_geom
}

/// VLLM_VULKAN_Q35_TP_FUSED (default ON as of 2026-07-25; set =0 to force the
/// host oracle): collapse each qwen3_5 TP reduce-segment's host-orchestrated
/// per-op compute into ONE fused command buffer, halving the dense TP-4 submit
/// tax (see `Flags::q35_tp_fused` doc).
pub(crate) fn q35_tp_fused_enabled() -> bool {
    flags::flags_global().q35_tp_fused
}

/// VLLM_VULKAN_NEMOTRON_1CB=1 (default OFF; cluster-gated): the Nemotron-H
/// resident-CB decode path (the WS3 port for Nemotron) — see
/// `nemotron::NemotronModel::mamba_mixer_1cb` and friends. Additionally
/// requires `engine.is_some()` and `n_tokens == 1`; falls back to the
/// existing per-op path when either is absent.
pub(crate) fn nemotron_1cb_enabled() -> bool {
    flags::flags_global().nemotron_1cb
}

/// VLLM_VULKAN_NEMOTRON_MOE_TAIL=1 (default OFF; cluster-gated): R1b —
/// collapse the resident MoE layer's 3 waited fences down to 1 by moving
/// relu² and the top_k routed accumulate onto the GPU. See
/// `nemotron::NemotronModel::nem_moe_resident_layer`. Flag OFF keeps the
/// existing 4-CB per-layer path (the correctness reference) unchanged.
pub(crate) fn nemotron_moe_tail_enabled() -> bool {
    flags::flags_global().nemotron_moe_tail
}

/// VLLM_VULKAN_NEMOTRON_GPU_SCAN=1 (default OFF; cluster-gated): R2 — fold
/// the Mamba2 SSD decode-scan (conv1d+SiLU, per-head recurrence+gate, gated
/// RMSNorm) onto the GPU so the resident Mamba layer's mandatory host
/// round-trip disappears and the layer becomes ONE unwaited ring CB. See
/// `nemotron::NemotronModel::nem_mamba_resident_layer`. Flag OFF keeps the
/// existing 2-CB host-scan path (the CPU correctness reference) unchanged.
pub(crate) fn nemotron_gpu_scan_enabled() -> bool {
    flags::flags_global().nemotron_gpu_scan
}

/// VLLM_VULKAN_NEMOTRON_TP_RING=1 (default OFF; cluster-gated): re-enable the
/// pipelined CB ring on the TP=2×PP resident span so the non-waited CBs PP-5
/// hides (mamba/attention out_proj CB_B, the GPU-scan mamba CB) stop being
/// exposed as blocking `submit_batch` drains under TP. A single ring drain is
/// inserted before each MoE `nem_tp_reduce_mix` so the tail CB's `NR_MIX`
/// partial is host-visible for the wire exchange — bit-exact vs the flag-OFF
/// (all-blocking) path. See `nemotron::NemotronModel`'s resident forward loop.
pub(crate) fn nemotron_tp_ring_enabled() -> bool {
    flags::flags_global().nemotron_tp_ring
}
/// item-4a toggle (VLLM_VULKAN_Q35_GPU_ATTN, default OFF): route the Qwen3.6
/// full-attention decode SDPA through the resident `_sg` GPU kernel
/// (`gpu_kv_append` + `gpu_sdpa_resident`) instead of `model::cpu_sdpa` over
/// the host `KvCache`. Also requires `VLLM_VULKAN_ATTN=sg` (checked at the
/// call site via `self.flags.attn`) — the win is long-context decode
/// (cpu_sdpa is O(seq_len) single-core; the GPU kernel reads the resident
/// KV plane directly). The host `KvCache` is still appended-to when this is
/// ON (dual-KV; no RAM saved — see item 4b), so `cpu_sdpa` stays reachable
/// as the correctness oracle and automatic fallback when the GPU call
/// returns `None` (no engine, or kv plane alloc failed).
pub(crate) fn q35_gpu_attn_enabled() -> bool {
    flags::flags_global().q35_gpu_attn
}

/// VLLM_VULKAN_Q35_TSTAMP=1: record GPU timestamp queries around the resident
/// qwen3.6 MoE-CB phases (+ the deltanet CB total) and bucket the per-phase
/// GPU-exec nanoseconds into the profiler (`q35ts_*`, read with dump_profile).
/// Lever-2 attribution tool: separates dispatch-launch overhead (CB wall ≫
/// Σ kernel time), shared-expert f32 bandwidth, and barrier serialization.
/// Ring-off (fenced) submits only — with the CB ring the MoE fence is deferred,
/// so the read-back point is undefined; instrumentation is skipped there.
#[inline]
pub(crate) fn q35_tstamp_enabled() -> bool {
    static F: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *F.get_or_init(|| std::env::var("VLLM_VULKAN_Q35_TSTAMP").map(|v| v == "1").unwrap_or(false))
}

/// VLLM_VULKAN_KV_BOUNDARY_DIAG: on-cluster localization for the KV chunk-
/// boundary GatedDeltaNet capture (`capture_gdn_boundary_resident`). Default
/// OFF → zero overhead and no behavior change (the CPU boundary-snapshot unit
/// test is unaffected). When ON, the resident path logs a stable per-layer
/// fingerprint (FNV-1a over the f32 bit pattern + L2 norm + first element) of
/// every resident linear layer's DEVICE conv/delta state at the boundary token
/// `N` AND at its neighbours `N-1`/`N+1`, plus at every `dn_gpu_sync_to_host`
/// (live export). This is the "capture at both pos and pos±1 and compare"
/// probe: if the mid-run `boundary` fingerprint for a with-suffix store equals
/// the `live_export` fingerprint of an independent fresh-N run, the device
/// capture is bit-identical `[0, N)` and the on-GPU gate's mismatch is
/// reference-side (device-vs-CPU cos>=0.99999 recurrence drift), NOT an
/// off-by-one; if instead the reference matches `pre(-1)` or `adv(+1)`, the
/// off-by-one is confirmed with its direction, and the neighbour-to-boundary
/// max_abs quantifies one token's state delta for direct comparison to the
/// gate's reported max_abs.
pub(crate) fn q35_kv_boundary_diag_enabled() -> bool {
    static F: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *F.get_or_init(|| std::env::var("VLLM_VULKAN_KV_BOUNDARY_DIAG").map(|v| v == "1").unwrap_or(false))
}

// VLLM_VULKAN_MOE_OVERLAP (the std::thread::scope shared-expert overlap) was
// RETIRED by WS2: the shared expert is now recorded into the SAME command
// buffer as the routed experts, so the GPU scheduler overlaps it for free and
// the thread-scope machinery is dead code. VLLM_VULKAN_QWEN35_RESIDENT
// (rayon-parallel CPU router/shared glue) is likewise vestigial on the GPU
// path — that glue no longer runs on the CPU there. Both env vars are now
// accepted-and-ignored; the MOE_GPU=0 fallback uses the serial CPU shared
// path (`moe_forward_token_quant`) regardless.

/// Free a MoE layer's host-side `quant_moe` expert Vecs (packed/scales/biases)
/// once `ensure_moe_gpu_layer` has fully mirrored them into GTT-resident GPU
/// buffers (VLLM_VULKAN_MOE_HOST_FREE). On the 15GB UMA BC-250, keeping both
/// copies resident (~0.5GB/MoE layer host + the GTT mirror) OOMs a 20-layer
/// PP-2 stage. Default ON. Set =0 to keep the pre-fix keep-both behavior —
/// e.g. if `VLLM_VULKAN_MOE_GPU=0` is flipped mid-session for the CPU quant
/// fallback (`moe_forward_token_quant`) to keep working after a layer went
/// resident (freeing makes that fallback read empty Vecs and panic; see
/// `ensure_moe_gpu_layer`).
pub(crate) fn moe_host_free_enabled() -> bool {
    flags::flags_global().moe_host_free
}

/// Eager per-layer MoE expert upload at LOAD time (VLLM_VULKAN_MOE_EAGER_UPLOAD,
/// default ON). When on, `VulkanModel::new` mirrors every resident MoE layer's
/// 4-bit experts into GTT (via the same `ensure_moe_gpu_layer`) right after the
/// checkpoint load and frees each host copy as it goes, so the forward sweep
/// never pays the host(~10GB)+GTT double-residency transient that OOMs a PP-2
/// 20-layer stage on a 15.2GB UMA BC-250. Set =0 to fall back to LAZY upload
/// (mirror on each layer's first forward) — an escape hatch to A/B the memory
/// profile on the constrained node without a cross-build, since this timing
/// change ships to hardware we can't exercise on the Mac. Only the WHEN differs;
/// the upload mechanism and result are identical either way. Read directly (not
/// via the `Flags` snapshot) because it is consumed exactly once, at load — it
/// has no per-dispatch mutation hazard, and its owner file `flags.rs` is outside
/// this change's scope.
pub(crate) fn moe_eager_upload_enabled() -> bool {
    std::env::var("VLLM_VULKAN_MOE_EAGER_UPLOAD").map(|v| v != "0").unwrap_or(true)
}

/// Upload the MTP draft head's 256 experts f16-resident on the GPU and dispatch
/// its MoE through the fused `mtp_moe_mlp_gpu` command buffer (plan §P2 D-gate,
/// VLLM_VULKAN_MTP_MOE_GPU, default ON). Set =0 to keep the head's MoE on the
/// CPU (the e743d6e rayon path) — the A/B lever that isolates the GPU-MoE D
/// win from the CPU baseline without a reload. Read directly (not via the
/// `Flags` snapshot) because it is consumed once, at `load_mtp_gpu` time, and
/// again per draft in `NodeOps::moe` as a pure `mtp_moe_gpu.is_some()` check —
/// no per-dispatch env read.
pub(crate) fn mtp_moe_gpu_enabled() -> bool {
    std::env::var("VLLM_VULKAN_MTP_MOE_GPU").map(|v| v != "0").unwrap_or(true)
}


/// Push constants for a `mul_mat_vec_*` dispatch computing `[1, n] = x[1, k] @ W[n, k]^T`.
/// Layout matches the per-layer `mv_pc` closure used by the Gemma4 path
/// (13 u32: ncols, stride_a, stride_b, nrows, … with t = 1 token).
/// Total physical system RAM in bytes, or 0 if it can't be determined.
/// Used to auto-enable low-RAM weight-loading modes.
/// Coarse host-RSS milestone print for load-time OOM diagnosis. Gated on
/// `VLLM_VULKAN_LOAD_RSS=1` so it is silent by default. Reads current + peak
/// resident set (VmRSS / VmHWM) from /proc/self/status (Linux only).
fn log_load_rss(tag: &str) {
    if std::env::var("VLLM_VULKAN_LOAD_RSS").ok().as_deref() != Some("1") {
        return;
    }
    #[cfg(target_os = "linux")]
    {
        if let Ok(s) = std::fs::read_to_string("/proc/self/status") {
            let field = |k: &str| -> u64 {
                s.lines()
                    .find(|l| l.starts_with(k))
                    .and_then(|l| l.split_whitespace().nth(1))
                    .and_then(|v| v.parse::<u64>().ok())
                    .unwrap_or(0)
            };
            let rss_gb = field("VmRSS:") as f64 / 1e6; // kB -> GB
            let hwm_gb = field("VmHWM:") as f64 / 1e6;
            eprintln!("[load-rss] {tag}: VmRSS={rss_gb:.2}GB VmHWM(peak)={hwm_gb:.2}GB");
        }
    }
    #[cfg(not(target_os = "linux"))]
    {
        let _ = tag;
    }
}

fn system_ram_bytes() -> u64 {
    #[cfg(target_os = "linux")]
    {
        if let Ok(s) = std::fs::read_to_string("/proc/meminfo") {
            for line in s.lines() {
                if let Some(rest) = line.strip_prefix("MemTotal:") {
                    // e.g. "MemTotal:        3650123 kB"
                    let kb: u64 = rest
                        .split_whitespace()
                        .next()
                        .and_then(|v| v.parse().ok())
                        .unwrap_or(0);
                    return kb * 1024;
                }
            }
        }
        0
    }
    #[cfg(not(target_os = "linux"))]
    {
        0
    }
}




























// ── Host-path profiler (env VLLM_VULKAN_PROFILE=1) ───────────────────────────
// Buckets time spent in host serialization / submit-fence / host read-back /
// CPU math to find where decode's wall-time goes (the GPU is ~5% busy → most of
// it is host overhead). Thread-local: the forward runs on the GIL thread.
thread_local! {
    static PROFILE: std::cell::RefCell<std::collections::HashMap<&'static str,(u128,u64)>> =
        std::cell::RefCell::new(std::collections::HashMap::new());
}
#[inline]
pub(crate) fn prof_on() -> bool {
    flags::flags_global().profile
}

/// VLLM_VULKAN_UNIFIED_1CB=1: collapse each unified decoder layer into ONE
/// command buffer (resident KV + on-GPU attention), 1 submit/layer instead of 2.
/// Only meaningful when VLLM_VULKAN_UNIFIED=1 (the dispatch lives in gpu_layer).
/// Read live per-layer (cheap relative to a GPU submit+fence) — matches the
/// live `VLLM_VULKAN_UNIFIED` read in `forward`, and lets one process validate
/// ref / 2-CB / 1-CB with a single (slow) model load.
#[inline]
pub(crate) fn unified_1cb_enabled() -> bool {
    std::env::var("VLLM_VULKAN_UNIFIED_1CB").map(|v| v == "1").unwrap_or(false)
}
/// Which resident-KV decode-attention kernel the 1-CB layer dispatches.
/// Default = the original per-output-element `paged_attn_decode_f32` (correct but
/// recomputes each QK dot head_dim× — slow). `VLLM_VULKAN_ATTN`:
///   sg   -> `paged_attn_decode_f32_sg`   (wave64 subgroup, one subgroup/head; fast)
///   coop -> `paged_attn_decode_f32_coop` (shared-mem reduce, one workgroup/head)
/// All three read the SAME resident KV plane + push-constants (drop-in); only the
/// dispatch geometry differs.
pub(crate) fn attn_decode_kernel() -> &'static str {
    match flags::flags_global().attn {
        flags::AttnKernel::Sg   => "paged_attn_decode_f32_sg",
        flags::AttnKernel::Coop => "paged_attn_decode_f32_coop",
        flags::AttnKernel::Scalar => "paged_attn_decode_f32",
    }
}
/// VLLM_VULKAN_Q35_PARREC: run the GatedDeltaNet delta-rule recurrence across
/// CPU cores (default ON; set "0" to force the single-threaded path). The
/// v-heads are independent so the parallel path is bit-exact.
#[inline]
pub(crate) fn par_deltanet() -> bool {
    flags::flags_global().q35_parrec
}
#[inline]
pub(crate) fn prof_add(name: &'static str, t: std::time::Instant) {
    if prof_on() {
        let ns = t.elapsed().as_nanos();
        PROFILE.with(|p| { let mut m = p.borrow_mut(); let e = m.entry(name).or_insert((0,0)); e.0 += ns; e.1 += 1; });
    }
}
/// PP fused-step role from the peer args (`pp_step_qwen35`): `recv_from < 0` ⇒
/// first stage (no recv, embeds the token); `send_to < 0` ⇒ last stage (no
/// send, returns the Rust argmax). Total over all sign combinations.
#[inline]
pub(crate) fn pp_step_role(recv_from: i32, send_to: i32) -> (bool, bool) {
    (recv_from >= 0, send_to < 0)
}

/// Partial top-`k` selection over a logit vector, returned as `(index, value)`
/// pairs sorted by value descending with the SAME strict-`>` earliest-index-wins
/// tie-break as `VulkanModel::forward_topk` / the driver's Python argmax — so the
/// top candidate is byte-identical to a full-vocab argmax and the distributed
/// `pp_step_laguna_topk` ring is bit-exact with a Python top-k over the same
/// `[vocab]`. O(vocab*k) scan (k small); `k` is clamped to `logits.len()`.
pub(crate) fn topk_select(logits: &[f32], k: usize) -> Vec<(u32, f32)> {
    let k = k.min(logits.len());
    if k == 0 {
        return Vec::new();
    }
    // Total order (value DESC, index ASC): fully deterministic — `top[0]` is the
    // strict-`>` global argmax, and the winner SET at boundary ties is uniquely the
    // k earliest-index tokens, so a Python top-k over the same `[vocab]` matches
    // byte-for-byte. `sort_unstable_by` is fine because the comparator is a total
    // order (no equal keys). O(vocab·log vocab) — trivial next to the lm_head matvec
    // that produced these logits and the ~76 ms/tok full-vocab marshal this replaces.
    let mut idx: Vec<u32> = (0..logits.len() as u32).collect();
    idx.sort_unstable_by(|&a, &b| {
        logits[b as usize]
            .partial_cmp(&logits[a as usize])
            .unwrap_or(std::cmp::Ordering::Equal)
            .then(a.cmp(&b))
    });
    idx.into_iter().take(k).map(|i| (i, logits[i as usize])).collect()
}

/// Pack a `topk_select` result into the `[2*k]` wire layout `[k logits][k
/// indices-as-f32]` the PP top-k ring rings back to rank0. Indices are encoded
/// as exact f32 (all vocab ids < 2^24 are exactly representable). Shared by the
/// `pp_step_{qwen35,gemma}_topk` last-stage senders (mirrors the inline pack in
/// `pp_step_laguna_topk`). Trailing slots (when `top.len() < k`, i.e. vocab < k)
/// stay zero — harmless, rank0's `_sample_topk` reads only real candidates.
pub(crate) fn pack_topk(top: &[(u32, f32)], k: usize) -> Vec<f32> {
    let mut packed = vec![0.0f32; 2 * k];
    for (i, &(idx, logit)) in top.iter().take(k).enumerate() {
        packed[i] = logit;
        packed[k + i] = idx as f32;
    }
    packed
}

/// Inverse of [`pack_topk`]: unpack a rung-back `[2*k]` pack into `(index,
/// logit)` pairs (descending, as `topk_select` produced them). Shared by the
/// `pp_step_{qwen35,gemma}_topk` rank0 receivers.
pub(crate) fn unpack_topk(packed: &[f32], k: usize) -> Vec<(u32, f32)> {
    let mut top: Vec<(u32, f32)> = Vec::with_capacity(k);
    for i in 0..k {
        let logit = packed[i];
        let idx = packed[k + i].round() as u32;
        top.push((idx, logit));
    }
    top
}

#[cfg(test)]
mod topk_select_tests {
    use super::topk_select;

    fn argmax(v: &[f32]) -> u32 {
        let (mut bi, mut bv) = (0u32, f32::NEG_INFINITY);
        for (i, &x) in v.iter().enumerate() { if x > bv { bv = x; bi = i as u32; } }
        bi
    }

    /// top[0] MUST equal the strict-`>` global argmax (the greedy fast-path token),
    /// and the result is sorted by value desc.
    #[test]
    fn top0_is_argmax_and_sorted() {
        let v = vec![0.1f32, 3.5, -2.0, 3.5, 1.0, 9.0, 9.0, 0.0];
        let top = topk_select(&v, 4);
        assert_eq!(top[0].0, argmax(&v));          // == 5 (earliest of the two 9.0)
        assert_eq!(top[0].0, 5);
        for w in top.windows(2) { assert!(w[0].1 >= w[1].1); }
        // earliest-index-wins on the 9.0 tie: idx 5 before idx 6
        assert_eq!(top[0], (5, 9.0));
        assert_eq!(top[1], (6, 9.0));
    }

    /// k >= vocab returns every element; k is clamped.
    #[test]
    fn k_clamped_to_len() {
        let v = vec![2.0f32, 1.0, 3.0];
        let top = topk_select(&v, 10);
        assert_eq!(top.len(), 3);
        assert_eq!(top[0], (2, 3.0));
    }

    /// The k winners are exactly the k largest (matches a full sort's head).
    #[test]
    fn winners_match_full_sort() {
        let v: Vec<f32> = (0..500).map(|i| ((i * 37 % 101) as f32) - 50.0).collect();
        let k = 12;
        let top = topk_select(&v, k);
        let mut full: Vec<(u32, f32)> = v.iter().enumerate().map(|(i, &x)| (i as u32, x)).collect();
        full.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap().then(a.0.cmp(&b.0)));
        assert_eq!(top, full[..k].to_vec());
    }

    /// pack_topk → unpack_topk round-trips the (index, logit) pairs bit-exactly:
    /// this is the qwen35/gemma [2*k] ring wire contract. Indices survive the
    /// f32 round-trip exactly (all vocab ids < 2^24). Guarantees rank0 recovers
    /// the SAME candidate set the last stage selected → greedy top[0] argmax-exact.
    #[test]
    fn pack_unpack_roundtrip() {
        use super::{pack_topk, unpack_topk};
        let v: Vec<f32> = (0..262144u32).map(|i| ((i.wrapping_mul(2654435761) >> 8) as f32) * 1e-4 - 5.0).collect();
        let k = 64;
        let top = topk_select(&v, k);
        let packed = pack_topk(&top, k);
        assert_eq!(packed.len(), 2 * k);
        let got = unpack_topk(&packed, k);
        assert_eq!(got, top);
        // top[0] is still the exact global argmax after the round-trip.
        assert_eq!(got[0].0, argmax(&v));
    }
}

#[cfg(test)]
mod vocab_ringback_tests {
    //! Bit-exactness gates for the registered `pp_vocab_ring` PP logits ring-back
    //! (`pp_send_vocab`/`pp_recv_vocab`, shared by qwen35/gemma/nemotron/kimi).
    //! The change is PURELY a buffer-registration swap: the last stage used to
    //! `send_f32` the full `[vocab]` f32 from a fresh per-call `Vec` (unregistered
    //! → per-step `ibv_reg_mr`/dereg + the "vocab ring-back buffer not registered"
    //! warn); it now stages the SAME bytes through a pinned, NIC-registered
    //! scratch. The vCCL wire is an identity transport for the payload (send X →
    //! recv X byte-for-byte), so the ONLY thing host-checkable without a fabric is
    //! that the staging + clone around the FFI call are a byte-passthrough — which
    //! is exactly what guarantees argmax/logits stay bit-identical to the old
    //! plain ring. The real 2-node wire (WARN-gone + per-step latency delta) is
    //! the deferred on-node check.
    use super::{stage_vocab_send, PpTokRing};

    fn bits(v: &[f32]) -> Vec<u32> { v.iter().map(|x| x.to_bits()).collect() }

    /// A synthetic `[vocab]` logit vector with the awkward values a real ring must
    /// carry losslessly: negatives, ±0.0, subnormals, NaN, ±inf, large magnitudes.
    fn synthetic_vocab(vocab: usize) -> Vec<f32> {
        let mut v: Vec<f32> = (0..vocab)
            .map(|i| ((i as f32) * 0.013 - (vocab as f32) * 0.5) * 1.000_123)
            .collect();
        // Sprinkle the awkward-but-lossless-in-f32 values a real ring must carry.
        let specials = [
            -0.0f32, 0.0, f32::MIN_POSITIVE / 3.0 /*subnormal*/, f32::NAN,
            f32::INFINITY, f32::NEG_INFINITY, f32::MAX, f32::MIN,
        ];
        for (i, &s) in specials.iter().enumerate() {
            if i < v.len() { v[i] = s; }
        }
        v
    }

    /// Model both transport paths at the buffer level and assert the value rank0
    /// ends up with is BIT-identical. `stage_vocab_send` is the real production
    /// sender-side staging; the FFI send/recv is modeled as an identity wire
    /// (vCCL guarantees `recv_f32_into` lands exactly the bytes `send_f32` put
    /// out — the same underlying `vcclSend`/`vcclRecv` the plain path uses).
    fn assert_paths_bit_identical(vocab: usize) {
        let out = synthetic_vocab(vocab);

        // --- PLAIN path (pre-change): last stage sends `out`; rank0's `recv_f32`
        //     returns those bytes verbatim. ---
        let plain_wire = out.clone();
        let plain_rank0 = plain_wire.clone();

        // --- REGISTERED path: last stage stages `out` into a PINNED ring, sends
        //     `ring.buf`; rank0's `recv_f32_into` writes the wire into its own
        //     pinned ring, then clones it out (exactly `pp_recv_vocab`). ---
        // A pinned ring == handle != 0 with a correctly-sized buffer (what
        // `pin_pp_hop` produces on a successful `comm_register`).
        let mut send_ring = PpTokRing { buf: vec![0.0f32; vocab], handle: 1 };
        let used_registered = stage_vocab_send(&mut send_ring, &out);
        assert!(used_registered, "pinned+sized ring must take the registered path");
        let reg_wire = send_ring.buf.clone(); // what send_f32(&ring.buf) transmits
        // rank0 recv_f32_into(&mut recv_ring.buf) then recv_ring.buf.clone():
        let mut recv_ring = PpTokRing { buf: vec![0.0f32; vocab], handle: 1 };
        recv_ring.buf.copy_from_slice(&reg_wire); // identity wire
        let reg_rank0 = recv_ring.buf.clone();

        // Byte-identical to the plain path (compare bit patterns so NaN counts).
        assert_eq!(bits(&reg_rank0), bits(&plain_rank0),
            "registered ring-back must be byte-identical to the plain ring");
        assert_eq!(bits(&reg_rank0), bits(&out),
            "registered ring-back must be byte-identical to the source logits");
    }

    /// The served arches' vocab sizes (qwen35 248320, gemma ~256k, nemotron/kimi
    /// ~163840) all round-trip bit-exactly through the registered ring.
    #[test]
    fn registered_ring_is_bit_exact_across_vocabs() {
        for &vocab in &[163_840usize, 248_320, 256_000, 100_352, 7] {
            assert_paths_bit_identical(vocab);
        }
    }

    /// Fallback contract: an UNPINNED ring (`handle == 0`) or a size mismatch must
    /// NOT be used — the caller then sends the source `out` directly (still
    /// bit-exact, just the per-call regMr). `stage_vocab_send` must leave the ring
    /// untouched in that case.
    #[test]
    fn unpinned_or_mismatched_ring_falls_back() {
        let out = synthetic_vocab(1024);

        // Unpinned (handle == 0): fall back, ring untouched.
        let mut unpinned = PpTokRing { buf: vec![0.0f32; 1024], handle: 0 };
        assert!(!stage_vocab_send(&mut unpinned, &out));
        assert!(unpinned.buf.iter().all(|&x| x == 0.0));

        // Wrong size (handle != 0 but len mismatch): fall back, ring untouched.
        let mut wrongsize = PpTokRing { buf: vec![0.0f32; 512], handle: 1 };
        assert!(!stage_vocab_send(&mut wrongsize, &out));
        assert_eq!(wrongsize.buf.len(), 512);
        assert!(wrongsize.buf.iter().all(|&x| x == 0.0));
    }
}

#[cfg(test)]
mod gemma_serve_seam_tests {
    //! Pure-logic gates for the `pp_step_gemma_logits` / `forward_pp_gemma_prefill`
    //! distributed-serve seams. The full device PP ring (recv/forward/send over
    //! vCCL, argmax-exact vs the single-node gemma forward) is a 2-node on-node
    //! check — no Mac Vulkan device + no vCCL fabric here. What IS host-checkable
    //! is the arithmetic every wire-sizing and pos-derivation decision rests on;
    //! the compute body itself is `forward_pp_gemma` verbatim (the same body
    //! `pp_step_gemma`/`forward_pp_gemma_argmax` already ship), so the ring seam
    //! is bit-exact with the argmax hop BY CONSTRUCTION — only the transport of
    //! the *result* differs (full `[vocab]` rung back vs one token argmaxed).
    use super::{pp_step_role, gemma_pp_kv_targets, gemma_pp_tkv_lens};
    use crate::model::Gemma4Config;

    /// The inter-stage composite message width `pp_gemma_msg_len()` computes as
    /// `hidden + num_layers*ple_dim + 2*Σ target_kv`. For g12b (no PLE, no
    /// KV-share) this MUST degenerate to exactly `hidden_size` — the invariant
    /// `serve_head.py`/`serve_peer.py` bank on when they size the prefill hop as
    /// `seq * H`. If this ever grows past H (e2b), that Python wire sizing must
    /// switch to `pp_gemma_msg_len` before g-with-PLE can serve.
    #[test]
    fn g12b_composite_msg_len_equals_hidden() {
        let cfg = Gemma4Config::g12b();
        let targets = gemma_pp_kv_targets(&cfg);
        assert!(targets.is_empty(), "g12b has num_kv_shared_layers=0 → no cross-stage KV targets");
        assert_eq!(cfg.hidden_size_per_layer_input, 0, "g12b has no PLE table");
        let total_ple = cfg.num_hidden_layers * cfg.hidden_size_per_layer_input;
        let tkv_total: usize = gemma_pp_tkv_lens(&cfg, &targets).iter().map(|&l| 2 * l).sum();
        let msg_len = cfg.hidden_size + total_ple + tkv_total;
        assert_eq!(msg_len, cfg.hidden_size, "g12b composite message must be bare [H]");
    }

    /// e2b DOES carry PLE + KV-share, so its composite is strictly wider than H —
    /// documenting the boundary where the Python `seq*H` sizing would need to
    /// switch to `pp_gemma_msg_len` (out of scope for the g12b PP-2 target).
    #[test]
    fn e2b_composite_msg_len_exceeds_hidden() {
        let cfg = Gemma4Config::e2b();
        let targets = gemma_pp_kv_targets(&cfg);
        let total_ple = cfg.num_hidden_layers * cfg.hidden_size_per_layer_input;
        let tkv_total: usize = gemma_pp_tkv_lens(&cfg, &targets).iter().map(|&l| 2 * l).sum();
        let msg_len = cfg.hidden_size + total_ple + tkv_total;
        assert!(msg_len > cfg.hidden_size,
            "e2b (PLE + KV-share) composite must exceed [H]: {msg_len} vs {}", cfg.hidden_size);
    }

    /// The four PP-ring roles the launcher drives the seam with. Mirrors exactly
    /// how `serve_head.decode` (rank0: rf=-1) and `serve_peer.do_decode`
    /// (rf/st per stage) call `pp_step_gemma_logits`; `is_first == recv_from < 0`.
    #[test]
    fn pp_ring_roles_for_pp2() {
        // rank0 = FIRST stage of PP-2: recv_from=-1, send_to=1.
        let (do_recv, is_last) = pp_step_role(-1, 1);
        assert!(!do_recv && !is_last, "first stage: embeds token, forwards onward");
        assert!(-1 < 0, "first stage is_first");
        // rank1 = LAST stage of PP-2: recv_from=0, send_to=-1.
        let (do_recv, is_last) = pp_step_role(0, -1);
        assert!(do_recv && is_last, "last stage: recv hidden, produce+ring [vocab]");
        // A MID stage (PP-3+): recv_from>=0, send_to>=0.
        let (do_recv, is_last) = pp_step_role(0, 2);
        assert!(do_recv && !is_last, "mid stage: recv, forward, send onward");
        // STANDALONE N=1: recv_from<0 && send_to<0 → is_first && is_last branch.
        let (do_recv, is_last) = pp_step_role(-1, -1);
        assert!(!do_recv && is_last, "standalone: embed → [vocab], no wire");
        assert!(-1 < 0, "standalone is_first");
    }

    /// g12b PP-2 canonical BOUNDS (even split of 48 layers): 0,24,48. Both stages
    /// own 24 dense layers; every layer appends its own KV each token (no
    /// KV-share), so `max(kv_caches.seq_len)` — the seam's pos derivation — equals
    /// the token position on BOTH stages in lockstep.
    #[test]
    fn g12b_pp2_bounds_even_split() {
        let cfg = Gemma4Config::g12b();
        let bounds = [0usize, 24, 48];
        assert_eq!(bounds[bounds.len() - 1], cfg.num_hidden_layers, "bounds cover all 48 layers");
        assert_eq!(bounds[1] - bounds[0], 24);
        assert_eq!(bounds[2] - bounds[1], 24);
        // No KV-share ⇒ every owned layer is an appending cache ⇒ seq_len tracks pos.
        assert_eq!(gemma_pp_kv_targets(&cfg).len(), 0);
    }
}

/// P4 chain α fix — pure lookup of the position→pre-norm ring. Returns the
/// pre-`model.norm` hidden recorded for `pos`, MOST-RECENT write first (so a
/// re-fed speculative position resolves to the current cycle, not a stale prior
/// one), or `None` if the ring never saw `pos` (caller falls back to the
/// freshest stash). Factored out of `prenorm_for_pos` so the sourcing contract
/// is unit-testable on the Mac without an engine — the exact defect this fixes
/// (drafting `d_1` off the freshest/deepest pass instead of the producing one)
/// is a wrong-position read, which a position-keyed lookup makes impossible.
fn prenorm_ring_lookup(ring: &std::collections::VecDeque<(usize, Vec<f32>)>, pos: usize) -> Option<Vec<f32>> {
    ring.iter().rev().find(|(p, _)| *p == pos).map(|(_, v)| v.clone())
}

#[cfg(test)]
mod prenorm_ring_tests {
    use super::prenorm_ring_lookup;
    use std::collections::VecDeque;

    /// Build a ring of `(pos, [pos_as_f32])` so each entry is identifiable.
    fn ring(entries: &[usize]) -> VecDeque<(usize, Vec<f32>)> {
        entries.iter().map(|&p| (p, vec![p as f32])).collect()
    }

    #[test]
    fn picks_the_producing_position_not_the_freshest() {
        // The regression: a depth-4 cycle at cposA=100 records passes for
        // positions 100..=104 (pass A + B_1..B_4). A partial accept k=1 refills
        // off the new real produced at position 101 (head_pos = new_pos-1 = 101).
        // The BUG drafted d_1 off the freshest (104). The lookup must return 101.
        let r = ring(&[100, 101, 102, 103, 104]);
        assert_eq!(prenorm_ring_lookup(&r, 101), Some(vec![101.0]),
            "d_1 must source the PRODUCING pass (101), never the freshest (104)");
        // Every reachable accept-prefix k∈0..=DEPTH maps to a distinct producing pos.
        for k in 0..=4 {
            assert_eq!(prenorm_ring_lookup(&r, 100 + k), Some(vec![(100 + k) as f32]));
        }
    }

    #[test]
    fn most_recent_write_wins_for_a_refed_position() {
        // A rejected speculative position from an earlier cycle is re-fed in a
        // later cycle as a confirmed-prefix pass; the ring holds both. The refill
        // reads the position IN the current cycle, so the newer write must win.
        let mut r = ring(&[103]); // stale prior-cycle write at 103
        r.push_back((103, vec![999.0])); // current-cycle write at 103
        assert_eq!(prenorm_ring_lookup(&r, 103), Some(vec![999.0]),
            "most-recent write for a re-fed position must win");
    }

    #[test]
    fn miss_falls_back_to_none() {
        // Positions the ring never saw (e.g. the prefill bootstrap head_base)
        // must miss so the caller falls back to the freshest stash.
        let r = ring(&[100, 101, 102]);
        assert_eq!(prenorm_ring_lookup(&r, 42), None);
        assert_eq!(prenorm_ring_lookup(&VecDeque::new(), 100), None);
    }
}

#[cfg(test)]
mod pp_step_role_tests {
    use super::pp_step_role;

    /// Branch selection is total: every sign combination maps to exactly one
    /// well-defined (recv?, argmax?) role; first-stage never recvs, last-stage
    /// always argmaxes, mid stages do both-recv-and-send.
    #[test]
    fn role_selection_total() {
        assert_eq!(pp_step_role(-1, 1), (false, false)); // first stage: embed → send
        assert_eq!(pp_step_role(0, 1), (true, false));   // mid: recv → send (peer 0 valid)
        assert_eq!(pp_step_role(3, -1), (true, true));   // last: recv → argmax
        assert_eq!(pp_step_role(-1, -1), (false, true)); // single-stage: embed → argmax
    }
}

/// Add a pre-measured duration (nanos) to a profiler bucket — for phases timed
/// inside a callee (e.g. the vCCL all-reduce copy-in/wire/copy-out split).
#[inline]
pub(crate) fn prof_add_ns(name: &'static str, ns: u128) {
    if prof_on() {
        PROFILE.with(|p| { let mut m = p.borrow_mut(); let e = m.entry(name).or_insert((0,0)); e.0 += ns; e.1 += 1; });
    }
}

// ── MTP draft head, GPU-dense wiring (plan §P2 remainder) ───────────────────
// The engine-less CPU path (`MtpHeadPy` below) is the Mac parity vehicle.
// These `VulkanModel` methods are the node path: the SAME `mtp::MtpHead` math
// (`head_hidden_with`'s pluggable `MtpOps`), but the dense projections
// (`fc`, `q/k/v/o_proj`) run through the resident-GPU `qwen35_matvec`, the MoE
// through the fused f16 `mtp_moe_mlp_gpu` command buffer, and the final logits
// reuse the target's shared lm_head (whatever quant format is resident there).

/// The node-path `MtpOps` (plan §P2 D-gate): dense projections via the resident
/// `qwen35_matvec`, the 256-expert MoE via the fused f16 `mtp_moe_mlp_gpu`. Owns
/// the head's host-f32 weights (moved out for the call) purely as fallbacks —
/// the dense weights are never hit on the node (`load_mtp_gpu` uploaded them,
/// so `gpu_weights.contains_key` is always true), and `moe_w` is the rayon MoE
/// path used only when GPU MoE is disabled (`VLLM_VULKAN_MTP_MOE_GPU=0`) or a
/// GPU submit returns None. Holds ONE `&mut VulkanModel` so both ops share a
/// single borrow (two `&mut self` closures cannot coexist).
// The prenorm-ring cap is used by the qwen3_5 spec-decode ring (pyseam_qwen35 /
// qwen35_forward), independent of whether the GPU MTP head (`mtp`) is compiled.
#[cfg(feature = "qwen35")]
impl VulkanModel {
    /// Cap of the `q35_prenorm_ring` (positions retained). Must exceed the max
    /// chain window (`DEPTH+1` passes/cycle, `DEPTH ≤ 4`) so every position a
    /// refill can ask for (`cposA..=cposA+DEPTH`) is still present; a little slack
    /// covers a re-fed speculative position from the prior cycle.
    const PRENORM_RING_CAP: usize = 16;
}

#[cfg(feature = "mtp")]
struct NodeOps<'a> {
    vm: &'a mut VulkanModel,
    fc: Vec<f32>,
    qp: Vec<f32>,
    kp: Vec<f32>,
    vp: Vec<f32>,
    op: Vec<f32>,
    moe_w: moe::MoeWeights,
    dims: moe::MoeDims,
    dense_ns: u128,
}

#[cfg(feature = "mtp")]
impl mtp::MtpOps for NodeOps<'_> {
    fn matvec(&mut self, name: &str, x: &[f32], k: usize, n: usize) -> Vec<f32> {
        let t = std::time::Instant::now();
        let in_gpu = self.vm.gpu_weights.contains_key(name);
        let fmt = self.vm.gpu_weights.get(name).map(|w| w.format);
        let out = if in_gpu {
            self.vm.qwen35_matvec(name, x, k, n)
        } else {
            let w = match name {
                mtp::MV_FC => &self.fc,
                mtp::MV_Q => &self.qp,
                mtp::MV_K => &self.kp,
                mtp::MV_V => &self.vp,
                mtp::MV_O => &self.op,
                other => panic!("mtp_draft: unknown matvec '{other}'"),
            };
            model::cpu_matmul(x, w, 1, k, n)
        };
        // STEP-7 draft debug: per-projection localization. in_gpu=false with an
        // EMPTY host weight ⇒ silent zeros (lean-load key mismatch); a huge/NaN
        // out_l2 ⇒ wrong shader for this weight's format; sane out_l2 on every
        // projection ⇒ the garbage is downstream (attn/MoE/norm).
        if std::env::var("VLLM_VULKAN_MTP_DRAFT_DEBUG").map(|v| v != "0").unwrap_or(false) {
            static N: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
            let c = N.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
            if c < 12 {
                let l2 = out.iter().map(|&v| (v as f64) * (v as f64)).sum::<f64>().sqrt();
                let xl2 = x.iter().map(|&v| (v as f64) * (v as f64)).sum::<f64>().sqrt();
                eprintln!("[MTP_MATVEC_DBG {c}] name={name} in_gpu={in_gpu} fmt={fmt:?} \
                           k={k} n={n} x_l2={xl2:.3} out_l2={l2:.3}");
            }
        }
        self.dense_ns += t.elapsed().as_nanos();
        out
    }
    fn moe(&mut self, ff_in: &[f32]) -> Vec<f32> {
        let dbg = std::env::var("VLLM_VULKAN_MTP_DRAFT_DEBUG").map(|v| v != "0").unwrap_or(false);
        // Confirmation/fallback toggle: force the bit-exact CPU rayon MoE.
        let force_cpu = std::env::var("VLLM_VULKAN_MTP_MOE_CPU").map(|v| v != "0").unwrap_or(false);
        let (mut path, mut out): (&str, Option<Vec<f32>>) = ("cpu_rayon", None);
        if !force_cpu && self.vm.mtp_moe_gpu.is_some() {
            if let Some(o) = self.vm.mtp_moe_mlp_gpu(ff_in, self.dims) {
                path = "gpu_f16"; out = Some(o);
            } else {
                path = "gpu_None->cpu"; // GPU submit returned None → CPU fallback
            }
        }
        let out = out.unwrap_or_else(|| moe::moe_forward_token_rayon(ff_in, &self.moe_w, self.dims).1);
        // STEP-7 draft debug: MoE path + in/out L2. A gpu_None->cpu with EMPTY
        // moe_w (lean load drops the host copy) ⇒ silent zeros; a huge/NaN out_l2
        // ⇒ the f16 expert MoE kernel is producing garbage.
        if dbg {
            static N: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
            let c = N.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
            if c < 6 {
                let il2 = ff_in.iter().map(|&v| (v as f64) * (v as f64)).sum::<f64>().sqrt();
                let ol2 = out.iter().map(|&v| (v as f64) * (v as f64)).sum::<f64>().sqrt();
                eprintln!("[MTP_MOE_DBG {c}] path={path} in_l2={il2:.3} out_l2={ol2:.3}");
            }
        }
        out
    }
    fn dense_mlp(&mut self, ff_in: &[f32], dm: &mtp::DenseMlp, hidden: usize) -> Vec<f32> {
        // DENSE 27B head SwiGLU. GPU-resident when the head was uploaded
        // (`VLLM_VULKAN_MTP_DENSE_GPU`, default ON): the three projections go
        // through the SAME `qwen35_matvec` the target's own forward uses; the SiLU
        // ⊙ up + the tiny [inter] hadamard stay on the host (matching `dense_swiglu`
        // exactly). Absent keys ⇒ the bit-exact host `dense_swiglu` (the flag-off
        // A/B path). NOTE: GPU f16 ≠ host f32 bit-for-bit; drafts stay in the
        // target's own numerical regime and verification guarantees greedy-exactness.
        if self.vm.gpu_weights.contains_key(mtp::MV_GATE) {
            let gate = self.vm.qwen35_matvec(mtp::MV_GATE, ff_in, hidden, dm.inter);
            let up = self.vm.qwen35_matvec(mtp::MV_UP, ff_in, hidden, dm.inter);
            let act = model::cpu_silu(&gate);
            let mid: Vec<f32> = act.iter().zip(&up).map(|(&a, &u)| a * u).collect();
            self.vm.qwen35_matvec(mtp::MV_DOWN, &mid, dm.inter, hidden)
        } else {
            mtp::dense_swiglu(ff_in, dm, hidden)
        }
    }
}

/// Convert an f32 slice to f16 little-endian bytes and upload to a fresh
/// host-coherent GPU buffer (P3 lean MTP loader). rayon: the switch tensors are
/// ~268M elems.
#[cfg(feature = "mtp")]
fn mtp_up_f16(eng: &mut compute::ComputeEngine, data: &[f32]) -> Result<compute::Buffer, String> {
    use rayon::prelude::*;
    let mut bytes = vec![0u8; data.len() * 2];
    bytes.par_chunks_mut(2).zip(data.par_iter()).for_each(|(c, &v)| {
        c.copy_from_slice(&half::f16::from_f32(v).to_bits().to_le_bytes());
    });
    let buf = eng
        .alloc_host_coherent_storage(bytes.len() as u64)
        .map_err(|e| format!("mtp lean f16 alloc: {e}"))?;
    buf.write(&bytes).map_err(|e| format!("mtp lean f16 write: {e}"))?;
    Ok(buf)
}

/// f32 slice → f32-bytes host-coherent GPU buffer (P3 lean MTP loader).
#[cfg(feature = "mtp")]
fn mtp_up_f32(eng: &mut compute::ComputeEngine, data: &[f32]) -> Result<compute::Buffer, String> {
    let bytes = f32_slice_to_bytes(data);
    let buf = eng
        .alloc_host_coherent_storage(bytes.len() as u64)
        .map_err(|e| format!("mtp lean f32 alloc: {e}"))?;
    buf.write(&bytes).map_err(|e| format!("mtp lean f32 write: {e}"))?;
    Ok(buf)
}

/// Build f16 LE bytes for a per-expert HALF of the fused `gate_up_proj`
/// (`hi=0`→gate, `hi=1`→up) DIRECTLY from the f32 source, skipping the
/// intermediate f32 split copy — halves the lean load transient (no 1.07GB
/// `switch_gate`/`switch_up` f32 arrays). `data` is `[E, 2*mi, h]` row-major.
#[cfg(feature = "mtp")]
fn mtp_gate_up_half_f16(
    eng: &mut compute::ComputeEngine, data: &[f32], e: usize, half: usize, hi: usize,
) -> Result<compute::Buffer, String> {
    use rayon::prelude::*;
    let e_blk = 2 * half;
    let mut bytes = vec![0u8; e * half * 2];
    bytes.par_chunks_mut(half * 2).enumerate().for_each(|(ex, chunk)| {
        let src = &data[ex * e_blk + hi * half..ex * e_blk + hi * half + half];
        for (i, &v) in src.iter().enumerate() {
            chunk[i * 2..i * 2 + 2].copy_from_slice(&half::f16::from_f32(v).to_bits().to_le_bytes());
        }
    });
    let buf = eng
        .alloc_host_coherent_storage(bytes.len() as u64)
        .map_err(|e| format!("mtp lean gate_up f16 alloc: {e}"))?;
    buf.write(&bytes).map_err(|e| format!("mtp lean gate_up f16 write: {e}"))?;
    Ok(buf)
}

#[cfg(feature = "mtp")]
impl VulkanModel {
    /// Load the MTP head (`mtp.safetensors`). On-node (engine present) this takes
    /// the P3 LEAN streaming path (`load_mtp_gpu_lean`): each `mtp.*` tensor is
    /// streamed bf16→f16 straight to a GPU buffer, so the head's multi-GB f32
    /// host copies and the whole-file bf16→f32 load transient NEVER materialize
    /// — the fix for the 14GB UMA rank-4 OOM that forced the unbalanced split.
    /// `VLLM_VULKAN_MTP_HOST_COPY=1` opts back into the full-f32 path (the
    /// engine-less Mac parity harness always uses it, since it has no GPU).
    ///
    /// Full path: uploads dense projections f16-resident under the exact
    /// weight-name keys `mtp.rs` threads through its matvec closure
    /// (`mtp::MV_FC`/`MV_Q`/…) so `qwen35_matvec` finds them in `gpu_weights`.
    pub(crate) fn load_mtp_gpu(&mut self, mtp_path: &std::path::Path) -> Result<(), String> {
        let cfg = self
            .qwen35
            .as_ref()
            .ok_or_else(|| "load_mtp_gpu needs a loaded qwen3_5 model".to_string())?
            .config
            .clone();
        // DENSE `qwen3_5_mtp` head (Qwen3.6-27B): top-level `fc.weight`, mlx4
        // 4-bit, dense SwiGLU. Load host-f32 via the P1-validated `load_dense`
        // (~66M params — tiny); the on-node draft runs the CPU head forward
        // (`NodeOps.matvec` falls back to these host weights; the dense head's
        // `layer_step` runs `dense_swiglu` inline, never `ops.moe`), so NO GPU
        // upload / MoE-resident state is needed. Replicated per TP rank.
        if mtp::mtp_checkpoint_is_dense(mtp_path)? {
            let head = mtp::MtpHead::load_dense(mtp_path, &cfg, 4)?;
            // GPU-resident dense draft (default ON on-node): upload the head's 5
            // attn projections + 3 SwiGLU-MLP weights f16 ONCE so every draft step
            // runs on the GPU via `qwen35_matvec` — the SAME path the target's own
            // forward uses — instead of single-threaded host `cpu_matmul`. This was
            // the TRUE Qwen3.6-27B spec-decode drafter cost: the whole dense head
            // forward ran on host CPU (~470 ms/step: `mtp_draft_dense` projections
            // + the mis-bucketed `mtp_draft_moe` = host `dense_swiglu`), NOT any MoE
            // / per-expert loop (the dense head has none). `VLLM_VULKAN_MTP_DENSE_GPU=0`
            // keeps the bit-exact host path for A/B. Mac (engine-less) stays host-f32.
            let gpu = std::env::var("VLLM_VULKAN_MTP_DENSE_GPU").map(|v| v != "0").unwrap_or(true);
            if self.engine.is_some() && gpu {
                self.mtp_upload_dense_gpu(&head)?;
                log::info!("qwen3_5 MTP: DENSE 27B head GPU-resident (8 f16 weights uploaded once; per-step draft on GPU)");
            } else {
                log::info!("qwen3_5 MTP: DENSE 27B head host-f32 (CPU draft path, no GPU upload)");
            }
            self.mtp_head = Some(head);
            return Ok(());
        }
        let host_copy = std::env::var("VLLM_VULKAN_MTP_HOST_COPY").ok().as_deref() == Some("1");
        if self.engine.is_some() && !host_copy {
            return self.load_mtp_gpu_lean(mtp_path, &cfg);
        }
        self.load_mtp_gpu_full(mtp_path)
    }

    /// Upload the DENSE 27B MTP head's 5 attn projections + 3 SwiGLU-MLP weights
    /// f16-resident to `gpu_weights` under the keys `mtp.rs` threads through its
    /// matvec ops (`MV_FC`/`MV_Q`/… + `MV_GATE`/`MV_UP`/`MV_DOWN`), so the on-node
    /// draft runs every projection AND the MLP through `qwen35_matvec` (GPU)
    /// rather than host `cpu_matmul`/`dense_swiglu`. One-time at load; the head's
    /// host f32 copies stay put as the bit-exact `VLLM_VULKAN_MTP_DENSE_GPU=0`
    /// fallback (the head is ~66M params, so host retention is negligible).
    fn mtp_upload_dense_gpu(&mut self, head: &mtp::MtpHead) -> Result<(), String> {
        let dm = head
            .dense_mlp
            .as_ref()
            .ok_or("mtp dense GPU upload: head has no dense_mlp")?;
        let jobs: [(&str, &[f32]); 8] = [
            (mtp::MV_FC, &head.fc),
            (mtp::MV_Q, &head.q_proj),
            (mtp::MV_K, &head.k_proj),
            (mtp::MV_V, &head.v_proj),
            (mtp::MV_O, &head.o_proj),
            (mtp::MV_GATE, &dm.gate),
            (mtp::MV_UP, &dm.up),
            (mtp::MV_DOWN, &dm.down),
        ];
        let Self { engine, gpu_weights, .. } = self;
        let eng = engine.as_mut().ok_or("mtp dense GPU upload needs an engine")?;
        for (key, data) in jobs {
            let buf = mtp_up_f16(eng, data)?;
            gpu_weights.insert(
                key.to_string(),
                GpuWeight { buffer: buf, format: QuantFormat::F16, aux: None },
            );
        }
        Ok(())
    }

    /// P3 LEAN node loader: stream `mtp.*` bf16→f16 straight to GPU, no f32 host
    /// retention. Peak host = one tensor's f32 (largest = `gate_up_proj` ~2.1GB)
    /// + two f16 halves (~1.06GB), vs the full path's ~6.8GB (raw map + head
    /// clone). Always uses the GPU MoE (the whole point of lean is no host f32
    /// MoE); `VLLM_VULKAN_MTP_MOE_GPU=0` is ignored here.
    fn load_mtp_gpu_lean(
        &mut self, mtp_path: &std::path::Path, cfg: &qwen35::Qwen35Config,
    ) -> Result<(), String> {
        let h = cfg.hidden_size;
        let mi = cfg.moe_intermediate_size;
        let e = cfg.num_experts;
        let half = mi * h; // per-expert gate (== up) rows
        let mut norms: std::collections::HashMap<String, Vec<f32>> = std::collections::HashMap::new();
        let mut router: Vec<f32> = Vec::new();
        let (mut g_gate, mut g_up, mut g_down) = (None, None, None);
        let (mut g_sg, mut g_su, mut g_sd, mut g_seg) = (None, None, None, None);
        {
            let Self { engine, gpu_weights, .. } = self;
            let eng = engine.as_mut().ok_or("mtp lean load needs an engine")?;
            model::for_each_safetensors_tensor_filtered(
                mtp_path,
                |n| n.starts_with("mtp."),
                |name, data| -> Result<(), String> {
                    let dense = match name.as_str() {
                        "mtp.fc.weight" => Some(mtp::MV_FC),
                        "mtp.layers.0.self_attn.q_proj.weight" => Some(mtp::MV_Q),
                        "mtp.layers.0.self_attn.k_proj.weight" => Some(mtp::MV_K),
                        "mtp.layers.0.self_attn.v_proj.weight" => Some(mtp::MV_V),
                        "mtp.layers.0.self_attn.o_proj.weight" => Some(mtp::MV_O),
                        _ => None,
                    };
                    if let Some(key) = dense {
                        let buf = mtp_up_f16(eng, &data)?;
                        gpu_weights.insert(
                            key.to_string(),
                            GpuWeight { buffer: buf, format: QuantFormat::F16, aux: None },
                        );
                        return Ok(());
                    }
                    match name.as_str() {
                        "mtp.layers.0.mlp.experts.gate_up_proj" => {
                            if data.len() != e * 2 * half {
                                return Err(format!(
                                    "mtp lean gate_up len {} != E*2*mi*h {}", data.len(), e * 2 * half));
                            }
                            g_gate = Some(mtp_gate_up_half_f16(eng, &data, e, half, 0)?);
                            g_up = Some(mtp_gate_up_half_f16(eng, &data, e, half, 1)?);
                        }
                        "mtp.layers.0.mlp.experts.down_proj" => g_down = Some(mtp_up_f16(eng, &data)?),
                        "mtp.layers.0.mlp.gate.weight" => router = data,
                        "mtp.layers.0.mlp.shared_expert.gate_proj.weight" => g_sg = Some(mtp_up_f32(eng, &data)?),
                        "mtp.layers.0.mlp.shared_expert.up_proj.weight" => g_su = Some(mtp_up_f32(eng, &data)?),
                        "mtp.layers.0.mlp.shared_expert.down_proj.weight" => g_sd = Some(mtp_up_f32(eng, &data)?),
                        "mtp.layers.0.mlp.shared_expert_gate.weight" => g_seg = Some(mtp_up_f32(eng, &data)?),
                        other => {
                            if mtp::MtpHead::norm_tensor_names().contains(&other) {
                                norms.insert(other.to_string(), data);
                            }
                            // any other mtp.* tensor is not needed by the draft head
                        }
                    }
                    Ok(())
                },
            )?;
        }
        let moe_gpu = MtpMoeGpu {
            gate: g_gate.ok_or("mtp lean: experts.gate_up_proj missing")?,
            up: g_up.ok_or("mtp lean: experts.gate_up_proj (up half) missing")?,
            down: g_down.ok_or("mtp lean: experts.down_proj missing")?,
            s_gate: g_sg.ok_or("mtp lean: shared_expert.gate_proj missing")?,
            s_up: g_su.ok_or("mtp lean: shared_expert.up_proj missing")?,
            s_down: g_sd.ok_or("mtp lean: shared_expert.down_proj missing")?,
            s_expert_gate: g_seg.ok_or("mtp lean: shared_expert_gate missing")?,
            router,
        };
        self.mtp_moe_gpu = Some(moe_gpu);
        self.mtp_head = Some(mtp::MtpHead::from_norms(cfg, 4, &norms)?);
        log::info!(
            "qwen3_5 MTP: LEAN GPU load — dense+MoE f16 streamed to GPU, no f32 host copy (~1.7GB GPU, ~0 host)");
        Ok(())
    }

    /// Full-f32 MTP load (Mac parity harness / `VLLM_VULKAN_MTP_HOST_COPY=1`):
    /// builds the whole head in host f32 and (if an engine exists) uploads f16
    /// dense + MoE, KEEPING the f32 host copy as the CPU-parity source / GPU
    /// fallback. Heavy (~6.8GB load peak) — node runs use the lean path instead.
    fn load_mtp_gpu_full(&mut self, mtp_path: &std::path::Path) -> Result<(), String> {
        let cfg = self
            .qwen35
            .as_ref()
            .ok_or_else(|| "load_mtp_gpu needs a loaded qwen3_5 model".to_string())?
            .config
            .clone();
        let head = mtp::MtpHead::load(mtp_path, &cfg, 4)?;
        if let Some(eng) = self.engine.as_mut() {
            for (name, data) in [
                (mtp::MV_FC, &head.fc),
                (mtp::MV_Q, &head.q_proj),
                (mtp::MV_K, &head.k_proj),
                (mtp::MV_V, &head.v_proj),
                (mtp::MV_O, &head.o_proj),
            ] {
                let mut f16_bytes = vec![0u8; data.len() * 2];
                for (i, &v) in data.iter().enumerate() {
                    f16_bytes[i * 2..i * 2 + 2]
                        .copy_from_slice(&half::f16::from_f32(v).to_bits().to_le_bytes());
                }
                let buf = eng
                    .alloc_host_coherent_storage(f16_bytes.len() as u64)
                    .map_err(|e| format!("mtp {name} GPU alloc failed: {e}"))?;
                unsafe {
                    std::ptr::copy_nonoverlapping(
                        f16_bytes.as_ptr(), buf.mapped_ptr.unwrap() as *mut u8, f16_bytes.len());
                }
                self.gpu_weights.insert(
                    name.to_string(),
                    GpuWeight { buffer: buf, format: QuantFormat::F16, aux: None },
                );
            }
        }
        // MoE experts → GPU (plan §P2 D-gate). 256 experts f16-resident + the
        // f32 shared expert, dispatched by the fused `mtp_moe_mlp_gpu` CB. Gated
        // by `mtp_moe_gpu_enabled` (default ON) so the CPU rayon MoE stays an
        // A/B baseline; needs an engine (Mac keeps `mtp_moe_gpu = None` and
        // drafts through the head's host-f32 rayon MoE). The host `moe_w` copy
        // is intentionally KEPT: the on-node parity gate replays the same
        // positions through the engine-less CPU head, and it is the `NodeOps`
        // MoE fallback if a GPU submit ever returns None.
        if mtp_moe_gpu_enabled() {
            if let Some(eng) = self.engine.as_mut() {
                let w = &head.moe_w;
                // f32 [len] → f16 little-endian bytes (rayon: the switch tensors
                // are ~268M elems each, one-time at load).
                let to_f16 = |data: &[f32]| -> Vec<u8> {
                    use rayon::prelude::*;
                    let mut out = vec![0u8; data.len() * 2];
                    out.par_chunks_mut(2).zip(data.par_iter()).for_each(|(c, &v)| {
                        c.copy_from_slice(&half::f16::from_f32(v).to_bits().to_le_bytes());
                    });
                    out
                };
                let up_f16 = |eng: &mut compute::ComputeEngine, data: &[f32]| -> Result<compute::Buffer, String> {
                    let bytes = to_f16(data);
                    let buf = eng.alloc_host_coherent_storage(bytes.len() as u64)
                        .map_err(|e| format!("mtp MoE f16 GPU alloc failed: {e}"))?;
                    buf.write(&bytes).map_err(|e| format!("mtp MoE f16 upload failed: {e}"))?;
                    Ok(buf)
                };
                let up_f32 = |eng: &mut compute::ComputeEngine, data: &[f32]| -> Result<compute::Buffer, String> {
                    let bytes = f32_slice_to_bytes(data);
                    let buf = eng.alloc_host_coherent_storage(bytes.len() as u64)
                        .map_err(|e| format!("mtp MoE f32 GPU alloc failed: {e}"))?;
                    buf.write(&bytes).map_err(|e| format!("mtp MoE f32 upload failed: {e}"))?;
                    Ok(buf)
                };
                let moe_gpu = MtpMoeGpu {
                    gate: up_f16(eng, &w.switch_gate)?,
                    up: up_f16(eng, &w.switch_up)?,
                    down: up_f16(eng, &w.switch_down)?,
                    s_gate: up_f32(eng, &w.shared_gate)?,
                    s_up: up_f32(eng, &w.shared_up)?,
                    s_down: up_f32(eng, &w.shared_down)?,
                    s_expert_gate: up_f32(eng, &w.shared_expert_gate)?,
                    router: w.gate.clone(),
                };
                self.mtp_moe_gpu = Some(moe_gpu);
                log::info!(
                    "qwen3_5 MTP: MoE head uploaded GPU-resident (256 f16 experts + f32 shared, ~1.6GB)");
            }
        }
        self.mtp_head = Some(head);
        Ok(())
    }

    /// One MTP draft position (P2 GPU-dense path). `embed_next` = `embed(t_next)`
    /// row [hidden]; `hidden_pre` = the target's pre-`model.norm` residual
    /// [hidden]; `pos` = the head-KV position (0 for the first draft off a
    /// fresh accept). Returns the draft logits [vocab] via the shared lm_head —
    /// the SAME `qwen35_matvec` call the target's own forward uses. Advances
    /// the head's KV. Errors if no head is loaded (`load_mtp_gpu` never ran).
    /// One MTP head forward step on the node path, returning BOTH the pre-`mtp.norm`
    /// residual (fed back as the next `hidden_pre` in a P4 chain) and the post-norm
    /// head hidden (lm_head input). Threads the dense projections through
    /// `qwen35_matvec` and the MoE through the fused f16 GPU CB via `NodeOps`,
    /// doing the take/restore weight dance so `head` can be mutably borrowed for
    /// its KV. Advances the head KV by one position.
    fn mtp_head_step(
        &mut self, embed_next: &[f32], hidden_pre: &[f32], pos: usize,
    ) -> Result<(Vec<f32>, Vec<f32>), String> {
        let mut head = self
            .mtp_head
            .take()
            .ok_or_else(|| "mtp_head_step: no MTP head loaded (VLLM_VULKAN_MTP_PATH / load_mtp)".to_string())?;
        let dims = head.dims;
        let (fc, qp, kp, vp, op, moe_w) = (
            std::mem::take(&mut head.fc),
            std::mem::take(&mut head.q_proj),
            std::mem::take(&mut head.k_proj),
            std::mem::take(&mut head.v_proj),
            std::mem::take(&mut head.o_proj),
            std::mem::take(&mut head.moe_w),
        );
        // Scope `ops` so its `&mut self` borrow is released before we restore head.
        let (residual, head_hidden, dense_ns, fc, qp, kp, vp, op, moe_w) = {
            let mut ops = NodeOps { vm: self, fc, qp, kp, vp, op, moe_w, dims, dense_ns: 0 };
            let (residual, head_hidden) = head.head_forward_with(embed_next, hidden_pre, pos, &mut ops);
            (residual, head_hidden, ops.dense_ns, ops.fc, ops.qp, ops.kp, ops.vp, ops.op, ops.moe_w)
        };
        prof_add_ns("mtp_draft_dense", dense_ns);
        head.fc = fc;
        head.q_proj = qp;
        head.k_proj = kp;
        head.v_proj = vp;
        head.o_proj = op;
        head.moe_w = moe_w;
        self.mtp_head = Some(head);
        Ok((residual, head_hidden))
    }

    /// Apply the target's shared lm_head to a head hidden and return the draft
    /// argmax token id (P4 chain step). Timed into the `mtp_draft_lmhead` bucket.
    fn mtp_lm_argmax(&mut self, head_hidden: &[f32]) -> u32 {
        let (h, vocab) = {
            let c = self.qwen35.as_ref().unwrap();
            (c.config.hidden_size, c.config.vocab_size)
        };
        let lm_name = self.qwen35.as_ref().unwrap().lm_head_name.clone();
        let t_lm = std::time::Instant::now();
        let logits = self.qwen35_matvec(&lm_name, head_hidden, h, vocab);
        prof_add_ns("mtp_draft_lmhead", t_lm.elapsed().as_nanos());
        let (mut bi, mut bv) = (0usize, f32::NEG_INFINITY);
        for (i, &v) in logits.iter().enumerate() {
            if v > bv { bv = v; bi = i; }
        }
        bi as u32
    }

    pub(crate) fn mtp_draft(
        &mut self, embed_next: &[f32], hidden_pre: &[f32], pos: usize,
    ) -> Result<Vec<f32>, String> {
        let (h, vocab) = {
            let c = self.qwen35.as_ref().unwrap();
            (c.config.hidden_size, c.config.vocab_size)
        };
        let (_residual, hidden) = self.mtp_head_step(embed_next, hidden_pre, pos)?;
        let lm_name = self.qwen35.as_ref().unwrap().lm_head_name.clone();
        let t_lm = std::time::Instant::now();
        let logits = self.qwen35_matvec(&lm_name, &hidden, h, vocab);
        prof_add_ns("mtp_draft_lmhead", t_lm.elapsed().as_nanos());
        Ok(logits)
    }

    /// Embedding row `[hidden]` of `token` from the resident f16 embed table
    /// (kept on the untied last stage for MTP). Shared by `mtp_draft_after` and
    /// the P4 chain.
    fn mtp_embed_row(&self, token: u32) -> Result<Vec<f32>, String> {
        let h = self.qwen35.as_ref().ok_or("mtp_embed_row: no qwen3_5 model")?.config.hidden_size;
        let embw = self.q35_f16_host.get("model.embed_tokens.weight").ok_or_else(|| {
            "mtp_embed_row: no embed table on this stage — set VLLM_VULKAN_MTP_PATH at \
             construction so the untied last stage retains the embed f16 host copy".to_string()
        })?;
        let base = token as usize * h;
        if base + h > embw.len() {
            return Err(format!("mtp_embed_row: token {token} out of embed range (len {})", embw.len()));
        }
        Ok(embw[base..base + h].iter().map(|&b| half::f16::from_bits(b).to_f32()).collect())
    }

    /// P4 chained draft: produce `depth` autoregressive drafts `d_1..d_depth` off a
    /// just-committed `first_token` in ONE call — the marshalling win the plan asks
    /// for (avoids `depth` pyo3 round trips per cycle). `d_1` consumes
    /// `embed(first_token)` + the stashed target pre-norm hidden (`q35_last_prenorm`);
    /// `d_j` (j≥2) consumes `embed(d_{j-1})` + the head's OWN residual from step
    /// `j-1` (the NextN self-chain, plan §1.2). Each step advances the head KV by
    /// one from `head_pos`. Mirrors `MtpHead::head_chain_cpu` with GPU dense/MoE +
    /// the shared lm_head. Returns `[d_1..d_depth]`.
    ///
    /// The driver keeps the head KV gap-free across cycles by `mtp_kv_rewind`-ing
    /// to the confirmed frontier before calling this (dropping the previous cycle's
    /// mispredicted speculative suffix while keeping the confirmed prefix's RoPE
    /// context). On-node α refinement (deferred): `q35_last_prenorm` is the freshest
    /// last-stage prenorm; when the new real came from a MIDDLE verifying pass a
    /// per-position prenorm ring would feed the exact producing hidden — noted in
    /// the P4 runbook. Greedy-exactness never depends on draft quality (verification
    /// catches every wrong draft), so this only affects the accept rate.
    pub(crate) fn mtp_draft_chain_impl(
        &mut self, first_token: u32, head_pos: usize, depth: usize,
    ) -> Result<Vec<u32>, String> {
        if depth == 0 {
            return Ok(Vec::new());
        }
        if self.mtp_head.is_none() {
            return Err("mtp_draft_chain: no MTP head loaded".to_string());
        }
        // P4 α fix: `d_1`'s hidden must be the pre-norm that PRODUCED `first_token`
        // (the pass at `head_pos`), NOT the freshest stash. On a partial accept the
        // freshest stash is the deepest verify pass (`cposA+DEPTH`) while the new
        // real came from `cposA+k` — sourcing by position keeps α_1 depth-independent
        // (see `prenorm_for_pos` + the `q35_prenorm_ring` doc). `d_j` (j≥2) uses the
        // head's own residual, unchanged. Falls back to the freshest stash for the
        // prefill bootstrap position the ring never saw.
        let mut hidden_pre = self
            .prenorm_for_pos(head_pos)
            .ok_or_else(|| "mtp_draft_chain: no captured pre-norm hidden — call after a last-stage forward".to_string())?;
        // STEP-7 draft debug (`VLLM_VULKAN_MTP_DRAFT_DEBUG=1`): the L2 of the
        // h_pre fed to d_1 (≈0 ⇒ zero/absent stash; a healthy pre-`model.norm`
        // residual is O(10s–100s), a post-norm hidden would be ~sqrt(hidden)).
        let dbg = std::env::var("VLLM_VULKAN_MTP_DRAFT_DEBUG").map(|v| v != "0").unwrap_or(false);
        let hpre_l2 = if dbg {
            hidden_pre.iter().map(|&x| (x as f64) * (x as f64)).sum::<f64>().sqrt()
        } else { 0.0 };
        let mut cur_tok = first_token;
        let mut drafts = Vec::with_capacity(depth);
        for step in 0..depth {
            let embed_next = self.mtp_embed_row(cur_tok)?;
            let (residual, head_hidden) = self.mtp_head_step(&embed_next, &hidden_pre, head_pos + step)?;
            let tok = self.mtp_lm_argmax(&head_hidden);
            drafts.push(tok);
            cur_tok = tok;
            hidden_pre = residual; // NextN self-chain: feed the head's own residual
        }
        if dbg {
            static N: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
            let c = N.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
            if c < 8 {
                eprintln!("[MTP_DRAFT_DBG call={c}] head_pos={head_pos} first_token={first_token} \
                           h_pre_l2={hpre_l2:.4} drafts={drafts:?}");
            }
        }
        Ok(drafts)
    }

    /// Reset the head's KV (start a fresh draft chain from a newly-accepted
    /// true token). No-op if no head is loaded. Also drops the position→pre-norm
    /// ring so a fresh generation never reads a stale prior-run hidden.
    pub(crate) fn mtp_reset(&mut self) {
        self.q35_prenorm_ring.clear();
        if let Some(head) = self.mtp_head.as_mut() {
            head.reset();
        }
    }

    /// The pre-`model.norm` hidden that PRODUCED the token at `pos+1` — i.e. the
    /// last-stage forward that was FED the token at position `pos`. Reads the
    /// position ring most-recent-first (so a re-fed speculative position resolves
    /// to the current cycle's write) and falls back to the freshest stash for
    /// positions the ring never saw (the prefill bootstrap). This is the P4 chain
    /// α fix: `d_1` must be drafted off the producing pass's hidden, and on a
    /// partial accept that pass is NOT the freshest one.
    fn prenorm_for_pos(&self, pos: usize) -> Option<Vec<f32>> {
        prenorm_ring_lookup(&self.q35_prenorm_ring, pos)
            .or_else(|| self.q35_last_prenorm.clone())
    }
}

/// Standalone MTP draft head (plan §P2), engine-less CPU path — the Mac parity
/// vehicle. Loads `mtp.safetensors` + the target `config.json` geometry; the
/// caller feeds `embed(t_next)` and applies the shared lm_head to the returned
/// head hidden (so no main checkpoint is loaded here). `head_hidden` advances the
/// head's own KV; `reset` starts a fresh draft chain.
#[cfg(feature = "mtp")]
#[pyclass]
struct MtpHeadPy {
    head: mtp::MtpHead,
}

#[cfg(feature = "mtp")]
#[pymethods]
impl MtpHeadPy {
    #[new]
    #[pyo3(signature = (mtp_path, config_path, max_depth = 4))]
    fn new(mtp_path: &str, config_path: &str, max_depth: usize) -> PyResult<Self> {
        let cfg_text = std::fs::read_to_string(config_path)
            .map_err(|e| PyRuntimeError::new_err(format!("read config {config_path}: {e}")))?;
        let cfg_json: serde_json::Value = serde_json::from_str(&cfg_text)
            .map_err(|e| PyRuntimeError::new_err(format!("parse config: {e}")))?;
        let cfg = qwen35::Qwen35Config::from_json(&cfg_json)
            .map_err(PyRuntimeError::new_err)?;
        let head = mtp::MtpHead::load(std::path::Path::new(mtp_path), &cfg, max_depth)
            .map_err(PyRuntimeError::new_err)?;
        Ok(MtpHeadPy { head })
    }

    /// One draft position. `embed_next` = `embed(t_next)` row [hidden]; `hidden_pre`
    /// = the target's pre-`model.norm` residual [hidden]; `pos` = the head-KV
    /// position (0 for the first draft off a fresh accept, incrementing along a
    /// chain). Returns the head hidden `mtp.norm(out)` [hidden]; apply the shared
    /// lm_head to it for the draft logits/argmax. Advances the head KV.
    fn head_hidden(&mut self, embed_next: Vec<f32>, hidden_pre: Vec<f32>, pos: usize) -> PyResult<Vec<f32>> {
        let h = self.head.cfg.hidden_size;
        if embed_next.len() != h || hidden_pre.len() != h {
            return Err(PyRuntimeError::new_err(format!(
                "expected embed_next/hidden_pre len {h}, got {}/{}",
                embed_next.len(), hidden_pre.len())));
        }
        Ok(self.head.head_hidden_cpu(&embed_next, &hidden_pre, pos))
    }

    /// Reset the head KV — begin a new draft chain from a freshly-accepted token.
    fn reset(&mut self) {
        self.head.reset();
    }

    #[getter]
    fn hidden_size(&self) -> usize {
        self.head.cfg.hidden_size
    }
}

/// ★ DeepSeek-V4-Flash GPU-resident PP-stage handle (Phase 2f).
///
/// Wraps a single [`dsv4_gpu::Dsv4GpuStage`] loaded over its `[layer_start,
/// layer_end)` window (mixed 2/6/8-bit MLX-affine, matvecs GPU-resident; MLA /
/// DSA / manifold-HC / MoE orchestration host-side). Exposes the PP prefill +
/// rolling decode seams so `scripts/dsv4/pp_dsv4.py` can ring the 10 stages
/// across the fleet — the GPU twin of the CPU-proven window chain
/// (`gate2b_pp10_window_chain_cpu`, argmax 11111). Cross-stage payload is the
/// `[seq, hc*h]` hyper-connection stream (NOT `[h]` — DSV4's residual stream is
/// `hc_mult=4` parallel streams).
#[cfg(feature = "dsv4")]
#[pyclass]
pub struct Dsv4Model {
    stage: dsv4_gpu::Dsv4GpuStage,
    /// Native vCCL communicator handle (0 = unset; set via `set_collective_comm`).
    collective_comm: usize,
    /// `hc_mult * hidden_size` — the per-token cross-stage stream payload length.
    hcd: usize,
    vocab: usize,
    first: bool,
    last: bool,
}

#[cfg(feature = "dsv4")]
#[pymethods]
impl Dsv4Model {
    /// Load ONE PP window `[layer_start, layer_end)` GPU-resident from `ckpt_dir`.
    /// `config_path` defaults to `{ckpt_dir}/config.json`. `load_edges` uploads
    /// `lm_head` resident on the last stage (`layer_end == num_hidden_layers`).
    #[new]
    #[pyo3(signature = (ckpt_dir, layer_start, layer_end, config_path=None, load_edges=true, device_idx=0))]
    fn new(
        ckpt_dir: &str,
        layer_start: usize,
        layer_end: usize,
        config_path: Option<String>,
        load_edges: bool,
        device_idx: usize,
    ) -> PyResult<Self> {
        let cfg_path = config_path.unwrap_or_else(|| format!("{ckpt_dir}/config.json"));
        let cfg_text = std::fs::read_to_string(&cfg_path)
            .map_err(|e| PyRuntimeError::new_err(format!("read config {cfg_path}: {e}")))?;
        let cfg_json: serde_json::Value = serde_json::from_str(&cfg_text)
            .map_err(|e| PyRuntimeError::new_err(format!("parse config: {e}")))?;
        let cfg = dsv4::Dsv4Config::from_json(&cfg_json).map_err(PyRuntimeError::new_err)?;
        let stage = dsv4_gpu::Dsv4GpuStage::from_ckpt_streamed(
            ckpt_dir, &cfg, layer_start, layer_end, load_edges, device_idx,
        )
        .map_err(PyRuntimeError::new_err)?;
        let hcd = cfg.hc_mult * cfg.mla.hidden_size;
        Ok(Dsv4Model {
            hcd,
            vocab: cfg.vocab_size,
            first: stage.first,
            last: stage.last,
            stage,
            collective_comm: 0,
        })
    }

    /// Single-node (this window == all layers) GPU-resident forward → `[S, vocab]`
    /// logits. Only meaningful when this stage owns `[0, num_hidden_layers)`.
    fn forward(&mut self, input_ids: Vec<u32>) -> Vec<f32> {
        self.stage.forward(&input_ids)
    }

    /// Last-position argmax + its logit (single-node GATE 2a helper).
    fn argmax_last(&mut self, input_ids: Vec<u32>) -> (u32, f32) {
        self.stage.argmax_last(&input_ids)
    }

    /// One PP-window PREFILL. `streams_in` empty ⇒ first stage (embeds
    /// `input_ids`); else the `[seq, hc*h]` payload from the previous stage.
    /// Returns `(is_logits, data)`: `(false, [seq, hc*h])` mid-stage streams, or
    /// `(true, [seq, vocab])` last-stage logits.
    fn forward_pp_stage_prefill(&mut self, input_ids: Vec<u32>, streams_in: Vec<f32>) -> (bool, Vec<f32>) {
        let sin = if streams_in.is_empty() { None } else { Some(streams_in) };
        match self.stage.forward_pp_stage_prefill(&input_ids, sin) {
            dsv4_gpu::WindowOut::Logits(l) => (true, l),
            dsv4_gpu::WindowOut::Streams(s) => (false, s),
        }
    }

    /// One PP-window DECODE step (advances the rolling cache). `streams_in` empty
    /// ⇒ first stage (embeds `id`). Returns `(is_logits, data)` as above with a
    /// single row: `(false, [hc*h])` streams or `(true, [vocab])` logits.
    fn decode_step_stage(&mut self, id: u32, streams_in: Vec<f32>) -> (bool, Vec<f32>) {
        let sin = if streams_in.is_empty() { None } else { Some(streams_in) };
        match self.stage.decode_step_stage(id, sin) {
            dsv4_gpu::WindowOut::Logits(l) => (true, l),
            dsv4_gpu::WindowOut::Streams(s) => (false, s),
        }
    }

    /// Drop the rolling decode cache (call between independent sequences).
    fn reset_decode_cache(&mut self) {
        self.stage.reset_decode_cache();
    }

    /// Set the native vCCL communicator handle (from `vccl.Communicator.handle`).
    fn set_collective_comm(&mut self, handle: usize) {
        self.collective_comm = handle;
    }

    #[getter]
    fn hcd(&self) -> usize {
        self.hcd
    }
    #[getter]
    fn vocab(&self) -> usize {
        self.vocab
    }
    #[getter]
    fn is_first(&self) -> bool {
        self.first
    }
    #[getter]
    fn is_last(&self) -> bool {
        self.last
    }
    #[getter]
    fn decode_pos(&self) -> usize {
        self.stage.decode_pos()
    }

    /// ★ LEVER A (pyo3-marshal fix): argmax-returning twin of `pp_step_dsv4_logits`.
    /// Mirrors the qwen35 `pp_step_qwen35` win applied to dsv4's ring topology: the
    /// LAST stage argmaxes the `[vocab]` logits IN RUST (strict-`>` first-max
    /// tie-break, bit-identical to the driver's `max(range(V), key=…)`) and rings
    /// back only the single token id (as one f32 — vocab≪2^24 so the round-trip is
    /// exact), instead of ringing the full `[vocab=129280]` float vector to rank0 and
    /// argmaxing in pure Python every token. This kills BOTH the ~129k-float vCCL ring
    /// payload AND the `Vec<f32>→PyList` + pure-Python argmax on rank0 (the dominant
    /// slice of the residual/marshal bucket).
    ///
    ///  - FIRST  (`recv_from<0`, `send_to>=0`): embed `token_id` → send `[hc*h]`
    ///    onward; then recv the 1-float token id ring-back from `last_rank`; return
    ///    `Some(tok)`.
    ///  - MID    (`recv_from>=0`, `send_to>=0`): recv `[hc*h]` → decode → send
    ///    `[hc*h]` onward; return `None`.
    ///  - LAST   (`recv_from>=0`, `send_to<0`): recv `[hc*h]` → decode → `[vocab]` →
    ///    argmax in Rust → send the 1-float token id to rank0; return `None`.
    ///  - STANDALONE N=1 (`recv_from<0` && `send_to<0`): embed → `[vocab]` → argmax;
    ///    return `Some(tok)` with no wire.
    ///
    /// Argmax-exact BY CONSTRUCTION (same strict-`>` tie-break as `pp_step_qwen35`
    /// and the Python driver). Requires `set_collective_comm` with a live handle.
    #[allow(clippy::too_many_arguments)]
    fn pp_step_dsv4(
        &mut self,
        py: Python<'_>,
        token_id: u32,
        recv_from: i32,
        send_to: i32,
        last_rank: i32,
    ) -> PyResult<Option<u32>> {
        if self.collective_comm == 0 {
            return Err(PyRuntimeError::new_err(
                "pp_step_dsv4: native comm not set (call set_collective_comm)",
            ));
        }
        let comm = self.collective_comm as *mut std::os::raw::c_void;
        let do_recv = recv_from >= 0;
        let is_first = recv_from < 0;

        // 1) recv the previous stage's [hc*h] streams (empty on the first stage,
        //    which embeds token_id).
        let streams_in: Vec<f32> = if do_recv {
            vccl_ffi::recv_f32(py, comm, self.hcd, recv_from).map_err(PyRuntimeError::new_err)?
        } else {
            Vec::new()
        };
        let sin = if streams_in.is_empty() { None } else { Some(streams_in) };

        // 2) resident stateful decode of this window (advances the rolling cache).
        let out = self.stage.decode_step_stage(token_id, sin);

        // 3) route the result.
        match out {
            dsv4_gpu::WindowOut::Logits(logits) => {
                // Last stage: argmax in Rust (strict-`>` first-max, == the driver's
                // `max(range(V), key=…)` and `pp_step_qwen35`).
                let (mut bi, mut bv) = (0usize, f32::NEG_INFINITY);
                for (i, &v) in logits.iter().enumerate() {
                    if v > bv { bv = v; bi = i; }
                }
                if is_first {
                    // STANDALONE N=1: this rank both embeds and samples.
                    return Ok(Some(bi as u32));
                }
                // Ring back ONLY the token id (1 f32; vocab≪2^24 ⇒ exact round-trip).
                let tok_f = [bi as f32];
                vccl_ffi::send_f32(py, comm, &tok_f, 0).map_err(PyRuntimeError::new_err)?;
                Ok(None)
            }
            dsv4_gpu::WindowOut::Streams(s) => {
                // First/mid stage: ship the [hc*h] streams onward.
                vccl_ffi::send_f32(py, comm, &s, send_to).map_err(PyRuntimeError::new_err)?;
                if is_first {
                    // rank0 receives the single-token ring-back from the last stage.
                    let tb = vccl_ffi::recv_f32(py, comm, 1, last_rank)
                        .map_err(PyRuntimeError::new_err)?;
                    Ok(Some(tb[0] as u32))
                } else {
                    Ok(None)
                }
            }
        }
    }

    /// ★ DISTRIBUTED-DECODE native-vCCL PP step (mirrors `pp_step_bailing_logits`):
    /// recv the previous stage's `[hc*h]` streams → resident stateful decode of this
    /// window (rolling cache advances IN PLACE) → send the `[hc*h]` streams onward,
    /// OR (last stage) ring the full `[vocab]` logits back to rank0 so the sampler
    /// sees the whole distribution. `recv_from < 0` ⇒ first stage (embeds
    /// `token_id`); `send_to < 0` ⇒ last stage. Returns `Some([vocab])` on the rank
    /// that samples (rank0 via ring-back, or standalone N=1), else `None`. Requires
    /// `set_collective_comm` with a live communicator handle.
    #[allow(clippy::too_many_arguments)]
    fn pp_step_dsv4_logits(
        &mut self,
        py: Python<'_>,
        token_id: u32,
        recv_from: i32,
        send_to: i32,
        last_rank: i32,
    ) -> PyResult<Option<Vec<f32>>> {
        if self.collective_comm == 0 {
            return Err(PyRuntimeError::new_err(
                "pp_step_dsv4_logits: native comm not set (call set_collective_comm)",
            ));
        }
        let comm = self.collective_comm as *mut std::os::raw::c_void;
        let do_recv = recv_from >= 0;
        let is_first = recv_from < 0;

        // 1) recv the previous stage's [hc*h] streams (empty on the first stage,
        //    which embeds token_id).
        let streams_in: Vec<f32> = if do_recv {
            vccl_ffi::recv_f32(py, comm, self.hcd, recv_from).map_err(PyRuntimeError::new_err)?
        } else {
            Vec::new()
        };
        let sin = if streams_in.is_empty() { None } else { Some(streams_in) };

        // 2) resident stateful decode of this window (advances the rolling cache).
        let out = self.stage.decode_step_stage(token_id, sin);

        // 3) route the result.
        match out {
            dsv4_gpu::WindowOut::Logits(logits) => {
                // Last stage.
                if is_first {
                    // STANDALONE N=1: this rank both embeds and samples.
                    return Ok(Some(logits));
                }
                // Ring the [vocab] logits back to rank0.
                vccl_ffi::send_f32(py, comm, &logits, 0).map_err(PyRuntimeError::new_err)?;
                Ok(None)
            }
            dsv4_gpu::WindowOut::Streams(s) => {
                // First/mid stage: ship the [hc*h] streams onward.
                vccl_ffi::send_f32(py, comm, &s, send_to).map_err(PyRuntimeError::new_err)?;
                if is_first {
                    // rank0 receives the vocab ring-back from the last stage.
                    let logits = vccl_ffi::recv_f32(py, comm, self.vocab, last_rank)
                        .map_err(PyRuntimeError::new_err)?;
                    Ok(Some(logits))
                } else {
                    Ok(None)
                }
            }
        }
    }
}

