#[pymodule]
fn _rs(m: &Bound<'_, PyModule>) -> PyResult<()> {
    env_logger::try_init().ok();

    m.add_function(wrap_pyfunction!(is_available, m)?)?;
    m.add_function(wrap_pyfunction!(get_device_count, m)?)?;
    m.add_function(wrap_pyfunction!(enumerate_devices, m)?)?;
    m.add_function(wrap_pyfunction!(get_device_info, m)?)?;
    m.add_function(wrap_pyfunction!(synchronize, m)?)?;
    m.add_function(wrap_pyfunction!(get_memory_info, m)?)?;
    m.add_function(wrap_pyfunction!(direct_engine::debug_direct_engine_replay, m)?)?;
    #[cfg(feature = "debug-api")]
    register_debug_api(m)?;

    m.add_class::<VulkanDevice>()?;
    m.add_class::<VulkanContext>()?;
    m.add_class::<GpuTensor>()?;
    m.add_class::<VulkanModel>()?;
    #[cfg(feature = "gemma")]
    m.add_class::<gemma_assistant::GemmaAssistant>()?;
    #[cfg(feature = "mtp")]
    m.add_class::<MtpHeadPy>()?;
    #[cfg(feature = "dsv4")]
    m.add_class::<Dsv4Model>()?;

    m.add("__version__", env!("CARGO_PKG_VERSION"))?;
    m.add("__vulkan_available__", device::is_vulkan_available())?;

    Ok(())
}


#[cfg(test)]
mod registry_tests {
    use super::*;
    use pipeline::ShaderClass;

    // Compiled-but-intentionally-unregistered shaders (mirrors build.rs::SKIP).
    const SKIP: &[&str] = &["div_f32_f32_f32", "sub_f32_f32_f32"];

    /// Independent re-derivation of build.rs::class_of, to catch a
    /// transcription bug in the generated registry.
    fn expected_class(name: &str) -> ShaderClass {
        if name == "rms_norm_f32" {
            ShaderClass::RmsNorm
        } else if name.ends_with("_subgroup") {
            ShaderClass::MatvecSubgroup
        } else if name.starts_with("mul_mat_vec_") {
            ShaderClass::Matvec
        } else if name.starts_with("matmul_") {
            ShaderClass::MulMm
        } else if name.starts_with("flash_attn_") {
            ShaderClass::Flash
        } else {
            ShaderClass::Plain
        }
    }

    #[test]
    fn cutover_guard_registry_len() {
        // Registry-integrity guard. The absolute shader count is a BUILD-TIME
        // artifact — build.rs::generate_registry enumerates the compiled
        // `OUT_DIR/spirv/*.spv`, drops build.rs::SKIP, and appends
        // build.rs::ALIASES — so it changes with every shader add/remove and
        // with which model features were compiled. Hardcoding it (the old
        // `== 131`) was fragile and had repeatedly gone stale. Instead we
        // DERIVE the expected length from the generated registry itself and
        // assert the runtime shader map is 1:1 with it:
        //
        // `include_all_shaders()` keys `SHADER_REGISTRY` by name into a
        // HashMap; if two rows ever shared a name the map would silently
        // collapse an entry and make that shader un-dispatchable. This guard
        // is exactly that invariant — every registry row survives into the
        // runtime map — which is the property that actually matters, and it
        // tracks the tree automatically instead of needing a magic-number
        // bump on every shader change. (`no_dup_names` below is the same
        // invariant stated on the registry side.)
        let expected = shader_registry::SHADER_REGISTRY.len();
        assert!(expected > 0,
            "shader registry is empty — build.rs registry generation failed");
        assert_eq!(include_all_shaders().len(), expected,
            "include_all_shaders() lost entries vs SHADER_REGISTRY \
             (duplicate shader name collapsed the runtime map)");
    }

    #[test]
    fn class_transcription_guard() {
        for (name, class, _) in shader_registry::SHADER_REGISTRY {
            assert_eq!(*class, expected_class(name), "class mismatch for '{name}'");
        }
    }

    #[test]
    fn alias_bytes_guard() {
        let map: std::collections::HashMap<&str, &[u8]> = shader_registry::SHADER_REGISTRY
            .iter()
            .map(|(n, _, b)| (*n, *b))
            .collect();
        let base = *map.get("flash_attn_f32_f16_f32").expect("base flash shader present");
        for alias in ["flash_attn_f32_f16_f32_hs256", "flash_attn_f32_f16_f32_hs512"] {
            assert_eq!(*map.get(alias).expect("alias present"), base,
                "alias '{alias}' bytes must equal flash_attn_f32_f16_f32 bytes");
        }
    }

    #[test]
    fn no_dup_names() {
        let names: std::collections::HashSet<&str> = shader_registry::SHADER_REGISTRY
            .iter()
            .map(|(n, _, _)| *n)
            .collect();
        assert_eq!(names.len(), shader_registry::SHADER_REGISTRY.len(), "duplicate shader name in registry");
    }

    #[test]
    fn skip_list_absent_from_registry() {
        for (name, _, _) in shader_registry::SHADER_REGISTRY {
            assert!(!SKIP.contains(name), "skip-listed shader '{name}' must not be registered");
        }
    }
}

/// EAGLE3 fast-verify correctness gate (design plan §3): `forward_batched`
/// exercised on the CPU-fallback branch (no Vulkan engine — deterministic on
/// Mac; the GPU 1-CB/layer path is bit-exact-by-construction and validated
/// on-device in the cluster re-gate, not here). Builds a tiny synthetic Qwen3
/// model in-memory (no safetensors file needed) with `engine: None` set
/// explicitly, so these tests exercise `forward_batched`'s CPU branch
/// regardless of whether this machine happens to have a working Vulkan
/// device.
#[cfg(all(test, feature = "gemma"))]
mod batched_forward_tests {
    use super::*;
    use std::collections::HashMap;

    /// Deterministic pseudo-random f32s in [-0.05, 0.05) (xorshift32), so
    /// every synthetic weight/embedding is reproducible without a `rand` dep.
    fn synth_vec(len: usize, seed: u32) -> Vec<f32> {
        let mut s = seed | 1;
        (0..len).map(|_| {
            s ^= s << 13; s ^= s >> 17; s ^= s << 5;
            ((s as f32 / u32::MAX as f32) - 0.5) * 0.1
        }).collect()
    }

    /// A tiny (engine=None) Qwen3-dense `VulkanModel`: hidden=8, 2 heads x
    /// head_dim=4 (q_dim=kv_dim=8, no GQA), intermediate=12, vocab=20, 2
    /// layers, tied embeddings. Every field mirrors `gpu_only`'s literal
    /// (§struct definition) with `qwen: Some(..)`, `engine: None`.
    fn tiny_qwen_model() -> VulkanModel {
        let cfg = model::Qwen3Config {
            hidden_size: 8,
            num_hidden_layers: 2,
            num_attention_heads: 2,
            num_key_value_heads: 2,
            head_dim: 4,
            intermediate_size: 12,
            vocab_size: 20,
            rms_norm_eps: 1e-5,
            rope_theta: 10000.0,
            tie_word_embeddings: true,
        };
        let h = cfg.hidden_size;
        let q_dim = cfg.num_attention_heads * cfg.head_dim;
        let kv_dim = cfg.num_key_value_heads * cfg.head_dim;
        let inter = cfg.intermediate_size;
        let vocab = cfg.vocab_size;
        let mut tensors: HashMap<String, model::SimpleTensor> = HashMap::new();
        let mut seed = 1u32;
        let mut put = |tensors: &mut HashMap<String, model::SimpleTensor>, name: &str, len: usize| {
            seed = seed.wrapping_add(0x9E3779B9);
            tensors.insert(name.to_string(), model::SimpleTensor { data: synth_vec(len, seed), shape: vec![] });
        };
        put(&mut tensors, "model.embed_tokens.weight", vocab * h);
        for i in 0..cfg.num_hidden_layers {
            let ln = |s: &str| format!("model.layers.{i}.{s}");
            put(&mut tensors, &ln("input_layernorm.weight"), h);
            put(&mut tensors, &ln("self_attn.q_proj.weight"), q_dim * h);
            put(&mut tensors, &ln("self_attn.k_proj.weight"), kv_dim * h);
            put(&mut tensors, &ln("self_attn.v_proj.weight"), kv_dim * h);
            put(&mut tensors, &ln("self_attn.q_norm.weight"), cfg.head_dim);
            put(&mut tensors, &ln("self_attn.k_norm.weight"), cfg.head_dim);
            put(&mut tensors, &ln("self_attn.o_proj.weight"), h * q_dim);
            put(&mut tensors, &ln("post_attention_layernorm.weight"), h);
            put(&mut tensors, &ln("mlp.gate_proj.weight"), inter * h);
            put(&mut tensors, &ln("mlp.up_proj.weight"), inter * h);
            put(&mut tensors, &ln("mlp.down_proj.weight"), h * inter);
        }
        put(&mut tensors, "model.norm.weight", h);
        // RMSNorm weights near 1.0 (not tiny random) so normalization doesn't
        // degenerate; overwrite the norm rows written above with a flat 1.0 +
        // small jitter.
        for name in tensors.keys().cloned().collect::<Vec<_>>() {
            if name.ends_with("norm.weight") {
                let t = tensors.get_mut(&name).unwrap();
                for v in t.data.iter_mut() { *v = 1.0 + *v; }
            }
        }
        let weights = model::ModelWeights { tensors };
        let kv_caches: Vec<model::KvCache> = (0..cfg.num_hidden_layers)
            .map(|_| model::KvCache::new(32, cfg.num_key_value_heads, cfg.head_dim))
            .collect();
        let qwen = model::Qwen3Model {
            config: cfg,
            weights,
            kv_caches,
            lm_head_name: "model.embed_tokens.weight".to_string(),
        };
        let placeholder = model::Gemma4Model {
            config: model::Gemma4Config::e2b(),
            weights: model::ModelWeights { tensors: HashMap::new() },
            kv_caches: Vec::new(),
        };
        VulkanModel {
            inner: placeholder,
            qwen: Some(qwen),
            qwen35: None,
            step3p7: None,
            max_seq_len: 32,
            engine: None,
            gpu_weights: HashMap::new(),
            act_bufs: Vec::new(),
            act_bufs_ready: false,
            pp_start: 0,
            pp_end: 0,
            pp_first: true,
            pp_last: true,
            tp_rank: 0,
            tp_size: 1,
            gemma_ple_bf16: None,
            gpu_kv: HashMap::new(),
            gemma_kv_filled: 0,
            qres_bufs: Vec::new(),
            qres_ready: false,
            gres_bufs: Vec::new(),
            gres_ready: false,
            gemma_norm_w: HashMap::new(),
            gpu_norm_w: HashMap::new(),
            ures_bufs: Vec::new(),
            ures_ready: false,
            unified_norm_w: HashMap::new(),
            bres_bufs: Vec::new(),
            bres_ready: false,
            q35_f16_host: HashMap::new(),
            collective_comm: 0,
            reduce_scratch: Vec::new(),
            reduce_scratch_handle: 0,
            pp_tok_ring: PpTokRing::default(),
            pp_hop_send: PpTokRing::default(),
            pp_hop_recv: PpTokRing::default(),
            pp_vocab_ring: PpTokRing::default(),
            gemma_hidden_ring: std::collections::VecDeque::new(),
            gemma_pp_hop: Default::default(),
            moe_gpu: HashMap::new(),
            moe_shared_gpu: HashMap::new(),
            dn_gpu: HashMap::new(),
            q35res_bufs: Vec::new(),
            q35res_ready: false,
            q35res_ok: None,
            spec_slots: Vec::new(),
            flags: Flags::from_env(),
            lm_shard: None,
            chunked_weights: std::collections::HashMap::new(),
            nemotron: None,
            nemotron_mtp_head: None,
            kimi: None,
            ling: None,
            laguna: None,
            laguna_gpu: None,
            mtp_head: None,
            mtp_moe_gpu: None,
            q35_last_prenorm: None,
            q35_prenorm_ring: std::collections::VecDeque::new(),
            spec_verify_gdn_inputs: Vec::new(),
            spec_verify_span: None,
            spec_verify_cols: false,
            kv_store: None,
        }
    }

    /// T=1 must be bit-exact vs the per-token `forward` — same math, same
    /// order (the CPU-fallback branch literally calls `Qwen3Model::forward`).
    #[test]
    fn forward_batched_t1_matches_forward() {
        let mut m = tiny_qwen_model();
        m.reset_kv_cache();
        let a = m.forward_rs(5, 0).unwrap();
        m.reset_kv_cache();
        let b = m.forward_batched_impl(vec![5], 0).unwrap();
        assert_eq!(a.len(), b.len());
        assert_eq!(a, b, "T=1 forward_batched must be bit-exact vs forward");
    }

    /// T>1 logits at each position must match T serial forwards over the same
    /// tokens from the same start (argmax must match exactly — what verify
    /// actually consumes). Exercised at T=3, T=8, and a start_pos>0 append
    /// onto a non-empty cache.
    fn check_matches_serial(tokens: &[u32], start_pos: usize) {
        let vocab = 20usize;
        let mut m = tiny_qwen_model();
        m.reset_kv_cache();
        // Prime the cache up to start_pos with distinct filler tokens so a
        // start_pos>0 case genuinely appends onto a non-empty cache.
        for i in 0..start_pos { m.forward_rs((100 + i) as u32 % vocab as u32, i).unwrap(); }
        let mut serial = Vec::with_capacity(tokens.len() * vocab);
        for (i, &tok) in tokens.iter().enumerate() {
            serial.extend(m.forward_rs(tok, start_pos + i).unwrap());
        }

        let mut m2 = tiny_qwen_model();
        m2.reset_kv_cache();
        for i in 0..start_pos { m2.forward_rs((100 + i) as u32 % vocab as u32, i).unwrap(); }
        let batched = m2.forward_batched_impl(tokens.to_vec(), start_pos).unwrap();

        assert_eq!(batched.len(), serial.len());
        for i in 0..tokens.len() {
            let s = &serial[i * vocab..(i + 1) * vocab];
            let b = &batched[i * vocab..(i + 1) * vocab];
            // CPU-fallback path calls the identical per-token `forward`, so
            // this is bit-exact (stronger than the plan's documented
            // GEMM-accumulation-order tolerance, which applies to the GPU path).
            assert_eq!(s, b, "position {i} logits mismatch (start_pos={start_pos})");
            let argmax = |v: &[f32]| v.iter().enumerate()
                .max_by(|a, b| a.1.partial_cmp(b.1).unwrap()).unwrap().0;
            assert_eq!(argmax(s), argmax(b), "position {i} argmax mismatch (start_pos={start_pos})");
        }
    }

    #[test]
    fn forward_batched_matches_serial_t3() {
        check_matches_serial(&[3, 7, 11], 0);
    }

    #[test]
    fn forward_batched_matches_serial_t8() {
        check_matches_serial(&[1, 2, 3, 4, 5, 6, 7, 8], 0);
    }

    #[test]
    fn forward_batched_matches_serial_start_pos_gt0() {
        check_matches_serial(&[2, 4, 6], 5);
    }

    /// Append + rewind repeatable (§5): call `forward_batched(tokens, 0)`
    /// twice with `truncate_kv(0)` between; the second call's logits must
    /// equal the first's — exactly what the bench loop (and a real
    /// spec-decode reject/rollback) needs.
    #[test]
    fn forward_batched_rewind_repeatable() {
        let mut m = tiny_qwen_model();
        let tokens = vec![9u32, 2, 14];
        m.reset_kv_cache();
        let first = m.forward_batched_impl(tokens.clone(), 0).unwrap();
        m.truncate_kv(0);
        let second = m.forward_batched_impl(tokens.clone(), 0).unwrap();
        assert_eq!(first, second, "forward_batched must be repeatable after a full rewind");
    }
}

/// P2 batched-prefill CPU-fallback gate (design plan, item-1 phase-2): a
/// mixed hybrid stage (`LinearAttention` then `FullAttention`, dense MLP) run
/// through `forward_qwen35_prefill` (the `self.engine.is_none()` branch, i.e.
/// `Qwen35Model::forward_pp_range_batched`) must reproduce
/// `Qwen35Model::forward` called `T` times in a row EXACTLY — the Linear
/// layer's T `delta_net` calls collapse into one `delta_net_scan` call
/// (already proven bit-exact-by-construction, see
/// `qwen35::spec_rollback_tests`/`delta_net_scan_bit_exact_vs_serial`); the
/// FullAttention/MLP sub-blocks stay literal per-token calls. Builds a tiny
/// synthetic qwen3.6 model in-memory (no checkpoint needed), engine-less.
#[cfg(all(test, feature = "qwen35"))]
// LOADER-ALIGNMENT NOTE (real-load-only surface, see the qwen36-batched-prefill
// audit): these fixtures now mirror the real split loader for `embed_tokens`/
// `lm_head` (f16-only via `q35_f16_host`, stripped from the f32 store — see
// `f16_roundtrip`/`q35_f16_host_from_weights` below) specifically because that
// mismatch is what caused the real crash this pass fixed. They do NOT,
// however, exercise `load_qwen35_weights_split` itself, nor the GPU-resident
// `on_proj` streaming sink (Consumed/KeepF32/quant-format/aux selection),
// TP sharding, or chunked-lm_head allocation — those are only reachable
// through an actual model load, which is cluster/real-checkpoint-only (no
// synthetic fixture substitutes for it). Anyone touching the loader<->forward
// weight-source contract again should re-run the queued single-stage cluster
// benchmark (`forward_qwen35_prefill` on a real checkpoint), not just this
// unit suite, before trusting a fix.
mod qwen35_prefill_tests {
    use super::*;
    use qwen35::{LayerType, Qwen35Config, Qwen35Model};
    use model::{ModelWeights, SimpleTensor};
    use std::collections::HashMap;

    /// Deterministic xorshift weight/input generator (same generator style as
    /// `qwen35::spec_rollback_tests::gen` / the `debug_*` probes).
    fn gen(seed: u64) -> impl FnMut() -> f32 {
        let mut s = seed.wrapping_mul(0x9E3779B97F4A7C15).wrapping_add(1);
        move || {
            s ^= s << 13; s ^= s >> 7; s ^= s << 17;
            ((s >> 40) as f32 / (1u32 << 24) as f32) * 2.0 - 1.0
        }
    }

    /// f16 round-trip (quantize then dequantize) — the REAL split loader
    /// (`load_qwen35_weights_split`'s `want_f16`) ALWAYS keeps
    /// `embed_tokens`/`lm_head` f16-only (never f32), unconditionally of GPU
    /// engine presence. Baking that lossy round-trip into the synthetic
    /// fixture's plain-CPU reference values too means the (untouched)
    /// `Qwen35Model::forward` oracle and the (fixed) `q35_f16_host`-sourced
    /// prefill path compute over the IDENTICAL quantized numbers, so the
    /// bit-exact assertions below stay meaningful post-fix.
    fn f16_roundtrip(v: &[f32]) -> Vec<f32> {
        v.iter().map(|&x| half::f16::from_f32(x).to_f32()).collect()
    }

    /// Raw f16 bit encoding — mirrors what the loader's `q35_f16_host` table
    /// holds for `embed_tokens`/`lm_head`.
    fn f16_bits(v: &[f32]) -> Vec<u16> {
        v.iter().map(|&x| half::f16::from_f32(x).to_bits()).collect()
    }

    /// Builds the `q35_f16_host` map a real split load would produce for
    /// `embed_tokens`/`lm_head`, from the (already f16-round-tripped) f32
    /// values in `w` — i.e. the SAME loader-alignment split this test guards
    /// against regressing.
    fn q35_f16_host_from_weights(w: &ModelWeights) -> HashMap<String, Vec<u16>> {
        let mut m = HashMap::new();
        m.insert("model.embed_tokens.weight".to_string(),
            f16_bits(w.f32_slice("model.embed_tokens.weight")));
        m.insert("lm_head.weight".to_string(),
            f16_bits(w.f32_slice("lm_head.weight")));
        m
    }

    const H: usize = 16;
    const NQ: usize = 4;
    const NKV: usize = 2;
    const HD: usize = 4;
    const NK: usize = 1;
    const NV: usize = 2;
    const KD: usize = 4;
    const VD: usize = 4;
    const KERN: usize = 3;
    const INTER: usize = 12;
    const VOCAB: usize = 12;

    fn cfg() -> Qwen35Config {
        Qwen35Config {
            hidden_size: H,
            num_hidden_layers: 2,
            vocab_size: VOCAB,
            rms_norm_eps: 1e-6,
            tie_word_embeddings: false,
            num_attention_heads: NQ,
            num_key_value_heads: NKV,
            head_dim: HD,
            attn_output_gate: true,
            rope_theta: 1e7,
            partial_rotary_factor: 0.5, // rotary_dim = 2 (even)
            linear_num_key_heads: NK,
            linear_num_value_heads: NV,
            linear_key_head_dim: KD,
            linear_value_head_dim: VD,
            linear_conv_kernel_dim: KERN,
            intermediate_size: INTER,
            num_experts: 0,
            num_experts_per_tok: 0,
            moe_intermediate_size: 0,
            shared_expert_intermediate_size: 0,
            layer_types: vec![LayerType::LinearAttention, LayerType::FullAttention],
        }
    }

    /// Builds a fresh copy of the same deterministic weights every call (weight
    /// data isn't `Clone`-friendly to share cheaply across two model
    /// instances, so both the serial reference and the batched-prefill model
    /// get their own copy from the same generator seed — bit-identical).
    fn build_weights() -> ModelWeights {
        let key_dim = NK * KD;
        let value_dim = NV * VD;
        let conv_dim = 2 * key_dim + value_dim;
        let q_dim = NQ * HD;
        let kv_dim = NKV * HD;
        let mut g = gen(0xC0FFEE);
        let mut mk = |rows: usize, cols: usize, scale: f32| -> Vec<f32> {
            (0..rows * cols).map(|_| g() * scale).collect()
        };
        let mut tensors: HashMap<String, SimpleTensor> = HashMap::new();
        let mut ins = |name: String, data: Vec<f32>| {
            tensors.insert(name, SimpleTensor { data, shape: vec![] });
        };
        // Round-tripped through f16 (see `f16_roundtrip`'s doc comment) — the
        // real loader NEVER keeps these as plain f32.
        ins("model.embed_tokens.weight".to_string(), f16_roundtrip(&mk(VOCAB, H, 0.05)));
        ins("lm_head.weight".to_string(), f16_roundtrip(&mk(VOCAB, H, 0.05)));
        ins("model.norm.weight".to_string(), mk(H, 1, 0.1).iter().map(|&v| 1.0 + v).collect());
        // Layer 0: linear_attn.
        let p0 = "model.layers.0";
        ins(format!("{p0}.input_layernorm.weight"), mk(H, 1, 0.1).iter().map(|&v| 1.0 + v).collect());
        ins(format!("{p0}.post_attention_layernorm.weight"), mk(H, 1, 0.1).iter().map(|&v| 1.0 + v).collect());
        ins(format!("{p0}.linear_attn.in_proj_qkv.weight"), mk(conv_dim, H, 0.05));
        ins(format!("{p0}.linear_attn.in_proj_z.weight"), mk(value_dim, H, 0.05));
        ins(format!("{p0}.linear_attn.in_proj_a.weight"), mk(NV, H, 0.05));
        ins(format!("{p0}.linear_attn.in_proj_b.weight"), mk(NV, H, 0.05));
        ins(format!("{p0}.linear_attn.conv1d.weight"), mk(conv_dim, KERN, 0.5));
        ins(format!("{p0}.linear_attn.A_log"), mk(NV, 1, 1.0));
        ins(format!("{p0}.linear_attn.dt_bias"), mk(NV, 1, 0.5));
        ins(format!("{p0}.linear_attn.norm.weight"), mk(VD, 1, 0.1).iter().map(|&v| 1.0 + v).collect());
        ins(format!("{p0}.linear_attn.out_proj.weight"), mk(H, value_dim, 0.05));
        ins(format!("{p0}.mlp.gate_proj.weight"), mk(INTER, H, 0.05));
        ins(format!("{p0}.mlp.up_proj.weight"), mk(INTER, H, 0.05));
        ins(format!("{p0}.mlp.down_proj.weight"), mk(H, INTER, 0.05));
        // Layer 1: self_attn (gated full attention).
        let p1 = "model.layers.1";
        ins(format!("{p1}.input_layernorm.weight"), mk(H, 1, 0.1).iter().map(|&v| 1.0 + v).collect());
        ins(format!("{p1}.post_attention_layernorm.weight"), mk(H, 1, 0.1).iter().map(|&v| 1.0 + v).collect());
        ins(format!("{p1}.self_attn.q_proj.weight"), mk(q_dim * 2, H, 0.05));
        ins(format!("{p1}.self_attn.k_proj.weight"), mk(kv_dim, H, 0.05));
        ins(format!("{p1}.self_attn.v_proj.weight"), mk(kv_dim, H, 0.05));
        ins(format!("{p1}.self_attn.o_proj.weight"), mk(H, q_dim, 0.05));
        ins(format!("{p1}.self_attn.q_norm.weight"), mk(HD, 1, 0.1).iter().map(|&v| 1.0 + v).collect());
        ins(format!("{p1}.self_attn.k_norm.weight"), mk(HD, 1, 0.1).iter().map(|&v| 1.0 + v).collect());
        ins(format!("{p1}.mlp.gate_proj.weight"), mk(INTER, H, 0.05));
        ins(format!("{p1}.mlp.up_proj.weight"), mk(INTER, H, 0.05));
        ins(format!("{p1}.mlp.down_proj.weight"), mk(H, INTER, 0.05));
        ModelWeights { tensors }
    }

    /// A tiny `VulkanModel` with `qwen35: Some(..)`, `engine: None` — mirrors
    /// `batched_forward_tests::tiny_qwen_model`'s literal field-by-field style
    /// but for the qwen3_5 path.
    fn tiny_qwen35_vulkan_model() -> VulkanModel {
        let mut weights = build_weights();
        // Mirrors the split loader: `q35_f16_host` is the ONLY source for
        // embed_tokens/lm_head (built above from the still-f32 copy), then
        // stripped from the f32 store — a real load never has both, and
        // leaving a stale f32 copy here would mask a regression back to the
        // `weights.f32_slice` bug this fixture exists to catch.
        let f16_host = q35_f16_host_from_weights(&weights);
        weights.tensors.remove("model.embed_tokens.weight");
        weights.tensors.remove("lm_head.weight");
        let qwen35 = Qwen35Model::new(cfg(), weights, 64, "lm_head.weight".to_string());
        VulkanModel {
            // `inner` is `Gemma4Model` with `gemma` on, `()` with it off — the
            // carve helper yields the right empty placeholder for either slice
            // so this qwen35 fixture builds under the gemma-less qwen35 slice too.
            inner: carve_placeholder_inner(),
            qwen: None,
            qwen35: Some(qwen35),
            step3p7: None,
            max_seq_len: 64,
            engine: None,
            gpu_weights: HashMap::new(),
            act_bufs: Vec::new(),
            act_bufs_ready: false,
            pp_start: 0,
            pp_end: 2,
            pp_first: true,
            pp_last: true,
            tp_rank: 0,
            tp_size: 1,
            gemma_ple_bf16: None,
            gpu_kv: HashMap::new(),
            gemma_kv_filled: 0,
            qres_bufs: Vec::new(),
            qres_ready: false,
            gres_bufs: Vec::new(),
            gres_ready: false,
            gemma_norm_w: HashMap::new(),
            gpu_norm_w: HashMap::new(),
            ures_bufs: Vec::new(),
            ures_ready: false,
            unified_norm_w: HashMap::new(),
            bres_bufs: Vec::new(),
            bres_ready: false,
            q35_f16_host: f16_host,
            collective_comm: 0,
            reduce_scratch: Vec::new(),
            reduce_scratch_handle: 0,
            pp_tok_ring: PpTokRing::default(),
            pp_hop_send: PpTokRing::default(),
            pp_hop_recv: PpTokRing::default(),
            pp_vocab_ring: PpTokRing::default(),
            gemma_hidden_ring: std::collections::VecDeque::new(),
            gemma_pp_hop: Default::default(),
            moe_gpu: HashMap::new(),
            moe_shared_gpu: HashMap::new(),
            dn_gpu: HashMap::new(),
            q35res_bufs: Vec::new(),
            q35res_ready: false,
            q35res_ok: None,
            spec_slots: Vec::new(),
            flags: Flags::from_env(),
            lm_shard: None,
            chunked_weights: std::collections::HashMap::new(),
            nemotron: None,
            nemotron_mtp_head: None,
            kimi: None,
            ling: None,
            laguna: None,
            laguna_gpu: None,
            mtp_head: None,
            mtp_moe_gpu: None,
            q35_last_prenorm: None,
            q35_prenorm_ring: std::collections::VecDeque::new(),
            spec_verify_gdn_inputs: Vec::new(),
            spec_verify_span: None,
            spec_verify_cols: false,
            kv_store: None,
        }
    }

    fn argmax(v: &[f32]) -> usize {
        v.iter().enumerate().max_by(|a, b| a.1.partial_cmp(b.1).unwrap()).unwrap().0
    }

    fn cosine(a: &[f32], b: &[f32]) -> f64 {
        let (mut dot, mut na, mut nb) = (0f64, 0f64, 0f64);
        for (&x, &y) in a.iter().zip(b.iter()) {
            dot += (x as f64) * (y as f64);
            na += (x as f64) * (x as f64);
            nb += (y as f64) * (y as f64);
        }
        dot / (na.sqrt() * nb.sqrt() + 1e-12)
    }

    /// `forward_qwen35_prefill` (CPU-fallback) vs `T` serial `Qwen35Model::forward`
    /// calls, for T=6 (>=4 per the plan's gate), mixed Linear+Full layers.
    #[test]
    fn forward_qwen35_prefill_cpu_fallback_matches_serial() {
        let tokens: Vec<u32> = vec![1, 3, 5, 2, 7, 0];
        let t = tokens.len();
        assert!(t >= 4);

        // Serial reference: a fresh `Qwen35Model::forward` call per token.
        let mut m_ref = Qwen35Model::new(cfg(), build_weights(), 64, "lm_head.weight".to_string());
        let mut serial = Vec::with_capacity(t * VOCAB);
        for (i, &tok) in tokens.iter().enumerate() {
            serial.extend(m_ref.forward(tok, i));
        }

        // Batched prefill: the CPU-fallback branch of `forward_qwen35_prefill`
        // (engine is None on this harness).
        let mut vm = tiny_qwen35_vulkan_model();
        let last_logits = vm.forward_qwen35_prefill_impl(tokens.clone(), 0)
            .expect("forward_qwen35_prefill_impl failed");

        let last_serial = &serial[(t - 1) * VOCAB..t * VOCAB];
        assert_eq!(last_logits.len(), last_serial.len());
        let cos = cosine(&last_logits, last_serial);
        eprintln!("prefill cpu-fallback vs serial: cos={cos}");
        assert!(cos >= 0.99999, "cos {cos} < 0.99999");
        assert_eq!(argmax(&last_logits), argmax(last_serial),
            "last-token argmax must match the serial reference exactly");
        // The CPU-fallback path is literally `forward_pp_range_batched`
        // (delta_net_scan collapsing the Linear layer's T calls, gated_attention
        // called T times for the Full layer) -- bit-exact by construction, so
        // hold it to the stronger bit-identical bar too.
        assert_eq!(last_logits, last_serial,
            "CPU-fallback prefill must be bit-exact vs T serial `forward` calls");
    }

    /// The layer-range fix itself: a resident STAGE covering only layer 0
    /// (`[0,1)` of the 2-layer `cfg()`, `pp_last=false` — the r0solo shape,
    /// just smaller) must (a) run ONLY that layer (not the full 2-layer
    /// model — this is what makes r0solo not need the whole model resident)
    /// and (b) return the raw `[T,h]` stage hidden output, not lm_head
    /// logits, since it isn't the last stage. Bit-exact vs T serial
    /// `Qwen35Model::forward_pp_range(.., 0, 1)` calls on a fresh full model
    /// (the "stage-serial" reference).
    #[test]
    fn forward_qwen35_prefill_cpu_fallback_respects_stage_layer_range() {
        let tokens: Vec<u32> = vec![1, 3, 5, 2, 7, 0];
        let t = tokens.len();
        let h = H;

        // Stage-serial reference: embed, then T serial `forward_pp_range`
        // calls restricted to layers [0,1) only (no norm/lm_head — a
        // non-last stage doesn't own those weights either).
        let mut m_ref = Qwen35Model::new(cfg(), build_weights(), 64, "lm_head.weight".to_string());
        let embed_w = m_ref.weights.f32_slice("model.embed_tokens.weight").to_vec();
        let mut serial_hidden = vec![0.0f32; t * h];
        for (i, &tok) in tokens.iter().enumerate() {
            let tok_embed = &embed_w[tok as usize * h..(tok as usize + 1) * h];
            let out = m_ref.forward_pp_range(tok_embed, i, 0, 1);
            serial_hidden[i * h..(i + 1) * h].copy_from_slice(&out);
        }

        // Batched prefill: a resident stage of JUST layer 0, `pp_last=false`
        // (start from the same full-model tiny harness, then narrow to the
        // 1-layer stage — mirrors how an r0solo stage is just a smaller
        // `[pp_start,pp_end)` over the same global config/weights).
        let mut vm = tiny_qwen35_vulkan_model();
        vm.qwen35 = Some(Qwen35Model::new_range(
            cfg(), build_weights(), 64, "lm_head.weight".to_string(), 0, 1));
        vm.pp_start = 0;
        vm.pp_end = 1;
        vm.pp_last = false;

        let stage_hidden = vm.forward_qwen35_prefill_impl(tokens.clone(), 0)
            .expect("forward_qwen35_prefill_impl (stage) failed");

        assert_eq!(stage_hidden.len(), t * h,
            "non-last stage must return the raw [T,h] hidden, not vocab-sized logits");
        assert_eq!(stage_hidden, serial_hidden,
            "stage-ranged batched prefill must be bit-exact vs T serial forward_pp_range(0,1) calls");
    }

    // ─── Design-A batched-verify identity gate (MTP re-gate, spec §5) ────────
    //
    // The de-risking crown jewel: on the SAME tiny hybrid (GDN + full-attn)
    // stage, a full draft→batched-verify→resolve_chain→commit+GDN-rollback
    // cycle MUST emit a byte-identical stream to plain greedy, for ANY drafter
    // — that is the whole resolve_chain invariant, here exercised against the
    // REAL forward + REAL recurrent-state rollback (not the fake world of
    // `spec_pipe::tests`). Engine-less, so GDN runs the CPU `delta_net_scan`
    // and full-attn the host KV — the exact code the prefill test already
    // proves bit-exact vs serial `forward`. This closes the loop steps 2 (all-T
    // logits), 3 (GDN/full-attn rollback), and 5 (cycle driver) all at once.

    /// Pure-greedy oracle via the T=1 verify path (no drafts, no rollback):
    /// feed the current token, argmax pos → next. This is the reference the
    /// speculative run must reproduce token-for-token.
    fn greedy_ref(t0: u32, n: usize) -> Vec<u32> {
        let mut m = tiny_qwen35_vulkan_model();
        m.reset_kv_cache();
        let mut out = Vec::with_capacity(n);
        let (mut tok, mut pos) = (t0, 0usize);
        while out.len() < n {
            out.push(tok);
            let logits = m.forward_qwen35_verify_impl(vec![tok], pos).unwrap();
            tok = argmax(&logits) as u32; // T=1 ⇒ logits is one [vocab] row
            pos += 1;
        }
        out
    }

    /// Run the full Design-A speculative cycle with a scripted drafter and
    /// return `(emitted[..n], total_committed_tokens, total_cycles)`. `draft_fn`
    /// produces `depth` draft tokens given the pass-A `real` token and its
    /// position — the greedy-exactness of the emitted stream must NOT depend on
    /// what it returns.
    fn run_spec(t0: u32, n: usize, depth: usize, draft_fn: &dyn Fn(u32, usize) -> Vec<u32>) -> (Vec<u32>, usize, usize) {
        let mut m = tiny_qwen35_vulkan_model();
        m.reset_kv_cache();
        let mut emitted: Vec<u32> = Vec::new();
        let (mut real, mut pos) = (t0, 0usize);
        let mut rollbacks = 0usize; // partial-accept cycles (accept_len < depth)
        while emitted.len() < n {
            // Snapshot resident state at `pos` (pre-verify) into ring slot 0.
            m.spec_snapshot_impl(0).unwrap();
            let drafts = draft_fn(real, pos);
            assert_eq!(drafts.len(), depth);
            let mut batch = Vec::with_capacity(depth + 1);
            batch.push(real);
            batch.extend_from_slice(&drafts);
            // ONE batched verify pass of T=depth+1 tokens; argmax each position.
            let logits = m.forward_qwen35_verify_impl(batch, pos).unwrap();
            let vocab = VOCAB;
            let outs: Vec<u32> = (0..depth + 1)
                .map(|ti| argmax(&logits[ti * vocab..(ti + 1) * vocab]) as u32)
                .collect();
            let a_out = outs[0];
            let b_outs = &outs[1..];
            let resolved = crate::spec_pipe::resolve_chain(&drafts, real, pos, a_out, b_outs);
            if resolved.accept_len < depth { rollbacks += 1; }
            emitted.extend_from_slice(&resolved.emitted);
            // Commit: roll resident state back to the accepted prefix (k+1 tokens).
            m.qwen35_verify_rollback_impl(0, resolved.accept_len).unwrap();
            real = resolved.new_real;
            pos = resolved.new_pos;
        }
        (emitted[..n].to_vec(), emitted.len(), rollbacks)
    }

    /// Wrong drafter (drafts almost never match): the PARTIAL-accept rollback
    /// path (spec_restore + full-attn truncate-up + GDN re-scan) fires on nearly
    /// every cycle. The emitted stream must still be byte-identical to greedy —
    /// proving the rollback restores resident recurrent state exactly.
    #[test]
    fn spec_batched_verify_identity_wrong_drafter() {
        const N: usize = 40; // positions < the fixture's 64-slot KV
        let refs = greedy_ref(3, N);
        let draft_fn = |real: u32, pos: usize| -> Vec<u32> {
            (0..4).map(|j| ((real as usize + pos + 7 * (j + 1)) as u32 + 5) % VOCAB as u32).collect()
        };
        let (emitted, _total, rollbacks) = run_spec(3, N, 4, &draft_fn);
        assert_eq!(emitted, refs, "wrong-drafter spec stream must equal greedy");
        assert!(rollbacks > 0, "wrong drafter must exercise the partial-accept rollback path");
    }

    /// Perfect drafter (drafts == the true continuation): full accept every
    /// cycle ⇒ commits depth+1 tokens/cycle, NEVER rolls back. Emitted stream
    /// must equal greedy (the no-rollback commit path).
    #[test]
    fn spec_batched_verify_identity_perfect_drafter() {
        const N: usize = 40;
        const D: usize = 4;
        let refs = greedy_ref(3, N + D + 2);
        let pos_of = refs.clone();
        let draft_fn = move |_real: u32, pos: usize| -> Vec<u32> {
            (1..=D).map(|j| pos_of[pos + j]).collect() // d_1..d_D = s_{pos+1}..s_{pos+D}
        };
        let (emitted, _total, rollbacks) = run_spec(3, N, D, &draft_fn);
        assert_eq!(emitted, refs[..N].to_vec(), "perfect-drafter spec stream must equal greedy");
        assert_eq!(rollbacks, 0, "perfect drafter must full-accept every cycle (no rollback)");
    }

    /// Mixed/pseudo-random drafter: full-accept (no rollback) and partial-accept
    /// (rollback) cycles interleave within one run. Still must be greedy-exact.
    #[test]
    fn spec_batched_verify_identity_mixed_drafter() {
        const N: usize = 40; // keep max position < the fixture's 64-slot KV
        const D: usize = 4;
        let refs = greedy_ref(3, N + D + 2);
        let chain = refs.clone();
        let draft_fn = move |real: u32, pos: usize| -> Vec<u32> {
            (1..=D).map(|j| {
                let mut x = (real as u64).wrapping_mul(0x9E3779B97F4A7C15)
                    ^ (pos as u64).wrapping_mul(0xD1B54A32D192ED03)
                    ^ (j as u64).wrapping_mul(0x2545F4914F6CDD1D);
                x ^= x >> 33;
                if x & 1 == 0 { chain[pos + j] } else { (chain[pos + j] + 1) % VOCAB as u32 }
            }).collect()
        };
        let (emitted, _total, rollbacks) = run_spec(3, N, D, &draft_fn);
        assert_eq!(emitted, refs[..N].to_vec(), "mixed-drafter spec stream must equal greedy");
        assert!(rollbacks > 0, "mixed drafter should hit at least one partial-accept rollback");
    }
}

/// KV-prefix export/import + kv_cache_store no-op/device-readback coverage
/// (the two real-hardware-validation defects this module's fixes target —
/// see the module doc on `dn_gpu_sync_to_host`/`dn_gpu_sync_from_host` in
/// `qwen35_forward.rs` and `KvStore::store`'s idempotent-skip log in
/// `kvstore.rs`). Engine-less (Mac): `dn_gpu` is always empty here, so these
/// exercise the HOST fallback path end-to-end at the `VulkanModel` pymethod
/// layer (not just `Qwen35Model::export_prefix`/`import_prefix` directly,
/// which `qwen35::kv_prefix_tests` already covers) plus confirm the
/// device-sync helpers are a harmless no-op when there is no GPU-resident
/// DeltaNet state to sync. The device-buffer readback itself
/// (`dn_gpu` non-empty) needs a real GPU and is DEFERRED to the next
/// cluster session — see IMPROVEMENTS.md / the task report.
#[cfg(all(test, feature = "qwen35"))]
mod kv_cache_pymethod_tests {
    use super::*;
    use crate::qwen35::kv_prefix_tests::populate;
    use crate::qwen35::{LayerType, Qwen35Config, Qwen35Model};
    use std::collections::HashMap;

    /// Same synthetic hybrid geometry as `qwen35::kv_prefix_tests::build_hybrid`
    /// (one linear + one full-attn layer), but with a caller-chosen
    /// `max_seq_len` — `build_hybrid` hardcodes 64, too small for the
    /// `kv_cache_store`/`kv_cache_load` tests here, which need to clear a
    /// real `kvstore::CHUNK` (256) boundary.
    fn build_hybrid_sized(max_seq_len: usize) -> Qwen35Model {
        let layer_types = vec![LayerType::LinearAttention, LayerType::FullAttention];
        let h = 32usize;
        let (nq, nkv, hd) = (4usize, 2usize, 8usize);
        let (nk, nv, kd, vd, kern) = (1usize, 2usize, 8usize, 8usize, 4usize);
        let n = layer_types.len();
        let cfg = Qwen35Config {
            hidden_size: h,
            num_hidden_layers: n,
            vocab_size: 16,
            rms_norm_eps: 1e-6,
            tie_word_embeddings: true,
            num_attention_heads: nq,
            num_key_value_heads: nkv,
            head_dim: hd,
            attn_output_gate: true,
            rope_theta: 1e7,
            partial_rotary_factor: 0.5,
            linear_num_key_heads: nk,
            linear_num_value_heads: nv,
            linear_key_head_dim: kd,
            linear_value_head_dim: vd,
            linear_conv_kernel_dim: kern,
            intermediate_size: 16,
            num_experts: 0,
            num_experts_per_tok: 0,
            moe_intermediate_size: 0,
            shared_expert_intermediate_size: 0,
            layer_types,
        };
        let weights = model::ModelWeights { tensors: HashMap::new() };
        Qwen35Model::new(cfg, weights, max_seq_len, "unused".to_string())
    }

    /// A bare (`engine: None`, `dn_gpu` empty) `VulkanModel` wrapping a small
    /// hybrid qwen3_5 stage (one linear + one full-attn layer), populated
    /// with seeded state — enough to exercise `kv_export_prefix`/
    /// `kv_import_prefix`/`kv_cache_store`/`kv_cache_load` end-to-end.
    /// `max_seq_len` is sized to comfortably clear one `kvstore::CHUNK`.
    fn tiny_q35_vulkan_model(full_seq_len: usize, seed: u64) -> VulkanModel {
        let mut m = build_hybrid_sized(512);
        populate(&mut m, full_seq_len, seed);
        VulkanModel {
            // `inner` is `Gemma4Model` with `gemma` on, `()` with it off — the
            // carve helper yields the right empty placeholder for either slice.
            inner: carve_placeholder_inner(),
            qwen: None,
            qwen35: Some(m),
            step3p7: None,
            max_seq_len: 64,
            engine: None,
            gpu_weights: HashMap::new(),
            act_bufs: Vec::new(),
            act_bufs_ready: false,
            pp_start: 0,
            pp_end: 2,
            pp_first: true,
            pp_last: true,
            tp_rank: 0,
            tp_size: 1,
            gemma_ple_bf16: None,
            gpu_kv: HashMap::new(),
            gemma_kv_filled: 0,
            qres_bufs: Vec::new(),
            qres_ready: false,
            gres_bufs: Vec::new(),
            gres_ready: false,
            gemma_norm_w: HashMap::new(),
            gpu_norm_w: HashMap::new(),
            ures_bufs: Vec::new(),
            ures_ready: false,
            unified_norm_w: HashMap::new(),
            bres_bufs: Vec::new(),
            bres_ready: false,
            q35_f16_host: HashMap::new(),
            collective_comm: 0,
            reduce_scratch: Vec::new(),
            reduce_scratch_handle: 0,
            pp_tok_ring: PpTokRing::default(),
            pp_hop_send: PpTokRing::default(),
            pp_hop_recv: PpTokRing::default(),
            pp_vocab_ring: PpTokRing::default(),
            gemma_hidden_ring: std::collections::VecDeque::new(),
            gemma_pp_hop: Default::default(),
            moe_gpu: HashMap::new(),
            moe_shared_gpu: HashMap::new(),
            dn_gpu: HashMap::new(),
            q35res_bufs: Vec::new(),
            q35res_ready: false,
            q35res_ok: None,
            spec_slots: Vec::new(),
            flags: Flags::from_env(),
            lm_shard: None,
            chunked_weights: std::collections::HashMap::new(),
            nemotron: None,
            nemotron_mtp_head: None,
            kimi: None,
            ling: None,
            laguna: None,
            laguna_gpu: None,
            mtp_head: None,
            mtp_moe_gpu: None,
            q35_last_prenorm: None,
            q35_prenorm_ring: std::collections::VecDeque::new(),
            spec_verify_gdn_inputs: Vec::new(),
            spec_verify_span: None,
            spec_verify_cols: false,
            kv_store: None,
        }
    }

    fn temp_store_dir(tag: &str) -> std::path::PathBuf {
        let mut p = std::env::temp_dir();
        p.push(format!(
            "vllm_vulkan_kv_cache_pymethod_test_{tag}_{}_{:?}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap()
                .as_nanos()
        ));
        p
    }

    /// Device-sync helpers must be a harmless no-op when `dn_gpu` is empty
    /// (engine-less Mac / `DN_GPU` off) — the host `layer_state` copy is
    /// already authoritative there, so there is nothing to sync.
    #[test]
    fn dn_gpu_sync_helpers_are_noop_without_gpu() {
        let mut m = tiny_q35_vulkan_model(4, 7);
        assert!(m.dn_gpu.is_empty());
        m.dn_gpu_sync_to_host().expect("sync_to_host must be Ok with no GPU-resident layers");
        m.dn_gpu_sync_from_host().expect("sync_from_host must be Ok with no GPU-resident layers");
    }

    /// `kv_export_prefix`/`kv_import_prefix` must still round-trip on the
    /// engine-less host path now that the hard DN_GPU error is gone (the
    /// pymethods route through `dn_gpu_sync_to_host`/`_from_host`, which are
    /// no-ops here) — a straight regression check on the wiring change, at
    /// the actual pymethod layer (not just `Qwen35Model::export_prefix`/
    /// `import_prefix` directly, which `qwen35::kv_prefix_tests` already
    /// covers).
    #[test]
    fn kv_export_import_prefix_pymethods_roundtrip_host_path() {
        pyo3::prepare_freethreaded_python();
        pyo3::Python::with_gil(|py| {
            let mut src = tiny_q35_vulkan_model(5, 11);
            let blob_obj = src.kv_export_prefix(py, 3).expect("export must succeed");
            let blob: Vec<u8> = blob_obj.extract(py).expect("blob must extract as bytes");

            let mut dst = tiny_q35_vulkan_model(0, 999); // fresh/empty state
            let n = dst.kv_import_prefix(&blob).expect("import must succeed");
            assert_eq!(n, 3);
        });
    }

    /// `kv_cache_store` with a prompt shorter than one `kvstore::CHUNK`
    /// (boundary aligns to 0) must be a clean `Ok(())` no-op — NOT an error,
    /// and it must not create a store file. This is the first hypothesis
    /// from the real-hardware finding: a short prompt legitimately no-ops
    /// (chunk-aligned v1 granularity, `kvstore.rs` module doc), which is
    /// easy to mistake for the silent-failure symptom. The no-op is now
    /// logged at `warn` (see `kv_cache_store`) instead of being silent.
    #[test]
    fn kv_cache_store_short_prompt_is_a_loud_noop_not_an_error() {
        let dir = temp_store_dir("short_prompt");
        let mut m = tiny_q35_vulkan_model(4, 3);
        m.kv_cache_init(dir.to_string_lossy().to_string(), 64)
            .expect("kv_cache_init must succeed");

        let token_ids: Vec<u32> = (0..100).collect(); // < kvstore::CHUNK (256)
        let res = m.kv_cache_store(token_ids, 100);
        assert!(res.is_ok(), "a too-short prompt must no-op cleanly, not error");
        let entries: Vec<_> = std::fs::read_dir(&dir).unwrap().collect();
        assert!(entries.is_empty(), "a sub-chunk boundary must write NO file");

        std::fs::remove_dir_all(&dir).ok();
    }

    /// `kv_cache_store` at a chunk-aligned boundary DOES write a file, and a
    /// second identical call (same token chain -> same content-address key)
    /// stays `Ok(())` and idempotently skips the backend write (per
    /// `KvStore::store`'s manifest gate) — the intermittency described in
    /// the real-hardware finding ("first run wrote the file; later identical
    /// runs didn't") is this by-design idempotent skip, not a swallowed
    /// error. Confirms the file exists (from the first store) and both calls
    /// return `Ok(())`.
    #[test]
    fn kv_cache_store_repeat_identical_call_is_ok_and_idempotent() {
        let dir = temp_store_dir("idempotent_repeat");
        let mut m = tiny_q35_vulkan_model(300, 5);
        m.kv_cache_init(dir.to_string_lossy().to_string(), 64)
            .expect("kv_cache_init must succeed");

        let token_ids: Vec<u32> = (0..300).map(|i| (i % 16) as u32).collect();
        m.kv_cache_store(token_ids.clone(), 300).expect("first store must succeed");
        let files_after_first: Vec<_> = std::fs::read_dir(&dir).unwrap().collect();
        assert!(!files_after_first.is_empty(), "a chunk-aligned store must write a file");

        // Re-run identically (same process, same content) — must stay Ok(())
        // and must not error, even though the manifest already has the key.
        m.kv_cache_store(token_ids, 300).expect("repeat identical store must stay Ok, not error");
        let files_after_second: Vec<_> = std::fs::read_dir(&dir).unwrap().collect();
        assert_eq!(
            files_after_first.len(), files_after_second.len(),
            "an identical re-store must not create additional files"
        );

        std::fs::remove_dir_all(&dir).ok();
    }

    /// `kv_cache_store` + `kv_cache_load` end-to-end through the pymethod
    /// layer (not just `Qwen35Model::export_prefix`/`import_prefix`
    /// directly) on the engine-less host path.
    #[test]
    fn kv_cache_store_then_load_roundtrip() {
        let dir = temp_store_dir("store_then_load");
        let token_ids: Vec<u32> = (0..300).map(|i| (i % 16) as u32).collect();

        let mut src = tiny_q35_vulkan_model(300, 21);
        src.kv_cache_init(dir.to_string_lossy().to_string(), 64)
            .expect("kv_cache_init must succeed");
        src.kv_cache_store(token_ids.clone(), 300).expect("store must succeed");

        let mut dst = tiny_q35_vulkan_model(0, 999);
        dst.kv_cache_init(dir.to_string_lossy().to_string(), 64)
            .expect("kv_cache_init must succeed");
        let loaded = dst.kv_cache_load(token_ids).expect("load must succeed");
        assert_eq!(loaded, 256, "must longest-prefix-hit at the one stored chunk boundary");

        std::fs::remove_dir_all(&dir).ok();
    }
}

/// Regression tests for the `forward_pp_gemma`/`pp_gemma_msg_len` cross-stage
/// KV-share target sizing (the 4096-vs-512 g12b panic).
#[cfg(test)]
mod gemma_pp_kv_target_tests {
    use super::{gemma_pp_kv_targets, gemma_pp_tkv_lens};
    use crate::model::Gemma4Config;

    /// g12b has `num_kv_shared_layers == 0` (no cross-stage KV sharing at
    /// all) so `first_kv_shared_layer() == num_hidden_layers`. Targets, tkv
    /// lengths, and therefore the tkv payload in the inter-stage message
    /// must all be empty — NOT the last sliding/global layer of the whole
    /// network (the bug: the old code picked those up as bogus targets and
    /// then sized the global one with a fixed `num_key_value_heads`(8)
    /// instead of its real MQA count(1), producing a 4096-vs-512
    /// copy_from_slice panic).
    #[test]
    fn g12b_has_no_kv_share_targets() {
        let cfg = Gemma4Config::g12b();
        assert_eq!(cfg.first_kv_shared_layer(), cfg.num_hidden_layers);
        let targets = gemma_pp_kv_targets(&cfg);
        assert!(targets.is_empty(), "g12b must have zero cross-stage KV-share targets, got {targets:?}");
        assert!(gemma_pp_tkv_lens(&cfg, &targets).is_empty());
    }

    /// e2b DOES have kv-shared layers (`num_kv_shared_layers == 20`), so the
    /// last sliding and last global layer before `first_kv_shared_layer()`
    /// must be picked up as the (exactly 2) targets, sorted ascending, with
    /// per-layer (not fixed) kv-head counts.
    #[test]
    fn e2b_has_two_kv_share_targets_sized_per_layer() {
        let cfg = Gemma4Config::e2b();
        let first_kv = cfg.first_kv_shared_layer();
        assert!(first_kv < cfg.num_hidden_layers, "e2b must have real kv-shared layers");

        let targets = gemma_pp_kv_targets(&cfg);
        assert_eq!(targets.len(), 2, "expected exactly [last_slide, last_full] before first_kv, got {targets:?}");
        assert!(targets.windows(2).all(|w| w[0] < w[1]), "targets must be sorted ascending");
        for &t in &targets {
            assert!(t < first_kv, "target layer {t} must precede first_kv_shared_layer {first_kv}");
        }

        let lens = gemma_pp_tkv_lens(&cfg, &targets);
        assert_eq!(lens.len(), targets.len());
        for (i, &t) in targets.iter().enumerate() {
            assert_eq!(lens[i], cfg.layer_num_kv_heads(t) * cfg.layer_head_dim(t));
        }
    }

    /// `pp_gemma_msg_len`'s tkv sizing must agree with `forward_pp_gemma`'s
    /// (both now derive from the same `gemma_pp_kv_targets`/
    /// `gemma_pp_tkv_lens` helpers) — this is what makes the vCCL recv
    /// buffer size match what the sender actually writes.
    #[test]
    fn tkv_total_matches_between_msg_len_and_forward_helpers() {
        for cfg in [Gemma4Config::g12b(), Gemma4Config::e2b()] {
            let targets = gemma_pp_kv_targets(&cfg);
            let tkv_total: usize = gemma_pp_tkv_lens(&cfg, &targets).iter().map(|&l| 2 * l).sum();
            if targets.is_empty() {
                assert_eq!(tkv_total, 0);
            } else {
                assert!(tkv_total > 0);
            }
        }
    }
}

// ─── mlx4 column-batched (cols) numeric-contract gate ────────────────────────
//
// OFFLINE (Mac, no GPU) proof of the invariant that lets the batched-prefill
// wiring route a 4-bit (mlx4-affine) weight projection through
// `mul_mat_vec_mlx4_cols` (NUM_COLS=T) INSTEAD OF T serial single-column
// matvecs: at column c, the T-wide dequant-ONCE-reuse-across-columns algorithm
// (the shader's structure — `shaders/mul_mat_vec_mlx4_cols.comp`, decode each
// nibble + affine scale*q+bias once and reuse the scalar across all T token
// columns) produces a result BIT-IDENTICAL to the single-column
// (NUM_COLS=1 / per-token) algorithm for that same column.
//
// This is the numeric heart of `qwen35_matvec_cols` (Mlx4 branch) +
// `qwen35_matvec_cols_tiled`: because output columns are independent and the
// per-element dequant is a deterministic function of (r,j), hoisting the
// dequant out of the column loop and batching T columns changes NOTHING about
// any column's value. The ORACLE here is the per-token single-column algorithm
// — exactly what the current prefill dispatches T times.
//
// The GPU kernel adds a strided BLOCK_SIZE tree-reduction on TOP of this (a
// different f32 summation order than this sequential-j reference), so GPU vs
// this CPU reference is argmax-exact / cos=1.0 rather than bitwise — that delta
// is the deferred ON-NODE ACO gate (mlx4-cols n53, 2026-08-02, cos=1.0). What
// this suite pins offline is the column-batching invariant itself, bitwise.
#[cfg(test)]
mod mlx4_cols_numeric_gate {
    /// Deterministic synthetic mlx4-affine weight `[n,k]`: packed nibbles (8 per
    /// u32, LSB-first) + per-(row,group) scales/biases, exactly as
    /// `model::dequantize_mlx_affine(bits=4)` and the cols shader read them.
    fn synth_mlx4(n: usize, k: usize, gs: usize, seed: u64) -> (Vec<u32>, Vec<f32>, Vec<f32>) {
        assert_eq!(k % 8, 0);
        assert_eq!(k % gs, 0);
        let groups = k / gs;
        let words_per_row = k / 8;
        let mut s = seed.wrapping_mul(0x9E3779B97F4A7C15).wrapping_add(1);
        let mut nu = || { s ^= s << 13; s ^= s >> 7; s ^= s << 17; s };
        let uf = |x: u64| (x >> 40) as f32 / (1u32 << 24) as f32; // [0,1)
        let mut packed = vec![0u32; n * words_per_row];
        let mut scales = vec![0f32; n * groups];
        let mut biases = vec![0f32; n * groups];
        for r in 0..n {
            for g in 0..groups {
                scales[r * groups + g] = 0.001 + uf(nu()) * 0.009;
                biases[r * groups + g] = -0.08 + uf(nu()) * 0.02;
            }
            for j in 0..k {
                let code = (nu() % 16) as u32;
                packed[r * words_per_row + j / 8] |= code << ((j % 8) * 4);
            }
        }
        (packed, scales, biases)
    }

    fn synth_x(t: usize, k: usize, seed: u64) -> Vec<f32> {
        let mut s = seed.wrapping_mul(0xD1B54A32D192ED03).wrapping_add(1);
        (0..t * k).map(|_| {
            s ^= s << 13; s ^= s >> 7; s ^= s << 17;
            ((s >> 40) as f32 / (1u32 << 24) as f32) * 2.0 - 1.0
        }).collect()
    }

    #[inline]
    fn dequant(packed: &[u32], scales: &[f32], biases: &[f32],
               words_per_row: usize, groups: usize, gs: usize, r: usize, j: usize) -> f32 {
        let word = packed[r * words_per_row + j / 8];
        let q = ((word >> ((j % 8) * 4)) & 0xF) as f32;
        let g = j / gs;
        scales[r * groups + g] * q + biases[r * groups + g]
    }

    /// ORACLE — single-column (NUM_COLS=1 / per-token) algorithm, run once per
    /// token: dequant per column, accumulate over j (0..k) sequentially.
    fn oracle_per_token(packed: &[u32], scales: &[f32], biases: &[f32],
                        x: &[f32], t: usize, k: usize, n: usize, gs: usize) -> Vec<f32> {
        let groups = k / gs;
        let words_per_row = k / 8;
        let mut out = vec![0f32; t * n];
        for c in 0..t {
            for r in 0..n {
                let mut acc = 0f32;
                for j in 0..k {
                    let w = dequant(packed, scales, biases, words_per_row, groups, gs, r, j);
                    acc += w * x[c * k + j];
                }
                out[c * n + r] = acc;
            }
        }
        out
    }

    /// BATCHED — the cols-kernel structure: dequant each (r,j) ONCE and reuse
    /// the scalar across all T columns (columns are the INNER loop), matching
    /// `mul_mat_vec_mlx4_cols.comp`'s `temp[nr][c] += w * x[c*k+j]`.
    fn batched_cols(packed: &[u32], scales: &[f32], biases: &[f32],
                    x: &[f32], t: usize, k: usize, n: usize, gs: usize) -> Vec<f32> {
        let groups = k / gs;
        let words_per_row = k / 8;
        let mut out = vec![0f32; t * n];
        for r in 0..n {
            let mut accs = vec![0f32; t];
            for j in 0..k {
                let w = dequant(packed, scales, biases, words_per_row, groups, gs, r, j);
                for c in 0..t { accs[c] += w * x[c * k + j]; }
            }
            for c in 0..t { out[c * n + r] = accs[c]; }
        }
        out
    }

    fn assert_bit_identical(a: &[f32], b: &[f32], msg: &str) {
        assert_eq!(a.len(), b.len(), "{msg}: length mismatch");
        for (i, (x, y)) in a.iter().zip(b.iter()).enumerate() {
            assert_eq!(x.to_bits(), y.to_bits(),
                "{msg}: element {i} differs: {x} ({:#010x}) != {y} ({:#010x})",
                x.to_bits(), y.to_bits());
        }
    }

    /// The core contract: on a real Qwen3.6-27B-class 4-bit projection shape,
    /// the T-wide cols algorithm is BIT-IDENTICAL, per column, to the per-token
    /// oracle — i.e. batching T tokens into one `mul_mat_vec_mlx4_cols` dispatch
    /// changes NO position's projection. Proven for the T=8 gate sweet spot.
    #[test]
    fn mlx4_cols_bit_identical_to_per_token_t8() {
        // gate/up_proj-ish: k=hidden(2560), n=inter/2 slice(1536), group_size=64.
        let (k, n, gs, t) = (2560usize, 1536usize, 64usize, 8usize);
        let (packed, scales, biases) = synth_mlx4(n, k, gs, 0xC0FFEE);
        let x = synth_x(t, k, 0xBEEF);
        let oracle = oracle_per_token(&packed, &scales, &biases, &x, t, k, n, gs);
        let batched = batched_cols(&packed, &scales, &biases, &x, t, k, n, gs);
        assert_bit_identical(&oracle, &batched,
            "mlx4 T=8 cols must equal T serial single-column projections bitwise");
    }

    /// Sweep every T in [1,8] (the registered `_r{rows}_c{t}` set) plus several
    /// shapes/seeds — the batching invariant must hold at every column width,
    /// including T=1 (byte-identical to the serial path by construction).
    #[test]
    fn mlx4_cols_bit_identical_all_t_and_shapes() {
        // (k, n): q_proj-fused (hidden->q+gate), kv_proj (small n), o_proj,
        // down_proj (inter->hidden). All k%8==0 and k%64==0.
        for &(k, n) in &[(2560usize, 5120usize), (2560, 512), (2048, 2560), (4096, 2560)] {
            for t in 1..=8usize {
                let seed = (k as u64) << 20 ^ (n as u64) << 8 ^ t as u64;
                let (packed, scales, biases) = synth_mlx4(n, k, 64, seed ^ 0x1111);
                let x = synth_x(t, k, seed ^ 0x2222);
                let oracle = oracle_per_token(&packed, &scales, &biases, &x, t, k, n, 64);
                let batched = batched_cols(&packed, &scales, &biases, &x, t, k, n, 64);
                assert_bit_identical(&oracle, &batched,
                    &format!("mlx4 cols invariant failed at k={k} n={n} t={t}"));
            }
        }
    }

    /// The per-element dequant this reference uses is the SAME arithmetic as the
    /// production `model::dequantize_mlx_affine` (bits=4) the loader/CPU-oracle
    /// rely on — so the invariant above is anchored to the real dequant, not a
    /// test-only stand-in.
    #[test]
    fn inline_dequant_matches_production_reference() {
        let (k, n, gs) = (512usize, 128usize, 64usize);
        let (packed, scales, biases) = synth_mlx4(n, k, gs, 0x5EED);
        let prod = crate::model::dequantize_mlx_affine(&packed, &scales, &biases, n, k, gs, 4);
        let groups = k / gs;
        let words_per_row = k / 8;
        for r in 0..n {
            for j in 0..k {
                let mine = dequant(&packed, &scales, &biases, words_per_row, groups, gs, r, j);
                assert_eq!(mine.to_bits(), prod[r * k + j].to_bits(),
                    "inline dequant != model::dequantize_mlx_affine at r={r} j={j}");
            }
        }
    }

    /// Column-tiling invariant (the driver of `qwen35_matvec_cols_tiled`):
    /// splitting the T columns into <=8-column tiles and concatenating the
    /// per-tile `[tile,n]` blocks in column order reconstructs the full `[T,n]`
    /// projection BIT-IDENTICALLY — the property that lets a long prefill run in
    /// <=8-token projection tiles with no numeric change. Mirrors the tiler's
    /// column slicing (incl. the fold-back that keeps a lone trailing column in
    /// a >=2-wide tile) for a prompt-length T the GPU kernel can't take at once.
    #[test]
    fn mlx4_cols_column_tiling_reconstructs_full_projection() {
        let (k, n, gs, tile) = (2048usize, 1024usize, 64usize, 8usize);
        let (packed, scales, biases) = synth_mlx4(n, k, gs, 0x7113);
        // T values around the tile boundary, incl. the % tile == 1 fold-back.
        for &t in &[9usize, 16, 17, 100] {
            let x = synth_x(t, k, 0x7113 ^ t as u64);
            let full = oracle_per_token(&packed, &scales, &biases, &x, t, k, n, gs);

            // Emulate qwen35_matvec_cols_tiled's column slicing over `oracle`
            // (each <=tile tile computed independently), then reassemble.
            let mut asm = vec![0f32; t * n];
            let mut c0 = 0usize;
            while c0 < t {
                let mut ct = (t - c0).min(tile);
                if ct == 1 { c0 -= 1; ct = 2; } // fold-back, exactly as the tiler
                let xt = &x[c0 * k..(c0 + ct) * k];
                let part = batched_cols(&packed, &scales, &biases, xt, ct, k, n, gs);
                asm[c0 * n..(c0 + ct) * n].copy_from_slice(&part);
                c0 += ct;
            }
            assert_bit_identical(&full, &asm,
                &format!("column-tiled cols must reconstruct the full T={t} projection"));
        }
    }
}
